// 由 yuboxie/chime（MIT，arXiv 2510.00567）导入的中文网络梗词典：1282 条。
// 字段 [梗, 含义, 例句, 出处]；已过滤 profanity/offense 词条并截断长度。
export const CHIME_LEXICON = [
  ['treetree的', '「treetree的「是一个谐音梗，通常用来形容食物或物品的口感或外观上的“脆脆”感觉。', '这款薯片好好吃，入口就是treetree的感觉。', '源于吃播，在直播中主播因为口音或习惯将“脆脆”发音为“tree tree”，之后被网友在评论区中玩梗并传播开来，尤其在抖音等平台上常见。'],
  ['牛马三件套', '“牛马三件套”指的是房贷、车贷和下一代，形容生活中常见的三种经济压力或责任。这个梗流行源于部分网友对自己的生活状态感到无奈，认为自己像牛马一样辛勤劳作却难以摆脱这些负担，因此这个词具有消极的意味。', '小王最近在调侃自己成了“牛马三件套”的典型代表，因为他要还房贷、车贷，还得操心小孩的教育费用。', ''],
  ['干饭哥', '“干饭哥”是对中国射击运动员盛李豪的昵称，来源于他的网名“光靠干饭就”。这个昵称表现了他的幽默个性。', '大家都在讨论“干饭哥”拿到金牌后的那条有趣的新闻。', '该梗出自盛李豪使用的网名“光靠干饭就”，因其在巴黎奥运会夺金之后被央视新闻提及而走红。'],
  ['水灵灵', '形容一种年轻、有活力的状态。', '水灵灵地挤个地铁，每天都充满活力。', '源自一位韩国女子组合成员在采访中的发言，她在展示合照封面时说自己“水灵灵地在中间”。'],
  ['北京到底有谁在啊', '“北京到底有谁在啊”用来调侃和引出讨论，尤其是在谈论与北京有关的话题时，用于幽默地表达对北京吸引力的好奇或吐槽。', '每次计划去北京旅游，朋友都喜欢用“北京到底有谁在啊”来调侃我。', '该梗出自电视剧《玫瑰的故事》中男女主角的一段争吵画面，剧中林更新饰演的方协文咆哮着问：“那你偏要去北京什么意思，北京到底有谁在啊？”'],
  ['邪恶摇粒绒', '“邪恶摇粒绒”是一个网络用语，形容脾气火爆、性格不太友好的毛茸茸小狗，特别是那些毛发像摇粒绒织物的小狗品种，如泰迪、比熊等。这个术语是基于这些小狗的外观与摇粒绒材料的相似性演变而来的。', '“我家那只邪恶摇粒绒最近又把沙发咬出一个洞，真是拿它没办法！”', ''],
  ['没苦硬吃', '“没苦硬吃”是形容老一辈人为了节约，在并不需要吃苦的情况下，主动去承受不必要的艰难，从而导致适得其反的行为。', '他家明明有空调，但为了省电费，硬是夏天不开，真是典型的“没苦硬吃”。', ''],
  ['脚臭柠檬茶', '“脚臭柠檬茶”是网友们给蜜雪冰城的新品“糯香柠檬茶”起的戏称。这款饮品在试喝后被一些网友形容为有一股“脚臭味”，因此被赋予了这个独特的称号。', '“周末我去蜜雪冰城尝了传说中的脚臭柠檬茶，果然名不虚传，真是一款传奇饮品。”', ''],
  ['已老实求放过', '“已老实求放过”是一个网络流行词，用于表达在面对无可奈何的状况或破防时自嘲的无奈情绪。当人们遇到无法改变的事实，或者在不便直接道歉或反抗时，通过这句话来展现一种俏皮和自嘲的态度。', '在游戏里和队友被敌人打得落花流水后，有人用语音说：“已老实，求放过，咱下局再战。”', '这个梗源自某个网民的评论“给你加两个准时宝就老实了”，最初是用于讽刺那些平时自得但吃到苦头就变得老实的人。随着时间的发展，特别是在冰红茶涨价这一事件中，大家运用相似的句式进行调侃，最终衍生出“已老实，求放过”这一自嘲用语。'],
  ['city不city', '“city不city”是用于形容事物是否洋气、新颖或具有现代化、时尚感的表达。', '明天去的那家咖啡馆装修很特别，真的是city不city？', '来源于外国博主“保保熊”，在他带着自己妹妹去北京长城玩时拍摄的一段视频中，博主用不太熟练的中文问妹妹，“妹妹，长城美不美。”“美”“city不city”“不city，啊。”“大自然里不city啊。”“毫无city啊”。两人魔性的英式中文（中英文混同）逗乐了不少网友。'],
  ['县城豪门', '“县城豪门”指在县城中过着高品质生活的一群人，他们拥有显著的经济优势，让回乡的城市上班族感到不如。', '我上次回老家，发现小学同学成了县城豪门，住着大别墅，真让我惊讶。', ''],
  ['技术宅拯救世界', '指技术宅能够通过自身强大的动手和创造能力，解决各种实际问题，甚至能承担起拯救世界的重任。', '在电影里，当病毒席卷全球，终究是技术宅拯救世界，用代码解开谜团。', ''],
  ['贵圈真乱', '“贵圈真乱”是用于调侃某个社群或圈子里复杂且错综的人际关系的表达。该短语是讽刺意味的，常用来指涉圈子内涉及权力、利益和情感等多种关联，这些关系通常不为外人所知，形容圈内的“水很深”。', '娱乐圈的明星们常常被调侃成“贵圈真乱”，因为他们的故事涉及的恋情、绯闻和幕后利益关系往往扑朔迷离。', ''],
  ['百合无限好可惜生不了', '“百合无限好，可惜生不了”是一种调侃，指的是女性之间的同性恋（也称为百合）虽然美好动人，但由于生物学上的限制，无法自然生育后代。', '在观看一部百合向动画时，有人感慨道：“虽然她们的感情发展得很好，但‘百合无限好，可惜生不了’，感觉有点遗憾。”', ''],
  ['只要可爱就算是男孩子也没关系', '只要一个男孩子足够可爱，相貌或性别就不那么重要，可以被接受或喜爱。这种观点折射出对可爱的一种包容性态度，性别在很多情况下变得次要。', '看到他化妆后的样子，我只能感叹，只要可爱就算是男孩子也没关系啊！', ''],
  ['下个ID见', '「下个ID见「是一种调侃，通常用于网友在哔哩哔哩（B站）看到可能会被平台删除的视频时，预测该账号可能会被封禁，所以戏谑地表示期待对方用新账号再次出现。', '视频作者上传了一段争议性内容，评论区一片“下个ID见”的弹幕。', ''],
  ['亚子', '“亚子”是“样子”的谐音，通常用来模仿口音并添加幽默效果。用可爱或卖萌的语气来吐槽或调侃某人行为方式。', '她穿着两只不同颜色的袜子上班，我忍不住说：“你怎么这个亚子？”', '该梗出自童年经典儿童剧《巴啦啦小魔仙》中角色游乐王子的台词。他的普通话发音有些不标准，经常说“你怎么这个样子”，听起来像“你怎么这个亚子”。因此，网友们将这句话制作成表情包，广泛用于调侃。'],
  ['皮这一下很开心', '指调皮、捣蛋后自得其乐，多用于搞笑、吐槽。', '他把我的饮料藏起来然后得意地笑着说：“皮这一下很开心！”', ''],
  ['人体描边大师', '“人体描边大师”用来调侃射击类游戏中玩家的糟糕枪法，通常指射击时弹道完美避开目标，就像在目标周围画了个轮廓线。', '“昨天晚上玩《绝地求生》，我跟朋友都成了人体描边大师，全程没打中一个人。”', ''],
  ['秦王步法', '“秦王步法”是一种游戏术语，指的是在游戏中，角色贴着掩体反复移动，以躲避敌人攻击的走位技巧。尤其用于形容角色残血时通过绕柱子等障碍物来阻挡敌人视线，等待支援或逃出险境。', '在玩射击游戏时，我学会了秦王步法，利用柱子周旋，虽然敌人火力很猛，但我成功坚持到队友来支援。', '该梗源于《战国策·燕策三》的典故，描述了历史上荆轲刺秦王时，秦王在大殿中绕柱子奔逃的情景。因为大殿上臣子们无法立即拔兵相助，秦王一时间只能以此方式暂避荆轲的追杀。'],
  ['开黑', '开黑指玩家通过语音等便利方式，组队进行对战类游戏的行为，通常能提升团队协作效率。', '周末我们找几个朋友一起开黑，打《英雄联盟》整晚。', '在网吧流行的早期阶段，家用电脑还不普及，许多玩家会选择去网吧进行游戏。相互认识的玩家常常组队一起去网吧玩。当时，网吧有时被称为“黑网吧”或“黑店”，于是玩家们将这种集体游戏的行为称为“开黑店”，后来简称为“开黑”。这一现象最早可以追溯到早期的对战游戏，如《Warcraft III》（War3）的对战地图；随着《英雄联盟'],
  ['抢人头', '抢人头指的是在多人在线游戏中，尤其是MOBA、MMORPG、FPS类型游戏中，某个玩家在别人快要击杀敌人时，抢先攻击并获得最后击杀，从而获得更多的奖励和成就感。', '我都快击杀那个人了，结果被队友抢人头了。', ''],
  ['送人头', '“送人头”指在MOBA类游戏中，玩家故意让对手击杀自己，为对方提供金币和经验。这种行为通常出于消极心态，导致游戏体验受损。', '他在游戏里一气之下开始送人头，结果队友都崩溃了。', ''],
  ['背锅', '「背锅「指一个人或组织在某个事件中替其他人或组织承担责任，通常是在事件失败后被归咎于某人。背锅的人被称为“背锅侠”。', '在这次项目失败后，小王被迫成了背锅侠，承担了所有责任。', ''],
  ['玄学', '「玄学「在游戏圈中指玩家通过非官方渠道尝试影响游戏中随机现象（如掉落概率、装备品质等）的行为。这类行为基于玩家总结的经验，而非游戏的公开机制。', '小明相信玄学，每次抽卡都在凌晨两点，希望这样能提高稀有角色的出现率。', ''],
  ['天胡', '“天胡”是一个游戏术语，源于麻将中指庄家开局即凑成和牌，这种情况被称为“天胡”。因为这种情况需要极高的运气，难度极高。在卡牌对战类游戏中，“天胡”同样用来指开局即拥有非常理想的牌型，能够快速建立优势，甚至直接获胜。然而，如果后续的运气不好导致输掉比赛，这种情况被称为“诈和”。', '《万智牌》玩家在开局得到了理想的组合牌，被称为“天胡小生物”，使得对手难以应对。', ''],
  ['吃鸡', '「吃鸡「源于赌场术语「Winner winner, chicken dinner「，意指大获全胜。经英国电影《决胜21点》和游戏《绝地求生》而流行，现在广泛用于指在任何比赛中取得好成绩。', '昨晚打游戏的时候，真的太刺激了，最后终于吃鸡！', '“吃鸡”一词源自美国赌场，因当时赌局的最低奖金为2美元，而赌场的鸡肉饭售价为$1.79，赢了赌局就能吃到鸡肉饭，赌徒们因此常说“Winner winner, chicken dinner”。这一口头禅在电影《决胜21点》中也被多次提及。随后，这句话因游戏《绝地求生》而广为人知，成为该游戏在中国大陆玩家中的代名词。'],
  ['弹幕', '“弹幕”是一种视频互动机制，用户可以通过评论，让这些评论像字幕一样在视频上滚动。它在网络文化中代表了一种即时的、群体性的观看体验。', '看电影的时候开了弹幕，有些评论特别搞笑，直接把我笑喷了。', '“弹幕”本义是指战场上由密集子弹或炮弹形成的火力网（子弹或炮弹密集得像幕一样）。弹幕机制起源于日本的视频网站niconico动画，并被中国的AcFun和哔哩哔哩等网站效仿。在中国，这种机制被称为“弹幕”。'],
  ['天下漫友是一家', '“天下漫友是一家”最初是弹幕视频网站Acfun的宣传语，旨在表达中国ACG（动画、漫画、游戏）爱好者团结友爱的愿望。实际上，随着圈内发生的多种经济利益冲突和信仰分歧，这句话被用作讽刺言论，用来形容圈内人经常发生的争端和矛盾。', '最近A站和B站的粉丝又在网上撕起来了，真是应了那句老话：天下漫友是一家。', ''],
  ['粉切黑', '“粉切黑”指“粉红的外表下内藏着腹黑的内在”，用于形容表面可爱、实则腹黑的角色。典型表现为拥有粉色头发的角色，常常具有腹黑、黑化或双重人格等特征。', '在动画《未来日记》中，我妻由乃就是典型的粉切黑角色，她的粉发外表下藏着一个极度腹黑的内在。', '“粉切黑”最初是用来评论《机动战士高达SEED》中的角色拉克丝·克莱茵。之后在动画及其他作品中，粉红发色角色常表现出腹黑特质，使得“粉红切开都是黑”成为一种现象。'],
  ['萝莉', '「萝莉「是「洛丽塔「（Lolita）的缩写，最初用于形容9至16岁之间幼小可爱的少女形象，逐渐发展为ACG文化领域中广泛使用的一个次文化术语。不再严格限定年龄，而更多是指代具有幼小、可爱特质的女性形象。', '「在这部动漫中，主角是一位典型的萝莉，受到很多粉丝的喜爱，因为她既可爱又勇敢。「', ''],
  ['团灭', '团灭指的是一个团体或团队的全部成员被消灭，通常用于描述游戏中团队的全员阵亡。', '在打BOSS的时候，由于坦克操作失误，团队被BOSS技能打到团灭。', ''],
  ['少女卷轴', '「少女卷轴「是指通过MOD大量美化和改造后的《上古卷轴》游戏，尤其是《上古卷轴4：湮没》。这些MOD使游戏中的女性角色和环境变得华丽，因此被戏称为「少女卷轴「。', '「我刚刚下载了一大堆MOD，现在我的《上古卷轴4：湮没》彻底变成了少女卷轴，角色美得不像话！「', ''],
  ['b站难民', '“B站难民”一词用于形容因为B站（哔哩哔哩）上因版权、审核等原因缺失某些动画或影视剧，导致原本在B站追剧的观众不得不转移至其他视频平台，成为“难民”的现象。这些观众在其他平台的弹幕和评论中常以“B站难民”自称。', '「《甲铁城的卡巴内利》下架后，我不得已成为了C站的一名B站难民。「', ''],
  ['新手光环', '“新手光环”是用来描述那些刚刚加入某个领域或活动的新手，出人意料地拥有超常运气的现象。这个说法通常带有戏谑性，暗指新手在涉及概率性活动（如游戏）时，因系统设置或纯粹运气使然，表现得异常幸运，从而引发其他参与者的羡慕和不满。', '小张刚刚注册账号，居然第一天就抽到了传说级装备，真是新手光环附体啊！', ''],
  ['爆肝', '“爆肝”指的是为了完成某项任务而付出大量时间和精力，尤其是在晚上熬夜的情况下。最初用于游戏玩家中，形容为了提升游戏角色、完成任务或获取稀有物品需要熬夜和大量投入精力。现也被用于任何需要长期努力和熬夜的活动。', '最近为了赶上游戏活动，我真是爆肝了一周，每天都睡得特别晚。', ''],
  ['外挂', '“外挂”指的是用于电脑游戏中实现作弊行为的软件，能够破坏游戏的平衡性和体验。广泛应用于网络游戏中，因其不公平性，严重影响游戏的体验。衍生义上，“外挂”可以用来形容某人或某事表现得特别出色，超过常人预期。', '这款游戏因为外挂泛滥，导致很多玩家退出游戏，失去了原来的乐趣。', ''],
  ['老头滚动条', '“老头滚动条”（简称“老滚”）是对《上古卷轴》系列游戏的戏称。', '最近我在玩“老头滚动条”，没想到这些Mod装完之后，简直像是换了一款游戏，特别是那些角色的美化Mod。', '由于天人互动在向大陆引进《上古卷轴3：晨风》时，使用了拙劣的机器翻译，因此造成游戏内大量文本无法阅读，甚至连游戏名称都被直接翻译成“老头滚动条”。虽然之后发布了升级补丁修正了大量文本错误，但是在爱好者中产生的恶劣影响已经无法消除。久而久之，“老头滚动条”（亦简称“老滚”）成为对《上古卷轴》这一作品的戏谑称法。'],
  ['补刀', '“补刀”是在MOBA类型游戏中指玩家在小兵或单位生命值很低、即将死亡时进行最后一击，从而获得经验和经济的游戏行为。这是游戏中提高英雄等级和经济的重要方法之一，直接影响玩家的游戏表现。', '在《英雄联盟》中，玩家需要不断练习补刀技巧，以便在对线阶段积累更好的经济优势。', ''],
  ['肝稿', '「肝稿「是指为了完成某项任务或作品（如绘画、动画、作业等）而熬夜耗费大量时间和精力的行为。「肝「作为动词，意味着投入大量时间和精力。', '这个周末我得好好肝稿，不然下周的作业肯定完不成。', ''],
  ['兵库北的微笑', '“兵库北的微笑”指的是声优花泽香菜在一档日本综艺节目中露出的迷人微笑。这一瞬间被捕捉并广泛传播，成为网络恶搞的素材。', '昨天看到一张兵库北的微笑，真的是让人忍俊不禁。', '出自某日本综艺节目，在该节目中，著名声优花泽香菜露出了无比带感的笑容，画面上正在同步滚动的日本各地天气预报刚好滚动到了“兵库北 ☔ 19℃ 60%/40%”，屏幕上还有 “美女声优 花泽香菜”字样。'],
  ['开放式结局', '开放式结局是一种结局形式，广泛应用于游戏、文学及影视作品中，不给出明确的结局，而是提供相关线索，让观众依照自己的想象进行推测。', '《盗梦空间》的结尾是经典的开放式结局，陀螺是否会停下引发了观众的无尽讨论。', ''],
  ['跳票', '指某人或公司未能兑现承诺，常用于指游戏、影视或数码产品等延期发行。', '这款备受期待的游戏再次跳票，让玩家们感到非常失望。', ''],
  ['违和感', '违和感指的是将两件或多件看似不相关或不协调的事物放在一起时产生的不舒适感或不适应感。相反的说法是「毫无违和感「，意指这些事物放在一起看上去自然协调，仿佛原本就应该在一起。', '这张猫咪和蜘蛛侠合成图看起来毫无违和感，仿佛它天生就是超级英雄。', ''],
  ['彩蛋', '彩蛋是指游戏或影视作品中隐藏的、非必需的额外内容，通常由制作方特意添加，供玩家或观众发现。', '我在这款游戏的隐藏关卡里找到了一个彩蛋，揭示了主角的过去。', ''],
  ['暴击', '“暴击”原指游戏中攻击造成超常伤害的情况，后引申为生活中造成强烈心理冲击或切中要害的行为或语言。', '他在游戏中提升了暴击率，现在基本每击都是红字。', ''],
  ['萌翻', '“萌翻”是一个源于ACG文化的网络用语，由“萌”衍生而来。作为形容词时，它是“萌”的加强版，表示某物非常可爱，相当于“可爱爆了”。作为动词时，它描述某物因为特别可爱而打动某人，使其特别喜欢。', '形容词用法：最近看《摇曳百合》，阿卡林真是萌翻了。', ''],
  ['恶意卖萌', '“恶意卖萌”指卖萌过度，显得刻意和不自然，甚至让观者反感。这个词被用于戏谑和调侃中，带有黑色幽默的意味。', '他每次用那种宠溺的眼神看人，简直是在恶意卖萌。', ''],
  ['小天使', '“小天使”是一种爱称，用来形容人物的可爱外表、善良纯真的性格，或具有吐槽意味，表示他们过于理想主义和天真。', '他在班上总是主动帮助同学，真是个小天使！', ''],
  ['小姐姐', '“小姐姐”是一种网络称呼，用于亲切地称呼温柔、美丽的年轻女性，常在ACG界和网络中使用。', '服部平次：“博士家那个小姐姐”。', '该词最早在Lovelive!企划中流行，是粉丝对μ‘s偶像组合成员的称呼。随着传播，逐渐泛指ACG作品及现实生活中可爱的年轻女性。'],
  ['口胡', '「口胡「是一个语气词，原指泄愤或感叹。在网络上，它被引申为“胡说”或“随意说说”的意思。', '你说今天要下雪，这是在口胡吧？', '本字是“㗅”，相当于“靠！”之类的泄愤词语。在香港漫画中，原本是普通的拟声词，后被引申为叹气的声音，港漫中为了加强语气把此字放大，就变成“口胡”了，后逐步演变为网络流行语。'],
  ['精分', '“精分”是精神分裂的简称，但在网络用语中，通常指一个人展现出多重人格或多种行为方式。在配音领域，指声优为不同角色切换音色和性格。', '看这部动漫，声优的精分真的太厉害了，完全听不出是一个人配的。', ''],
  ['无法直视', '「无法直视「表示由于某事物或场景太过诡异、令人震惊或滑稽，以至于不能用正常的眼光去看待。表达一种因槽点满满而无力吐槽或感到感叹的情感。', '看完这段视频，我再也无法直视婚礼中的舞台表演了，太搞笑了。', ''],
  ['蛐蛐', '蛐蛐在网络语境中指小声在背后议论别人，通常是八卦、不好的方面，可以是闲话、坏话或者无中生有的八卦。', '你小心点，那些同事会在背后蛐蛐你的。', ''],
  ['毁三观', '毁三观是指某件事情过于令人震惊，以至于颠覆了大多数人对世界的基本看法或理解，包括他们的世界观、人生观和价值观。这可以涉及传统认识的各个方面，例如物质守恒等科学理论。', '看完这部电影之后，我的三观简直被彻底毁灭了，完全和我之前的认识背道而驰。', ''],
  ['脑残粉', '「脑残粉「是对某人或事物表现出毫无理由地、理性丧失地极度崇拜和维护的粉丝的贬义称呼。这些粉丝常常不允许他人对他们崇拜的对象有任何负面评论。', '尽管那位明星被爆出丑闻，她的脑残粉依然毫无条件地支持他，认为一切都是误会。', ''],
  ['玻璃心', '玻璃心指的是一种敏感脆弱的心理状态，形容人容易受伤、容易感到被冒犯，承受批评或挫折时显得尤为脆弱。', '明明只是开个小玩笑，他却玻璃心碎一地，撂下饭不吃就走了。', ''],
  ['铁三角', '铁三角指形成牢固搭档关系的三个人或三个组织，常用于吐槽或描述固定搭配的三个角色或组织。', '在《哈利·波特》系列中，哈利、赫敏和罗恩组成了魔法世界中的著名铁三角。', ''],
  ['感人', '网络用语“感人”是用来讽刺或吐槽某物或某人在某方面表现得非常差、低、弱、矬、烂等，以至于让人感到无奈或无语。', '这场比赛的解说全程跑题，真是水平感人。', ''],
  ['魔性', '“魔性”是一种网络用语，源于御宅文化，指代具有某种谜之魔力的事物，令人欲罢不能，仿佛被恶魔施加了诱惑力。它描述的对象常让人感到精神中毒或难以停止。可以作为形容词或名词来使用。', '鬼畜视频都充满魔性。', ''],
  ['给力', '“给力”是一种表示事物发展出乎意料地好或很有意思的形容词，类似于说某事很棒或很酷。', '今天的演唱会真给力，现场气氛超级棒！', '“给力”一词最早出现在2010年5月，由中国传媒大学南广学院学生上传的一段日本动画片《西游记：旅程的终点》配音中，台词“这就是天竺吗？不给力啊老湿！”出自cucn201配音组。'],
  ['神回', '“神回”是用来描述某部动画中某一集在剧情、演出、作画、配音、音乐等方面达到极高水准，或引发极大话题的一集。它可能因为震撼的剧情、出人意料的转折、优秀的画质和作画、感染力强的配音和音乐等因素而受到赞誉。', '“昨天看的那集动画真是神回，各方面都太完美了，尤其是最后的剧情反转，完全没有想到。”', ''],
  ['中毒', '中毒指的是对于某些具有强感染力或魔性的音频、视频、动态图像等产生上瘾的状态，使人反复观看或收听，并且欲罢不能。', '听到这首电波曲后，我沉迷其中，现在已经中毒，无限循环播放。', ''],
  ['发糖', '「发糖「是一种形容情节甜蜜温馨的网络用语，通常用于描述一对情侣角色之间秀恩爱的情景，类似于现实中在婚礼上发喜糖的习俗。', '这集动画简直是官方发糖，大方播出主角们的甜蜜日常。', ''],
  ['洗白', '「洗白「指的是反派角色或具有负面历史的角色通过剧情发展或揭示正面形象而改变为正面角色。这种变化通常涉及故事情节的显著转折，以及观众对角色的重新认识。', '在这部剧中，那个被认为是最大反派的角色在最后一集竟然被洗白，原来他一直在暗中帮助主角。', ''],
  ['坑爹', '坑爹一般用来描述被骗、上当或遇到不如预期的体验，也有做子女的让父亲陷入困境的意思。', '他竟然在游戏里花了几千块，真是坑爹啊！', ''],
  ['恋人未满', '“恋人未满”是描述一种人际关系的术语，表示两个人之间的感情比朋友更深厚，但尚未达到恋人的程度。这种关系包含着比普通朋友更加亲密和暧昧的互动，但由于欠缺明确的恋人承诺，所以显得异常美好而脆弱。', '他们两人总是形影不离，大家都觉得他们是恋人未满的最佳诠释。', '“恋人未满”一词来源于日语的熟语“友達以上、恋人未満”（朋友之上，恋人之下）。它通常出现在ACG（动画、漫画、游戏）作品中，用于形容关系特别好的青梅竹马、或者感情升温的男女搭档。'],
  ['有生之年', '“有生之年”用于形容长时间等待后，终于看到某作品更新或完结的惊讶与激动。常用来表达对更新缓慢的调侃或抱怨，也可纯粹表达欣喜之情。', '我居然在有生之年看到了这部拖更多年的作品终于更新！', ''],
  ['打码', '打码是一种图像或视频处理手段，通过对特定区域进行模糊化处理，使其无法辨认，主要用于掩盖露点、血腥、暴力及隐私内容。其效果类似于打马赛克，通常用于保护隐私或遵守相关法律法规。', '观看影片时，一些敏感部分会被打码，以符合影片分级标准。', ''],
  ['套路', '原指武术中的招式组合。后衍生为各种含义，例如社交网络中，指精心策划的计划或阴谋；游戏中，指某种特定的玩法；媒体内容中，指被用过太多次的设定或剧情；程序设计中，指语法糖、设计模式等。', '在社交中，小李总觉得自己被套路了，一切都在对方的计划中。', ''],
  ['安利', '“安利”在网络语境中通常指“强烈推荐”某物或某事。它表达了一种出于个人喜好而热切分享和推荐的态度。', '最近真的被朋友安利了一部超好看的电视剧，晚上不舍得睡觉就为了多看一集。', '该词来源于美国直销公司安利（Amway）。这种推荐方式因其强调诚心推荐和热心分享而闻名，尽管最初有些贬义，随着网络的发展逐渐中性化。'],
  ['划水', '“划水”指在工作或游戏中偷懒、不认真对待、出工不出力的行为。这个词来源于古代划船时一些水手假装用力，但实际上并没有真正用力，全程敷衍的情况。现代语境中接近“打酱油”的意思。', '今天太累了，我就在办公室划水度日，希望老板不要发现。', ''],
  ['懒癌', '「懒癌「是一种戏称，非常懒惰的人被称为“得了懒癌”，形容这种懒散的状态如同不治之症。', '你整个周末都躺在床上，是不是懒癌又犯了？', ''],
  ['下限', '“下限”在网络用语中通常用来形容容忍无节操事物的最低标准或底线。有时是用于形容一个人或事物在道德、行为上的最低限度，通常带有贬义，特别是在形容那些毫无节操、几乎无法更加低俗的状况或行为时。', '“那档节目真是刷新了我的下限，太夸张了！”', ''],
  ['节操', '“节操”在ACG文化中多用于表现对某种目的和欲望的抵抗力，或者指坚持不降低自我底线的能力。也用于形容行为没有下限，被称为“无节操”。', '这张图，真是无节操，不能直视啊啊啊啊。', ''],
  ['先秦淑女步', '先秦淑女步是一种描述女性优雅、从容步伐的风格，要求步伐快速且无波动，呈现一种平移的感觉，不让裙摆摆动。它形容的是一种古典的淑女走路形式，通过网络传播成为流行梗。', '看了她的走路视频，我才知道什么叫真正的先秦淑女步。', '这个梗最初在电视剧《甄嬛传》中被提及，后由博主“氧气在巴厘岛”通过多部视频创作，将“先秦淑女步，素～步步有态度，素～”作为开场语，并在网络上走红。'],
  ['人生赢家', '“人生赢家”通常指的是在现实生活中取得全面成功的人，即事业、人生和爱情上都取得了良好结果的人。在二次元和宅文化中，它特指那些在朋友或爱情方面达到了理想状态的人物，常让人羡慕嫉妒。', '他事业有成，家庭美满，真是个不折不扣的人生赢家。', '该梗出自日本动画作品《幸运☆星》（原作漫画版第二集），角色泉此方的父亲泉总次郎（此方爸）因为其萝莉控属性，对家中住进可爱的小早川优而心生感慨，心中想着：“我真可是人生的赢家啊！”'],
  ['精神污染', '精神污染指对人的心理造成严重负面冲击的现象，导致精神状态发生明显变化，如敏感、焦躁、不安，甚至崩溃。通常指观看鬼畜、洗脑、重口味作品后产生的感受。', '昨天看了个超重口味的视频，我觉得这是严重的精神污染。', ''],
  ['么么哒', '“么么哒”是一个表达亲密和喜爱的卖萌词汇，类似于“亲亲”，通常用于恋爱中的情侣之间，表示对对方的钟情与喜爱。现在被用于关系较亲密的朋友之间表达暧昧或友好。', '妹纸下班说要来接我，简直开心得飞起，么么哒！', ''],
  ['吃手手', '「吃手手「起初指婴幼儿自发的自然行为，后来因网络表情包的影响而被萌化、恶搞，成为网络流行语，通常用于表现可爱、卖萌的状态。', '在聊天时，我用了一张“吃手手”的表情包，朋友立刻回了一句“萌翻了！”', ''],
  ['大雾', '“大雾”是一个网络用语，通常用于表示之前的陈述或评论是故意曲解或以开玩笑的态度发表的。它也可以表示上一句话具有深刻或不可捉摸的含义，是“大误”和“大污”的变形。', '喜羊羊与灰太狼真是一部极其富有内涵的动画片，孩子们看了之后，智商急速向 1024 奔去！且成年人看了，也十分有助于帮助掌握宇宙的真理。(大雾)', ''],
  ['正宫', '“正宫”在ACGN作品中指男主角的主要情感对象，通常指女主角，也是出镜率和与男主匹配度最高的角色。该角色通常是故事的核心，与剧情和世界观关系紧密。', '在这部动漫中，小美无疑是正宫，她和男主的情感线最深入人心。', ''],
  ['现象级', '“现象级”用来描述某一作品引起了广泛的社会关注，而不仅仅是局限在其原有的小圈子内。这样的作品能够突破其原本的受众群体，甚至吸引到社会整体的注意力。', '《进击的巨人》因其扣人心弦的剧情和丰富的视觉效果，被称为一部“现象级”作品，吸引了大量圈内外的观众。', '“现象级的”错译自英语phenomenal，该词之所以被错译为“现象级的”，是因为译者不了解同源词phenomenon的释义而望文生义。同源词phenomenon有两个释义，一是“现象”，二是“杰出的人；非凡的人”。译者只知前者，不知后者，于是将phenomenal错译成了“现象级的”。'],
  ['黑科技', '黑科技指超越当前人类科技水平、缺乏科学依据但表现异常强大的技术、产品或现象。常用于描述那些令人难以理解、感觉“高深莫测”的技术或发明。', '这款新手机的快充技术简直是黑科技，让手机几分钟内充满电。', '这一术语最早出自《全金属狂潮》，用来形容超越人类现有科技水平的知识。如今在日常生活中也常用于描述让人惊叹或感到“不可思议”的创新技术和产品。'],
  ['倒贴', '指女生主动追求男生，并用财物贴补对方。这个用语常见于ACG领域，尤其在一些二次元作品中，典型场景为萌妹子追求并“倒贴”给男生。', '在那部动画中，女主角为了博得男主的好感，不仅表白，还倒贴给他买游戏装备。', ''],
  ['处刑曲', '「处刑曲「是一种ACG（动画、漫画、游戏）作品中使用的背景音乐（BGM），通常在关键时刻伴随主角翻转局势或施放强大技能出现，表现出激昂和振奋的氛围，是胜利和力量的象征。它分为两种类型：一是在主角反攻或胜利时使用的音乐；二是字面意义上的处刑音乐。', '当比赛进入关键时刻，音乐突然变为激昂的 「处刑曲「，让整个场馆的气氛都变得热血沸腾。', ''],
  ['辣眼睛', '“辣眼睛”是用来形容看到某一事物时，感觉难受且无法直视，通常用于评价一些奇葩或充满槽点的事物。', '那张精神污染图真是太辣眼睛了，我得洗洗眼。', ''],
  ['熊孩子', '“熊孩子”是一个带有贬义的称呼，形容那些调皮、无法无天，并且尚未受到良好家庭教育的孩子。尽管他们行为惹人讨厌，但通常是出于一时顽皮和无心之过。这个词也可用作对调皮孩子的爱称，表示一种调侃的喜爱。', '家长在饭馆用餐时，对桌的小孩不停地大喊大叫，其他食客只能无奈地摇头说：“这熊孩子真让人头疼。”', ''],
  ['悬着的心终于死了', '“悬着的心终于死了”表示在经历了长时间的担忧和不安之后，事情虽然得到了不理想的结果，但这也让人不再需要继续为此操心或纠结。这里的“死”意指心理上的放下和结束，而不是生理意义上的死亡。', '他一直期盼的升职机会落空了，知道结果后他说：“悬着的心终于死了，总算不用再想了。”', ''],
  ['女A男O', '女A男O指的是一种恋爱关系，强调女性强势、男性弱势的动态。通常，女性在这种关系中具有主导权和领导力，而男性则较为柔弱或依赖女性。', '在新的电视剧中，女主是个成功的律师，男主则是个温柔的厨师，这种女A男O的角色设定让我充满期待。', '这一概念源于欧美同人圈，其中「A「代表Alpha，意指强者和领导者；「O「代表Omega，通常指较为柔弱的一方。这种角色设定后来在影视剧和小说中受到欢迎。'],
  ['乱入', '“乱入”是ACG（动画、漫画、游戏）用语，指在一部作品中出现来自另一部作品的角色、道具或场景。这种现象类似于“穿越”，通常用于搞笑或致敬。', '在最新一集动画中，居然看到小丸子和柯南同时出现，这真是一次有趣的“乱入”。', ''],
  ['爆表', '「爆表「指的是超出了极限或标准的测量范围，无法计量。通常表示某种程度极高、非常厉害或强大的意思。', '这款游戏的画质美感简直爆表，让人一秒入迷。', '最早出现于鸟山明的漫画《七龙珠》的赛亚人篇中，孙悟空在对战贝吉塔时使用了界王拳，自身的战斗力瞬间猛增以至于超过布尔玛（捡拉蒂兹遗留的探测器）的探测上限，导致战斗力探测器爆炸，即「战斗力爆表「。'],
  ['吓尿了', '“吓尿了”是一种夸张表达，用来表示因恐惧、惊吓、恶心等负面情绪而产生的强烈反应。其含义实则是反义，通常并不是字面上的真的吓出尿来，而是借此夸大以引起注意或表达不满。', '看完那个惊悚电影的结局，简直吓尿了，晚上都不敢一个人睡觉。', ''],
  ['233', '233是网络用语，通常表示大笑，有时可以表达嘲讽或讽刺。', '他讲的笑话太好笑了，简直233！', '来源于猫扑论坛的第233号表情符号，一张捶地大笑的表情。经过QQ和其他论坛的传播，成为流行语。'],
  ['拉仇恨', '“拉仇恨”原指在游戏中利用仇恨值控制敌人攻击目标的策略。现常用于网络，指发表或进行容易引起他人不满的言论或行为，成为众矢之的。', '在团队副本中，坦克要注意拉稳仇恨，确保怪物不会攻击其他队友。', ''],
  ['骚技能', '“骚技能”是指那些标新立异、与众不同的新想法、新点子或新技能，通常与主流审美或思想不符，展现发明人的独特性。这一说法常用于自嘲或自吹。', '我今天在游戏里发现了一个超级厉害的骚技能。', ''],
  ['打脸', '「打脸「是在中文网络和宅圈中常见的用语，用来形容某人对事情发展抱有很大自信，提出断言后，事态的发展却出乎意料地与预期相反，令人尴尬，就像被一记耳光打在脸上。这个术语也可以指字面上的物理打脸，常与比喻意义的「打脸「一同出现。', '在游戏晚期，解说员自信地说“他们这次绝对输了”，却没想到队伍在最后时刻创造奇迹翻盘，让解说员被打脸了。', ''],
  ['虐狗', '「虐狗「是指“虐单身狗”的简称，用来形容当单身人士看到情侣秀恩爱时感受到的羡慕、嫉妒、甚至是自嘲的心理状态。这里的“狗”指的是“单身狗”，是网络流行的自嘲称呼，而非真实的狗。', '每次在朋友圈看到朋友秀恩爱的照片，都觉得自己被狠狠地虐狗了。', ''],
  ['查水表', '「查水表「是用于调侃警察或相关人员以虚假借口诱捕或接触嫌疑人的行为。这一用语也讽刺和调侃互联网或社会对政治敏感信息的监控和封禁。', '最近网上讨论敏感话题的热度高，不知道会不会被“查水表”。', '该用语最早来源于2007年9月新华社一篇关于警方破获跨国赌博窝点的报道，后因2008年电视剧《重案六组》或《派出所的故事》第6集中的台词而流行。'],
  ['带节奏', '“带节奏”是指故意挑起群众跟风或争端的行为，常表现为煽动他人争斗或传播负面情绪。虽然在游戏中有正面的领导作用，但在网络上通常具有负面意义，往往涉及谣言传播和情绪化反应。', '最近在某论坛上，有人不停带节奏，把整个话题引向了毫无根据的攻击。', ''],
  ['布吉岛', '布吉岛是“不知道”的谐音网络用语。', 'A：你记得明天的活动安排吗？      B：偶布吉岛啊。', ''],
  ['钓鱼', '“钓鱼”在网络文化中指的是一个人通过发布虚假或夸张的信息吸引他人注意，并引导他们进行讨论或分享。在网络交流中，钓鱼的目的是让人上当，进而引起群体围观与批评，实现影响舆论的目的。钓鱼者通常以“渔民”身份出现，故意发布挑衅性言论或信息来激怒或误导他人。', '昨天我在论坛上看到一个帖子特别夸张，结果发现只是在钓鱼，想引我们去争论。', ''],
  ['咸鱼', '“咸鱼”指代稀里糊涂地玩游戏、没有理想或目标、不努力争取游戏奖励的人。也可指现实中不愿努力、不成功的人，多用于自嘲。', '我最近真的是个咸鱼，游戏上线就摸鱼，很久没拿到奖励了。', ''],
  ['实锤', '“实锤”指的是能够证明某事件真实发生的可靠证据，通常具备较强的说服力。', '实锤！某明星出轨证据被曝光，引发网友热议。', ''],
  ['作死', '「作死「用于形容不知轻重、不顾危险的行为，相当于「自寻死路「。多用于吐槽某人做出了可能引发危险的行为，常带有喜剧效果。', '他开车的时候看手机，真是作死行为。', ''],
  ['机智', '「机智「在网络用语中指做了聪明或巧妙事情的人，虽然原本是褒义词，但网络上常用于讽刺或恶搞。', '面对复杂的题目，机智的张三用巧妙的方法解决了难题。', ''],
  ['装逼', '装逼指的是表面上装作很厉害或拥有某项特殊技能，以使别人相信自己的某种能力很强。这种行为可以是为了满足虚荣心，也可以是为了获得某种优势。在特定情况下，谦虚也可以算是一种装逼行为。', '你在开会时总是表现出一副专业的样子，真是个装逼高手。', ''],
  ['撕逼', '撕逼指的是在网络上，尤其是论坛中，网民之间进行的激烈争吵或骂战，常涉及谩骂和揭露隐私。', '昨天的帖子太激烈了，大家在评论区撕逼得不可开交。', ''],
  ['耐撕', '“耐撕”是网络流行语，源自英语“nice”的音译，具有双关含义。除了表示正面积极的意思外，“撕”也可以指撕名牌、撕逼、撕小三等含义。', '在今天的比赛中，他表现得非常出色，是一个非常耐撕的对手。', '该词语来源于中国大陆大型真人秀节目《奔跑吧兄弟》，在某一季节目中，一名成员说要做一个“耐撕”的人，这种说法因其双关意味而流行开来。'],
  ['潜力股', '“潜力股”在网络和ACG用语中指一个人（或事物）现在可能不出色，但具备很大潜力并在未来能够取得巨大成就。在择偶语境中，通常指有发展前途的年轻男性。', '她觉得他是个潜力股，虽然现在工作普通，但他很有上进心。', ''],
  ['扫地僧', '“扫地僧”指代那些表面上看起来平凡甚至不起眼，但实际上技能超群、实力深不可测的人。这种人物常常在关键时刻展现出令人震惊的能力，给人以大隐隐于市、卧虎藏龙的感觉。', '在公司工作多年，大家都没注意到这位不起眼的老员工，直到他在技术难题上展现了惊人的解决能力，真是个不折不扣的扫地僧。', '“扫地僧”一词来自金庸小说《天龙八部》中少林寺的无名老僧。他表面上是普通的扫地僧，但却拥有极高的武功水平，被认为是金庸小说里的第一高手。'],
  ['嘤嘤怪', '“嘤嘤怪”是一个网络流行称呼，指那些说话嗲嗲的、恶意卖萌且习惯用“嘤嘤嘤”作为口癖的人。', '嘤嘤嘤，不给我买东西……', ''],
  ['打酱油', '打酱油表示对某事不关心或不想发表意见，与自己无关，相当于“路过”或“无可奉告”。', '朋友们在热议最新的明星绯闻，我只是默默打酱油。', '源自2008年广州电视台的采访事件，一位市民被问及艳照门事件时回答“关我鸟事，我出来买酱油的”，引发网络热议，成为流行语。'],
  ['摸头杀', '摸头杀是一个流行于网络的术语，用来描述在女生情绪低落时，用摸头这种动作给予安慰，并因此赢得好感或产生额外情感的效果。这个动作通常伴随着温暖的话语，可以大大提升安慰效果。', '小明看到小丽因为考试失利而难过，轻轻给了她一个摸头杀，小丽瞬间破涕为笑。', ''],
  ['三秒规则', '“三秒规则”是一种迷信说法，认为掉在地上的食物在三秒内捡起来还能吃，这种观念常见于ACG作品中，作为吃货的一种萌属性或者是表现角色珍惜食物的方法。', '在漫画中，主角掉了一块饼干在地上，立刻捡起来说：“三秒内，没事的，还是可以吃的。”', ''],
  ['上帝视角', '上帝视角指的是第三人称视角，能够以无所不知的方式描写任何事物。在网络文学中，这种视角用来指代在第一人称写作中不该出现的对他人心理活动的了解。', '这部小说使用上帝视角，不仅描述了主人公的行动，还揭示了其他角色的内心想法。', ''],
  ['又双叒叕', '“又双叒叕”用于形容某件事情发生次数过于频繁和密集。', '枫哥枫哥你又双叒叕被打爆了吗。', '2012年12月17日晚间，日本朝日新闻中文网微博发布了一条微博，“我们又双叒叕要换首相了。”这句话的关键在“又”字，四个汉字拆开就是10个“又”字，反映日本频繁换首相。'],
  ['神作', '“神作”指水平极高或拥有特殊设定、剧情的作品。可能表现出思想深度、艺术结合完美。其使用已泛化，出现了贬义倾向，甚至恶搞用法。', '很多人认为《命运石之门》是近几年的神作，因为它巧妙的剧情设计和深刻的主题。', ''],
  ['神曲', '“神曲”指作曲精湛、影响广泛的音乐作品。这些作品通常因其卓越的艺术水准和广泛的受众认可而被称为“神曲”。', '那部动画的主题曲真是一首神曲，听过的人都赞不绝口。', ''],
  ['根本停不下来', '“根本停不下来”是一个用来形容对某件事情极度沉迷或享受，以至于无法停止的表达方式。通常带有幽默和夸张的成分，用来吐槽自己在某个爱好或活动中乐此不疲。', '那家餐厅的麻辣小龙虾太美味了，我吃得根本停不下来。', '这句话最初来自“炫迈”口香糖广告。在广告中，多个角色因为口香糖持久的味道而乐此不疲地从事某些活动，最后都以“根本停不下来”来强调口香糖的持久性和吸引力。'],
  ['好像身体被掏空', '“好像身体被掏空”形容极度疲惫或精力耗尽，常用于调侃或自嘲。', '网吧通宵10连跪后，他无奈地说：“感觉身体被掏空。”', '此梗来源于中国大陆2016年的汇仁肾宝广告，广告中提到“肾虚，有时是在过度劳累之后，仿佛身体被掏空……”。因广告的广泛传播，这句话成为网络流行语，并被用于各种场合。'],
  ['你是猴子请来的救兵吗', '用于调侃对方搞笑或不太靠谱。现在常被替换“你是猴子请来的逗比吗”，用来调侃对方搞笑。', '他修电脑修了一整天，结果还没修好，真是猴子请来的救兵。', '央视86版《西游记》中红孩儿对观世音菩萨说的话。'],
  ['挖掘机技术哪家强', '这个梗用于调侃，通常在表述严肃或复杂的话题后，以「挖掘机技术哪家强？「来突然转折，增加幽默效果。', '有人问为什么有些人总是热衷于追求名利，殊不知生活的真正意义在于内心的平和和满足。然而问题来了，挖掘机技术哪家强？', '源自蓝翔职业技术学校的广告，该广告由唐国强代言，问句“学挖掘机学校哪家强？中国山东找蓝翔！”成为经典。'],
  ['屎上雕花', '“屎上雕花”形容对本质上很糟糕的事物进行不必要的修饰和包装，这种行为虽然耗费精力，但并不会改变其糟糕的本质。', '这个项目虽然包装得很漂亮，但其实就是屎上雕花，没有实际价值。', ''],
  ['既视感', '「既视感「是一种生理现象，指人在没有实际经历过的情况下，对某个场景产生强烈曾经见过或经历过的感觉。该词来自法语「Déjà vu「，意为「已经看过「，也指一种似曾相识的感觉。', '走进这间旧房子我突然有种强烈的既视感，好像我曾经来过这里。', ''],
  ['存在感', '存在感指的是一个角色在作品中的活跃程度和受欢迎程度。角色出场次数多、时间长、表现活跃，存在感就越高。此外，存在感也可以是作者赋予角色的设定，影响角色在读者或其他人物中的印象深刻程度。', '虽然他是主角，但由于剧情设定的关系，他在故事前期几乎没有存在感。', ''],
  ['泪流满面', '“泪流满面”原指极度悲伤，后来在网络上用来表示激动、惊讶或哭笑不得的心理状态。“内牛满面”是它的谐音变体，带有幽默感。', '看到偶像在演唱会上向粉丝们表达感激，粉丝们纷纷表示“泪流满面”。', ''],
  ['雨露均沾', '“雨露均沾”指的是不偏袒或过分宠爱某少数人，而是平等对待所有人或事物，达到制衡的目的。此词语在网络语境中，常用于调侃或讽刺某种极致偏爱的现象，通常以重复的句式加深喜剧效果。', '自打我出生以来啊，就独得上帝恩宠，我劝上帝一定要雨露均沾，可上帝非是不听呢，就让我单身，就让我单身，就让我一直单身。', ''],
  ['领便当', '「领便当「用于指代影视、动画、游戏等作品中角色的死亡，因角色在故事中完成任务后如同演员完成演出，被「打发「离场，类似于影片中配发便当的桥段。这一术语后来在网络上广泛流行，被用于表达角色在剧情中退出。', '在诸多战斗系动画中，随着剧情的推进，主角团的指挥官最终悲壮「领便当「，观众纷纷表示不舍。', '该词源于周星驰的影片《喜剧之王》，电影中，他饰演的小角色在完成简单的表演后被给予一盒便当作为「打发走人「的象征。'],
  ['黑历史', '黑历史指那些过去做过的、现在回想起来会觉得羞耻或者不愿意提及的事情，类似“污点”。', '他谈起了自己的黑历史，大家听了都忍不住大笑。', '黑历史一词起源为日本动画《∀高达》的用语，指被封印起来的历史。剧中特指战争的历史。'],
  ['涨姿势', '“涨姿势”是“长知识”的谐音，表示获得新知识或了解到新鲜事物。', '今天才知道北极熊是左撇子，真是涨姿势了。', ''],
  ['魔改', '魔改指对一个已有作品或事物进行大幅度且违背原作本意的修改，常呈现出夸张和意想不到的效果。', '这款游戏的剧情被魔改过，现在的走向完全出乎意料。', ''],
  ['剁手', '“剁手”是网购热潮中的一种自嘲和调侃，指那些无法控制自己购物欲望的人，尤其是在网购时往往沉迷于疯狂购物，最后购买了许多不需要的东西，造成金钱和时间的浪费。即便意识到了问题，仍然无法克制购物冲动。', '双十一来了，我已经准备好做一名合格的剁手党了，购物车塞得满满的。', ''],
  ['狗带', '“狗带”是“go die”的谐音，意为去死或者死亡，通常用于幽默或夸张的表达方式。', '今天工作实在太多了，我选择狗带。', '“狗带”出自韩国组合EXO前成员黄子韬的一段说唱，开始于2015年10月左右在互联网流行。原句为“我不会轻易的狗带”。'],
  ['我读书少你不要骗我', '「我读书少，你不要骗我「是一句反语，用来表明说话者已经看穿了对方的企图或虚假信息，意在告诉对方不要再继续尝试欺骗。虽然字面上是承认自己读书少，实际上是讽刺对方的误导或不实之辞。', '对某些虚假广告的回应：在看到一个声称“减肥药一星期内减掉20斤”的广告时，网友留言道：“我读书少，你不要骗我。”', '这句话出自1972年电影《精武门》中，由李小龙饰演的角色陈真对巡捕房探长说的话。在电影中，这也是一句反语。'],
  ['快到碗里来', '“快到碗里来”是用来表达好感或表白，表示“你是我的菜”或你已经注定属于我了，是调侃和娱乐的方式。', '我看你这么可爱，快到碗里来吧！', '该短语来源于一则牛奶巧克力豆的广告。广告中，一个男孩拿着碗对巧克力豆说“快到碗里来！”，巧克力豆则回应“你才到碗里去！”'],
  ['你值得拥有', '“你值得拥有”是一句表达鼓励和推荐的流行语，常用于强调某人应获得某物或某种体验。', '看完这部电影，我觉得你真的应该去看看，绝对值得拥有。', '这句话最初出现在巴黎欧莱雅的广告词中，由多位知名明星在代言时使用。'],
  ['让子弹飞一会儿', '“让子弹飞一会儿”指在面对某件事情或问题时，不要急于下结论，耐心等待，观察事情的发展变化。带有一种胸有成竹和运筹帷幄的态度，预期事情会朝着自己希望的方向发展。', '在看到股市短期波动后，他决定不急着操作，心想“让子弹飞一会儿”，观察未来的市场趋势。', '该梗出自2010年上映的电影《让子弹飞》中的一句对白。在影片中，角色张麻子在伏击中让子弹飞了一会儿，结果证明枪击的效果如他所想，象征着计划的运筹和事件的最终发展。'],
  ['躺着也中枪', '“躺着也中枪”表示在没有招惹任何人的情况下无缘无故被牵连或受到言语攻击。它是一种自嘲和无可奈何的表达，类似于“伤及无辜”。', '昨晚的会议上，他们为了业绩互相指责，结果我这个无关人员也被点名批评，真是躺枪。', '出自周星驰的电影《逃学威龙》，在一个激烈打斗场景中，一名本装死的人被误伤后发出的经典台词：“我靠！ 躺着都能中枪！”'],
  ['我从未见过有如此厚颜无耻之人', '用来形容某人极为厚颜无耻的行为，或在看到恶搞、鬼畜类视频时用于吐槽、讽刺。', '在观看某个搞笑视频时，诸葛亮用力说：“我从未见过有如此厚颜无耻之人！”弹幕密密麻麻刷屏。', '这句话出自1994年版国产电视剧《三国演义》第69集中诸葛亮的台词，原本只是一句普通的影视剧对白。然而，随着鬼畜文化的兴起，这段诸葛亮与王朗对峙的6分钟视频被网友用于鬼畜素材进行恶搞，使这句话在各大视频网站走红。剧情讲述了王朗试图通过辩论让诸葛亮投降，结果却被诸葛亮的犀利言辞气得跌落马下，最终死于“厚颜无耻”一言。'],
  ['我的内心毫无波动甚至还想笑', '“我的内心毫无波动甚至还想笑”是一个网络流行用语，用来表达一种戏谑和淡然的态度。主要用于看客对某些事件表示无动于衷或不受影响，可能因为没有兴趣或因为见多不怪。', '看着这场撕逼大战，我的内心毫无波动，甚至还想笑。', '该梗大约起源于2014年7月，出自某金姓网友在百度贴吧被人肉和P图黑后所说的话。原话的具体内容不详，网络上流传有不同版本，其中以“我的内心毫无波动，甚至还想笑”最为广泛。'],
  ['装作四处看风景', '“装作四处看风景”用来形容装傻充愣、顾左右而言他的行为。', '老板问我项目进度的时候，我只好装作四处看风景。', '该梗出自香港某中学三年级学生梁逸峰在第61届香港学校朗诵节上的表演，梁同学称自己在诗的初段会“装作四处看风景”以配合朗诵。'],
  ['正义也许会迟到但绝不会缺席', '“正义也许会迟到但绝不会缺席”是对正义最终会得到实现的信念，尽管有时会有延迟。这句话反映了一种乐观态度，认为虽然现实中正义可能会来得晚，但它最终会到来，这也常用于调侃或在面对负面局面时鼓励自己和他人。', '在这场迟迟未决的官司中，我始终相信正义也许会迟到但绝不会缺席。', ''],
  ['只要推力大板砖也能飞上天', '“只要推力大，板砖也能飞上天”这句话的含义是，某些气动性能较差的飞行器可以通过增强动力来弥补其缺陷，从而使其能够有效飞行。尽管这种方法不能替代所有的航空设计原理，但在一定程度上，足够的推力能够弥补气动设计的不足。', '在科幻电影中，当主角乘坐看似不可能飞行的飞船时，观众不禁调侃，“只要推力大，板砖也能飞上天。”', '这句话最初来源于美国洛克希德战术战斗机系统分部前项目经理巴特·奥斯本：“With enough power, you can make a brick fly.”这是奥斯本对早期ATF设计时面临的超音速飞行问题的形象描述。它在1998年被发表在美国《Code One》杂志的一次采访中。'],
  ['虽不明但觉厉', '「虽不明但觉厉「意思是“虽然不明白说的是什么，但觉得很厉害”。用来形容对于一些复杂、不易理解的内容的敬佩或吐槽。', '他写了篇关于量子物理的论文，我看了之后，虽不明但觉厉。', ''],
  ['高端大气上档次', '“高端大气上档次”原指形容事物规格高、品味优雅。现在多用于反讽，如指代过于追求表面的高端和奢华，或形容甲方不切实际的要求。', '这个酒店装修得高端大气上档次，但服务水平实在跟不上。', '源于电视剧《武林外传》第39集，中秋节，钱掌柜要求李大嘴做月饼送客户，对他提了三个要求：高端、大气、上档次。'],
  ['理都懂', '“理都懂”表示“道理我都懂”/“我理解你说的道理”，通常用来表达一种无奈、吐槽或讽刺的情感。意思是虽然道理大家都明白，但现实中往往行不通或无法解决问题。', '道理我都懂，但为什么生活还是这么难？即使掌握了全部理论，现实中的琐事依然让人疲惫不堪。', '该梗出自电影《后会无期》中的一句台词：“听过很多道理，依然过不好这一生”。随着时间的推移，这句话演变成了“理都懂”这一流行语。'],
  ['虽现狗', '指虽然现在是单身，但有对未来婚恋的期待。', '我想有个女儿，虽现狗。', '“虽现狗”一词来源于华南理工大学一名教师的课堂发言。当时老师说：“某同学计划举行一场盛大的婚礼（虽现狗）”，并解释道：“虽现狗，虽然现在是单身狗，同学们记住了吗？” 这一说法迅速在网络上流传，引发网友热议。'],
  ['人艰不拆', '“人艰不拆”是用来形容人生已经很艰难，希望大家不要互相揭开难堪的真相。它表达了一种体谅和包容的态度。', '当朋友指出她不擅长的事情时，她笑着说：“人艰不拆。”', '出自林宥嘉的歌曲《说谎》中的歌词：“人生已经如此的艰难，有些事情就不要拆穿。” 被广泛应用于网络论坛和调侃场合。'],
  ['十动然拒', '“十动然拒”是“十分感动，然后拒绝了他”的缩写。通常用于形容某人虽然被感动，但由于对方使用了不当的方式或对方本身不适合，所以仍然拒绝了求爱者。常用来嘲讽他人的不当追求方式或自嘲自己被拒绝的经历。', '小李花了大半年时间制作了一份表达心意的视频，女生看后十动然拒，让他很尴尬。', '2012年11月，华中科技大学文华学院一位男生用212天写了16万字的情书向心仪女生表白。女生表示很感动，但还是拒绝了他。这一事件通过微博走红，引发网友的广泛讨论和恶搞。'],
  ['喜闻乐见', '“喜闻乐见”原本是褒义词，指某事物很受大众欢迎，大家乐意看到并且喜欢听到。但在网络中，它常被用作讽刺和调侃，意味着幸灾乐祸。其含义已经与本义相去甚远，常用于表达一种调侃或嘲讽的意思。', '隔壁班的期末成绩全班不及格，真是喜闻乐见的结果啊！', ''],
  ['锦鲤', '“锦鲤”原意是指一种色彩斑斓的观赏鱼，象征富贵、吉祥和好运。在网络文化中，“锦鲤”成为好运的象征，人们通过转发锦鲤图片以期获得好运，把这种行为戏称为“转锦鲤”。这一行为已演变成一种现代的网络迷信和社交行为。', '我这周要大考试了，赶紧转发几个锦鲤，希望能带来好成绩。', ''],
  ['冲鸭', '「冲鸭「是「冲呀「的谐音，用于表示充满朝气和斗志，通常用于可爱卖萌或加油打气。', '今天比赛要加油，大家一起冲鸭！', '起源于网络语“我的马鸭”的衍生语，最早因一组《今天也要加油鸭》里面的“冲鸭”表情包走红，流行于2018年6月。'],
  ['杠精', '“杠精”指的是那些喜欢在讨论中抬杠，故意反驳他人观点的人，他们不注重客观事实，目的只是为了反对而反对。这种人通常利用抬杠作为网络消遣和娱乐方式。', '和他讨论简直太累了，什么话题都要反驳，真是个杠精。', ''],
  ['凉凉', '“凉凉”通常表示完了、死了、惨了，表达绝望或毫无希望的状态，也能指失望或反应冷淡。', '看这次考试成绩，简直就是一首凉凉送给我的心情。', '“凉凉”最初来源于张碧晨和杨宗纬为电视剧《三生三世十里桃花》演唱的片尾曲《凉凉》。在2018年，这个词在网络中流行，特别是在主播玩游戏失败时，观众用“一首凉凉送给主播”来表达。'],
  ['臣妾做不到啊', '“臣妾做不到啊”用来表达对某些要求或任务的无奈或难以完成，通常用夸张和幽默的方式来表达内心的抗拒和无力感。', '当朋友打算放弃晚餐的甜点时，他诧异地说：“饭后不吃甜点？臣妾做不到啊！”', '该梗源自电视剧《甄嬛传》中的一幕，皇帝要求皇后憎恨他，皇后就哭诉着喊出这句台词。这一台词因其夸张和情感冲击力而被网友广泛引用并恶搞。'],
  ['做人要厚道', '“做人要厚道”是一种呼吁大家在生活中要温和待人、与人为善的观念，言行中要留有余地，不要过分、不要做出损害他人利益的行为。', '在游戏《英雄联盟》中，小张总是抢队友人头，惹得其他玩家不满，大家纷纷提醒他：“做人要厚道！”', '该梗出自冯小刚2004年贺岁电影《手机》。电影中，葛优饰演的严守一在与旧情人通话时假装听不见，被同行的费墨识破后，严守一戏谑地回应了一句“费老，做人要厚道”，之后在电影中被反复使用。'],
  ['我想做个好人', '“我想做个好人”是一种表达悔改或想要改善自己行为的愿望，通常用于反派角色在剧情中转变立场或动机时。同时，它也可以用作一种自嘲或玩梗的方式，表示对某事心有余而力不足，或者在调侃自己想要做好人但处境不佳时使用。', '他收起了手里的投机生意，叹了口气说：“唉，我想做个好人。”', '该梗出自2002年香港电影《无间道》，由角色刘建明在尝试脱离黑帮生活、寻求赎罪时的一句台词。'],
  ['棺材板压不住了', '“棺材板压不住了”是一种讽刺性表达，意在说明某种事情荒谬或违背常理到令人无法忍受，以至于“死去的人都被气得活过来”。', '由于一部科幻电影中物理现象不合理，观众纷纷在弹幕中留言：“物理学家的棺材板都压不住了。”', ''],
  ['吃柠檬', '“吃柠檬”是一种网络用语，表示羡慕、嫉妒的心情。由于柠檬的酸味，用“吃柠檬”或“你好酸啊”来形容求而不得、羡慕嫉妒交织的状态。它也可以用于自嘲，表达对美好事物的向往却又无法得到的心情。', '在比赛中o队夺冠，x队粉丝冷嘲热讽时，o队粉丝还击道：“吃柠檬了？”', ''],
  ['班味', '形容上班族身上常见的疲惫气质，表现出一种无法掩饰的疲劳和改变。', '每天加班到深夜，我的班味越来越重了。', ''],
  ['我和我的小伙伴们都惊呆了', '表达一种极度惊讶和无法置信的情绪。', '昨天看到他竟然徒手爬上了十米高的墙，我和我的小伙伴们都惊呆了。', '来源于2011年11月14日，新浪微博网友“苏隐衡”的一条微博。该微博配图为一篇小学作文，其中小学生用夸张的想象力描述了端午节的由来。'],
  ['我的内心几乎是崩溃的', '“我的内心几乎是崩溃的”用于形容一种受到负面冲击后的崩溃心情。这句话用来表达对意外、不满或尴尬情况的无奈和震惊。', '明天就要上学了，我的报告还没有完成，我的内心几乎是崩溃的。', '该梗出自2015年中国漫画家陈安妮在采访中提到的一句话：“当我得知年终奖的金额时，我的内心几乎是崩溃的。”由于表达了很多人在面对意料之外的情况下的心情，该句很快在网上流行开来并被广泛使用。'],
  ['保证打不死你', '“保证打不死你”是一种调侃性的表达，通常用来表示即使对某人感到不满，行为上也不会真的对他造成伤害。这个说法用于让对方放松警惕，实际上可能会导致一定程度的“惩罚”或“教训”。', '老爸：考得怎么样？       儿子：全班倒数。       老爸：赶紧过来，我保证打不死你。', '该梗源于《爸爸去哪儿》节目中吴镇宇的一句话：“来来，爸爸保证不砍死你。”之后被演变为“你过来，我保证不打死你”。'],
  ['然而早就看穿了一切', '“然而早就看穿了一切”用来形容对某些事情已经完全了解或看透，不再感到惊讶或在意。这句话常被用来幽默地表示一种机智、淡定的态度。', '当同事重复他的小把戏时，我心中不禁默念：然而我早就看穿了一切。', '该梗出自BBC与CCTV合作的纪录片《美丽中国》，其中“龙之心”一集中出现的一句台词“然而猴王早已看穿了一切”。这句话在两种中文版本中均有翻译，但大意相似。猴王面带机智的神情加上这句台词引发了网友的共鸣，被广泛传播成为梗。'],
  ['求心理阴影面积', '“求心理阴影面积”是用于形容一个人在经历某种痛苦或打击后，内心受到创伤，并以面积大小来幽默地表达心理受伤程度。', '小明考试没及格，老师在班上批评了他一整节课，求小明的心理阴影面积。', ''],
  ['喜提', '“喜提”是指得到某样东西时高兴的心情，通常带有调侃或讽刺的意味。', '我今天终于喜提驾照，感觉像拿到了全世界！', ''],
  ['也是蛮拼的', '表示“非常努力”或“特别努力”，有时带有讽刺意味，强调尽管努力了但不一定成功。', '今天他为了赶上会议，凌晨三点就起床出发，真的是也是蛮拼的。', '源自爱奇艺剧《白衣校花与大长腿》热帖，通过《爸爸去哪儿2》的曹格之口发扬光大。'],
  ['毫无ps痕迹', '“毫无PS痕迹”用于评论图像处理作品，看似完美无瑕但实际上经过精心修饰，常含讽刺意味。', '这张明星照修得太假了，毫无PS痕迹啊！', ''],
  ['霸气侧漏', '“霸气侧漏”形容一个人的气场或才华过于强烈，以至于显露得过于明显，引起轻微的反感或被调侃。', '他一上台发表演讲，就霸气侧漏，瞬间吸引了全场的目光。', '该词改自“霸气外露”，流行于2010年，由姜文自导自演的电影《让子弹飞》让其火了一把。片中角色黄四郎（周润发扮演）说：“霸气外露！找死！”'],
  ['品如的衣服', '用以调侃或吐槽某人的言谈举止或穿着过于奔放、张扬或有“骚气”感。', '今天他的打扮太亮眼了，简直像是穿着品如的衣服。', '该梗出自中国大陆电视剧《回家的诱惑》的第11集。剧中男主洪世贤在女主林品如和女二艾莉之间游离不定。当艾莉穿着林品如的衣服出现时，洪世贤心生惊奇并半开玩笑地说“你好骚啊”。'],
  ['偷感很重', '形容人在某些情境下感到拘谨、畏缩，显得偷偷摸摸或不自然。', '她在聚会时总是偷感很重，一直躲在角落不敢说话。', ''],
  ['泪失禁患者', '“泪失禁患者”形容那些在情绪激动时容易流泪的人。此类人在争吵时虽然内心愤怒，但外在表现却是不断流泪，显得很脆弱。', '吵架的时候她就是个泪失禁患者，话还没说几句眼泪就下来了。', ''],
  ['硬核', '“硬核”原本用于形容说唱音乐和游戏，指具有力量感或存在一定难度的形式。作为网络流行语，“硬核”被广泛地用来形容事物或行为的厉害、酷炫、彪悍或刚硬特性。', '他真的是个硬核玩家，不仅通关了难度最高的游戏，还能无伤速通。', ''],
  ['我信你个鬼哦你个糟老头子坏得很', '表达对被欺骗或被糊弄的不满和愤怒，但不带恶意。', '朋友说他永远不会迟到，我信你个鬼哦，你个糟老头子坏得很！', '来源于抖音的搞笑段子，一名美团外卖员用广西方言讲述自己的故事：我8岁那年碰到一个算命先生，算命先生说我二十四岁会黄袍加身，餐餐都有大鱼大肉为伴。最后他来了一句总结性的神评论：我信你个鬼哦，你个糟老头子坏的很，算得真TM准。。'],
  ['你是魔鬼吗', '用于表达对某人行为或话语的惊讶或调侃，带有搞笑的意味。', '当朋友出其不意地说了一句冷笑话，我忍不住大笑：“你是魔鬼吗？”', '综艺节目《爸爸去哪儿》第三季，林永健父子争吵片段，当时林大骏突然对爸爸说了一句“你是魔鬼吗？”然后林永健回答“我是你爹”，随后网友们都开始跟着争相模仿，因此走红网络。'],
  ['脱粉', '“脱粉”是指不再关注或支持某个明星，从其粉丝群体中退出。', '因为对新作品不满意，小兰决定脱粉。', ''],
  ['我酸了', '“我酸了”表示一种羡慕或嫉妒的情感，通常用在看到别人拥有甜美爱情或幸福生活的时候。酸在这种语境中代表了嫉妒，与柠檬的意象相似。', '看着他们两个在校园里牵手逛，我酸了，每天都努力吃狗粮。', ''],
  ['一个能打的都没有', '「一个能打的都没有「是一种夸张的说法，通常用于描述一个场合或群体中没有一个出色或有能力的人。它可以用于嘲讽或表达对某事物的不满或失望。', '这吧帖子太少了！一个能打的都没有！', '该梗出自电影《叶问》，由樊少皇饰演的角色金山找在电影中说出：“他奶奶的，佛山一个能打的都没有！”这一句台词。随后，该台词在2009年被用作网页游戏的宣传广告，并通过挂马方式在一些网站传播，引发用户的不满和恶搞。'],
  ['出来混迟早要还的', '「出来混迟早要还的「是一种警告或预言，意指一个人即使现在做了违反法律或道德的事情，但迟早会面临报复或者惩罚。这句话强调因果报应、善恶终有报的道理。', '在一场激烈的打斗后，那个平时嚣张跋扈的混混被抓住了，围观看热闹的人都窃窃私语：“出来混迟早要还的。”', ''],
  ['不抛弃不放弃', '“不抛弃不放弃”是一种鼓励人们坚持信念、理想和原则的精神。这句话强调在任何艰难情况下，都要坚持到底，不放弃希望和努力，体现了对人性平等和情感的尊重。', '在面临人生低谷时，他常常用“不抛弃不放弃”来激励自己，希望能够重新振作精神。', '这句话出自电视剧《士兵突击》，是王宝强饰演的角色许三多的经典台词之一。'],
  ['黎叔很生气后果很严重', '「黎叔很生气，后果很严重「是用来表达警告或最后通牒的梗。通常意味着如果再不改正行为或做出回应，后果将会非常不利。', '昨晚忘记遛狗，我的狗现在很生气，后果很严重——地毯全毁了。', '该梗出自电影《天下无贼》，是由葛优饰演的角色黎叔在影片中的经典台词。在电影中，黎叔因误以为同伙王博欺骗自己而愤怒地说出这句台词。'],
  ['不能同意更多', '「不能同意更多「是由英文「can’t agree more「直译而来的流行语，表示极度同意某个观点。它的真正含义是「同意到了极点，无法增加更多同意「，而不是字面上误解的「不能同意「。', '这个电影真的拍得很好，我不能同意更多。', ''],
  ['元芳你怎么看', '“元芳你怎么看”用于转移话题、与人互动或掩盖自己理解能力低。当下多为玩梗使用。', '昨天的比赛你看了吗？元芳，你怎么看？', '该梗源于电视剧《神探狄仁杰》。李元芳是狄仁杰手下的将军兼护卫，剧中狄仁杰常让元芳发表见解。'],
  ['这个锅我不背', '“这个锅我不背”是一句用来拒绝承担不应由自己承担的责任的流行语。它源于“背黑锅”的简称“背锅”，指代替他人承担失败或错误的责任。', '在工作项目出了问题后，小李毫不犹豫地说：“这个锅我不背，是数据的问题，不是我的失误。”', ''],
  ['信息量很大', '「信息量很大「是用来吐槽某句话或场景所包含的丰富信息和隐含内涵。这句话常提示需要听者或观众进行大量脑补和遐想。', '听完他的发言，我只有一个想法：信息量太大，需要慢慢消化。', ''],
  ['我也是醉了', '「我也是醉了「用于表达对某人或某事感到无奈、无语或无法理解，通常伴随着一种无力吐槽的感觉。也可以用来自嘲自己的遭遇或行为。', '打了一下午匹配的全是猪队友，我也是醉了，也是不多说。', ''],
  ['友谊的小船说翻就翻', '“友谊的小船说翻就翻”用来形容朋友之间的关系因为一点小事就变得恶劣或终止，用以吐槽友谊的脆弱性。它传达了友谊不稳定的一面，但同时也影射了真正的友谊应该能够经受住考验。', '在工作中意见不合的小事后，小王和小李再也没说过话，真是友谊的小船说翻就翻。', '该梗出自“友谊”的英文“friendship”，直译就是朋友船。因为喃东尼创作的漫画《企鹅北游记》，在2016年4月开始流行，并成为当年的十大流行语之一。'],
  ['土豪我们做朋友好不好', '「土豪我们做朋友好不好「是中文网络用语，用来幽默地表达普通人对有钱人的羡慕和调侃，以及自嘲式的表达对奢华生活的一种向往。这句话通常在看到别人花费巨资购置奢侈品或进行高消费行为时，用作开玩笑的调侃。', '在朋友圈看到有人买了一辆新跑车，我忍不住评论说：“土豪，我们做朋友好不好？”', '该语句来源于一个网络笑话，讲述了一名富有却不快乐的青年向禅师请教生活之道，而禅师提出了一句调侃的话：「不，土豪。我们，可以做朋友吗？「 该句于2013年因微博上发起的“与土豪做朋友”活动而走红。'],
  ['慌得一比', '「慌得一比「是一种调侃语，其含义为恐惧、不安的意思。', '在公司年会上，我居然被安排上台演讲，瞬间慌得一比。', ''],
  ['乙女游戏', '乙女游戏是专为女性设计的电脑游戏类型，通常以浪漫或吸引人的男性角色为卖点。与Galgame相对，乙女游戏更注重女性玩家的体验。虽然多数与恋爱相关，但也包含非恋爱和BL（男同性恋）题材。', '小丽特别喜欢玩乙女游戏，她说那些故事让她很有代入感。', ''],
  ['童年阴影', '「童年阴影「是指小时候因为观看某些恐怖的动画、影视作品或经历某些恐怖事件而留下的心理阴影。这些作品或事件之所以令人产生阴影，是因为它们包含了令人不安、恐怖或不适宜儿童观看的内容，而通常是在孩子心智尚未成熟时观看的，因而影响较深。', '我小时候看《魔方大厦》，那诡异的音乐和画风真的给我留下了很深的童年阴影。', ''],
  ['心灵毒鸡汤', '心灵毒鸡汤是一种通过黑色幽默和嘲讽来戏谑现实的梗。起源于心灵鸡汤，心灵毒鸡汤以消极和负面的表达方式评论生活的现实，折射出生活中的无奈和讽刺，但同时也在某种程度上潜藏着隐藏的正能量。', '「转角一般不会遇到爱，只会遇到乞丐。「 — 这句毒鸡汤语句通过对生活预期的讽刺，来揭示现实的无奈。', ''],
  ['心灵鸡汤', '“心灵鸡汤”是一种旨在安慰和激励他人的文体，通常通过故事传递道理，具有激励性和正能量，但有时被批评为缺乏实际意义。', '生活不是等待暴风雨过去，而是要学会在雨中跳舞。', '词源于励志大师杰克·坎菲尔德，他的作品《心灵鸡汤》名字灵感来自奶奶为他治病熬制的鸡汤。'],
  ['社会摇', '社会摇是一种以重复式身体摆动为基础的舞蹈表演形式，伴随劲爆电子音乐，风靡网络。', '在商场外的广场上，有一群年轻人正在热情地跳社会摇。', ''],
  ['社会人', '“社会人”在互联网上通常指拍摄土味视频的人。此外，它也可以指各种群体，包括黑道人士、社会青年、与学生相对的职场人士。在不同的语境中，社会人可以表现出对社会经验、利益关系的理解和驾驭。', '小猪佩奇身上纹，掌声送给社会人。', ''],
  ['罗密欧与朱丽叶效应', '“罗密欧与朱丽叶效应”指的是在恋爱关系中，外界的干扰或反对会使两人的感情更加强化，使关系更加牢固。这一现象也适用于其他领域，即越是被禁止的事物，人们反而越感兴趣和渴望。', '明明知道他父母坚决反对，丽莎和男友反而越来越相爱，真是典型的罗密欧与朱丽叶效应。', '该效应以莎士比亚名作《罗密欧与朱丽叶》命名。在该剧中，罗密欧与朱丽叶的爱情因家族的反对而更加坚定，成为这种现象的典型例子。'],
  ['质疑伍佰理解伍佰成为一千', '这个梗是网友对凤凰传奇演唱会的调侃。由于伍佰的歌曲传唱度极高，演唱会上几乎全由粉丝合唱，伍佰老师几乎不用自己唱，被戏称为“990元是合唱费”。而凤凰传奇最近的演唱会也出现了类似场景，玲花一开口，粉丝们就开始大合唱，导致两位歌手在台上只能伴舞，享受着粉丝合唱的“快乐”。因此，网友戏谑道：从质疑伍佰到理解伍佰，再加上凤凰传奇两人合体，因此调侃为“成为一千”。', '每次去伍佰的演唱会，我都觉得自己是来付990元合唱费的，完全理解“质疑伍佰，理解伍佰，成为一千”的调侃。', ''],
  ['精神续作', '“精神续作”指的是一个新作品沿用了一部知名作品的部分核心内容或玩法，但不涉及其知识产权。新作品通常被认为是对原作品精神或风格的延续，尤其是在原作品可能不再推出续作的情况下。', '在原作不再开发续作的情况下，玩家们将这款新推出的多人冒险游戏视为经典游戏《探险之旅》的精神续作。', ''],
  ['总有刁民想害朕', '“总有刁民想害朕”用来形容一种疑神疑鬼的状态，指那些没有皇上命却有皇上疑心病的人，总以为全世界都与他为敌。它常用于搞笑和吐槽的情境中。', '周末出去逛街，看到周围的人都用奇怪的眼神看着我，我不由得想，总有刁民想害朕啊。', ''],
  ['葛优躺', '形容一种懒散、颓废的状态。', '最近实在太累了，只想回家葛优躺一整天。', '1993年情景喜剧《我爱我家》，剧中由葛优饰演的角色季春生在沙发上的姿势。'],
  ['北京瘫', '“北京瘫”是一种形容坐姿的网络用语。最初是指北京人坐姿随意、不拘小节的状态，身体与椅背呈120度角，给人一种放松却略显懒散的印象。现在，这一词语已经引申为一种放松和毫无拘束的表现方式。', '看那小子坐在那里，一副“北京瘫”的架势，懒得动一下。', ''],
  ['碧瑶坐', '“碧瑶坐”指的是电视剧《青云志》中由赵丽颖饰演的角色碧瑶的独特坐姿。由于这些姿势别具一格，并在剧中频繁出现，引发了网友和粉丝的模仿与热议。', '最近大家都在模仿“碧瑶坐”，真是太有趣了。', '来源于2016年电视剧《青云志》，由赵丽颖饰演的碧瑶因其独特的坐姿而走红网络。'],
  ['亚洲蹲', '亚洲蹲指的是亚洲人常用的一种蹲姿，特点是双脚完全着地，臀部靠近脚踝，双膝分开。这种姿势与如厕习惯有关，被认为对健康有益。', '在野外露营时，他轻松地摆出一个标准的“亚洲蹲”。', ''],
  ['吊桥效应', '吊桥效应是一种心理学现象，指在危险或刺激的情境下，人们可能错误地将生理反应（如心跳加速）归因于对身边人的吸引力，从而以为自己对那个人产生了感情。', '小李在过山车上认识了小美，当晚就觉得自己可能喜欢上了她，这可能就是吊桥效应。', '源自心理学家阿瑟·阿伦（Arthur Aron）的实验。他让男生们在不同环境下接受美女的问卷调查，并根据一张图片编故事，包括安静的公园、稳固的石桥和危险的吊桥。结果显示，吊桥上的男生更多地给美女打电话，并编出情感色彩更浓的故事。阿伦解释说，男生误将因危险环境导致的生理反应（心跳加速等）归因于美女的吸引力，因而对她产生了'],
  ['一首凉凉送给你', '“一首凉凉送给你”表示事情失败或糟糕的调侃和自嘲。常用于表示某人或某事“凉了”，即完蛋或无望。', '明天就要考试，但我什么都没复习，一首凉凉送给自己。', '起源于直播间中主播在游戏中失败时，观众在弹幕中用来调侃的词汇，具体来源于张碧晨和杨宗纬演唱的《三生三世十里桃花》片尾曲《凉凉》。'],
  ['脸盲症', '脸盲症原指一种真实存在的医学状况，即面部识别能力缺乏症，也叫prosopagnosia或face blindness。患者视觉正常但无法分辨或记住他人的脸。在流行文化中，这个术语被用来形容那些由于对虚拟角色面部辨识过于依赖，导致在现实生活中分辨不了不同面孔的人。', '他因为长期沉迷于日本动漫，逐渐发展成为“脸盲症”患者，居然连办公室同事都认不出来了。', ''],
  ['壁咚', '壁咚是一种以手拍击墙壁发出“咚”声的动作，通过将对方逼到墙边进行告白或展示亲密情感。这种动作在少女漫画和动画中常见，也是秀恩爱的一种方式。', '在看那部少女漫画时，男主突然对女主来了个壁咚，情节变得非常紧张。', ''],
  ['腰斩', '腰斩指的是计划中途被迫停播或缩减，通常因人气不足或其他因素导致的作品提前结束。', '这个新番人气太低了，很可能要被腰斩。', ''],
  ['泡面番', '“泡面番”是指单集长度很短的动画，通常在2-6分钟，类似于泡面泡好的时间。', '这个泡面番搞笑又轻松，看完正好能吃上泡面。', ''],
  ['伸手党', '“伸手党”指在网络上，特别是论坛和贴吧中，那些只会索取资源而不愿自行查找或付出努力的人。', '这个帖子刚发出来就被伸手党们刷屏要资源了。', ''],
  ['标题党', '「标题党「是指在网络媒体上使用吸引眼球的夸张标题，但内容与标题实际不符或联系不大的现象。其目的通常是为了提高点击率或进行恶作剧，往往令人失望。', '新闻网站上又出现了一个标题党作品，“震惊！男人看了沉默，女人看了流泪……”但实际上内容非常平淡。', ''],
  ['百合党', '百合党是指热衷于百合题材、百合CP（女性之间的浪漫关系）的人群，类似于对BL题材感兴趣的腐女/腐男。他们对自身性取向没有特定要求。', '小美是个不折不扣的百合党，她整天讨论新的百合作品。', ''],
  ['我想静静', '“我想静静”表达了人在面对不快情绪时，想要寻求内心平静或发泄无奈的需求。它也包含了一种幽默解读，将“静静”视为一个人的名字。', '今天被老板批评了半天，我想静静，别问我静静是谁。', ''],
  ['我好菜啊', '「我好菜啊「用于表达自己不如别人时的羞愧，或用作对他人的赞美或讽刺。这里的“菜”指的是弱、能力不足。', '在游戏中总是输，我真想哭：“我好菜啊！”', ''],
  ['我今天吃药的时候看到一个新闻', '这是一种情侣间的情感测试，用来测试对方对自己是否关心。重点在于测试对象的第一反应是关注新闻还是“吃药”的原因。', '女：“我今天吃药的时候看到一个新闻。”    男：“啥新闻？”    女：“我都生病吃药了你却只关心新闻，你不爱我！”', ''],
  ['我给你一次重新组织语言的机会', '“我给你一次重新组织语言的机会”是一种吐槽和调侃的用语，通常用于对某人说出的话不满意时的回应。该短语带有幽默感，可以让对方重述或修正其话语，而不至于引发严重的冲突。与“住口/闭嘴”相似，但表达更委婉，通常用于熟人之间的玩笑。', '群友在群里大肆吐槽群主在游戏中的失误：“你们知道吗，这个群主是个超级菜鸟！”    群主幽默回应：“我给你一次重新组织语言的机会，考虑清楚哦。”', ''],
  ['我编不下去了', '“我编不下去了”用于承认之前的描述或故事是虚构的，通常是为了搞笑或制造惊讶。该短语用于在一段虚构叙事的结尾，给听众或读者意想不到的转折，提醒他们这不是事实。', '在论坛里，有人分享了一个离奇的幽灵故事，最后一句来了个“我编不下去了”，原来全部都是想象。', '该梗起源于有人观看法语战争电影《光荣岁月(Indigènes)》时发现字幕是假的的经历。据说，有位观众在看影片时，字幕突然消失，并出现提示“前边都是我编的”，表示之前的翻译是编出来的。此事被分享至网络后，引发了模仿和广泛使用。'],
  ['图样图森破', '“图样图森破”是英文“too young, too simple”的音译，用于讽刺某人的想法过于简单和幼稚，即“很傻很天真”。此词调侃那些因经验不足而误信某种舆论或做出愚蠢行为的人。', '他以为靠运气就能赚钱，真是图样图森破，还需要多读书提高自己的姿势水平。', ''],
  ['坟头草丈五', '“坟头草丈五”是网络流行语，指某人已经去世多年，坟头的草都长得很高，暗示这个人无人悼念、关系不佳。常用于表达对某人行为的不满或讽刺。', '你又在这里装模作样，小心最后像那谁，坟头草丈五。', '来源于网友自编打油诗：“吾有故友吊似汝，而今坟头草丈五”。'],
  ['神马都是浮云', '“神马都是浮云”是一句网络流行语，源于“什么都是浮云”的谐音。它表达的是一种无所谓的态度，表示任何事情都不值得在意，带有一种抱怨或感叹的意味。同时，也可以用来自我安慰，表示任何烦恼或曾经在意的事情都犹如过眼云烟，转瞬即逝。', '每天为了工作上的小事烦恼不已，转念一想，神马都是浮云，不必太纠结。', '该梗源于“天涯社区”一个关于“小月月”事件的帖子。小月月是一位被描述为性格及行为极其独特的女性，令作者与读者都经历了异乎寻常的情感冲击。经历了这个事件后，帖子作者觉得所谓的“极品女”都不算什么，因此创造并传播了这个表达。'],
  ['人在家中坐锅从天上来', '“人在家中坐锅从天上来”是一个网络流行语，用于形容某人无缘无故成为了替罪羊或遭到指责，和“躺枪”有相似的意思。它通常用于描述一件自己未参与的事情却被推卸责任或受到负面影响的情况。', '在团队项目中，小明本来只是参与了一部分，结果出了问题却被全组的人指责：“小明这真是人在家中坐，锅从天上来。”', ''],
  ['怪我咯', '“怪我咯”是一个网络流行语，通常用于反问或讽刺，表示某个情况不应该怪罪到自己头上。它可以用于轻松地化解尴尬或结束讨论。', '我变成这样怎么想都是世界的错！      世界：「怪我咯？「', ''],
  ['我是一个没有感情的杀手', '“我是一个没有感情的杀手”用于自嘲，表达人在某些情况下不得不冷漠的态度，类似于“冷漠脸”。', '今天加班加到凌晨，我已经是一个没有感情的杀手了。', '该词源于一张走红的表情包，表情包的主人公是某直播网站的网红长鼻毛大叔，走红于2017年。2018年，明星林更新通过微博进一步推动该梗的流行。'],
  ['请允许我做一个悲伤的表情', '「请允许我做一个悲伤的表情「（简称“请允悲”）是一个网络用语，实际上用来表示一种嬉笑、嘲讽或自黑的心态。当一个人听到某个故事或经历时，虽然心里觉得好笑或荒谬，但为了避免直接笑出来，会用这句话来掩饰真实的感受并略带幽默地表示同情或其他复杂的情感。', '当朋友分享了一个他考试时闹出的笑话，我强忍笑意，用手捂住嘴说：“请允许我做一个悲伤的表情。”', ''],
  ['口吐芬芳', '口吐芬芳是一种用来形容说脏话或爆粗口的委婉说法。这个短语本身是中性的，不指代具体的脏字或粗话。', '在激烈的游戏对战中，某位玩家因为失误而开始口吐芬芳，引起其他玩家不满。', ''],
  ['怎么办我也很绝望啊', '“怎么办我也很绝望啊”是一种表达绝望、无奈和自嘲情绪的流行语。人们在面对无能为力或无可奈何的情况时，用它来调侃和吐槽自己，同时也带有一种幽默感。', '面对工作上的无力回天，她用手捂住脸无奈地说：“怎么办我也很绝望啊。”', ''],
  ['这tm是人干的事吗', '「这tm是人干的事吗「是一句用来表达对某种不可接受或者过于荒谬的事件的强烈不满或吐槽。通常用于描述那些让人感到无奈或不满的情况。', '看完这部剧，最后的反转和主角的死亡让我大呼：“这tm是人干的事吗？”', ''],
  ['走错片场了', '“走错片场了”用来形容某人在特定情境下显得不合群或不属于这个场合。可以指误入不合适的环境、进错评论区、发错信息等，也可能表示两个作品的人物形象相似或遭遇不符预期的局面。', '在严肃的学术会议上，她突然开始讲搞笑段子，让人觉得她好像“走错片场了”。', ''],
  ['人与人之间最基本的信任在哪里', '表达对社会中缺乏信任现象的无奈和愤慨，通常用于调侃不符实际的情况。', '网购买家收到货发现与描述不符，留言：“人与人之间最基本的信任在哪里？(╯°口°)╯(┴—┴)”', '出自2014年北京新闻的一则报道。北海一名摩的司机假装载客，成功将劫匪送至派出所抓获。事后，劫匪在录供时感叹道：“心好累，人和人之间最起码的信任都没有了。” 这句话本是劫匪对社会的无奈控诉，但由于出自犯罪分子之口，反而显得讽刺，引发了网友的广泛调侃。'],
  ['贴脸开大', '“贴脸开大”原本是游戏术语，指在非常近的距离使用大招。网络中常用于比喻在社交或工作场合表现得过于热情、亲近甚至冒失的行为，常让他人感到尴尬或不适。', '他昨天在会议上直接贴脸开大，把自己的所有想法都抛给了老板，场面一度非常尴尬。', ''],
  ['当然是选择原谅她', '“当然是选择原谅她”用于调侃被女朋友或老婆出轨的人，看似劝解实则是一种站着说话不腰疼的吐槽。', '面对朋友的感情问题，他无奈地笑着说：“那还能怎么办，当然是选择原谅她啊。”', ''],
  ['蓝瘦香菇', '「蓝瘦香菇「是“难受，想哭”的谐音，是用广西普通话说出的一种表达伤心、失望情绪的句子。', '今天加班，结果所有的努力都泡汤了，我真的蓝瘦香菇。', '该梗出自2016年10月广西南宁一名失恋男子录制的视频。他在视频中用地方口音表达自己的失落，因其口音将「难受，想哭「说成了「蓝瘦，香菇「而迅速走红。'],
  ['你妈喊你回家吃饭', '「你妈喊你回家吃饭「用来吐槽和调侃某个人，通常用于提醒或打断对方正在进行的无意义或荒谬的行为。这个短语带有一种幽默的意味。', '看到他又在论坛上争论不休，我只好提醒他：“你妈喊你回家吃饭！”', '该梗出自2009年7月16日，最初是百度WOW贴吧中一个题为“贾君鹏你妈妈喊你回家吃饭”的帖子。帖子在短时间内引起了极大的关注和讨论。'],
  ['你们城里人真会玩', '「你们城里人真会玩「是一种用来表达对某种无法理解、复杂或新奇行为的惊讶或吐槽。通常使用在看到一些夸张、有创意或难以理解的事物或行为时，用来表示感叹和不解。', '在观看某些设定复杂的动漫比赛时，有观众评论：「这规则也太复杂了，你们城里人真会玩。「', ''],
  ['你行你上啊', '「你行你上啊「是一句用于反驳批评者的网络流行语。通常在议论中，当一方对他人表现提出不满或指责时，另一方用这句话来表示如果批评者认为自己更有能力，那就应该自己去尝试或实践。这句话的本质是一种嘲讽或者转移话题的方式，是典型的杠精言论。', '在网络游戏论坛中，有玩家吐槽某职业太弱，有人立马回怼：“你行你上啊，看你能玩得多好。”', ''],
  ['你知道的太多了', '“你知道的太多了”用于调侃知道太多内幕或秘密的话，可能会导致危险。在网络上，它被用来调侃对敏感问题、对迟来的消息反应，以及回应他人对自己的调侃。', '“你居然知道我小时候的糗事，你知道的太多了！”', ''],
  ['喝最烈的酒', '“喝最烈的酒”是互联网流行的句式，用来表达一种刺激、豪放和不羁的生活方式。它通常用于强调一种追求极致的态度或生活方式。', '喝最烈的酒，恋最美的人，这就是我追求的人生。', '该句子源自古龙的小说《萧十一郎》，原句描绘了江湖女子风四娘追求刺激的生活。在网络上，这句话被改编并加上了对仗的部分而广泛流行。'],
  ['不要迷恋哥哥只是个传说', '“不要迷恋哥，哥只是个传说”是一句网络流行语，表达了一种傲娇和洒脱的态度。它传递了一种表面上谦虚、低调但实际上又希望受到崇拜和关注的自我定位，像是一种反向的自抬身价。', '小明在朋友圈发了一个特别拽的自拍，并附加文字：“不要迷恋哥，哥只是个传说。”', '源于2009年猫扑大杂烩上的一篇名为《不要迷恋哥，哥只是个传说……》的帖子。发帖者用第一人称的形式夸耀自己，并配上几张非主流风格的图片。这篇帖子迅速引发了网友的围观和恶搞，原帖中的非主流图片被P上这句话，成为流行的表情包，广泛传播。'],
  ['厉害了我的哥', '表示对他人表现出色的赞叹或表扬，有时也用于反讽。', '看到他在比赛中拿了冠军，大家都纷纷说：“厉害了我的哥！”', '源自一名学生在军训时玩游戏被教官发现，教官以极高的水平完成游戏，引起队友的惊叹。'],
  ['建国后不许成精', '“建国后不许成精”是一句调侃用语，最初用于形容动物过于聪明或具有类似人类的行为，仿佛动物已经“成精”。后来，这一说法也扩展到其他事物或现象。', '看到这只狗居然会自己开门，真是活久见，不愧是建国后偷偷成精了。', '这一梗源于2014年网络上流传的一条关于广电总局的“奇葩禁令”。国产恐怖片的审查通常要求剧情最终以精神病幻觉或装神弄鬼收尾，若不符合此要求便无法通过审核。然而，对于传统文学作品如《聊斋》中的鬼怪情节，只要尺度控制得当，依然可以通过审核。网友因此杜撰出“建国后不许成精”这一说法，用以讽刺广电总局的双重标准。虽然此“禁令”'],
  ['红红火火恍恍惚惚', '“红红火火恍恍惚惚”表示在遇到大事后精神恍惚，不知所措，或者懒惰自嘲。“h”打字容易，也用于表示大笑或“呵呵”。', '看完那部电影之后，我整个人都是红红火火恍恍惚惚的状态。', '源于智能ABC输入法的设定，打出首字母“hhhhhh”会得到“红红火火恍恍惚惚”。'],
  ['不服来辩', '“不服来辩”是一个中文网络常见句式，表示“如果不服气就来辩论”，表明说话者希望通过辩论展示自身优势，通常用于引战帖或钓鱼帖中，追求通过争论占据理性的制高点。', '“关于全球变暖是否真实存在，这份报告给出了一些新的证据，不服来辩。”', ''],
  ['是一种什么样的体验', '「是一种什么样的体验「是一个在知乎上流行的提问句式，通常用于表达对某种经历的好奇心或探寻他人经验的渴望。这类问题通常引发许多有趣或启发性的回答，尽管答案不一定都是真实的。网友们通过使用这种格式来征集各种生活体验的描述，无论这些体验是正面的、负面的，还是滑稽的。', '在知乎上看到有人问，拥有超高智商是一种什么样的体验，底下的回答五花八门，还有人自称智商180。', '该梗来源于知乎，许多用户使用这一句式来提问以获取他人的经验分享。虽无法明确指出谁是最早使用者，但其已成为知乎上的常见问句。'],
  ['这不科学', '“这不科学”是网络流行语，最初用于形容违反唯物主义常识的现象，表达对某事的难以置信。虽然不具有严肃性，但多用于轻松的吐槽场合。', '某个游戏角色秒杀了所有对手，网友纷纷评论：“这不科学，也太强了吧！”', '“这不科学”起源不详，但最广泛的说法是源自江苏卫视科学真人秀节目《最强大脑》。在节目中，科学判官魏坤琳常常强调“科学是我评判的唯一标准”，这句话随着节目的流行演变出了各种形式，“这不科学”便是其中之一。'],
  ['在xx的边缘试探', '“在xx的边缘试探”是一句用于吐槽或调侃各种可能带来不良后果的冒险行为或挑衅行为的流行语。起初用于严肃批判位于法律灰色地带的不道德行为，现多用于形容看似作死或将招致麻烦的举动。尽管这些行为不违法，后果却可能不佳。', '他在老板面前吐槽公司待遇，真是在被炒鱿鱼的边缘试探啊。', '该梗来源于一个表情包，其中一只白鹭在海边伸腿试探海浪，配置文字“在作死的边缘试探”。这个形象生动地表现了“冒险试探”的意味，引起网友共鸣，并衍生出更多以“在xx的边缘试探”为模板的表情包和用法。'],
  ['送命题', '指让人难以选择或回答的问题，回答不当可能引发麻烦或尴尬。', '女朋友问：“你知道你错哪了吗？”这简直是道送命题。', ''],
  ['这是一道送分题', '“这是一道送分题”用来形容一些非常简单明了的问题。其背后含义是，这个问题答案显而易见，任何人都可以轻松回答，含有嘲讽和调侃的意味。', '在一个科技论坛中，有人问到了如何打开电脑电源，下面的回复调侃道：“这是一道送分题啊同学们！”', '这句话来源于教学场景中，老师在解释一些简单问题时常用的句子。因某位学生将老师生动的演示拍成视频上传到网络后，借此而走红。'],
  ['有钱就是任性', '指富有的人在处理事情时展现出一种随心所欲、不受限制的态度，通常用来调侃炫富行为。', '马云谈及做中国首富的烦恼时，网友调侃道：“马云，有钱，就是这么任性！”', ''],
  ['你们感受一下', '“你们感受一下”用于邀请他人对自己的观点、照片等发表看法，通常带有一种希望被认同的语气。', '《程序员装逼速成手册：你们感受一下》', ''],
  ['有件事说出来你可能不信', '“有件事说出来你可能不信”是一句网络用语，经常用于引出一些看似荒诞或不可思议的解释，以达到幽默或戏谑的效果。', '老师，有件事说出来你可能不信，我的作业被风吹走了。', ''],
  ['Skr', '该梗有两个含义：1. 描述轮胎空转的声音；2. 网综《中国新说唱》中由吴亦凡带火的口头禅，谐音“是个”。', '这车的轮胎一打滑就发出“skr skr”的声音。', '该词最初来源于轮胎打转的拟声词“skrt”的简化，由吴亦凡在《中国新说唱》中推广，后成为网络用语。'],
  ['一脸懵逼', '“一脸懵逼”是指人们在面对无法理解或令人震惊的事情时，表现出的目瞪口呆、茫然不知所措的表情。', '我本来以为会议是下午开，结果上午突然通知我要去，一脸懵逼地赶过去。', ''],
  ['虐妻一时爽追妻火葬场', '“虐妻一时爽，追妻火葬场”这个梗指的是在爱情故事中，男主角一开始对女主角不够珍惜或者态度冷淡，事后意识到自己的错误并感到后悔，于是开始努力想要挽回对方。然而，这种反差常常伴随着艰难的追妻过程，所以称为“火葬场”。', '最近看的小说又是虐妻一时爽，追妻火葬场的套路，男主为了追女主真是付出不少。', ''],
  ['圣人婊', '“圣人婊”是一个网络用词，用来形容那些以道德和善良的名义来绑架和限制他人的人。他们通常通过展示自己道德上的高尚来要求他人牺牲，实质上可能通过这种方式对他人造成伤害。', '小张总是用“朋友之间就要互相帮助”来推卸个人责任，简直就是个圣人婊。', '“圣人婊”出自新浪微博的一篇文章《有一种人叫圣人婊》，由作者白小帆创作。'],
  ['路人转粉', '“路人转粉”是指一个人对某明星、品牌或事件原本没有特别关注，但因某事情而成为其粉丝。这个词可以用在各种场合，不仅限于对明星的喜爱，也可能是对某产品或事件的兴趣增加。', '我之前对王一博没什么特别感觉，但看了《陈情令》后，我彻底路人转粉了，他演的真不错。', ''],
  ['种田文', '“种田文”是一种小说类型，始于游戏中，原指在策略游戏中通过发展基础设施和资源积累来增强实力的玩法。小说中的“种田文”最初描写主角通过经济、科技等方面的积累逐渐壮大实力，后期则可能涉及更大的权力争夺。后来，“种田文”也用于指家庭日常生活的细致描写，强调人物关系和心理描写。', '在这部种田文里，主角利用自己掌握的现代农业技术，成功在异世建立起一片富饶的庄园，吸引了无数追随者。', ''],
  ['十点差三分', '“十点差三分”是一个表白梗，有两种解读。第一，9.57的数字和爱你的谐音对应（9+5+7=21）。第二，21.57的数字和爱你无期的谐音对应，表达对某人的爱意或思念。', '每天到了十点差三分，我就忍不住想起你。', ''],
  ['he tui', '「he tui「 是一个象声词，用来模拟吐痰时的声音，通常表示生气、故意装作不爽或鄙视的情绪。尽管来源于吐痰声，但实际上并不带有攻击性，有时被用作一种可爱的语气词，类似于“哼”。', '看到朋友偷偷吃掉了蛋糕，他气得对着空气来了一句“he tui”。', ''],
  ['支棱起来', '“支棱起来”是一句来自东北方言的流行语，具有多重意义。它可以指头发竖起来，暗示不顺滑；也可以用来形容一个人处于低谷但重燃希望并取得成果的状态；在对峙场景中，表示挑衅或找麻烦。', '遇到困难时不要气馁，你得支棱起来，勇敢面对挑战。', ''],
  ['你在大声什么啦', '“你在大声什么啦”是一个用于形容自知理亏但态度嚣张、试图掩盖心虚的幽默表达。', '在网络争论中明知道理亏的一方还不停地狡辩，旁观者就会调侃：“你在大声什么啦！”', '该梗出自台湾富堡车业老板陈平伟在面对记者和顾客诘问时所说的一句话。'],
  ['你咋不上天呢', '「你咋不上天呢「是一个具有多重含义的网络流行语，主要用于表达对某人过分行为的愤怒和鄙视、对某些不可能行为的佩服和惊奇，或极度不赞同时的嘲讽。', '当有人炫耀时，你可以说：「你装啥，你咋不上天呢！「', ''],
  ['你心里没点b数吗', '表示对方不明事理，揣着明白装糊涂，有智障或傻的意思。', '他明知道这样做会出问题，却还是继续，我真想问他一句：你心里没点b数吗？', ''],
  ['韦一敏', '「韦一敏「是一个因误解而产生的搞笑梗，用于形容在交流中产生的误会，特别是通过文字交流时，由于缺乏标点或符号导致的误解。它具有幽默讽刺的意味，常用于调侃类似的情况。', 'A：我真的很讨厌他 B：你不是一个人 A：我只是发表我的想法，我就不是人了？', '该梗源于抖音的一个热门评论区。一位网友名叫“敏”，在博主的评论区询问一部动漫的名称。博主回复“你的名字”，原是指动漫《你的名字。》。但该网友把它理解成是博主在询问他的名字，并回答道：“韦一敏”。由于博主缺少书名号，导致了这场误会。'],
  ['轻舟已过万重山', '“轻舟已过万重山”表示在人生旅途中，通过努力和坚持，克服了重重困难，达到新境界。', '在经历了无数挫折后，他终于成功，就像“轻舟已过万重山”。', '出自唐代李白的《早发白帝城》，随着国漫电影《长安三万里》的爆火，放在影片结尾的这句诗词再次走红。'],
  ['世界破破烂烂总有人缝缝补补', '「世界破破烂烂，总有人缝缝补补「表达的是尽管世界有诸多不完美和问题，总有一些人在努力解决这些问题，使世界变得更好。这种说法强调了正能量和无私奉献的精神，类似于那些悄悄付出自己力量来维持和改善生活的人们。', '在地震发生后的救援场景中，人们自发组织起来互相帮助，真是「世界破破烂烂，总有人缝缝补补「的真实写照。', '这句话最早出现在游戏《CS:GO》中，当队伍在比赛中处于不利局面时，一名队友却通过自己的努力帮助团队逆转时常常用这句话表达感谢和赞赏。随着时间的推移，这句话传播开来，尤其在社交媒体上，常出现在正能量或见义勇为相关的视频和帖子后。'],
  ['冷脸洗内裤', '“冷脸洗内裤”这个梗形容一种在生气或感到不满时仍继续执行日常家务或工作的行为，带有一种讽刺和嘲讽的意味。它反映了人们在不愉快的情绪下依然无法逃避生活琐事的无奈。', '她和男友大吵一架后，回到家还是冷脸洗内裤，这种情绪和行为真是让人又好气又好笑。', '此梗出自网络小说，用于形容小说中女主角在生气时依然冷漠地进行家务，如洗内裤的情景。'],
  ['历史总是惊人地相似', '“历史总是惊人地相似”是对相似历史事件或现象的一种观察和总结。这句话表达了当我们在不同时间或地点发现相似的历史发展轨迹或事件时的惊讶和感慨，常用于描述事情的重复性或发展模式。', '当我看到这次经济危机的某些迹象与十年前的金融危机如此相似，我只能感慨，历史总是惊人地相似。', ''],
  ['感觉亏了一个亿', '「感觉亏了一个亿「是一种吐槽和自嘲的网络用语，通常用来形容在遭受金钱、财物或利益损失后感到心理上吃亏或委屈的情况。这种说法特别常用在游戏圈和投资圈中。', '在游戏中强化极品装备最后一步却失败了，装备爆了，我真是感觉亏了一个亿。', ''],
  ['老实人孤立你', '「老实人，孤立你「用于调侃那些在网络上对明显的玩笑或梗认真解释或评论的人，表示他们不懂幽默，显得有些「老实「或「较真「。', '在一个搞笑视频下，有人认真指出其中的不合理之处，其他人纷纷回复：“老实人，孤立你”。', ''],
  ['别人家的孩子', '“别人家的孩子”是用于形容一个表现得非常完美且优异的人，通常是在父母口中被用来与自己的孩子作比较，意在激励而实际上可能给孩子带来压力和负面情绪。', '我每次成绩单拿回来，父母总要提起“别人家的孩子”，真是压力山大。', ''],
  ['报复社会', '“报复社会”最初指因社会不公在公共场合做出有害行为。如今在网络中被用于恶作剧，常指故意传播重口味内容、在网络平台上发布吸引眼球的图片或视频，尤其是深夜发布引起食欲的食物图片，来“恶心”他人。', '他半夜在群里发火锅图片，说是为了报复社会，让大家都馋得睡不着。', ''],
  ['骠悍的人生不需要解释', '“骠悍的人生不需要解释”是一句调侃性质的网络流行语，用于表示无需为某种特别且无法理解的行为或状态作出解释。其核心在于强调个性、自信或另类的生活方式，常被用于吐槽、自嘲或恶搞。', '面对每天都在熬夜写文章却依然精力充沛的自己，她像是安慰自己般说：“作死的人生不需要解释。”', '这句话最初出自新东方老师罗永浩的语录。后来在郭敬明的粉丝引用时，将“骠悍”改为了“彪悍”，逐渐在网络上流传开来，并成为一种网络文化现象，其中“彪悍”常被替换为其他表达。'],
  ['累成狗', '“累成狗”是一句网络用语，表示达到极度疲劳的状态，相当于非常累。类似的表达有“冻成狗”、“虐成狗”等。', '加班到深夜，我已经累成狗了，赶紧回家休息。', ''],
  ['朋友圈友谊', '朋友圈友谊指的是一种主要存在于社交媒体上的关系，在这种关系中，双方在朋友圈中频繁互动（如点赞、评论），但在现实生活中关系一般，甚至不认识，也不会通过私聊或电话保持联系。这种友谊常被认为较为虚无。', '小李在朋友圈里和小张的互动特别频繁，但他们从来没有真实见过面，这可能就是典型的朋友圈友谊。', ''],
  ['编剧式观影', '编剧式观影指的是一种观影方式，即观众在观看影视作品时，不介意提前被剧透，甚至主动去了解剧情走向，以便在观影过程中对剧情发展有充分的掌控，不喜欢意外因素。', '小明就是典型的编剧式观影，每次新剧开播前他都要先了解剧情概要，确保观看时没有意外。', ''],
  ['积极废人', '积极废人指心态积极，有目标，但行动力不足，总是立下目标却无法实现的人。他们心态上积极向上，但实际行动上显得懒散和无力。', '小李总是说要每天跑步，但这计划已经停留在口头上好几个月了，真是个积极废人。', ''],
  ['教科书式', '“教科书式”通常用于形容某种行为、动作或处理方式极其规范、标准、无懈可击，完美到足以作为示范写进教科书中。这一说法可以用于正面或负面的行为，只要其典型且具有指导性。', '这位厨师的刀工堪称教科书式，每片蔬菜都切得完美无瑕。', ''],
  ['溜了溜了', '指见机不对或做了羞耻的事时，表达想要立刻离开的意思，通常用于主动认怂、缓解尴尬的场合。', '在游戏中被队友发现失误，他尴尬地说：“哈哈，我溜了溜了。”', ''],
  ['联动', '「联动「指两个作品之间产生关联，并且各自的角色可能同时出现在同一场景中。联动通常用于作品的宣传推广，与“乱入”不同（乱入可能出于致敬或恶搞等目的）。联动可能发生在相同或不同世界观的作品之间，发生在ACGN（动画、漫画、游戏、小说）各种载体之间。', '在动画《鲁邦三世VS名侦探柯南》中，两个作品的角色共同出现在同一故事里，形成了一次精彩的联动事件。', ''],
  ['抖包袱', '抖包袱是一个相声术语，指在表演中通过铺垫，在关键时刻揭示出令人意想不到的幽默或主题，使作品更具吸引力和感染力。', '评委说，这个节目最大的亮点就是最后抖出的那个包袱。', ''],
  ['粉丝滤镜', '「粉丝滤镜「指的是粉丝在看待自己喜欢的偶像时，会无意识地忽略或美化偶像的缺点和不足，认为偶像是最优秀和完美的。类似于「情人眼里出西施「，即使面对客观的不完美，粉丝也会有一层美化的偏见。', '即使这部电影的评分很低，但是在塑料花粉丝滤镜下，她仍被称作绝佳的演技派。', ''],
  ['塑料花姐妹', '形容姐妹之间的情谊表面看起来坚固永不凋谢，实际上充满了虚情假意和勾心斗角。', '她们两人总是一起逛街，真是一对塑料花姐妹啊。', ''],
  ['乌鸦坐飞机', '乌鸦坐飞机是动画《成龙历险记》里，反派人物阿福的一个招式名称。由于令人印象深刻， 后来出现人、动物或者某种事物的造型类似该姿势时，都会被恶搞称作是乌鸦坐飞机，现在也指一些生活中、游戏中等的骚操作。', '在健身房里，看到小李使用器械的姿势，我忍不住笑着说：“这不就是乌鸦坐飞机吗？”', '来源于动画《成龙历险记》中反派角色阿福的招式名称。由于该招式原名「Angry Crow Takes Flight「被错误翻译为“乌鸦坐飞机”，这一神翻译以及阿福的搞笑招式动作让观众印象深刻。'],
  ['内容引起舒适', '“内容引起舒适”用于表达对某篇文章或视频内容感到满意和舒适，通常用于对喜闻乐见的内容进行评价。', '当看到某知名反派角色在电影结局中得到应有的惩罚时，弹幕纷纷刷：“内容引起舒适，这就是我们想要的结局！”', ''],
  ['你摊上事了', '指“你惹上祸了”或“你遇到坏事了”。', '看到他那么紧张，我就知道他摊上事了。', '2012年春节联欢晚会小品《你摊上事了》。'],
  ['钢铁直男', '「钢铁直男「用于形容那些性格直爽、不善变通、不解风情的男性。他们通常在社交和情感上比较迟钝，不懂得女生的言外之意和情感需求，因而在某些情况下显得呆板和笨拙。他们的行为常常被认为是不懂得关心和体贴。', '昨天出去约会，我暗示他说我冷，结果这钢铁直男就说“谁让你不多穿衣服”，真是无语。', ''],
  ['废柴', '“废柴”是一个带有贬义的词语，指的是无能、无用的人，相当于“废物”的意思。它强调一个人在某些方面没有价值或无作为。', '他连这么简单的事情都做不好，简直就是个废柴。', ''],
  ['你说气人不', '表达一种幽默或夸张的不满或炫耀，通常用于调侃。', '今天买东西又打折了，你说气人不？', '电视剧《正阳门下小女人》，由剧中角色贺倔头常用的一句口头禅。'],
  ['秋名山车神', '指代飙车技术高超的人，或在网络上形容“老司机”。', '他在游戏里开得风驰电掣，简直就是秋名山车神。', '出自动漫《头文字D》，指藤原拓海的父亲。'],
  ['蓝氏禁言术', '“蓝氏禁言术”是一种幽默的网络用语，指当某人在网络评论中看到不喜欢的评论或自己的评论被抢先发出后，用“蓝氏禁言术”来表达让对方闭嘴或停止发言的意思。这个词源于一种“魔法”或手段，旨在让对方停止多话。它借用了严肃、安静而又有威慑力的角色形象来自嘲或调侃他人。', '在看到某条无聊的评论后，李明无奈地回复：“蓝氏禁言术！”', '该梗来源于小说《魔道祖师》，作者是墨香铜臭。后来此作品被改编成动漫，蓝氏禁言术是动画中“姑苏蓝氏”家族的一种特别术法。蓝忘机这个角色因其生性安静、话少而成为这一技能的代表。'],
  ['法院见', '“法院见”用来形容某件事情非常搞笑，让人笑个不停，甚至用夸张的方式表示要对这种笑负责。', '你这个段子真绝了，让我笑到不行，法院见！', '源于一则新闻，周某给苟某讲笑话导致苟某大笑猝死。虽然苟某有冠心病，但周某被判需赔偿6万元。网友借用“法院见”来指代特别好笑的事情。'],
  ['笑到头掉', '形容笑得非常开心，以至于夸张地描绘成脑袋后仰到看不见的状态。', '那个喜剧太搞笑了，我简直笑到头掉。', ''],
  ['假笑男孩', '假笑男孩指的是一种看似强颜欢笑的表情，表达面对艰辛生活时的无奈和尴尬。', '当同事说加班是为了公司好，我对他展示了假笑男孩的表情包。', '假笑男孩的真名是Gavin Thomas，他的照片因独特的表情而成为网络表情包。'],
  ['要恰饭的嘛', '“要恰饭的嘛”意为“要吃饭的嘛”，含有“为了生计，无奈之举”的意思，常用来自我开脱或解释行为。', '我接这些奇怪的广告，也是要恰饭的嘛，希望大家理解。', '该词最初火于主播孙笑川，在其直播中因支付宝乞讨码被举报，账号封停，愤怒中反复使用该句。也源自守望先锋主播大牙与另一主播的对话，用于开脱行为。'],
  ['A爆了', '「A爆了「是一个用于形容某人非常帅气或酷炫的网络流行语，常用于饭圈来称赞偶像或其他令人印象深刻的人。', '看他舞台表演的时候，那种气场真是A爆了！', '该词最早出自同人圈的abo设定，其中A通常指代比较强大或有影响力的人。随着时间的推移，这个用法被引申和变化，成为了形容某人特别帅或酷的流行词汇。'],
  ['菜到抠脚', '「菜到抠脚「指某人在某项活动中水平差，表现很糟糕，导致闲得无事可做。最初用于形容游戏玩家，现已扩展到其他领域。', '他在LOL里真是菜到抠脚，一场游戏等死了一半的时间。', ''],
  ['放鸽子', '放鸽子指的是已约定的事情或约会但未按时赴约，使对方白白等候。', '昨天我在咖啡馆等了两个小时，没想到他放我鸽子了。', ''],
  ['因缺思厅', '“因缺思厅”是英文“interesting”的谐音，表示某事或某物有趣、有意思。', '看到这位网友的评论，真是因缺思厅。', ''],
  ['跟谁俩呢', '“跟谁俩呢”是一句东北方言，表达对他人态度的不满或质疑，意思包含“你跟谁装呢？”、“我们很熟吗？”、“你在跟谁摆架子呢？”', '他进来就拍我肩膀，我心想：跟谁俩呢，这么自来熟。', ''],
  ['愚蠢的欧多多', '“愚蠢的欧多多”意为“愚蠢的弟弟”。欧多多，也可以写成欧豆豆，是日语“おとうと”的空耳，意思是弟弟。用于调侃或玩笑。', '他又没听懂这个梗，我只能无奈地说：“愚蠢的欧多多。”', '来自日本动漫《火影忍者》，角色宇智波鼬对弟弟宇智波佐助说的话。'],
  ['带球跑', '“带球跑”是网络小说中的一个用语，指的是女主角在怀孕的情况下，选择离开男主角，独自抚养孩子。这里的“球”指的是怀孕的大肚子。', '这部小说的情节真狗血，女主在误会男主之后，就带球跑了。', ''],
  ['宽油', '宽油指在烹饪时用大量油滑锅，使内部沾上一层油，以增香入味。', '看了王刚的视频，我也想试试宽油做菜，看味道是不是真的更好。', '该词源自美食作家王刚的教学视频，他的料理中常用宽油滑锅，因而走红。'],
  ['黑心小棉袄', '“黑心小棉袄”用来形容那些不太温顺乖巧，反而行为上让父母感到头疼的女儿。这一称呼是在传统观念中“女儿是父母的贴心小棉袄”这一说法的基础上，形象化地反映出某些女儿带来的并不是温暖和安慰，而是让父母感到扎心的行为。', '小丽最近的叛逆行为让她的父母无奈地称她为“黑心小棉袄”。', ''],
  ['炸了你的鱼塘', '“炸了你的鱼塘”意指消除一个人身边的所有备胎（恋爱候选人），而成为其唯一的恋爱对象。这个说法源于将备胎比喻为鱼塘里的鱼，而拥有较多备胎的人被称为“海王”。', '她决定再也不忍受他的周旋，高喊一声：“我要炸了你的鱼塘，做你的唯一！”', ''],
  ['走流程还是直接喷', '表示对某人或事物的不满，倾向于直接辱骂，而非委婉批评。', '新出的游戏又有严重的bug，网友纷纷表示：“来晚了，请问是走流程还是直接喷？”', ''],
  ['我是自愿上班的', '表达心不甘情不愿、被逼无奈做某件事情的心酸和沮丧。', '当闹钟响起时，我默默对自己说：“我是自愿上班的。”', ''],
  ['广东人最后的倔强', '“广东人最后的倔强”这个梗指的是广东人坚持自己不吃辣的饮食习惯，即使在面临极端天气如台风导致的抢购潮中，他们仍然不会购买辣椒这种辛辣食材。这显示了广东人对不吃辣传统的坚守。', '台风来临，超市的货品被抢购一空，唯有辣椒依旧在货架上，这真是广东人最后的倔强。', ''],
  ['你算哪块小饼干', '“你算哪块小饼干”是“你算什么东西”的可爱版本，通常用于表达一种带有幽默和傲娇的态度，意思是对对方不满或不屑，但带有一种轻松和玩笑的语气。', '当朋友惹她生气时，她撅起嘴说：“哼，你算哪块小饼干，我才不理你！”', '该用法据说来源于美剧《生活大爆炸》。剧中角色Sheldon为了避免说脏话，把“son of a bitch”改成了“son of a biscuit”，其中“biscuit”意为饼干，由此产生了“你算哪块小饼干”这种说法。'],
  ['你若安好便是晴天', '“你若安好便是晴天”表面上是说，只要你过得好我就会很幸福。通常用于关心某人或表达情感。', '如果你能顺利毕业，我就放心了，真是“你若安好便是晴天”。', '出自白落梅的书《你若安好便是晴天：林徽因传》，描述了林徽因的传奇一生。'],
  ['一家人最重要的是整整齐齐', '指一家人应该团结一致，但现在多用于讽刺，形容以家庭为单位的人在某事件中都表现不佳或遭遇相同坏结果。', '一家人在游乐园插队被制止，结果招来网友评论：“一家人最重要的是整整齐齐”。', '源于香港TVB剧，原台词为粤语“一家人最要紧是齐齐整整”，在传播过程中演变为较贴近普通话的版本。'],
  ['人类的本质是鸽子', '指一些喜欢爽约、放鸽子的人，强调人类频繁违约的习惯。', '我们都说好了今晚一起打游戏，他居然没有上线，真是人类的本质是鸽子。', ''],
  ['这世界车水马龙', '“这世界车水马龙”是一句用于暗恋或表白的句子，类似于“今晚月色真美”，表达对对方的喜欢或爱慕之情。', '昨天他跟我说“这世界车水马龙”，我想他可能在暗示他喜欢我。', ''],
  ['小猪佩奇社会人', '佩戴或使用小猪佩奇相关物品的人被调侃为“社会人”，表达对这种反差萌的幽默看法。', '他手上戴着小猪佩奇手表，瞬间就变成了“社会人”。', ''],
  ['多喝岩浆', '“多喝岩浆”是对“多喝热水”的一种夸张回应，用以表达对这种表面关心的调侃和不满。通常由女生用来讽刺那些认为自己在关心女生，但实际上只是在说空话的男生。也可以被用作男生对被称为“直男”这种评价的不满反驳。', '女生：我今天不舒服。      男生：多喝热水。      女生：你还是多喝岩浆吧！', ''],
  ['软饭硬吃', '“软饭硬吃”指一个人用自信而理直气壮的态度接受依赖配偶或伴侣的经济支持。', '他说自己在家照顾孩子，工作由妻子负责，这是他“软饭硬吃”的选择。', ''],
  ['吃某人的颜', '“吃某人的颜”指某人的长相非常符合个人的审美，颜值很高。', '这个明星太帅了，我真的太吃他的颜了！', ''],
  ['你在微博买房了吗', '“你在微博买房了吗”用于调侃那些频繁出现在某个社交平台或社区的人或事，形象地比喻他们如同在此“定居”一般。这个表达可以变形用于其他社交平台，意指某人总是出现在你的视野中。', '“这位明星最近太火了，各大新闻都能看到，看得我都想问一句：‘你在微博买房了吗？’”', ''],
  ['看海模式', '看海模式指的是由于暴雨天气导致某地出现严重积水，形容城市被雨水淹没的状态，类似于在看海景。', '昨天的暴雨让我们的小区也开启了“看海模式”，路面上积水都快到膝盖了。', ''],
  ['留下了不学无术的泪水', '「留下了不学无术的泪水「是用来调侃自己在看到别人优秀的学习或技能水准时，因自叹不如而感到伤心。', '每次看到她弹钢琴，我就留下了不学无术的泪水。', ''],
  ['今晚月色真美', '「今晚月色真美「是表达「我爱你「的一种文艺和含蓄的方式，源自日本文化背景，代表了一种不直白但极具浪漫色彩的情感表达方式。', '在一次浪漫的晚餐后，他看着她，轻声说道：“今晚月色真美”，她瞬间心领神会，脸上泛起了红晕。', '这一表达方式广泛流传自日本作家夏目漱石的传说。夏目漱石作为一名英语老师时，曾告诉学生要用更含蓄的方式表达“I love you”，因此说日本人可能会用“月が綺麗ですね”(月色真美)这样的句子来含蓄表达爱意。'],
  ['有事漂流瓶联系', '“有事漂流瓶联系”意思是不要再联系。', '他跟我说有事漂流瓶联系，我看是彻底没戏了。', ''],
  ['皇帝的金锄头', '“皇帝的金锄头”讽刺一种因眼界狭窄而产生的对富裕生活的误解，指井底之蛙式的贫穷幻想。', '小明总觉得有钱人每天都在游山玩水，这就是典型的“皇帝的金锄头”思维。', '来源于一个段子，讲的是两位古代老农民对皇帝奢华生活的天真想象。'],
  ['人设崩塌', '「人设崩塌「指某人长期以来营造的某种对外形象被曝光与现实不符，导致这种形象被摧毁。常用来描述明星或公众人物因为负面新闻等原因，失去了原本的公众形象。', '那位一直以环保达人自居的明星被拍到乱丢垃圾，这次人设崩塌真是致命打击。', ''],
  ['麻瓜', '麻瓜指没有魔法能力的普通人，现用于形容对某个圈子或领域完全不懂的人，有时带有贬义，指水平有限却固执己见的人。', '在程序员的聚会上，他就像一个麻瓜，对他们讨论的技术完全不懂。', '麻瓜出自英国作家J.K.罗琳的《哈利波特》系列，“muggle”由罗琳创造并在国内音译为“麻瓜”。'],
  ['这集我看过', '“这集我看过”用来表达对某件事的熟悉感或预见性，意指“类似的事情之前发生过”或“我预测会有这样的结果”。它也可以用于调侃内容老套、缺乏新意。', '当看到电视剧中男主和女主又一次错过时，网友纷纷在弹幕上打出“这集我看过”，表示对此剧情的预料和熟悉感。', ''],
  ['放飞自我', '「放飞自我「指的是打破自己原有的人设和拘束，无拘无束地追求个人梦想或做自己喜欢的事情。它也可以用来调侃某人突然做出一些令人意外或难以理解的行为。', '明星在综艺节目中放飞自我，全然不顾形象，反而获得了更多粉丝的喜爱。', ''],
  ['奔现', '“奔现”是指从线上虚拟交往发展到线下现实交往的过程，尤其是指从网络恋爱到现实恋爱的转变。', '小王和小李在游戏里认识了一年，终于决定下个月奔现，特别期待见面的那一天。', ''],
  ['爆灯', '爆灯用来表达对某个人或某样事物的强烈喜欢。', '这个新出的游戏太好玩了，我为它爆灯！', '源于相亲节目《非诚勿扰》，女嘉宾通过按下爆灯键表达对男嘉宾的喜欢。'],
  ['全裸待机', '全裸待机形容迫不及待地等待某事发生，表达了极大的期待和准备。', '新的游戏马上要上线了，我已经全裸待机，就等它开服。', ''],
  ['我们白着呢', '“我们白着呢”是一句用来强调自己皮肤白皙的话，常带有一种自豪感和傲娇的语气。它也常被用来称赞他人皮肤白皙。', '小明在晒了一整个夏天后仍然保持着白皙的肤色，他自豪地说：“我不黑，我们白着呢。”', '这句话出自浙江卫视亲子综艺节目《爸爸回来了》，是嘉宾贾乃亮的女儿贾云馨（昵称甜馨）的一句经典语录。在节目中，家人聊天时提到皮肤黑，甜馨用这句俏皮话反驳，表现出对自己肤色的自信。'],
  ['错的不是我而是这个世界', '形容动漫中角色因悲惨过去而黑化，既有理解也有无奈。', '面对被误解的处境，他无奈地说：「错的不是我，而是这个世界。「', '出自《反叛的鲁鲁修》。金木研也曾说过，但含义不同。'],
  ['人生的走马灯', '“人生的走马灯”用于描述一些极端体验，如同濒临死亡时产生的感觉，让人觉得自己的生命在眼前快速闪过。', '吃完这道黑暗料理，我有一种“人生的走马灯”感觉，简直反胃到极致。', ''],
  ['磕死我了', '「磕死我了「用来表达因喜欢的人或CP（虚构或真实的伴侣组合）的互动过于甜蜜而激动、开心甚至有点受不了的心情。「磕「指对某对CP或某个人的关注和喜爱。', '「这对新人在发布会上的互动真是磕死我了，太甜了！「', ''],
  ['社会的毒打', '“社会的毒打”指的是认清现实的残酷或被周围的人教训。', '他以为能轻松找到工作，但很快就遭受了社会的毒打。', ''],
  ['好惨一男的', '“好惨一男的”用于形容某位男士无辜卷入与自己无关的负面消息或流言，被迫面对不应有的麻烦。', '他明明只是路过，却被误认为是小偷，真是好惨一男的。', '该梗源于2019年，因台湾某恐怖游戏中的反派角色名字与明星何炅相同，导致网友误以为何炅出负面新闻，何炅无辜受累，亲自在微博上发言“何炅好惨一男的”自证清白。'],
  ['拜个早年', '「拜个早年「在网络语境中指的是当面对尴尬或槽点过多的情况时，不知道该如何回应，只能以提前祝对方春节快乐的方式来缓和气氛。这句话本是传统的节日祝福，却被用来打破尴尬场景或者表现无奈与戏谑。', '在群聊中，某人分享了一段极其冷场的视频，大家都不知道说什么好，有人冒出一句：“没啥说的了，给您拜个早年吧。”', ''],
  ['安静的做个美男子', '「安静的做个美男子「是一种形容保持安静和不喧哗的幽默表达，也可以意指一个人低调但充满魅力。', '面对朋友的争辩，他只是微微一笑，决定还是安静的做个美男子，不参与其中。', '该短语源于《万万没想到》第二季第1集中叫兽的台词：“我想我还是安静地当一个美男子算了。”之后，「盗墓笔记「的作者南派三叔在微博上用该句表达对自身肥肉的调侃，使得这句话在网络上迅速流行。'],
  ['且行且珍惜', '一边前进，一边珍惜走过的路。表达珍惜当下的态度。', '工作中总会遇到挫折，但要学会且行且珍惜，不断前进。', '原句来自林语堂的文章。因文章出轨事件，马伊琍在公开发文时引用，使该句广为流传。'],
  ['套路深啊', '“套路深啊”指某人使用了精心策划的方法和手段，以达到其目的，这些手段非常巧妙，以至于一般人难以预料。可以表达一种震惊或感叹，具体的褒贬意义要根据具体语境来判断。', '“这次的竞争对手套路深啊，提前就做好了准备，给我们留下的空间不多。”', ''],
  ['富贵色', '「富贵色「是一种网络用语，通常指的是富丽堂皇、显眼的大红大紫大绿等颜色。这些颜色一般在视频网站的弹幕中作为会员专属色，用来展示网友通过充值成为会员的特权。', '在B站上看到有人刷“富贵色”，不禁感叹这才是真正的土豪。', ''],
  ['社会主义兄弟情', '“社会主义兄弟情”是一个用来形容在受到审查的文化娱乐作品中，以友谊或兄弟情的形式表现的潜在浪漫关系。该梗尤其用于指代被弱化或掩盖的同性情感。', '在这部影片里，男主和他的朋友总是形影不离，粉丝们调侃这是“社会主义兄弟情”。', ''],
  ['走花路', '走花路表示前程似锦，走上人生巅峰。通常用来表达自己成功时的喜悦或祝福他人前途美好。', '祝你在新的一年里事业顺利，走花路！', '该词源于韩国综艺节目《Produce 101》中金世正获得第一名时的获奖感言：“走花路吧”。此后，该词在各个粉丝圈中广泛使用。'],
  ['布谷鸟', '布谷鸟在网络上指按时守约的人，是鸽子的反义词。因为“布谷鸟”可以拆解为“布（不）谷（咕）”，即不会爽约。', '他每次说要来的活动从不缺席，简直就是个布谷鸟。', ''],
  ['我佛不渡穷逼', '“我佛不渡穷逼”用来讽刺当今一切都向金钱看齐的现象，即使是宗教信仰也成为牟利的工具，反映出穷人在物质社会中的无奈和自嘲。', '在这个金钱至上的时代，我佛不渡穷逼，看来只能靠自己了。', '该梗源于网易云音乐将滇津喇嘛版本的《大悲咒》设为VIP专属，网友觉得这与佛教的普度众生思想相悖，进而调侃出“我佛不渡穷逼，只渡VIP”。'],
  ['全靠同行衬托', '“全靠同行衬托”是用来形容某人或某事物尽管本身不太出色，但由于同行或同类的表现更差，反而显得相对优秀的讽刺表达。通常用于自谦或对比行业内其他竞争对手的表现来幽默地批评现状。', '在现如今的国产手机市场中，有的品牌虽然质量一般，但面对那些频频爆炸的产品，全靠同行衬托，反而脱颖而出。', '这个梗因相声演员郭德纲常常在节目中自嘲使用而走红。郭德纲的相声风格幽默搞笑，但遭到主流相声界批评为低俗。为了回应这些批评，他常说“不是我很优秀，全靠同行衬托”，以此自谦并讽刺批评者。'],
  ['一刀建林流泪', '“一刀建林流泪”用来形容切糕价格十分昂贵，一刀切下来的切糕价钱高到让富翁也为之流泪。', '朋友买了块切糕，结果查账单后发现简直是一刀建林流泪，这价格可真是不一般！', ''],
  ['闭麦', '「闭麦「原指关闭麦克风停止发言，现指在某话题上保持全面沉默，不发表公开意见。', '在这次争议事件中，不少人选择了闭麦，不再发表任何看法。', ''],
  ['百因必有果', '“百因必有果”是用来形容某人对他人的报复或反击，传达“遇到我就是你的报应”的意思。常以夸张和戏谑的方式用于社交表达。', '被朋友嘲笑后，她摆出韩美娟的经典姿势说：“百因必有果，你的报应就是我！”', '这句话出自抖音作者韩美娟（韩佩泉）的视频作品。该视频因韩美娟独特的嗓音、夸张的造型和肢体语言而走红，成为其标志性语句。'],
  ['彩虹屁', '彩虹屁指对偶像进行过度、花式的吹捧和赞美，即使是普通的事情也能被夸奖得天花乱坠。', '这位粉丝夸偶像喝水的样子像艺术品，真是彩虹屁大赏。', ''],
  ['一开始我是拒绝的', '“一开始我是拒绝的”用于表示最初不同意或不情愿做某事，后续经过考虑或者尝试后改变了态度。', '她让我参加舞蹈社团，老实说，一开始我是拒绝的，但去了一次发现还挺有趣。', '该梗源自成龙在采访中，谈及拍摄霸王洗发水广告时的描述。'],
  ['小老弟', '“小老弟”是一种对比自己年轻或经验浅的男性的亲切称呼，现指比自己实力弱、缺乏经验的人。', '看到他在那里手忙脚乱，我忍不住说：“怎么回事小老弟？”', ''],
  ['手里的鸡腿突然不香了', '用于表达对他人的嫉妒和羡慕，与“柠檬酸”类似，形容自己感到酸溜溜的。', '看完好朋友求婚成功的现场回放，我手里的鸡腿突然不香了。', ''],
  ['聊五毛钱的', '“聊五毛钱的”用于表达想要与人聊天的意图，并不涉及真正的消费。', '你有空吗？咱们聊五毛钱的，我现在特别想找人说说话。', '这个梗疑似出自赵本山与宋丹丹的小品《钟点工》，其中的对话反映出一种因为孤独而渴望陪伴的心理。'],
  ['双标', '“双标”是“双重标准”的缩写，指在比较多个事物或人时，使用不一致或偏向性的评判标准。常用于批评那些对自己宽容而对他人苛刻的人。', '他平时不准别人迟到，但自己却总是找理由晚来，真是个双标狗。', ''],
  ['宝宝心里苦', '“宝宝心里苦”是一种卖萌式的自嘲，用来表达遇到不顺心的事或心情不好的委屈感。', '今天的工作太多了，宝宝心里苦，但宝宝不说。', ''],
  ['二月红前来求药', '指代为急切追求某事物或表达某种状态的幽默调侃，也可以理解为“到此一游”。变种梗为“二月绿前来求药”，表现人物被绿。', '朋友看到限量版球鞋发售，弹幕直呼：“二月红前来求药，鞋子我一定要买到！”', '电视剧《老九门》。角色二月红为救妻子，在雨中向张启山求药。'],
  ['万人请辞', '“万人请辞”是网络上表达强烈反对某事物、请求停止或改善该事物的夸张说法。常用于对不满的某人或某项规定，表达众多人的不满或抗议。', '某电视剧大结局改编引发观众不满，评论区充满了“万人请辞编剧”的留言。', ''],
  ['难顶', '“难顶”表示无法承受某种情况，形容感到非常吃力或很难熬。它可以表达一种达到忍耐极限的状态。', '最近工作压力太大了，真的有点难顶。', ''],
  ['不要在网络上逼逼赖赖', '这句话强调的是不应该在网上随意对别人批评和评头论足，并且暗指如果有问题就当面解决或面对现实，不要只停留在网络上。它反映了一种对网络匿名攻击的反感和对现实解决办法的推崇。', '每次看到有人在评论里吵架就想说：“不要在网络上逼逼赖赖，有本事现实碰一碰！”', '这句话出自抖音网红韩美娟的视频。他以戏剧化的表演风格、夸张的造型和独特的声音闻名。'],
  ['云梦江氏紫电警告', '“云梦江氏紫电警告”是一个用于表达不满或警告某人言论的网络用语，通常用于评论不喜欢的言论或有人发言被抢先时表示不满。', '在群聊中小明发了一个冷笑话没人笑，结果他紧张地说：“哎，我这是开玩笑的，不要对我来个云梦江氏紫电警告啊！”', '该梗源自电视剧《陈情令》，故事中的云梦江氏是五大家族之一，家主为江澄。他的法器“紫电”是一种可以化为戒指的软鞭，是江氏的独门绝技且认主仅江澄使用。江澄的脾气暴躁，对不满的事会直接使用“紫电”惩罚，包括对人气主角魏无羡等。'],
  ['把话筒塞他嘴里', '“把话筒塞他嘴里”是一种夸张用法，意指“给他说话的机会，让他讲出自己的故事”，通常用于搞笑场合。', '当有人说出惊人的秘密时，朋友们打趣地说：“快把话筒塞他嘴里，看他还能说出什么来。”', ''],
  ['地铁老头看手机', '“地铁老头看手机”是一种表情包，形象地表达了当看到手机上令人困惑、不解或反感内容时的反应。这种表情包常用于无声地表达不理解、困惑或厌恶的情绪。', '今天在网上看到一个新潮流，结果我的反应只能用“地铁老头看手机”来形容。', '这个梗来源于一张广泛流传的表情包，图中一个老爷爷坐在地铁上，皱眉并以夸张的迷惑表情注视着手机屏幕。'],
  ['阿瓦达砍大瓜', '「阿瓦达砍大瓜「是对《哈利波特》中死亡咒语「阿瓦达索命「（Avada Kedavra）的发音空耳，以造成幽默效果。', '在游戏直播中，玩家突然失败，弹幕刷满了“阿瓦达砍大瓜”。', ''],
  ['房子塌了', '“房子塌了”指想看别人热闹，结果发现是自己家的事情。在娱乐圈和饭圈，这一说法通常用于形容爆料中涉及自己的偶像特别是恋爱新闻时的感受。', '今天看到大明星的绯闻，没想到“房子塌了”，主角竟然是我家偶像。', '来源于一张采访图片，一位女士说，“看到那边有房子塌了，就过去看看热闹。但过去发现是我家的房子塌了。”'],
  ['play的一环', '“Play的一环”指的是在游戏、项目或任务中作为某个特定环节、角色或任务的重要组成部分。也可以用于形容在某些特定情境下充当配合角色的人。', '你们吵架还要我调停，我怎么感觉自己成了你们play的一环？', ''],
  ['天龙人', '“天龙人”用来形容那些拥有特权、态度嚣张、自视甚高，常常瞧不起别人的人。', '他总是觉得自己高人一等，真像个天龙人。', '源自《海贼王》中的一个贵族群体，后来由台大BBS站批踢踢乡民使用，逐渐被网友用来嘲讽享有特权的政商权贵和有优越感的人。'],
  ['表面亲戚', '“表面亲戚”这个梗用来形容那些只在表面上看起来很亲近的亲戚，虽然存在血缘联系，但他们的行为举止常常令人失望和心寒。平时在表面上友好热心，但真正遇上需要帮助或支持的时候，他们往往却躲在一旁，毫无实质性帮助。', '每次过年回家，表面亲戚总是热情的邀请我们去他家吃饭，结果到了饭桌上就开始吹牛和数落别人。', ''],
  ['嘴上都是主义心里全是生意', '“嘴上都是主义，心里全是生意”这句话用来讽刺那些口头上说得冠冕堂皇，强调各种主义和正义，但实际上内心只关心个人利益的人，是对表里不一、虚伪行为的有力批评。', '他每天都在社交平台大谈环保主义，但私下却投资了许多污染严重的企业，真是“嘴上都是主义，心里全是生意”。', '这句话出自电视剧《潜伏》，是角色谢若林的经典台词。最初专用于讽刺官员，后来被广泛地应用于其他出入于公众视野、内外不一致的“大人物”。'],
  ['可奶可狼', '“可奶可狼”是对男生两种性格的描述：同时具备温柔可爱的“奶”属性和强势有安全感的“狼”属性。这个形容词用来评价既能撒娇卖萌，又能展现男友力的男生。', '他真是可奶可狼，既会在周末带我去郊游，又能在关键时刻保护我。', ''],
  ['道友请留步', '“道友请留步”用于形容某人试图挽留他人，并劝说其加入某个计划或组织，通常带有不怀好意和忽悠的意思。', '每当这位主管对新人说“道友请留步”，我们就知道他又要开始洗脑了。', '出自《封神演义》中申公豹的经典台词，申公豹用这句话来拉拢能人异士助纣为虐。'],
  ['新手村', '“新手村”指网络游戏中玩家刚开始游戏时的起始地点。它通常是为了帮助新手玩家熟悉游戏而设立的区域，提供各类功能NPC、任务以及游戏教学。', '我刚进入这款新游戏，目前还在新手村熟悉操作和任务系统。', ''],
  ['跳起来打你膝盖', '“跳起来打你膝盖”是一种自我调侃，形容身高较矮。', '别看我矮，我可是能跳起来打你膝盖！', ''],
  ['划船不用桨', '形容一个人行为大胆、放肆，很「浪「或很敢于冒险。', '他今天在聚会上大跳热舞，真是划船不用桨，靠浪。', ''],
  ['打嘴炮', '「打嘴炮「是网络流行语，用来形容那些爱吹牛的人，他们说到做不到，只会空谈。在ACGN文化中，“打嘴炮”也指主角通过口若悬河的言论或声嘶力竭的喊叫对敌人施加心理或精神上的影响，作为一种语言武器。', '小明总是说要减肥，但从来不见他运动，真是会打嘴炮。', ''],
  ['铁憨憨', '“铁憨憨”指一时糊涂的傻子，通俗叫法是二愣子、愣头青。', '他昨天在大庭广众下踢足球，撞到柱子上，真是个铁憨憨。', ''],
  ['老阴比', '形容那些表面看似无害，但实际上非常精明和深藏不露的人。', '小王看起来很老实，没想到是个老阴比，把整个计划都掌握在手里。', ''],
  ['恰烂钱', '“恰烂钱”指赚取不道德或有损良心的钱，通常描述为了利益而进行不诚实的行为。', '那个主播最近总是在推不靠谱的产品，真的是在恰烂钱。', '该词衍生自“恰饭”的概念，源自孙笑川在直播中提到的“要恰饭的嘛”，后来逐渐演变成“恰烂钱”，用来批评不道德的赚钱方式。'],
  ['注入灵魂', '“注入灵魂”指在创作或表演中通过加入独特的行为或元素，使作品或表现更加出色和生动，起到画龙点睛的作用。', '这幅画本来很普通，但艺术家在最后用立体线条勾勒了轮廓，给整幅作品注入了灵魂。', '该梗出自撒盐哥的视频，他以独特的撒盐动作广受欢迎。视频中，他用一种放荡而精致的姿势撒盐，被人们形象地称为在菜肴中“注入灵魂”。'],
  ['给跪了', '“给跪了”是表达叹服、拜服或无奈的网络用语。用于表明对某事或某人感到无奈、崇拜或调侃，带有自嘲和幽默意味。', '他一口气背完了全部诗词，真是给跪了！', ''],
  ['塑料普通话', '“塑料普通话”是用来形容一个人的普通话非常不标准，讲得很不地道，容易让人听不懂。', '她用塑料普通话分享了旅游见闻，弄得大家哭笑不得，完全不明白她在说什么。', ''],
  ['好人卡', '“好人卡”指在表白过程中，被对方以委婉拒绝的方式拒绝，通常用“你是个好人，但是我们不合适”等话来表达。', '他给我发了一张好人卡，说我们还是做朋友比较好。', ''],
  ['高端黑', '高端黑是一种用文明、幽默的语言在表面上赞美，实则讽刺、调侃某人或某事的技巧，相比直接抨击更优雅且不易引起反感。', '他说你太优秀了，大家都不敢和你竞争，这种高端黑真是滴水不漏。', ''],
  ['吊车尾', '“吊车尾”用来形容那些做事总是落后、拖后腿，或能力相对较差的人。', '在班级考试中，他总是吊车尾，但并不影响他对数学的热爱。', '最早出自日本漫画《火影忍者》，主人公鸣人在故事的开头被认为是“吊车尾”，然而他通过努力逆袭，最终成为火影。'],
  ['花店不开了花继续开', '这句话的含义是表达一种对爱的坚持和延续，即使爱的人不在了，自己的爱依然继续。它体现了一种深情和不懈的情感态度。', '分手后的她反复对自己说：“花店不开了花继续开”，努力说服自己继续过好自己的生活。', '这句话出自台湾作家蔡仁伟的《伪诗集》中的短诗《世界》。'],
  ['沉淀文学', '沉淀文学用来调侃人们在遇到不顺利的事情时，自我安慰需要“沉淀”一下，以降级目标的方式面对困境。', '听说大明找工作不顺，他笑着说要沉淀一年再看看。', ''],
  ['神金', '“神经”因为敏感被屏蔽，于是网友们用“神金”来代替，逐渐演变为网络用语，以隐晦或搞笑的方式指代“神经”。“害得我笑了一下”是表达对某些事件或段子的搞笑反应，常用于聊天或评论中。', '“有人说我最近有点神金，我表示，我这不是一直都很正常吗？”', ''],
  ['众筹出书', '“众筹出书”是一种网络用语，用于表达对他人精彩和有趣发言的欣赏和赞美。它建议将这些发言整理成书，并表示如果缺乏资金，可以通过众筹的方式筹集资金。', '你的发言实在是太精彩了，简直可以众筹出书，让更多人受益。', ''],
  ['爆冷', '“爆冷”即“爆冷门”，指比赛结果出人意料，与多数人期待相反。通常指弱者出人意料地战胜强者或强者意外失败。', '在这场激烈的比赛中，弱旅队爆冷击败了卫冕冠军，引起了广泛关注。', ''],
  ['何方道友在此渡劫', '用于形容视频中出现打雷场景时的调侃或幽默评论，来源于仙侠小说中角色渡劫时天上劈下雷电的情景。', '视频里的乌云密布加闪电，弹幕瞬间刷屏：“何方道友在此渡劫？”', ''],
  ['他带我去了美特斯邦威', '形容与现实反差过大、夸赞用力过猛的情况，带有反讽意味。', '他买了部新手机，非说功能逆天，我感觉他快要说出“他带我去了美特斯邦威”了。', '电视剧《一起来看流星雨》，郑爽饰演的楚雨荨角色台词。'],
  ['老子懂孔子和孟子不懂', '「老子懂孔子和孟子不懂「是一种表达自我理解力和智慧优于他人的方式。这句话常用于调侃和自夸，表示自己已经明白某个道理或内容，而连孔子、孟子这样的圣人都不懂，借此来突显其难度和深奥。', '看完这个复杂的数学题解，我能说老子懂孔子和孟子不懂吗？这解法也太深奥了吧。', ''],
  ['孔子懂了孟子懂了只有老子没懂', '这个梗用“孔子懂了孟子懂了，只有老子没懂”来讽刺或调侃一些视频内容空洞、题目与内容不符。这里的“老子”指的是观众自己，表示没看懂视频，想要别人解释。', '这视频标题写得挺好，结果看完我只能说：孔子懂了孟子懂了，只有老子没懂。', ''],
  ['群众里有坏人', '“群众里面有坏人”是一种调侃，通常用来讽刺那些在犯错后不愿承认自责，而是把责任推给他人或环境的行为。最初用来形容贪官和贪图美色的官员推卸责任的话语，但后来延伸至形容任何不肯承认自己错误的人。', '他每次出问题都说是环境不好，真是典型的群众里面有坏人。', '该梗出自电影《私人订制》中，由范伟饰演的角色在做检讨时说的话。他为了辩解自己的错误，把责任推给身边的人，说“群众里边有坏人啊”。'],
  ['百度死', '指通过百度搜索自己的身体症状后，得到的结果常常让人感到情况严重甚至致命，形容网上自诊后的心理负担和恐慌。', '我昨晚嗓子有点疼，结果一百度，感觉自己命不久矣，真是百度死。', ''],
  ['不愧是我', '“不愧是我”是一个带有傲娇意味的调侃用语，通常用来形容自己或他人表现出自豪或骄傲的神情。', '过完年又胖了三斤，不愧是我！', '这个梗来源于演员王一博。在《陪你到世界之巅》剧组，他曾一脸傲娇地指着视频中骑摩托的人说“it is me”，网友将这翻译为“不愧是我”，从而成为专用的调侃语。'],
  ['安静如鸡', '“安静如鸡”是指在本不该说话的时候保持安静，通常用于描述一种人们规避尴尬或打脸时的反应。', '公司发布了新政策，这下同事们都安静如鸡，不敢再抱怨了。', ''],
  ['会说话就多说点', '“会说话就多说点”用来赞美或调侃那些评论精准、有趣且角度独到的网友，表达对巧妙评论的欣赏。有时也用于吐槽那些说话不委婉的人。', '网友A发表了一则妙趣横生的评论，网友B回复：“哈哈，会说话就多说点！”', ''],
  ['游泳健身了解一下', '“游泳健身了解一下”是一句调侃或委婉吐槽的话，通常用于暗示某人需要减肥或锻炼身体，通常具有幽默和亲切的意味。', '最近你的肚子好像大了一圈呢，游泳健身了解一下？', '这一短语来源于健身馆推销人员常用的推销术语。该短语成为网络流行梗的原因是因为粉丝们用它来调侃陈奕迅和周杰伦的体型。在一次活动中，粉丝对陈奕迅喊了这句话，引发了趣味互动，这一情景迅速走红网络。而周杰伦因被拍到身形发胖，也被网友用这句话调侃。'],
  ['猫狗双全', '“猫狗双全”是指一种理想和成功的生活状态，代表拥有足够的经济能力和时间，能够同时养猫和狗。这是一种幽默调侃，类似于追求家庭美满的“儿女双全”。', '小王虽然还很年轻，但已经猫狗双全，每天过着无忧无虑的生活，实在让人羡慕。', ''],
  ['令人窒息的操作', '“令人窒息的操作”用于形容意想不到、令人惊讶或震惊的行为或方法，可能是吐槽也可能是赞扬。', '游戏时他突然反杀，这真是令人窒息的操作。', ''],
  ['我秦始皇打钱', '「我秦始皇打钱「是一种讽刺网络骗局的流行语，用以调侃那些假冒名人身份、编造离奇故事来骗取钱财的行为。', '在社交平台上，有人留言：“我秦始皇打钱，我的兵马俑正等着我请客吃饭。”', ''],
  ['秋水誓', '“秋水誓”是一个特殊的发誓手势。由于张一山在《春风十里不如你》中角色名为秋水，这个手势被冠以“秋水誓”，成为网友调侃的“真爱标准”。', '大家都来挑战“秋水誓”，却发现这个手势看似简单，实际很难做到。', '出自电视剧《春风十里不如你》，由剧中张一山饰演的角色秋水使用的发誓手势而得名。'],
  ['敲黑板划重点', '“敲黑板划重点”是用来强调接下来的信息非常重要，相当于提醒大家注意核心内容，类似“前方高能”。', '“大家注意，敲黑板划重点，这次考试的范围就包括这几个章节。”', ''],
  ['细软跑', '“细软跑”指在发表敏感言论后，可能面临惩罚或调查的风险，因此需要赶紧收拾贵重物品逃跑的幽默说法。是提醒和调侃某人因发表敏感言论而可能需要迅速“跑路”。', '“他刚才在群里说的那些话，真的很大胆，我都替他捏一把汗，快点细软跑吧！”', ''],
  ['请允悲', '“请允悲”是“请允许我做一个悲伤的表情”的缩写，常用于表达对他人不幸遭遇的调侃。在对方倾诉糗事或不幸经历时，内心觉得搞笑但表面上假装同情，因此说“请允悲”以表达这种内心的矛盾与调侃。', '朋友跟我说他早上出门急得穿错鞋，我忍不住想笑，但还是回复了一句：“请允悲。”', ''],
  ['杠铃般的笑声', '“杠铃般的笑声”形容一个人的笑声粗犷、豪爽、自然不做作，也用来表示事情非常好笑，令人笑得夸张和不可自持。', '他讲了个笑话，结果我不禁发出了杠铃般的笑声，全场都看向了我。', ''],
  ['整容般演技', '“整容般演技”指一个演员通过出色的演技改变了观众对其外貌或角色不适合性的最初看法，使观众全然沉浸在角色所带来的魅力中，仿佛演员自身发生了惊人的蜕变。这是一种对演员演技的高度赞美，表示其能通过角色诠释忽略长相。', '在这部新电影中，小李子的整容般演技让观众完全忘记了他外形上的缺陷，深入角色本身。', '这一说法主要在对电视剧《三生三世十里桃花》中赵又廷饰演的夜华一角的评价中产生。赵又廷用其精湛的演技化解了外界对其外貌与角色不符的质疑，从而被赞为“整容般演技”。'],
  ['地主家的傻孩子', '“地主家的傻孩子”用于形容某人来自富裕或有实力的家庭，但本人性格单纯、傻乎乎的，说话和做事显得有点傻气但无害。这一表述有调侃和亲切的意味，并不是真正地贬低智力。', '小王总是穿着昂贵的名牌，却在商场里迷路，这场面真像个地主家的傻孩子。', '该梗来自湖南卫视综艺节目《花儿与少年》。在节目的一段花絮中，嘉宾井柏然误打误撞看到郑爽换衣服，表现得十分慌张，引起大姐毛阿敏的安慰。由于井柏然和杨洋一同在节目中表现得较为呆萌，后期制作团队给他们配上了“地主家的傻儿子”的字幕。'],
  ['老母猪戴胸罩', '“老母猪戴胸罩”是一个歇后语，后半句是“一套又一套”，用来形容某人有很多套路、说话或做事的方法特别多。', '小李在谈判中的表现真是一绝，简直是老母猪戴胸罩——一套又一套。', ''],
  ['劈个叉都是爱你的形状', '“劈个叉都是爱你的形状”是指无论做什么事情，最后看起来和某种动作或事物结合，都是“爱你的形状”。这是网友们用来调侃的一种方式，表达一种无厘头的幽默。', '今天心情很好，连吃块蛋糕都是爱你的形状。', ''],
  ['口嗨', '口嗨指的是在言语上吹牛、说得好听但做不到的人。多用于吐槽那些光说不练、承诺无法兑现的行为，含有吹牛、撩骚的意思。', '他总是在工作群里口嗨，说项目如何如何牛，但其实一进展就卡壳了。', ''],
  ['本以为是青铜没想到是王者', '“本以为是青铜，没想到是王者”用于形容一个人或者事情出乎意料地优秀或出色。最初认为其能力或水平较低，但经过接触或观察后发现其实极为厉害，是深藏不露的高手。', '他平常不怎么说话，大家都以为只是个普通人，没想到他在关键时刻站出来，解决了大问题，真是本以为是青铜，没想到是王者。', '该说法源于手机游戏《王者荣耀》，其中“青铜”是游戏中的最低段位，而“王者”是最高的段位。这样形成了一个对比强烈的反差，用于形容表面与实际能力的不一致。'],
  ['九头蛇万岁', '“九头蛇万岁”是九头蛇组织的标志性口号，通常用于识别成员或表示效忠。', '在漫展上，粉丝们纷纷扮演九头蛇成员，高喊“九头蛇万岁”。', '源自漫威宇宙中的反派组织九头蛇，特别在电影《美国队长》系列中多次出现。'],
  ['犹豫就会败北果断就会白给', '「犹豫就会败北，果断就会白给「是一个源自游戏文化的俚语，用来形容在面临困境时，不论是犹豫不前还是过于果断，结果都可能以失败告终。「犹豫就会败北「意味着在游戏《只狼：影逝二度》中，如果玩家在对抗剑圣苇名一心时犹豫，就很容易被击败。「果断就会白给「则是网友在讽刺性地扩展了这个说法，指出即便是果断也可能落得失败的命运，把资源或机会拱手让人。', '玩《只狼》的时候，我几次犹豫不前，果然就被苇名一心打败了，简直是「犹豫就会败北「的真实写照。', '「犹豫就会败北「来源于游戏《只狼：影逝二度》中剑圣苇名一心的台词。随后，玩家和网友们根据这一说法，结合「白给「这一来源于《CS:GO》的术语，创造了「果断就会白给「这一说法。'],
  ['删了让我说', '“删了让我说”是一种善意的调侃，表示自己的想法或评论被别人抢先发表的无奈和不甘心。', '看到热评写的跟我想的一模一样，我只能无奈地回复一句“删了让我说”。', ''],
  ['文化祭', '“文化祭”指日式校园中的一种文化活动，类似校园文化节，包括丰富多样的活动，如文艺表演、营业服务等，还常成为同学社交和告白的好时机。', '在文化祭上，班级出售手工艺品，同学们忙得不亦乐乎。', ''],
  ['OOC', 'OOC，全称“Out of Character”，指角色在同人创作或改编作品中行为言辞偏离原作设定，不符合角色个性或世界观，俗称“出戏”。', '在这篇同人小说中，主角突然变得无比温柔，简直就是OOC。', ''],
  ['亲儿子', '“亲儿子”或“亲女儿”是一个ACG（动画、漫画、游戏）用语，用来形容在游戏或其他ACG作品中，某个角色特别强力或受作者青睐的情况。这些角色拥有明显的优势，比如技能、剧情份额、好运和角色羁绊等，常表现得特别出色或重要，甚至有时超越主角。如果角色有明显优势且频繁出现在游戏中的剧情和版本更新中，可能被称为游戏公司的“亲儿子”/“亲女儿”。', '“在这部新番中，XX无疑是作者的亲儿子，每次关键时刻总能化险为夷。”', ''],
  ['失踪人口', '「失踪人口「原指登记过户口但下落不明的人，现在常用于调侃在Bilibili等弹幕视频网站上的UP主，指那些很久未更新内容的创作者。类似的用法也适用于贴吧、论坛、微博等社交平台。', '经过半年没有更新，UP主小明终于上传了新视频，弹幕纷纷刷屏“失踪人口回归”。', ''],
  ['绅士', '在传统意义上，“绅士”指温文有礼、品味高雅的男性。然而，在ACG（动画、漫画、游戏）文化中，“绅士”被用来指有独特兴趣爱好的“高等变态”，即在语气和思想上具备变态倾向但行为表现得绅士的人物。这种用法源自对带有反差萌的角色的一种戏谑描述。', '他总说喜欢收藏美少女手办的都是绅士，而不是普通的宅男。', '这个梗源于《搞笑漫画日和》，其中角色熊吉的一句名言：“我不是变态；就算是变态，也只是冠有变态之名的绅士！”（变態じゃないよ、仮に変態だとしても変態という名の紳士だよ！）'],
  ['就怕杠精有文化', '「就怕杠精有文化「是一种调侃和讽刺之语，最初的意思是对有文化且有理有据地挑错和批评的人的一种夸奖，但随着「杠精「一词的贬义色彩，它也逐渐被用来讽刺那些故意装出有文化的样子来抬杠的人，或者只是因为自己辩论不过而自我调侃一句。', '他总能在我自信满满时指出各种小错误，真的是就怕杠精有文化啊。', ''],
  ['说多了都是泪', '用来表达一件事情让人感到非常悲伤、无奈或痛苦，再多说只会更伤心。', '每次提到那段分手的往事，我总是无言以对，说多了都是泪。', ''],
  ['神仙组合', '“神仙组合”用来形容某个组合中的成员非常厉害、优秀且在某一领域中顶尖。这个词汇体现了一种对组合中成员实力的高度赞扬和喜爱。', '当听说周杰伦和阿信合作的新歌时，粉丝们兴奋地说：“这是什么神仙组合啊！”', ''],
  ['你为什么不问问神奇海螺呢', '用来调侃那些不愿自己动手找答案的人，表示不想回答。', '朋友老是问怎么做饭，我说：“你为什么不问问神奇海螺呢？”', '出自动画《海绵宝宝》。在一集中，海绵宝宝建议犹豫不决的章鱼哥“问问魔法海螺”。'],
  ['儿时不懂语中意此时已是话中人', '小时候不懂大人话里的深意，长大后经历类似情境才明白。', '小时候不明白为什么妈妈总和邻居叮嘱自己多吃饭，现在自己住在外地才懂得那份牵挂，真是“儿时不懂语中意，此时已是话中人”。', '源自“初闻不知曲中意，再听已是曲中人”，出自2017年刘若英演唱会后的微信公众号文章。'],
  ['我胡汉三又回来了', '「我胡汉三又回来了「是一句反映卷土重来的经典台词。通常用来形容一个人或事物在被打击后重新出现，尤其是在经历挫折或消失一段时间后，又重新站稳脚跟，常带有贬义或自嘲的意味。', '疫情期间这一家餐馆曾一度关闭，但现在他们硬着头皮重新开业了，真是应了那句：“我胡汉三又回来了。”', '这句话出自70年代红色电影《闪闪的红星》，是由反面角色胡汉三在电影中得意喊出的一句台词。他是一个地主恶霸，在经历行将被推翻的绝境后得以复出，再次挑战大众。因此，这句话被用来形容经历挫折之后的反扑或重新出现的情景。'],
  ['啥家庭啊家里有矿啊', '“啥家庭啊家里有矿啊”是用于讽刺或调侃别人很有钱，乱花钱不顾节俭的网络梗。常用于形容或吐槽别人似乎有很雄厚的经济背景。', '看他每天买那么多奢侈品，我都不敢想象，啥家庭啊家里有矿啊。', '该梗源自赵本山在电视剧《马大帅》中的一种表情，被制作成表情包。它因2018年俄罗斯世界杯期间很多赌球者输得很惨而流行开来，用来讽刺他们的奢侈行为。'],
  ['谢飞机', '“谢飞机”是对《乡村爱情》角色谢腾飞的调侃称呼，因其在剧中将自己的名字误说成“谢飞机”，且具有搞怪的演技和夸张的舞技，逐渐走红网络。这个角色的有趣特质以及尴尬时刻被广泛制作成表情包，受到网友热捧。', '今天心情不好，用谢飞机的表情包逗逗自己，瞬间好多了。', '出自电视剧《乡村爱情》，是角色谢腾飞创造的无心之语，被网络二次创作后广泛传播。'],
  ['求你做个人', '网络常见的吐槽语，用于讽刺或规劝心怀恶意的人变得善良。', '看到有人恶意抹黑明星，有粉丝评论道：“求你做个人。”', ''],
  ['这瓜保熟吗', '有三种含义：1. 表达一种威慑或警告，意指“别惹我，惹我就对付你”；2. 调侃孙红雷出演的角色，从黑社会大哥视角提醒他人小心；3. 用于表达对某事物或情况可靠性的疑问，比如“行不行”。', '你这样说话小心点，“这瓜保熟吗？”', '出自电视剧《征服》第九集，孙红雷饰演的角色刘华强与卖西瓜的小贩的一段经典对话。'],
  ['你大爷永远是你大爷', '“你大爷永远是你大爷”用于赞美一方，表示对方实力或地位不可动摇，通常带有对另一方的蔑视。', '他在公司里总能解决难题，你大爷永远是你大爷啊。', '该梗出自2006年春晚赵本山和宋丹丹合作的小品《说事儿》。'],
  ['我不尴尬尴尬的就是别人', '「我不尴尬尴尬的就是别人「这个梗的意思是，只要自己不在乎和不觉得尴尬，那么在尴尬场合中感到尴尬的人就会是别人，而不是自己。这种态度展现了一种自信和积极的姿态，意味着不让外界评价和他人对自己的看法影响到自身情绪和行为。', '在一场相亲会上，我高唱K歌，就算走调我也不在乎，因为我不尴尬尴尬的就是别人。', ''],
  ['淡人浓人', '“淡人”和“浓人”是一种网络用语，分别用来描述两种不同性格的人。淡人是指那些个性较为平稳、情绪不常剧烈波动的人，通常表现为淡泊名利、宁静致远。浓人则是指情绪丰富、表现外向的人，他们的言行举止充满表达情绪的词汇。', '我在公司表现得像个淡人，实际上朋友们都知道我是个地道的浓人。', ''],
  ['虾仁猪心', '“虾仁猪心”是“杀人诛心”的谐音梗，用来调侃和形容揭露、指责人的思想和动机。本意是指消灭肉体不如谴责动机，但在网络用语中，多用于游戏场景中，引申为攻击他人时意在击中对方的心理弱点。', '玩游戏的时候，他总是虾仁猪心，不仅打败我，还要说些让我气愤的话。', ''],
  ['芳心纵火犯', '「芳心纵火犯「指代让女生着迷、心动的男生，尤其用于迷妹们形容自己的爱豆。这类男生被认为能点燃心中的激情和浪漫情感。', '在粉丝眼中，他无疑是一个标准的芳心纵火犯，无论走到哪里都有一群迷妹为他疯狂。', '该梗最早出现在2017年3月，在明星推理真人秀节目《明星大侦探》中，撒贝宁自称为「芳心纵火犯「，声称他的魅力能够燃烧各年龄段女性的心。这一说法迅速走红，成为饭圈常用的形容词。'],
  ['我顶你个肺', '表达惊讶、不满或作为口头禅的一句广东俚语。在广东话中，也可作为骂人的话。', '甲：这款手机居然不用充电！      乙：我顶你个肺，这么厉害！', ''],
  ['是个狼人', '“是个狼人”指代比“狠人”更厉害、更狠的人，通常用于表达对某人或某事的惊讶、赞叹和佩服。这个网络流行语通过字面的字数比较，“狼人”的“狼”比“狠人”的“狠”多一点，形象地表示了程度更高的厉害。', '他连续三个通宵完成了所有代码任务，真是个狼人！', ''],
  ['糟了是心肌梗塞的感觉', '“糟了是心肌梗塞的感觉”是一种夸张表达，源于“糟了，是心动的感觉”，用于形容某事物或某人非常令人心动，甚至用心肌梗塞来形容心动程度之大。也可以用于表达一种反向幽默感，当某事物或行为夸张或搞笑到让人“窒息”时，也可以用这种说法表示。', '当他突然在舞台上微笑的时候，我忍不住想，糟了是心肌梗塞的感觉。', ''],
  ['白月光', '白月光指的是可望不可即的挚爱或理想的人事物，是一种理想化且无法真正拥有的存在，常常令人怀念和向往。', '在他心中，她永远是那道白月光，无论多少年过去，仍然是最深的牵挂。', '出自张爱玲的小说《红玫瑰与白玫瑰》，书中提到不同类型的女性并进行了象征性的比喻。该词在《延禧攻略》中被用来形容剧中乾隆皇帝心中对富察皇后的怀念，也让该词成为饭圈常用语。'],
  ['翻水水', '「翻水水「用来形容即将失败、面临困境或事情的结果即将糟糕的状况。最初在游戏对战中用于表示「这局要输了「，后来被引申为遇到大事或糟糕结果。', '人生在世，谁还没过几次翻水水的瞬间？', '「翻水水「来源于游戏《英雄联盟》的知名主播PDD，他曾使用“PDD翻皮水”来形容失败的游戏局面，后被网友简化为“翻水水”。这个词形象地比喻鱼儿翻肚子的状态，即面临生命危机。'],
  ['算了不骂人', '「算了不骂人「是一种通过心理建设和自我安慰的方式来调整心态，不与让自己生气的人或事较真的方法。它鼓励人们自我安慰，把别人想象成傻子或仅仅是会说话的人民币，以此来化解内心的愤怒和不满。', '面对无理取闹的客户，小王深吸一口气，心里说“算了不骂人”，这才没有跟对方争吵。', ''],
  ['不提也罢', '“不提也罢”用于表示某人或某事没有值得评论或详述的价值，表现了无奈、不愿讨论或评论的态度，相当于“一言难尽”或“算了，不说了”。', '在最近的会议上，某人的表现不堪回首，真是不提也罢。', ''],
  ['继承蚂蚁花呗', '形容某事特别好笑，同时自嘲经济状况不好，只能给别人留下蚂蚁花呗的负债。', '你这个笑话太好笑了，想把我笑死好继承我的蚂蚁花呗吗？', ''],
  ['原谅色', '原谅色指绿色，与“绿帽子”相关，象征着出轨后的宽容和原谅。', '在朋友的调侃中，他戴着一顶纯绿色的帽子，被戏称为原谅色。', ''],
  ['秀住了', '“秀住了”是用来夸赞某人的表演、操作或者行为十分出色的网络用语，尤其是在赞美某人的表现非常精彩时使用。这个词还可以用来讽刺那些表现不佳的人，类似于表示他们的表演像是在“秀”一样。', '在这场比赛中，他的操作真是秀住了，无可挑剔。', ''],
  ['人血馒头', '“人血馒头”这个梗用于讽刺那些通过踩低别人来获取利益或关注的人，行为卑鄙，无情。常用于批评利用他人的不幸、悲剧，或者通过伤害他人来提升自己的人。', '某明星去世后，很多不怀好意的人开始以各种方式炒作事件，网友评论：“这些人真是吃人血馒头，毫无底线。”', '该梗的现代使用来源于鲁迅先生的小说《药》。在小说中，有一个传说认为沾过人血的馒头可以治病，故事中主人公让孩子吃这种人血馒头以治病。鲁迅通过这个情节讽刺了当时人们对革命者的冷漠无情。而“人血馒头”这一说法也被延伸用来形容现代社会中一些不道德的行为。'],
  ['姨父笑', '姨父笑指的是一种慈祥、欢快的笑容，通常由年长者对年轻偶像的喜爱和宠溺的表现。类似于姨妈笑，是一种慈爱的花痴微笑。', '看到新剧里的帅气男主角，我忍不住姨父笑了。', ''],
  ['老太太钻被窝', '“老太太钻被窝”这个梗有两个主要含义：1. 形象地形容摔跤的动作，尤其是四脚朝天、屁股着地的那种姿势，类似于老太太进被窝时的动作；2. 作为歇后语，指劲小、力气不足或动作缓慢，意指做事太含蓄或没有用力。', '昨天打篮球时不小心滑倒了，摔了个“老太太钻被窝”，朋友们见状都笑得不行。', ''],
  ['没起色', '「没起色「用来形容一个人没有志气、颓废没落、懒惰消极、不努力、没有骨气、没有前途和希望，做事总是一事无成，是一种对人生活状态或性格的负面评价。', '「他整天啥也不干，就知道玩游戏，真是没起色。「', ''],
  ['停靠在八楼的二路汽车', '“停靠在八楼的二路汽车”是刀郎歌曲《2002年的第一场雪》中的歌词，指乌鲁木齐的公共汽车站“八楼”站。这个站名源自有46年历史的昆仑宾馆，是乌鲁木齐的一座地标建筑。', '我听了《2002年的第一场雪》，才知道二路汽车停靠在“八楼”是什么意思。', '刀郎的歌曲《2002年的第一场雪》。'],
  ['按在地上摩擦', '“按在地上摩擦”形容在对抗中双方实力差距明显，其中一方被另一方彻底击败，表现出毫无还手之力的状态。', '昨天的比赛真激烈，A队把B队按在地上摩擦，全程压制对手。', '该梗源自庞麦郎2012年的歌曲《我的滑板鞋》中歌词“摩擦摩擦，在这光滑的地上摩擦”。它后来被网友们运用在电子竞技比赛中，用来形容一方被另一方完全碾压的情景。'],
  ['和善的眼神', '「和善的眼神「是一个网络调侃用语，用来讽刺和形容那些看起来威胁性很强、阴森或充满敌意的眼神。表面上称为和善，实际上与善良和友善完全相反。', '他盯着我，目光犀利得仿佛能穿透人心，真是个“和善的眼神”。', '该梗最早出自动画《北斗神拳》第14集，其中角色拳四郎被误认为坏人，长老却通过他的眼神来判断他不是坏人，并称其为“和善的眼神”。这一具有讽刺意味的说法被网友们用来调侃那些并不和善的眼神。'],
  ['笑容逐渐缺德', '有两个含义：1. 做了一些调皮恶作剧或幸灾乐祸的事情，内心感到喜悦，用于自嘲；2. 笑到无法控制。', '我是买到限定的最后一个人，看着后面的长长队伍，我的笑容逐渐缺德。', ''],
  ['猥琐发育别浪', '“猥琐发育别浪”指做人要低调，避免冲动和炫耀。在游戏中，是劝告玩家不要冒险或过于自信，而是要积累实力，为后期做好准备。', '在团战中，他提醒队友：“猥琐发育别浪，等我们装备起来再打。”', ''],
  ['你膨胀了', '「你膨胀了「指一个人变得傲娇，觉得自己很了不起，有时带有轻蔑他人的态度。这个说法通常是用来开玩笑或调侃，表示对方因为某些成功或好事而变得自大。', '粉丝：爱豆你这么膨胀，以后跑通告就别坐飞机了，自己膨胀成氢气球来回穿梭吧。', ''],
  ['膨胀', '“膨胀”指人骄傲自满，获得一点成绩后洋洋得意。如今多用于自黑和自我调侃，不再是贬义，而是一种开玩笑的方式。', '今天我考试得了满分，感觉有点膨胀了。', ''],
  ['奥斯卡欠你一座小金人', '「奥斯卡欠你一座小金人「用于调侃某人表现夸张、戏多，好像他们的演技应该获得奥斯卡奖。可以是赞美演技高超，也可能是讽刺他们爱博眼球。', '你刚才那段表演太精彩了，奥斯卡欠你一座小金人！', ''],
  ['清华北大选一个', '表示某人在某方面极具才华或能力，通常为赞美或调侃。', '这个小朋友居然能自己编程序，清华北大选一个吧！', ''],
  ['不准套娃', '“不准套娃”指禁止反复套用别人的话，造成无休止的循环。这种行为被类比为俄罗斯套娃的层层套嵌。', '他们在聊天时不停地互相套娃，让人觉得话题永远没有尽头，所以有人突然说“不准套娃”来结束这个循环。', ''],
  ['我怀疑你在偷窥我的生活', '这个梗用来表达一种被说中心事的感觉，像是自己的生活被别人窥视了一样。通常是用来调侃别人对自己的描述非常准确，有趣地表明别人“监控”了自己的生活。', '“你刚才说的那些简直就是我的日常，我怀疑你在偷窥我的生活！”', ''],
  ['你是不是在我家装了监控', '这个梗用于表达当别人说出的某些描述或感受与自己的现状高度契合时，产生一种被窥探或监视的感觉。用这个表达方式来调侃自己被“说中了”，往往是为了增加幽默感和氛围。', '「今天刷到一个帖子，内容跟我最近的状况一模一样，我都怀疑是不是在我家装了监控。「', ''],
  ['但凡吃点花生米', '“但凡吃点花生米”用来讽刺某人做梦或反常表现，意指像喝醉酒的人那样不着边际地说胡话。它劝告人们要清醒，不要做白日梦。', '他又在谈论要当亿万富翁的事情了，但凡吃点花生米，他也不会说这样的话。', ''],
  ['来人把他麦给我闭了', '“来人把他麦给我闭了”是一种要求对方立即停止说话的口头表达，多用于提醒对方言辞不当。这句话通常用于直播或语音聊天中，意指关闭麦克风来让对方不再说话。', '主播在直播间里对捣乱的观众说：“来人把他麦给我闭了，这里不欢迎说这些话的人。”', ''],
  ['铁汁萌', '“铁汁萌”是“兄弟们”的谐音，表达一种感慨和亲切的称呼。', '“铁汁萌，昨晚的比赛太精彩了，我们下次接着看！”', ''],
  ['蹦就完事了', '「蹦就完事了「表示一种无忧无虑、不加思索的态度，类似于一种口头禅或调侃，暗示别过于考虑，直接行动。', '这个项目有点复杂，总觉得计划赶不上变化，不如蹦就完事了。', ''],
  ['钱不钱的无所谓', '“钱不钱的无所谓”表面上表示对金钱无所谓，但实际上表达了一种对金钱的强烈关注和追求。它通常是以幽默的方式来展现对金钱的渴望。', '我想坐在奔驰里面哭。钱不钱的我无所谓，我主要是喜欢哭。', ''],
  ['寿命论', '寿命论是指在作品中具有不同寿命的一对角色之间的悲伤情节，通常一方寿命短暂，另一方寿命长久，最终导致一方注视着另一方先死去。这种情节引发对角色未来命运的思考，表达出岁月无情对深厚感情的冲击。', '在《东方Project》中，永琳和辉夜姬之间永恒却又充满忧伤的关系被粉丝称为“寿命论”的典型代表。', ''],
  ['三集定律', '三集定律是一种评估动画是否值得继续观看的标准，通常在观看到第三集时做出决定。如果在第三集出现剧情突变或引起强烈兴趣，则通常会继续观看；否则可能选择放弃。', '朋友推荐了一部新番，但我决定遵循三集定律，看完前几集再决定要不要追下去。', ''],
  ['影帝影后', '“影帝/影后”在网络用语中指那些擅长伪装自己真实意图的角色。这个词用来描述一个人为了达到目的所进行的佯装、欺诈或表演。该词可以表达对角色演技的惊叹或对其内心狡诈的讽刺，也常用来描述心口不一的政客和双面性格人物。', '这部剧的男主每次转身后的表情变化太快了，简直是影帝级别的反应。', ''],
  ['卧槽无情', '「卧槽无情「是一句调侃用语，带有搞怪意味，常用于表达惊讶、疑惑或愤怒等多种情绪。', '当他得知自己彩票中大奖后，他下意识地说：“卧槽无情，居然真中了！”', '该词最早出自快手网红“二龙湖二哥”视频。在该视频中，二龙湖二哥以搞怪的形象和幽默风格说出了这句台词，随后被添加上魔性音乐广泛传播。'],
  ['妈妈我想吃烤山药', '“妈妈我想吃烤山药”是一个来源于抖音的梗，模拟一段孩子向母亲请求买烤山药的对话，用于形容那些有异想天开、做白日梦倾向的人。', '朋友说他要中彩票，别人就用调侃的语气说：“妈妈，我想吃烤山药。”', '源自一位网友拍摄的卖烤山药的广告视频，视频中模仿了孩子和母亲的对话。此广告在抖音上流传甚广，之后网友对对话进行了各种改编和恶搞，使其成为流行梗。'],
  ['铁锅炖自己', '表示歉意或形容处于不利和压力重重的环境中。', '我错了，真是铁锅炖自己，希望你能原谅我。', '电影《羞羞的铁拳》，由马丽饰演的角色在社交媒体上发布的视频。'],
  ['匡扶汉室', '“匡扶汉室”这个词已经成为《全面战争：三国》这款游戏的代名词，指的是玩家沉迷这款游戏，希望在游戏中实现刘备“匡扶汉室”的理想。', '最近工作效率特别低，不是我懒，只是心中只想匡扶汉室。', ''],
  ['手动狗头', '「手动狗头「用于表示评论内容为反讽，提醒读者与所说之话相反，常常用来避免误会或误伤友军，表示“我是友军/忠装反，别打我”。', '这次笑话绝对是我今年听的最好笑的笑话，真的完全笑不出来，手动狗头。', '该梗来源于微博更新后出现的一个基于doge脸设计的表情符号。由于doge表情自带一种魔性且具有强烈的嘲讽感，用户在发表反话时经常在文末附上此表情以示反讽和戏谑。后来，文字化的“手动狗头”代替这些表情符号，被经常用作警示用户内容是反话，特别是在懒惰或不便使用图片的情况下。'],
  ['按闹分配', '「按闹分配「是一个用来批评和讽刺那些通过无理取闹、扰乱公共秩序来获取利益的社会现象的网络用语。这种行为通常被形容为“会哭的孩子有糖吃”，意指通过不当手段达到目的。此外，这一说法也用来形容部分情况下，由于某些机构的不作为，人们不得不通过“闹”来争取本应得到的合法权益。', '张三在会议上一直打断别人发言，结果领导为了息事宁人，按照“按闹分配”的原则答应了他的无理要求。', ''],
  ['梁静茹给的勇气', '用于嘲讽别人哪来的勇气说出某些话或做出某些事，暗指不合适或者过于大胆。', '你敢当众表白，是梁静茹给的勇气吗？', '源于2017年梁静茹发微博晒自己做的午餐，图中汤里有一只没削皮的小土豆。许多网友留言询问为什么不削皮，梁静茹起初翻牌回应，但后来生气地表示自己喜欢这样吃。随后，有粉丝调侃道：“谁给你的勇气问梁静茹土豆削没削皮？梁静茹吗？” 这个梗巧妙结合了梁静茹的经典歌曲《勇气》，迅速走红。'],
  ['想要什么颜色的麻袋', '表达对某人或某事的喜爱，幽默地问对方想要什么颜色的麻袋，象征“绑走”带回家。', '这个小朋友太可爱了，想问他想要什么颜色的麻袋。', ''],
  ['当个人吧', '“当个人吧”是一种提醒或规劝他人注意其言行表现的表达，主要用于讽刺言辞粗俗或恶毒的人，并可以用来对不道德的行为表示愤怒或谴责。', '在该帖子下看到一些恶意评论后，他忍不住留言：“当个人吧，这种话也说得出口？”', ''],
  ['阿姨我不想努力了', '“阿姨我不想努力了”是一个用于调侃的网络梗，通常指男生希望通过被年长的、富有的女性包养而摆脱生活压力。这句话常用于表达男生在面对现实生活的压力与挫折时的一种自嘲和无奈。', '每天加班到深夜，真的好累啊，阿姨我不想努力了。', ''],
  ['邪魅狂狷', '“邪魅狂狷”是用来形容那些在网络小说中常见的霸道总裁、黑道少主或商界精英等角色的一种气质。这个词强调他们具备强大的潜在能力和魅力，能够超然地处理事务，并常常无视法律与社会常规。同样，他们的举止既豪放又自律，对待规矩有选择性地遵守。', '他一进门，所有目光都聚焦在他身上，那种邪魅狂狷的气质让人无法忽视。', ''],
  ['爆炸吧现充', '“爆炸吧现充”是一种怨恨并带有玩笑性质的表达，意指那些生活充实的人去死吧。这种说法反映了宅对现充（现实生活丰富多彩的人）的羡慕和嫉妒。', '看着朋友圈又有人出国旅游，真想说“爆炸吧现充”！', ''],
  ['老虚', '「老虚「是对日本编剧家虚渊玄的昵称，因为他以创作黑暗、悲剧性故事而闻名。他的作品常常涉及角色死亡和沉重的情感，所以他的名字被用来形容任何在动画或影视作品中触发死亡flag的剧情。', '在看到主角推倒重伤的反派时，观众们纷纷调侃：“快按住老虚，不要让他再推动剧情反转了！”', ''],
  ['强行水逆', '“强行水逆”指假装在水星逆行期间，把自己的不顺归咎于水逆现象，找借口安慰自己。', '今天丢了钱包，我只能强行水逆，说服自己这是因为水星逆行。', ''],
  ['互联网不是法外之地', '指在网络空间中必须遵守法律法规，不能任意发布不当内容，如虚假、诈骗、攻击、恐怖、色情等行为。', '有人散布恶意谣言，小心被举报，互联网不是法外之地。', '出自习近平总书记在网络安全和信息化工作座谈会上讲话的内容。'],
  ['祖师爷赏饭', '“祖师爷赏饭”是一个网络用语，用来形容一个人在某一领域拥有令人难以企及的天赋或与生俱来的条件。这些条件是后天努力无法改变的，使得他们在该领域中能够轻松取得成功。如果拥有这些天赋的人还特别努力，就更让人望尘莫及。', '她刚出道就拿下了演艺界的大奖，真是祖师爷赏饭，这样的天赋让人不得不服。', ''],
  ['奈何本人没文化', '「奈何本人没文化「是用于表达在面对令人惊叹或难以用言语描述的事物时，因词汇匮乏而只能简单感叹的幽默说法。它反映了一种故作自嘲的态度，用于快速表达赞叹与惊讶。', '在高山之巅，看着日出绚丽多彩，我却无言以对，只能心中默念：“奈何本人没文化，一句卧槽行天下。”', ''],
  ['抄作业式旅行', '抄作业式旅行指的是那些不愿意自己做详细旅行计划的人，出发前匆忙在网上搜索或购买别人已经做好的旅行攻略，就像考试时抄别人的作业一样。', '小李一直说要去日本旅行，但他好懒得查资料，到了最后一刻只好抄作业式地买了个现成的旅行攻略。', ''],
  ['我家猫会后空翻', '「我家猫会后空翻「用于以幽默和间接的方式邀请别人到自己家里，尤其在约会场合中，通过描述一种稀奇的情景引起对方的好奇心，引导对方接受邀请。它暗示了一种目的性较强的邀约，但形式上更加轻松和幽默。', '和新认识的朋友聊得很投缘，他笑着对我说：“我家猫会后空翻，你要不要来看看？”', ''],
  ['饮水机管理员', '“饮水机管理员”用来形容团队中那些几乎没有上场机会、被边缘化的正式成员，他们只能在团队中打杂或做后勤工作。', '自从那次失误以后，小李就被调去当饮水机管理员了，再也没上过场。', ''],
  ['国师所言极是', '“国师所言极是”表示对某人意见或观点的高度认可。这句话一般用于评论区表达对视频内容或评论的赞同，或者认为某个评论者的发言非常准确。', '在一个分析时事的短视频评论区，有网友详细解释了某政策背后的影响，获得了很多点赞，楼下一位用户评论说：“国师所言极是，我也觉得这个解读很透彻。”', ''],
  ['用魔法打败魔法', '“用魔法打败魔法”指的是以某种方式或工具对抗并解决同类问题，强调以其人之道还治其人之身。', '在网上，一个游戏玩家使用作弊工具对抗其他作弊者，评论区纷纷传来“用魔法打败魔法”的声音，调侃其以同类手段应对问题。', '这个梗出自动画片《成龙历险记》，片中角色老爹通过使用反派的魔法战胜反派后，询问其他角色学到的教训，众人异口同声回答“必须用魔法打败魔法”。'],
  ['六人定律', '六人定律指的是你和世界上任何一个人之间最多只相隔六个中间人，通过这些中间人即可建立联系。', '我好想认识那位明星，不过放心，按六人定律，我一定能找到人帮我牵线。', ''],
  ['地狱模式', '“地狱模式”指游戏中的最高难度等级，需要极高水平才能完成，也用于形容在生活中遭遇极大阻力或恶劣环境。', '今天的早高峰简直是地狱模式，地铁站挤得水泄不通。', ''],
  ['云养娃', '「云养娃「指的是不愿意或无法在现实中生养小孩的人，通过网络观看萌娃视频和图片来暂时满足对养娃的渴望。', '每天下班后，她习惯“云养娃”，看着小宝宝的视频放松心情。', ''],
  ['整活', '“整活”是指开始表演或做一些出人意料或特别的事情。这可以理解为“搞事情”或者“开始行动”的意思。', '今天聚会，我们一定要整点活，来一场不一样的K歌比赛。', ''],
  ['你是闰土我是猹', '表示我一直喜欢你，追随你，心甘情愿被你伤害，甚至愿意被支配。', '他对她表白时说：“你是闰土我是猹，我心甘情愿被你支配。”', '源自鲁迅的小说《少年闰土》中角色闰土与猹的关系，在故事中闰土的工作是看守瓜田，但猹经常偷瓜吃，所以闰土经常会拿着钢叉刺猹。后来有网友将闰土和猹的故事改编成了爱情故事，还写成了一首歌《闰猹抄》，大概意思是猹其实很喜欢闰土。'],
  ['你这是在玩火', '指挑逗或者游走在危险边缘。', '她故意靠近他，笑着说：“看看你会怎么办。”他冷冷回应：“你这是在玩火。”', '源自霸道总裁类型的文学作品，男主角在面对喜欢的女生的一些行为和话语时会说：女人，你这是在玩火！意思是：你这是在激起我的欲望。'],
  ['你品你细品', '“你品你细品”指的是仔细品味某事物，因为它可能包含更深层的意义或暗示。看表面可能无法发现其中的内涵。', '这个产品宣传说比任何品牌都好，你品你细品，是不是真的呢？', '源自网络上一段搞笑视频，视频中男子劝老婆不要买包，最后让老婆在买包和买房两个选择中思考，用“你品，你细品”来让她细想其中的意义。'],
  ['拉胯', '“拉胯”是一个北方方言，意指在关键时刻掉链子或表现不佳。', '昨天的比赛关键时刻，他突然拉胯，全队都很失望。', ''],
  ['你就是个弟弟', '“你就是个弟弟”是用来形容某人能力不足、资历浅或者没有地位的表达方式。通常带有轻蔑和调侃的意味。', '在游戏中嘲讽对手时，你可以说：“你就是个弟弟，还敢来挑战我？”', ''],
  ['我缺这点流量吗', '“我缺这点流量吗”是用来调侃那些在关键时刻截断视频的博主，表达自己对没有看到完整内容的不满和对流量控制的不屑，意指我有足够的流量，你不用担心流量问题，尽管把完整视频放出来。', '当这个探险视频在最精彩的地方结束时，我直接在评论区留言：“我缺这点流量吗，把后面的放出来！”', ''],
  ['贩卖焦虑', '“贩卖焦虑”是指通过各种宣传手段（如文章、视频等），故意夸大或制造人们对某些事情的担忧，从而获取关注度、流量或直接的经济利益。', '某些自媒体账号常常贩卖焦虑，用似是而非的健康建议来吸引流量。', ''],
  ['抢七', '“抢七”指在比赛中，当双方打成平局进入决胜局时，争夺该决胜局的胜利。最初源于网球比赛中的第七局决胜局。', '在那次激烈的网球比赛中，双方进入抢七，观众的心都提到了嗓子眼。', '网球比赛，当比分为6:6时进入的决胜局。现用于其他体育比赛，如篮球、台球等。'],
  ['自信点去掉可能', '“自信点去掉可能”表示对于某种结果充满信心，认为该结果必然发生，不要再存有侥幸心理。', '“我今天没带伞，可能会被淋湿。”      “自信点，去掉可能。”', ''],
  ['相望于江湖', '“相望于江湖”表示彼此在世间远远地关心着对方，但不打扰。说明双方仍关注对方的动态，虽不在一起，却也不曾忘记。', '分手后，他们选择相望于江湖，不再联系却默默祝福对方。', '源自对成语“相濡以沫，不如相忘于江湖”的演变，原成语出自《庄子·内篇·大宗师》及《庄子·外篇·天运》。'],
  ['在爱河里搓澡', '“在爱河里搓澡”是一个网络流行梗，用来形容两人处于甜蜜而幽默的恋爱状态。它不仅表达恋爱中的幸福感，还带有一点幽默和沙雕的意味。', '每次看到他们俩的互动，我总觉得他们是在爱河里搓澡，甜蜜又搞笑。', '这个梗最初来源于一位女生形容明星范丞丞、Justin和朱正廷的关系，像是在爱河里互相搓澡，而非单纯坠入爱河。之后，网络视频作者“十九万少女的梦”剪辑了日剧《我是大哥大》中京子和伊藤的恋爱片段，命名为“京子跟伊藤今天也很努力在爱河里搓澡鸭!!!”，从而让这句话在网络上流行起来。'],
  ['把你骨灰给你扬了', '用来表达愤怒或不满的情绪，是一种极端的警告或威胁。', '你再这样挑衅，我可要“把你骨灰给你扬了”！', '出自快手用户“刀弟”，他在与人争论时虽面带微笑，但语气警告性地说出这句话。'],
  ['遍地都是ETC', '“遍地都是ETC”这个梗指很多人喜欢唱反调或抬杠，形容身边有太多不友好或喜欢争论的人。这是一种隐晦且诙谐的讽刺，用来描述网络上喜欢争论的现象。', '在论坛上发个帖子总有人抬杠，真是遍地都是ETC啊。', ''],
  ['全网无前任有也不承认', '“全网无前任，有也不承认”通常用于营造一种幽默和轻松的氛围，表达在感情上无牵无挂的潇洒态度。即使有前任，也可以当作没有。', '在社交媒体上，他写道：“全网无前任，有也不承认，希望大家多多指教！”', ''],
  ['吸渣体质', '「吸渣体质「指的是那些在恋爱中总是容易被渣男或渣女吸引的人，这些人通常是感情受到玩弄的爱情傻瓜。尽管不断遭遇不认真对待感情的人，他们还是会一再陷入这种关系。', '她总是抱怨自己的吸渣体质，每段恋爱都以失望告终。', ''],
  ['我是你的破壁人', '“我是你的破壁人”指的是我能看透你的想法，了解你的真实内心。', '他一眼就看出了我的伪装，果然是我的破壁人。', '出自刘慈欣的科幻小说《三体》。在小说中，地球为对抗三体人实施了“面壁计划”，让面壁人独立策划反制方案，三体人通过智子监控地球，但智子无法读取人类的内心。为了破解面壁人的真实意图，三体组织从叛变的人类中选出了4位“破壁人”，专门负责揭露面壁人的策略。'],
  ['翻车鱼', '“翻车鱼”现在常用于形容性格敏感纤细、胆小容易惊慌不安的人，尤其是社交恐惧症患者。', '他在聚会上总是站在角落，活脱脱一个翻车鱼。', '源于翻车鱼生活习性的谬传，描述其因各种心理原因而死亡的搞笑内容。这些描述因反差萌而广为流传，尽管后来有人辟谣，但“翻车鱼”胆小和社恐的形象已经深入人心。'],
  ['只有0次和无数次', '“只有0次和无数次”指的是某些行为或习惯一旦开始就会不断重复，具有极强的成瘾性和吸引力。这意味着某件事要么从未发生，要么一旦发生就会频繁出现。', '对于熬夜工作这件事，真的是只有0次和无数次，明明知道对健康不好，却总是改不了这个习惯。', ''],
  ['我方水晶', '“我方水晶”用来指代需要保护的对象，意指某人是自己人，需要被保护和守护。', '「她是我在恋爱中的我方水晶，必须好好保护。「', '该梗源自游戏《王者荣耀》，游戏中“水晶塔”是主要的防守和进攻目标。玩家需保护己方的水晶塔不被摧毁，并努力摧毁对方的水晶塔。'],
  ['求翻牌', '“求翻牌”是指评论者渴望博主能回复自己的评论，表达对博主的喜欢和希望获得互动。', '看到你更新了，赶紧来求翻牌，希望这次能被看到！', '源自古代皇帝翻牌选择妃子陪伴的习俗。电视剧《步步惊心》中，吴奇隆与粉丝互动，“翻牌”成为得到明星或博主回应的代称。'],
  ['给秀儿削个苹果', '“给秀儿削个苹果”用于赞赏评论中看法犀利、分析到位的人，对他们表示极度认可和重视。', '他那句点评太精准了，给秀儿削个苹果！', ''],
  ['驴粪蛋子表面光', '指人或事物表面光鲜亮丽，但实际上没有内涵，徒有其表，常用来形容虚伪或注重外表但忽略内在的情况。', '他的新项目看起来很不错，但深入了解后才发现是驴粪蛋子表面光，没有实际内容。', ''],
  ['酸爽', '“酸爽”是一种复杂的感受，包含酸涩与清新的双重感觉。形容某种体验虽然有些刺激或不适，但同时又有一种愉悦或满足的感觉。', '看完这场紧张刺激的冒险片，这酸爽，过瘾！', '该词最早来自湖南卫视主持人汪涵为老坛酸菜方便面代言时所用的广告词：“这酸爽，不敢相信！”'],
  ['疯求了', '“疯求了”是指“疯了”的意思，是四川、重庆、山西等一些地区的方言，用于表达对某事或某人的极度无语或震惊。', '昨天看到一个人居然在雪地里穿短袖，真是疯求了。', ''],
  ['出离愤怒', '“出离愤怒”指极度愤怒，愤怒到极致，甚至超越了愤怒的感觉，达到一种无法再愤怒的状态。', '当我得知那个项目被无故取消时，我感到出离愤怒，几乎说不出话来。', '该词语出自鲁迅的作品《记念刘和珍君》，文中鲁迅形容一种极致的悲凉与愤怒状态。'],
  ['雪崩时没有一片雪花是无辜的', '“雪崩时没有一片雪花是无辜的”意思是每个人在群体行为中都有责任，即使觉得自己的影响微乎其微。这个说法强调个人在集体中的责任。', '在环境污染的问题上，我们都不能推卸责任，正如雪崩时没有一片雪花是无辜的。', '出自《伏尔泰语录》中的一句话：“雪崩时，没有一片雪花觉得自己有责任”。'],
  ['扑克脸', '「扑克脸「指的是面部表情非常冷漠、无表情，给人一种距离感，难以透露情感或情绪变化。它可以用来形容一个人在特定场合下（如面对陌生人或竞争对手）保持冷淡、不泄露内心情绪的面部状态。', '小李在会议上一直保持扑克脸，让其他同事看不出他的真实想法。', '「扑克脸「来源于牌类游戏中的一种技巧。打扑克时，为了不让对方猜测手中牌的好坏，玩家会刻意保持无表情的状态。这种状态就被称为「扑克脸「。'],
  ['未知全貌不予置评', '“未知全貌不予置评”表示因不了解全部情况，所以不随便发表意见。这反映出一种谨慎和客观的态度。', '在网上看到新闻后，我决定未知全貌不予置评，避免误解真相。', '出自电视剧《陈情令》。蓝忘机在魏无羡推测晓星尘事件时说：“不知全貌，不予置评”。'],
  ['没毛病', '“没毛病”是一句用来调侃的网络用语，意思是指某件事情或某个人实际上是有问题、有毛病的，通常用来形容那些让人无言以对、啼笑皆非的情况。', '当朋友参加了一场节奏极慢的马拉松比赛后，拿到最后一名，但他却豪言壮语称：“我这是为了享受沿途风景，就是不夺冠又怎样？”旁边的朋友无奈地说：“哦，没毛病。”', '该词出自2016年辽宁卫视春晚，宋小宝的小品《吃面》。在小品中，一名服务员向老板解释顾客不付钱的原因，老板笑着称“没毛病”，这一情节让观众捧腹大笑，之后该词迅速走红网络。'],
  ['时间是把杀猪刀', '「时间是把杀猪刀「是一句网络流行语，形象地将时间比喻为无情的“杀猪刀”。这一比喻用来感叹岁月的残酷无情，它不仅在容颜上留下皱纹，也让曾经美好的事物和过去的情感变得物是人非。这句话表达了对光阴飞逝和岁月流逝的感慨，告诫人们要珍惜当下。', '看着老照片，不得不感叹，时间真的是把杀猪刀啊，我都快认不出曾经的那个自己了。', ''],
  ['整段垮掉', '“整段垮掉”是一种自嘲或吐槽的表达方式，用来形容某段描述或情境非常尴尬无趣，没有任何效果。这句话常用于找台阶、找梗，或对困境的调侃。', '在朋友们面前讲了一个冷笑话却没人笑，我只好无奈地说：“哎，整段垮掉。”', '该词最早出自薛之谦在综艺节目《火星情报局》中的常用口头禅。'],
  ['踢到铁板', '“踢到铁板”指以为对方容易对付，结果发现对方很强大，自己反而吃亏。它也作为一种提醒，提示做人要低调，不要随意招惹别人。', '他以为对手是个新人，没想到经验丰富，比赛中彻底踢到了铁板。', ''],
  ['古墓派公知', '“古墓派公知”形容那些认知水平落后、用过时手段宣扬他国优越的公知，实际上是不切实际的盲目吹捧他国并贬低中国的人。', '这篇文章说巴黎街头免费发放葡萄酒，感觉像是出自古墓派公知之手。', ''],
  ['核能打火机', '“核能打火机”是用来吐槽恐怖游戏或解谜游戏中道具打火机的不科学设定。在游戏中，打火机常作为唯一的光源，能在长时间的游戏过程中始终保持亮度，燃料似乎用之不竭，像是由核能驱动一样。', '玩这款恐怖游戏时，主角一直拿着核能打火机，走遍整个鬼屋都不必担心光源问题。', ''],
  ['一袋米要抗几楼', '“一袋米要抗几楼”是《火影忍者》中角色长门（佩恩）台词（痛みを感じろ，意为“感受痛苦吧”）的搞笑音译版。原句是关于痛苦和和平的深刻讨论，这个梗却通过音译将其变得幽默和无意义。', '每次听到“一袋米要抗几楼”，就想起长门那段让人痛彻心扉的演讲，真是又好笑又深刻。', ''],
  ['咕杀', '咕杀（くっ殺）=咕…杀了我吧！（「くっ…殺せ！」），指代女战士或女骑士在战败后，表达“士可杀不可辱”的精神。这句话表示宁死不屈，意为“杀了我吧”。', '在这款游戏中，女骑士的经典台词“咕杀”让玩家印象深刻。', ''],
  ['哈士奇大眼睛', '形容人因愤怒或其他情绪而睁大眼睛，并因此与哈士奇犬的表情相似。', '她一生气就瞪着哈士奇大眼睛让人有些害怕。', '美国喜剧犯罪类电视剧《致命女人》，角色Jade在第九集中被背叛后愤怒地看着男友，男友形容她的眼神为「crazy eyes「，字幕翻译为“哈士奇眼睛”。'],
  ['杀疯了', '“杀疯了”是形容某个人做某件事的程度或某件事发展的程度极高。', '那位游戏主播昨晚连续五杀，粉丝都说他杀疯了。', ''],
  ['坏起来了', '「坏起来了「是对「好起来了「的反向玩梗，用于调侃或讽刺。当主播取得优势时，反而说“坏起来了”，表现一种幽默的反向。', '主播刚刚拿下三杀，弹幕却纷纷刷屏“坏起来了”，让大家捧腹大笑。', ''],
  ['好起来了', '“好起来了”表示情况有所改善或变好。在电竞直播特别是《英雄联盟》（LOL）直播中，当主播或选手取得优势时，观众通常会在弹幕中刷这句话。同时，一些调皮的观众会反向操作，在主播处于劣势时刷“好起来了”，或在主播优势时刷“坏起来了”，以此进行调侃。此外，这句话也用于表达一个主播人气上升时的欣喜。', '在这场紧张的LOL比赛中，红方终于拿下大龙，弹幕纷纷刷起“好起来了”来为他们庆祝。', ''],
  ['彳亍口巴', '“彳亍口巴”是“行吧”的拆字表达，具有一种无奈妥协的意味，表示在不情愿的情况下勉强同意或妥协。', '朋友再次发生了重复犯错的情况，我实在无话可说，只能“彳亍口巴”了。', ''],
  ['我想把这玩意儿染成绿的', '想通过把头发染成绿的来变得酷炫吸引异性，具有讽刺和搞笑的意味，因为绿色在文化中另有“戴绿帽”的意思。', '每次提到要染发，我脑袋里就立刻浮现出“我想把这玩意儿染成绿的”。', '电视剧《家有儿女》，刘星的台词。'],
  ['床前明月光', '“床前明月光”原本是李白诗作《静夜思》的一句诗，用来描述一种略带乡愁和思念的情感，现在常被用来形容心中清纯、难以忘怀的爱人。同时，它也是广播节目《一些事一些情》的粉丝之间用来相互识别的暗号。', '在广播节目《一些事一些情》的论坛上，有人发了暗号“床前明月光”，立刻就有粉丝接上“恭喜发财”进行互动。', '有三个出处：1. 李白的《静夜思》：诗句表达了对故乡和寂寞情感的思念；2. 张爱玲的小说《红玫瑰与白玫瑰》：借用来表达两种女性在男性心中的地位；3. 广播节目《一些事一些情》：节目粉丝之间的互动暗号。'],
  ['听君一席话白读十年书', '“听君一席话，白读十年书”是一种讽刺的表达，用来形容某人说的话充满常识错误或逻辑混乱，令听者感到自己的知识毫无用处。此表达戏谑地指出，说话人的观点与令人难以理解或与科学常识相悖。', '当某位嘉宾在节目中极力推销伪科学产品时，网友评论：“听君一席话，白读十年书。”', ''],
  ['同一片海', '「同一片海「指的是同一个圈子或世界，表达对某个话题或文化的共同理解和共鸣。', '当大家讨论起最新的网络热点时，我忍不住插了一句，结果发现全员都在同一片海，大家都笑了。', '源自村上春树的小说《舞！舞！舞！》。在书中，村上春树写道：“不是所有的鱼都会生活在同一片海里”，表达了每个人有自己的生活和世界，不一定都能产生共鸣。'],
  ['这届网友不好带啊', '“这届网友不好带啊”这个梗用来调侃网友们在网络上的犀利评论和不按常理出牌的行为。表达网友们表现出幽默、机智和难以预料的嘴炮能力，有时候评论中直指事件槽点，令人捧腹。', '某明星微博自称自己减肥成功，图片中却有修图痕迹，网友评论：“ps瘦身效果不错”，随后有人回复：“这届网友不好带啊！”', ''],
  ['偷心盗贼', '「偷心盗贼「用来形容一个人对另一个人产生了强烈的爱慕或者喜欢，心被对方“偷走”，因而将对方称作“偷心盗贼”。', '听了他给我的表白，那种调皮又略带霸道的语气让我忍不住称他为“偷心盗贼”。', ''],
  ['这背太适合拔火罐', '用夸张和调侃的方式赞美他人背部好看、吸引人。', '在一个健身博主晒出背部锻炼成果的视频下，有人评论：“这背太适合拔火罐！”', ''],
  ['上头', '「上头「通常指因某种刺激或影响而产生的亢奋状态，或是在冲动下不理智地行动。可以是因酒精或其他物理刺激引发的头晕状态，也可以是被某个想法、音乐、视频等内容吸引并重复在脑海中引起兴奋或模仿的状态。目前多指第二种。', '这首新歌我循环了无数次，旋律实在是太上头了。', ''],
  ['正经人谁写日记啊', '“正经人谁写日记啊”这个梗的含义是讽刺或调侃，人们通常不会把自己的真心话写在日记里，因为日记可能会被看到或泄露，因此不大可能写出真实的内心想法。', '今天我把所有的吐槽都写进日记里，越写越觉得“正经人谁写日记啊”。', '该梗来源于姜文编剧和导演的电影《邪不压正》。在电影中的一段对话中，角色用这句话来讽刺蒋介石，指他的日记不是真心话，而是一种为自己辩解的工具。'],
  ['今天晚上打游戏不', '“今天晚上打游戏不”通常用于邀请对方一起玩游戏，有时也可能含有挑衅或开玩笑的意味。', '好久没一起玩了，今天晚上打游戏不？', ''],
  ['夹枪带棒', '“夹枪带棒”用来形容说话讽刺、伤人，语言中像藏着武器一样尖锐不友好。', '在网上讨论时，他总是夹枪带棒地评论别人，让人难以接受。', '该成语出自《红楼梦》第三十一回中袭人的一句话：“姑娘倒寻上我的晦气。又不像是恼我，又不像是恼二爷，夹枪带棒，终久是个什么主意？”'],
  ['我真的一滴都没有了', '这个梗用于形容某种物质或精神状态已经枯竭，可能是金钱、情感、精力或其他资源的耗尽，表达一种“我已经无力再承担”的状态。', '这部电视剧太虐心了，我真的一滴眼泪都没有了。', ''],
  ['忍一时卵巢囊肿退一步乳腺增生', '这个梗用于警示女性不要压抑情绪，应适当发泄，以维护健康。', '她总是不愿意跟人争执，真担心她会“忍一时卵巢囊肿，退一步乳腺增生”。', ''],
  ['无痛当妈', '「无痛当妈「指的是在不经历实际生育和抚养孩子的痛苦情况下，直接享受当母亲的快乐。粉丝常用这个词来描述他们喜爱偶像的可爱之处，尤其是那些年龄较大的女性粉丝面对比自己小很多的偶像时，感受到如同母亲般的保护欲和亲切感。', '「看到这个小奶娃般的爱豆，实在忍不住‘无痛当妈’的冲动，真是太可爱了！「', ''],
  ['吃灰', '“吃灰”形容某物长时间闲置不用，积累灰尘。', '自从买了新游戏机，旧的就一直在吃灰。', ''],
  ['散装英语', '“散装英语”指的是人们在使用英语时，语法和句子结构混乱、不完整，给人一种不成句、不成文的感觉，通常显得滑稽可笑。这通常用于形容那些不太会说英语的人在尝试用英语交流时的表现。', '「If you don’t drive good good, your mother and father cry cry!「 这种幽默的语句让人一下子就想到了“散装英语”的画面。', ''],
  ['我起了一枪秒了有什么好说的', '“我起了一枪秒了有什么好说的”用来形容在游戏中因为被对手快速击杀而无话可说的窘境。这句话带有无奈和自嘲，多用于甩锅，表示自己在无能为力的情况下被击败，也不需要再多解释。', '当我在游戏里被敌人瞬间秒杀，我只能说：“我起了一枪秒了，有什么好说的。”', '这句话出自CSGO主播“茄子”的一次直播。当时，茄子在游戏中没有对队伍提供帮助，并被敌人快速击杀，因此对队友的质疑做出了这番回答。'],
  ['融梗', '融梗是一种存在于文字创作中，将其他作品中的出彩部分、情节设置等融入自己作品的行为。这种做法在对比原作时，通常可以明显看出其来源，与抄袭类似但更加复杂。融梗通常涉及从多部作品中借用素材，而抄袭多为单一来源。', '他的新小说被网友指责为融梗，因为其中的主要情节和几个经典作品过于相似。', ''],
  ['反射弧太长', '形容一个人反应迟钝或对某些事情的理解较慢。', '小明在大家都笑过之后才哈哈大笑，大家调侃他反射弧太长了。', '源于生物学中“反射弧”的概念，是指人体接收外界信息并作出反应的神经结构，信息在反射弧上需要一定时间传递。如果反射弧较长，意味着人体作出反应的时间会更长。'],
  ['一斤鸭梨', '“一斤鸭梨”是网络用语，表示“反对”或“有异议”。', '在某部动漫里，看到角色要做出不合理的决定时，网友纷纷发弹幕：一斤鸭梨！', '该梗来源于动漫《逆转裁判》，是日语“異議あり”的空耳。在故事中，律师成步堂龙一在法庭关键时刻用这句台词表达反对。'],
  ['诡异的光', '“诡异的光”用于形容一种言者无心、听者过度解读的情形。说话者本无深意，却被听者强行解释得极其复杂。', '他只是随口说了一句，结果大家开始解读，真是让人感叹“诡异的光”又来了。', '该梗源于2017年浙江高考语文阅读理解文章中的描述。作者巩高峰在文章结尾中所用的“诡异的光”被出题者设为题目，引发考生和网友热议。'],
  ['他只是个孩子', '「他只是个孩子「是用于为某人不当行为开脱的常见说法，意指因为对方年幼无知，所以不应受到严厉指责。它常用来讽刺那些纵容孩子或某些行为不当的成年人。', '每当那个熊孩子闯祸时，他的父母总是急忙解释：“他只是个孩子，你得原谅他。”', '该短语出自2014年古装电视剧《绝世高手之大侠卢小鱼》中的一句台词。最初用于家长为孩子的错误行为辩护。'],
  ['行走的生化武器', '行走的生化武器指一个人说话方式或内容非常雷人甚至“有味道”，能让人觉得不适。', '看到他在聚会上发言，我心中默念：“行走的生化武器”真名副其实。', ''],
  ['大姐哥', '「大姐哥「是一个结合了“大姐”和“大哥”气质的梗，用来形容那些既有大哥般霸气，又有大姐般温柔的性格特征的人，或者性别不易辨别但充满个人魅力的人。', '她真是个大姐哥，不仅领导能力强，还有无限的亲和力。', ''],
  ['千里送人头礼轻情意重', '“千里送人头，礼轻情意重”是用于调侃那些自投罗网或者不自量力的行为，通常形容远道而去面对对手却被对方轻易击败或者损失的情形。', '在网游《英雄联盟》中，他千里送人头，礼轻情意重，结果被对面两下秒了。', ''],
  ['盖楼', '在网络论坛或社交平台上，通过发布吸引人回帖的帖子，形成多层回复，被形象地比喻为“盖楼”。', '他在论坛上发了一个有趣的问题，没想到大家积极回复，很快就“盖楼”了。', ''],
  ['是洋葱我加了洋葱', '“是洋葱，我加了洋葱”用来调侃某些事情很简单或通过简单步骤就能够实现，常用来回答对某事成果的疑问。', '朋友夸道：“你做的这道菜真好吃！”我回答：“是洋葱，我加了洋葱。”', '最初出自电影《食神》，周星驰饰演的主角因为加入洋葱而战胜了敌人，在解释自己为什么取胜的时候，说“是洋葱我加了洋葱”，从而被大众所记得。'],
  ['皮划艇', '指上班或表演时严重偷懒的人。', '你最近工作状态不太好，一直在皮划艇啊。', '源自韩国女团Blackpink成员Jennie某场表演动作随意，与其他成员对比鲜明，被称为“人间皮划艇”，意指专业划水的人。'],
  ['纸带', '「纸带「用于嘲讽某人消息落后，意指某人对当前的信息或事件知之甚少或反应迟钝。', '「你居然不知道这件事？你是纸带了吧？「', '该词源自知名微信公众号自媒体“差评”公司内部的黑话。起源可追溯到2018年9月19日的一篇文章中，解释为因为远古时期计算机程序是用带孔纸带输入程序。随着时间的推移，这种说法逐渐被粉丝和撰文者简化使用。'],
  ['遇事不决量子力学', '遇到难以解决的问题时，依靠复杂或高深莫测的科学理论（如量子力学）来强行给出解释，常用于掩盖逻辑上的漏洞。', '这部电影的结尾实在太匪夷所思，真是遇事不决，量子力学的典型案例。', ''],
  ['长在了笑点上', '形容某人自带笑点，无论其言语或行为，甚至不做什么，仅仅存在就能引人发笑。', '这个演员真是长在了笑点上，一出场我就忍不住笑。', ''],
  ['苍蝇搓手', '“苍蝇搓手”作为网络流行语，形容一种莫名兴奋、激动、期待且略显猥琐的状态，常用于自黑和自嘲。', '一看到这个游戏上市的消息，他立刻苍蝇搓手，满心期待。', '该词的灵感来自苍蝇的生理现象，苍蝇常常搓手是一种自我清洁方式。之后这种动作被网友们制作成表情包用于调侃。'],
  ['稳住我们能赢', '「稳住我们能赢「是用来稳定军心和鼓舞士气的一句话，但在游戏中常被当作一个不太可靠的flag。', '打团战的时候，他一直在喊“稳住我们能赢”，结果队伍还是被团灭了。', '出自游戏《王者荣耀》的系统提示音，随着游戏流行，这句话也成为玩家的口头用语。'],
  ['真是嗨到不行', '“真是嗨到不行”通常被引用来表达激动、欣喜若狂或得意忘形的心情。', '考试通过了，真是嗨到不行！', '出自《JOJO的奇妙冒险》第三部，是反派DIO的名台词。在最终战中，DIO吸收了乔瑟夫的血后，能力大增并说出了这句话。'],
  ['干啥啥不行吃饭第一名', '“干啥啥不行，吃饭第一名”用来自嘲一个人除了吃饭擅长外，其余事情都不擅长。通常表示一种无奈和自嘲的幽默。', '别看我工作上不行，干啥啥不行，吃饭我可是第一名。', ''],
  ['血是绿色的', '该梗是对视频网站中将血液颜色改为其它颜色以通过审核的调侃。', '看完这个战斗场面，弹幕纷纷刷“血是绿色的”，果然是过审秘籍。', ''],
  ['键盘上撒把米鸡都比你会', '“键盘上撒把米鸡都比你会”这个梗用于形容某人在游戏或电脑操作上的水平很低，对方的操作甚至不如鸡随机啄击键盘的。', '“你这操作也太糟了，键盘上撒把米，鸡都比你会走位。”', ''],
  ['天然呆', '天然呆是一种性格特征，指一个人天生就显得傻乎乎、呆呆的，往往表现为反射弧较长、关注点不集中等，从而产生一种可爱的印象。', '“富冈义勇在《鬼灭之刃》中简直是个天然呆，总是让人忍俊不禁。”', ''],
  ['满分作文', '「满分作文「指的是文学气息浓厚、真情实感显露、内容丰富的文字或语言表达，形容某人的表达能力非常优秀，值得满分。', '他的演讲非常感人，大家纷纷称赞那是满分作文。', ''],
  ['手搓核弹', '“手搓核弹”指用手完成一件非常厉害或极具影响力的事情。原意是动漫中角色仅凭手就能发出威力巨大的招式，象征该角色的强大实力。现在用于形容某人用手完成了出色的作品或任务。', '他只用了15分钟就写完了一篇精彩的文章，简直像是手搓核弹。', ''],
  ['人间水蜜桃', '“人间水蜜桃”形容长相甜美、气质如水蜜桃般的人，通常指外貌甜美、皮肤白皙泛粉红、具少女感的人。', '她笑起来特别甜，有一种人间水蜜桃的感觉。', ''],
  ['汝听人言否', '“汝听人言否”的完整表达是“你听听，这是人说的话吗？”，用于表达对某人言论或行为的震惊、不理解或羡慕，通常带有调侃、讽刺的意味。它质疑某人说的是不是“人话”。', '当某人炫耀自己的奢侈消费时，朋友们在群里纷纷调侃：“汝听，人言否？”', ''],
  ['太阳能维修月亮可更换', '“太阳能维修，月亮可更换”是一种俏皮且温馨的表达方式，代表着生活中的趣味和与他人分享小事的快乐。这种表达常用于传达爱意，是幻想遇到一个温柔可爱的人可以与自己共同分享无厘头话题的美好愿望。', '看着窗外的月亮，我不禁想到“太阳能维修，月亮可更换”，希望你能陪我一起聊这些无厘头的美好。', '这个表达来源于日常生活中常见的广告语，如“太阳能维修”等，通过在后面添加“月亮可更换”这种无厘头的夸张想象，使其变得生动有趣，受到网友的喜爱。'],
  ['柠檬树上柠檬果柠檬树下你和我', '“柠檬树上柠檬果，柠檬树下你和我”用来形容心里酸溜溜的感觉，通常表示因嫉妒或羡慕而产生的心理不平衡。', '某明星跨年夜出来唱几首歌又可以休息一整年！！柠檬树上柠檬果QWQ', '该梗的原句出自少儿栏目《智慧树》中的歌词“智慧树上智慧果，智慧树下你和我。” 后来被网友改编为“柠檬树上柠檬果，柠檬树下你和我”。柠檬代表酸，表达“我酸了，我羡慕，我嫉妒”。'],
  ['封麦', '“封麦”指的是歌手决定不再在公开场合演唱歌曲，隐退歌坛，告别舞台的行为。', '费玉清在他的最终告别演唱会后宣布封麦，这标志着他47年歌唱生涯的结束。', ''],
  ['烂怂大雁塔有啥看的', '「烂怂大雁塔有啥看的「表达了人们对自己家乡的一种复杂感情：可以自己批评，但不允许外人指责。', '小李总是说自家城市没啥好，但一听外地人批评就说：“烂怂大雁塔有啥看的，你不懂！”', '源于一段采访视频中，一位西安市民起初随意评价道：“烂怂大雁塔有什么好看的。”然而，当记者告知他这段采访会上电视后，他立刻改变态度，开始认真地向记者介绍大雁塔的历史和文化。这种突然转变的态度引发网友的调侃。'],
  ['人间精品', '形容人或物特别优秀、出色，达到了一个比较稀有罕见的程度。', '人间精品大张伟，朋克巨星！', '大张伟在《奇葩说》节目中常用此词夸赞别人；大张伟也有一张名为《人间精品》的专辑。'],
  ['打不过就加入', '「打不过就加入「是用来调侃一个人无法战胜对手时，选择加入对方，站到对方阵营中的行为，常用于形容人转变立场或改变阵营的情况。', '张三原本一直批评公司的竞争对手，但在新项目中，他突然选择跳槽到竞争对手公司。大家都在背后笑说他是“打不过就加入”。', ''],
  ['耿直boy', '「耿直boy「指的是说话直接、不拐弯抹角的男生。有时这样的直率会显得情商低，因为说实话可能会伤人。但另一方面，这种直率和诚实也让人觉得可爱，因为少有人敢于如此坦诚。', '他真是个耿直boy，直接在大会上指出了公司的问题，大家都看呆了。', ''],
  ['出门记得穿防弹衣', '「出门记得穿防弹衣「是一种幽默劝诫，用来提醒他人不要过于嚣张或招摇，以免引来不必要的麻烦或敌视。它暗示一个人如果过于自信和得意，很可能会得罪别人，从而导致负面后果。', '老王最近在公司升职后天天炫耀，我提醒他出门记得穿防弹衣，低调点总没错。', ''],
  ['二当家', '「二当家「通常指在某个领域或团体中地位仅次于最高领导者的人。在网络梗中，特别是指那些冒充淘宝卖家的人，因为商家是第一位，而冒充者排在第二位，因而被戏称为「二当家「。该词也常用于形容内心戏丰富、喜欢在评论区「演戏「的网友。', '在抖音评论区，常有一些人自称「二当家「，表演自己的内心戏。', ''],
  ['精神小伙', '精神小伙原本是指精神气质好的年轻人，现在通常指打扮和行为很有特色，喜欢跳社会摇的土嗨小伙子。', '他穿着豆豆鞋和紧身裤，骑着电动车，就像一个标准的精神小伙。', ''],
  ['不买立省', '“不买立省”是指在购物节期间，面对各种促销优惠活动，如“满减”“立减”等，尽管这些优惠方式标榜能够省钱，真正最省钱的方法其实是不购买任何商品。这是一种调侃和自嘲，因为大部分消费者最终还是会忍不住消费。', '每到双十一前夕，我就在心里默念“今年一定要不买立省”，然而总是被各种优惠击败。', ''],
  ['团战可以输提莫必须死', '“团战可以输，提莫必须死”表达了玩家们对游戏《英雄联盟》中角色提莫特殊技能的反感，表示宁愿在团战中输掉比赛，也要先解决掉提莫以免被他的技能影响。', '每次遇到对面有提莫，我的队友都喊“团战可以输，提莫必须死”。', ''],
  ['电竞黄浦军校', '“电竞黄浦军校”指的是YM战队，尽管成绩不理想，但培养出多位知名选手。类似于黄埔军校在军事领域的影响力，YM在电竞圈为多支冠军队伍输送人才。', 'YM真是电竞黄浦军校，培养出了这么多顶尖选手。', ''],
  ['暴风雪山庄模式', '暴风雪山庄模式是一种环境描写手法，通常用于营造悬疑、推理或恐怖故事的氛围。在这种模式中，一群人因某种原因被困在一个与世隔绝的地方，如孤岛、别墅或城堡，并且因为天气或其他因素无法离开，也无法与外界联系。', '电影《闪灵》就是一个典型的暴风雪山庄模式，全家人被困在雪封的酒店中，而恐怖的事件接二连三地发生。', '源自推理小说和悬疑题材影视作品的一种舞台设定模式，由英国女作家阿加莎·克里斯蒂的小说《无人生还》首创。'],
  ['没图没真相', '“没图没真相”是用来质疑或反驳网络上某些看似难以置信的陈述，要求对方提供照片或图片作为证据的表达方式。通常用于表示怀疑或不相信某件事，直到有实质性的视觉证据出现。', '朋友群里有人说自己偶遇了明星，大家纷纷回复：“没图没真相，快发照片。”', ''],
  ['为什么不ban加里奥', '“为什么不ban加里奥”这一梗表达了对比赛策略的质疑，尤其是在英雄联盟比赛中，未能禁止对手选择一个特别强大的或具有影响力的英雄可能导致失败的场景。', '在昨晚的比赛中，我们队就是因为对方的加里奥太强大而输掉了，真该听大家的建议，早早ban掉加里奥。这种情况下，真是应了那句「为什么不ban加里奥「。', '这个梗来源于英雄联盟全球总决赛（S7）半决赛，其中韩国战队SKT的中单选手Faker多次成功使用加里奥对抗中国战队RNG，最终导致RNG以2:3不敌SKT。这场比赛后，很多观众质疑RNG的禁用策略，该梗因此流行开来。'],
  ['以前我没得选', '「以前我没得选「是用来调侃自己的无奈处境，或表达对过去选择的无力感，而现在希望改变或得到某种东西。因其来源的严肃背景，在使用时带有一种装逼又搞笑的效果。', '看到同事们都有奖金，而我没有，我只好苦笑道：「以前我没得选，现在我只好搬砖「。', '这句话出自电影《无间道》中刘德华和梁朝伟的天台对话。刘德华饰演的角色对梁朝伟表示，以前没有选择的机会，而如今希望做出不同的选择。后被周星驰引用于他的喜剧电影中，使其变得更为幽默流行。'],
  ['跪着用电脑', '对某人或某事表示极高的尊敬或敬佩，形象地用“跪着”来表现这种心情。', '这位画师的作品太精美了，我真是跪着用电脑来研究他的每一个细节。', ''],
  ['正常能量释放', '“正常能量释放”原为气象用语，指的是小地震的发生属正常现象，意图让民众安心，但在网络上被用来讽刺频繁发生的异常事件，表达对这些现象的习以为常或无奈态度。', '最近楼下超市又起火了，真的是正常能量释放，每隔几个月就有一场小火。', '该梗来源于中央气象局在发生小规模地震后用来安抚民众的官方说法，后被网友用来讽刺频繁的社会现象。'],
  ['蜜汁自信', '“蜜汁自信”用于形容一个人莫名其妙地自我感觉良好，具有一种毫无逻辑的傲娇心态，对他人持有藐视的态度。常用于吐槽那些自信但不明所以的人。', '他每次说话都带着蜜汁自信，好像自己永远是对的。', ''],
  ['老实巴蕉', '“老实巴蕉”是“老实巴交”的谐音，形容人规规矩矩，谨慎胆小的样子。', '看见王一博那“老实巴蕉”的样子，我都笑喷了。', ''],
  ['生命探测仪', '“生命探测仪”是对验孕棒的幽默称呼。这个梗通过一种调侃的方式，用“生命探测仪”来形容验孕棒的功能，即检测女性是否怀孕。', '他紧张地去药店问店员：“请问你们有生命探测仪吗？”', '这个梗来源于一个短视频。在视频中，一名男子在医院妇科询问护士是否有“生命探测仪”，在得到护士疑惑的回应后，他解释是“验孕棒”，引发了护士的笑声，随后该梗在网络上迅速流行。'],
  ['我尿黄我来', '「我尿黄我来「意思是我想先撒泡尿泼醒他，用来讽刺或调侃一些人说话或行为不切实际、白日做梦。它是一种轻松幽默的方式去提醒或打断对方。这个短语中的“尿黄”是一个玩笑般的借口，用于强调自己在某种情况下有优先发言或行动的权利。', '在小组讨论中，小明说了一堆不切实际的方法，老王无奈地说：“我尿黄我来，我看还是得找个靠谱点的方案！”', ''],
  ['杯具', '“杯具”是“悲剧”的谐音，用于形容令人遗憾或不幸的事件。', '昨天的约会取消了，真是个杯具。', '该梗来源于易中天在《百家讲坛》的截图被加上“悲剧啊！”的字幕，随后“杯具”作为其谐音被网友创造使用，最早的名言改编版本是“人生是一张茶几，上面摆满了杯具”，句式来自张爱玲的名言。'],
  ['折翼的天使', '“折翼的天使”最初用于形容一种无病呻吟的自怜状态，经过网络流行，演变为讽刺那些过于矫情或自认为悲情的人的代名词，也可以泛指各种悲剧情况。', '他每次面临小挫折就表现得像个折翼的天使，实在太夸张了。', '该梗来源于中国大陆的社交网站校内网（后来更名为人人网），最初是被用于无病呻吟的感慨或文章中。受一部爱情畅销书影响，该书中提到每个女孩上辈子都是折翼的天使。后来，这一表达广泛传播并被用作调侃或讽刺。'],
  ['扫地老太太', '扫地老太太是一个虚构的全知型人物，可以在特定领域中以超凡的洞察力指出专业错误。这个梗表达了一种理想化的“老练高人”形象，常以幽默的方式呈现。', '据说在每一个金融公司里，都有一个扫地的老太太。很偶然地，当她经过一个分析师的身边，扫一眼屏幕上的数据，会低声提醒对方说：小心，汇率预测错误了。', '2011年1月3日，新浪微博用户“程序员幽默”发布了一则关于扫地老太太的帖文：“据说在每一个互联网公司里，都有一个扫地的老太太。她偶然经过程序员身边，扫一眼代码，低声提醒：‘小心，栈溢出了。’”，引发网友创造出多个行业版本的故事。'],
  ['穿山甲说什么', '这个梗是指一种未完待续的悬念或谜团，让人感到好奇但无法得知答案，强调了不满足和困惑的心情。', '这电影结尾太突然了，完全就是“穿山甲说了什么”的状态，让我百思不得其解。', '出自《暴走大事件》第二季第9期，由主持人王尼玛讲述的一个故事。在节目中，两个死刑犯在行刑前进行最后的对话，其中一个犯人开始讲述一个故事，最后他说到：“穿山甲说......”，但话还没说完，他就被枪决了。另一个死刑犯哭喊着问：“穿山甲到底说了什么？” 这个悬念式的结尾引发了观众的好奇和调侃，成为一个反复使用的梗。'],
  ['丑萌', '「丑萌「是指一种外表看似不太好看，但意外地让人觉得可爱、有趣的反差属性。尽管第一印象可能因为长相而不突出，但随着时间推移，其幽默和可爱之处逐渐显露出来。这种特质常延伸至小孩子、小动物、小物件或新奇风格的表情包，带有正面和积极的意味。', '「这只猫虽然脸上整天皱巴巴的，但是它的动作真的很丑萌，忍不住就觉得可爱极了！「', ''],
  ['左右横跳', '「左右横跳「是一种源自动漫《在下坂本，有何贵干》的搞笑动作，指的是来回跳动的幽默表现。这个动作在网络上被用作各种搞笑表情包，因为其魔性和幽默感。', '每次老板提出新要求时，我感觉就像在左右横跳，不知道该先做哪个。', '该梗出自动漫《在下坂本，有何贵干》，剧中的角色坂本使用的特殊动作，「左右横跳「被用来制造风，引起骚动，是他的一个招式。'],
  ['人形挂件', '“人形挂件”指的是一种形容在亲密关系中，一个人因非常喜欢另一个人而时常依偎在对方身边的状态。这个人就像是对方的“挂件”，因为“挂件”是人，所以称为“人形挂件”。', '郎朗说：“我去哪里吉娜都会跟着，大家都说她是我的人形挂件。”', ''],
  ['洗剪吹', '「洗剪吹「原指理发店提供的洗头、剪头、吹风等服务，但作为网络梗，它用来调侃那些造型奇特、风格独特，类似杀马特风格的人。这个梗也衍生出形容词的用法，专门描述另类和夸张的时尚风格。', '你今天的造型真是太洗剪吹了，让人一眼就能注意到。', ''],
  ['狗听完死了', '用来形容自己压力特别大，烦恼过多。', '最近工作实在太忙，感觉讲给狗听狗都听完死了。', ''],
  ['开幕雷击', '「开幕雷击「指的是在刚打开视频时，就立即看到令人震惊或出乎意料的内容，类似于被雷击般的强烈冲击。', '“这部影片真是开幕雷击，我完全没准备好迎接如此刺激的开场。”', '该梗源于游戏“舰队collection”。在这款游戏中，携带潜艇和特定装备的角色会在战斗开始前进行一次鱼雷攻击，被称为开幕雷击。之后，该术语被B站的弹幕和视频标题引用，并在各大平台上广泛传播。'],
  ['欢迎回家', '“欢迎回家”用于调侃游戏玩家在高难度游戏中失败并回到起点时，表达观众对玩家处境的戏谑和“鼓励”。', '主播刚要到达顶峰，却一个失误掉了下来，弹幕瞬间刷满“欢迎回家”。', ''],
  ['马猴烧酒', '“马猴烧酒”是“魔法少女”一词的日语发音的中文空耳。这个梗用于调侃和泛指各种形式的魔法少女，常见于网络上尤其是涉及日本动漫的讨论。', '「看完这部番，我也特别想穿上好看的裙子当一名马猴烧酒！「', ''],
  ['钩直饵咸', '“钩直饵咸”用来形容那些企图耍别人的人技巧拙劣，构思不周，被轻易识破。主要用于讽刺智商不够的人在尝试诱导或操纵他人时，被一眼看穿的情况。', '那个帖子一看就是钓鱼贴，内容编得太假，真是钩直饵咸。', ''],
  ['我的公主殿下臣来迟了', '“我的公主殿下臣来迟了”是一种表达歉意和敬重的说法，用于表示自己迟到了并对对方地位的高度尊重。这句话蕴含着先认错的态度，希望对方能够原谅自己。', '每次我迟到的时候，我都会对女友说：「我的公主殿下臣来迟了「，她听完总会无奈地笑笑。', '该短语来源于抖音用户嘉文yang上传的视频。在这个视频中，王者荣耀的角色诸葛亮和武则天共同演绎了这句台词，随后迅速走红，成为网络上的流行语。'],
  ['你还说你不会武功', '「你还说你不会武功「用于调侃某人试图掩饰自己的真实水平。在对方在某方面表现得不太在行，或故意隐藏实力时，用这句话暗示他们的能力或意图已被识破。', '你刚才连赢了五把，居然说你不会打麻将，你还说你不会武功？', '该梗出自周星驰电影《九品芝麻官》。影片中的反派常威在杀人后自称不会武功，但最后被揭穿，周星驰饰演的主角对他讽刺道：“常威，你还说你不会武功？”'],
  ['常威打来福', '用于表明自己是个不明真相的看客，只看到事情的表象，并不知道背后的原因。', '在网上看到两个网友争论，我只好评论：“常威打来福，我是看到了，但因为什么打的，我不清楚。”', '源自周星驰电影《九品芝麻官》打更官的台词：“我一进门，就看见常威在打来福。”'],
  ['翻滚吧牛宝宝', '「翻滚吧牛宝宝「是一种用更文明的语言表达「滚犊子「这种带玩笑性质的东北方言，意在让人离远点。它在网络上流行起来作为一种不带脏字的方式来说脏话。', '在游戏中队友频频失误，小王忍不住想说脏话，但最后憋出了一句：“翻滚吧牛宝宝！”', ''],
  ['兵长一米六', '“兵长一米六”用来调侃《进击的巨人》中角色利威尔兵长的身高。尽管他是被誉为“最强男人”，长相帅气，战斗力极高，但他的身高却只有1.6米，这在动画设定中显得较为矮小。因此，这个梗被用来作为一种反差萌的调侃点。', '每次看见超高个子的三笠站在兵长旁边，我就忍不住想起“兵长一米六”这个梗，真是反差萌的极致。', ''],
  ['家里有矿', '“家里有矿”用于形容一个人特别有钱，花钱非常大方，也可以用来吐槽某件事情非常烧钱或价格过高。', '看到他换了一辆新车，又买了一堆奢侈品，果然是家里有矿的人。', '该梗源自电视剧《马大帅》中，由赵本山扮演的角色马大帅的一句台词：“不懂球就买，啥家庭啊？家里有矿啊？”'],
  ['他真的是那种很少见的那种', '“他真的是那种很少见的那种”用于开玩笑地形容某物或某人很少见或者非常独特。', '看到他用背包自制降落伞成功着陆后，我只能感叹他真的是那种很少见的那种。', '出自2016年由周星驰导演的电影《美人鱼》中邓超饰演的男主在警局报案时说的一句台词。该台词因其幽默的表达方式而被观众熟知并广泛使用。'],
  ['rua死你', '「rua死你「是一种调侃的表达方式，意指打死你、揉死你、捏死你。它并非真正想要伤害对方，而是一种亲密的表现。', '看到你这么可爱，真想rua死你。', ''],
  ['还能再战xx年', '“还能再战xx年”用于表示某作品或事物仍具备持久的活力和价值，远未过时。其中，“xx年”通常被夸大来表达对事物持久性的幽默或喜爱。', '看看这部经典漫画，不得不说，它还能再战50年！', '出自《机动战士高达0079》中的一句台词，在动画中敖德萨会战后，角色麦克白上校声称“吉翁还能再战10年”，尽管军队已颓势明显。然而仅三个月后，吉翁就灭亡了。这句话后来演变为一种流行的说法。'],
  ['花蟹', '花蟹指代那些无故妨碍他人，损人不利己，不懂团队合作的人。', '他总是喜欢在团队项目中扯后腿，真是个花蟹。', '来源于综艺节目《新西游记》，姜虎东用来形容那些互相妨碍完成任务的成员。'],
  ['树洞', '树洞是人们用来倾诉秘密和心声的地方，尤其是在无法对身边人直接表达时，常通过网络匿名平台诉说。', '我今天心情不好，找个树洞倾诉一下。', '源于童话故事《皇帝长了驴耳朵》，皇帝的理发师将皇帝长了驴耳朵的秘密对树洞诉说，避免憋在心中难受。'],
  ['好奇心害死猫', '“好奇心害死猫”用于告诫人们对某些事情保持必要的克制，不要过于好奇，以免引发不必要的麻烦或危险。', '当你忍不住想要打开室友的私人信件时，请记住“好奇心害死猫”。', ''],
  ['原地结婚', '原地结婚是一种网络用语，指对一对情侣或CP（情侣配对）非常看好，并希望他们能够立刻在一起。并不意味着真的要在原地结婚，而是表达对他们关系的祝福和期待。', '看完这部剧后，所有观众都希望男女主演能原地结婚，因为他们的互动实在是太甜了。', ''],
  ['迷惑行为', '迷惑行为指那些让人感到不解、很奇怪或耐人寻味的行为。在网络语境中，这个词语通常用来形容那些看似无厘头、让人感到困惑甚至有些搞笑的举动，但随着时间推移，逐渐也带有一些批判意味。', '他竟然在图书馆大声地背诵课文，真是让人佩服的迷惑行为。', ''],
  ['练功发自真心', '「我练功发自真心「是一个常用于网络鬼畜视频的梗，指代一种发自内心的强烈情感或努力。原句来自于一位被称为“德国BOY”的网络红人在视频中大喊德语时的空耳翻译。这句话常被用来自我调侃或者形容某人特别积极和执着。', '他每天都在练习跑步，简直就是「我练功发自真心「。', '该梗出自网络红人Leopold Andreas Slikk（即德国BOY）的视频。在视频中，德国BOY因德语台词「哦我的天发生了什么事「的发音被中文网友们空耳为“我练功发自真心”。由于德国BOY在视频中的激烈表现，这句话在网络上迅速流行并成为鬼畜视频的经典桥段。'],
  ['摄影穷三代单反毁一生', '“摄影穷三代，单反毁一生”是一句幽默的自嘲，主要强调摄影爱好者常因购买昂贵的摄影器材而花费巨大的金钱和精力，带来经济上的负担。这句话描述了摄影圈中常见的现象，即不断更新和升级器材，容易陷入“器材穷”。', '最近我又看上了一款新镜头，真是印证了“摄影穷三代，单反毁一生”这句话。', ''],
  ['BE和HE', 'BE和HE是用来描述作品结局类型的术语。BE（Bad Ending）指的是悲剧结局，而HE（Happy Ending）则指的是大团圆结局或开心幸福的结局。', '这部电影虽然整个情节充满了悬念，但最后是个HE，让观众感到十分欣慰。', ''],
  ['钓鱼穷三年玩鸟毁一生', '「钓鱼穷三年，玩鸟毁一生「 是一句警示语，意在告诫年轻人不要玩物丧志，要把精力集中在学习和奋斗上。强调在年轻时过多沉迷于钓鱼和玩鸟等消遣活动，会影响自我成长和发展。', '他总是沉迷于钓鱼，我只好提醒他一句：“钓鱼穷三年，玩鸟毁一生。”', ''],
  ['死兆星', '“死兆星”是一种不祥的象征，代表即将面临死亡或悲惨结局的预兆。在现代网络语境中，当人们调侃或预感到某种灾难即将降临时，常引用这个梗。', '面对即将到来的考试周，小明感叹道：“感觉这门课就是我的死兆星，看完这周的复习计划，我都快要透不过气来了。”', '“死兆星”这一概念的普及源于日本经典漫画《北斗神拳》。在该作品中，能够看到死兆星的人被预示将在一年内死亡。'],
  ['占戈哥欠走已', '“占戈哥欠走已”是“战歌起”的拆字形式，用于形容热血、燃系BGM或歌曲响起所带来的激动氛围，常出现在剧情高潮或战斗场景。', '在《进击的巨人》激战开始时，弹幕上满是“占戈哥欠走已”，观众都被燃得热血沸腾。', ''],
  ['唐氏表演法则', '唐氏表演法则是指电视剧《爱情公寓》中角色唐悠悠总结的表演技巧。这些法则强调演员要争取话语权、制造意外剧情、创造丰满的故事背景，以及增加复杂的人物关系和剧情。', '看邓家佳的新剧，我总觉得她在用唐氏表演法则，剧情真是不按常理出牌。', '该表演法则出自电视剧《爱情公寓》，由角色唐悠悠于第二季第五集中首次提及。'],
  ['老八秘制小汉堡', '「老八秘制小汉堡「是指一种由快手吃播博主岛市老八创作的独特“汉堡”料理。这种“汉堡”的制作过程和配料听起来非常奇特，包含吐司、生菜、王致和臭豆腐、腐乳和切片柠檬。由于配方怪异且富有创意，这成为了一种网友调侃的对象，并且流传网络，成为流行梗。', '今天中午没想好吃什么？不如试试传说中的老八秘制小汉堡，既实惠还管饱！', '该梗出自快手人气土味美食吃播岛市老八的直播节目，在一次直播中，老八展示了他自创的“秘制汉堡”的制作过程，并配以一段有趣的语录。'],
  ['萧亚轩的快乐', '「萧亚轩的快乐「指的是她频繁更换年轻帅气男友的生活方式，是一种让人羡慕且向往的幸福。', '她最近换了个男朋友，大家都在说她过上了萧亚轩的快乐。', ''],
  ['一脸dio样', '“一脸dio样”形容一个人表现得嚣张傲慢、玩世不恭，源自于使用这种神态的角色。', '他今天上课回答问题时一脸dio样，好像全世界他最聪明。', '该梗源自日本动漫《JoJo的奇妙冒险》中的反派角色迪奥·布兰度（Dio Brando）。迪奥成为吸血鬼后总是蔑视人类生命，摆出高傲神态，因此这种神态成为了他的标志，被称为「一脸dio样「。'],
  ['保安日记', '“保安日记”是指一些以幽默和夸张的方式写成的假装保安的工作日志，它的内容通常是一些普通但搞笑的小事。因其诙谐逗趣的文字风格而受到大众喜爱，并在网络上迅速走红。', '“昨天又刷了一整天的保安日记，每篇都笑到肚子疼，这些编故事的网友真有才！”', '这一梗起源于一篇网上的网文，其中描述了保安在微信群里撰写的搞笑日常日志。这篇文章最初是在“秀tv吧”供网友调侃使用，后来被传到微博上广泛流行，吸引了大量网友效仿。'],
  ['芋泥啵啵奶茶', '“芋泥啵啵奶茶”来自“我要一杯芋泥啵啵奶茶，不要芋泥不要奶茶，只要啵啵”，是通过俏皮的方式表达想要亲吻，用撒娇来达到撩人的效果。', '我想喝芋泥啵啵奶茶，不要芋泥不要奶茶，只要啵啵！', ''],
  ['阿姨压一压', '“阿姨压一压”是一种源自音乐吟唱部分的谐音梗，主要指代某些歌曲中“啊咿呀咿呀”的部分，并延伸为对这些歌曲的戏称。在网络文化中，该词通常指代《Butterfly》或《大家一起来》等曲目，以及在《JOJO的奇妙冒险》相关语境中指代《Awake》的主题曲，因其独特的风格特征而被广泛讨论和二次创作。', '朋友问我为什么最近总哼着“阿姨压一压”，我说这是《Butterfly》的魔力。', ''],
  ['不是鱼露是鲈鱼', '这句话来源于游戏《集合啦！动物森友会》，玩家在游戏中钓到鲈鱼时，会出现这样魔性的提示语。', '昨天在《动物森友会》里钓鱼，慢慢悠悠的结果又出现了“不是鱼露是鲈鱼哦”。', ''],
  ['正道的光', '“正道的光”梗通常用来讽刺那些为了流量而摆拍假正能量视频的人。其含义因背景不同，有时用来宣扬正能量，有时用来讽刺不切实际的正能量宣传。', '他们拍了个视频捡垃圾，音乐一放“正道的光~”，真是让人哭笑不得。', '该梗出自黄渤演唱的歌曲《正义之道》，其中歌词“正道的光，照在了大地上”被许多短视频平台上的视频作为背景音乐使用。'],
  ['洗洁精式演技', '对演员演技的肯定，特指黄晓明在电视剧《鬓边不是海棠红》中的演技突破了以往的油腻感，被形容为像洗洁精一样去油。', '黄晓明这次在《鬓边不是海棠红》里的表现真的不油腻，被网友称为洗洁精式演技。', ''],
  ['我的青春结束了', '“我的青春结束了”是一种表达对过去某段美好时光结束的感慨，最初用于形容热爱的一位选手退役带来的失落感。现泛指任何喜爱或关注的事情/事物结束时的伤感或调侃。', '《权力的游戏》大结局播完了，我的青春结束了。', ''],
  ['富贵使我们相遇', '这个梗是指为了获得某种需要花钱才能得到的东西而结识的情境。此处的“相遇”可以是现实中见面，也可以是在虚拟空间中的相遇，比如视频网站的评论区或弹幕中。', '在一款手机游戏里，我和朋友都充了钱，这才有了“富贵使我们相遇”的机会，比拼谁最先收集全城最强皮肤。', ''],
  ['奇怪的知识增加了', '表示一个人获得了一些无关紧要或奇怪的知识。', '今天刷微博时，奇怪的知识增加了，居然有人吃冰淇淋配辣椒酱。', '来自MUR猫的表情包，这只猫表情魔性，被称为“儿童邪典”。'],
  ['打工是不可能打工的', '“打工是不可能打工的”是一个基于嘲讽和幽默的网络流行语，用于形容一些厌倦常规工作的群体或个人，传达了一种不愿意或反感从事普通打工生活的态度。', '朋友问小李为什么不去找份工作，他半开玩笑地说：“打工是不可能打工的，我这辈子都不可能打工的。”', '该梗源自网络上传播的一段新闻采访视频，采访对象是南宁一位偷车贼周某。他在视频中声称“打工是不可能打工的”。'],
  ['王牌飞行员申请出战', '“王牌飞行员申请出战”是一种在社交媒体上展示自己酷炫转变的流行语录，常用于视频中展示形象转变或酷炫时刻。', '在抖音上，她的视频以“王牌飞行员申请出战”开场，变换成酷炫的造型，惊艳了很多粉丝。', '这句语音出自《英雄联盟》角色库奇（英勇投弹手）的台词，后在抖音等平台作为背景音乐流行，搭配展示转变的视频效果。'],
  ['让本不富裕的家庭雪上加霜', '形容原本就处于困窘状态的家庭遇到了意外打击，以至于更加艰难。现在，这句话被用在网络上自嘲一些生活中小倒霉事，表达运气不好的自嘲意味。', '刚刚买的手机被摔坏了，真是让本不富裕的家庭雪上加霜。', '最早出自法制类节目或农民致富节目中的播音腔解说，用于描述本就困难的家庭因意外境况更加恶化。'],
  ['哭不死董卓', '“哭不死董卓”讽刺那些只会沉溺于情绪和悲伤，却不采取实际行动去解决问题的人。用来提醒人们光是哭泣或抱怨没有任何用处，必须采取实际行动才能改变状况。', '小王面临工作困难时总是抱怨，却从不试图改变，真是“哭不死董卓”。', '该梗出自《三国演义》，在故事中，王允因董卓乱政而伤心流泪，众官也随之痛哭。曹操见状则讽刺地质问：“满朝公卿，夜哭到明，明哭到夜，还能哭死董卓否？”借此表达对无谓的哭泣的不屑和倡导实际行动的态度。'],
  ['玛卡巴卡', '“玛卡巴卡”是指一种在抖音上流行的可爱风格舞蹈或视频，背景音乐是根据动画角色玛卡巴卡创作的魔性BGM。', '最近抖音上很多人在玩玛卡巴卡挑战，舞蹈真是又可爱又有趣。', '源自卡通动画《花园宝宝》，玛卡巴卡是其中一个可爱的角色。后来在抖音上，该角色的主题曲被用作背景音乐，成为模仿视频的背景音乐。'],
  ['今年夏天又四十度了', '「今年夏天又四十度了「是一个表白梗，用来表达对过去某个美好时光和某个人的怀念。这个梗通过描述夏天温度来隐喻人生中曾有过的一段亲密关系，从而传达出对过去夏天共同度过的时光和身边那个人的想念。', '看着天气预报中今年夏天又四十度了，我不禁回想到去年的夏天，那个有你在的岁月。', ''],
  ['韩信带净化', '“韩信带净化”是对网络主播老八常说的一句口头禅“还是那句话”的谐音恶搞。原句被粉丝们用来调侃和恶搞。', '每次听到老八的直播，我就忍不住想起“韩信带净化”，这句谐音梗真的洗脑。', ''],
  ['小鸟伏特加', '小鸟伏特加是网络博主“新二的快乐生活”用来指代他自制的一种饮料。这种饮料通常装在一个贴有小鸟画纸的白色大水瓶中，模仿俄罗斯人喝酒的风格。', '每次看到“新二的快乐生活”视频时，总能看到他端起那瓶小鸟伏特加，真是入戏太深。', ''],
  ['奶瓶给你打掉', '用来回怼对方奶声奶气、不够成熟的话语，风趣地讽刺对方幼稚。', '你这样说话太奶里奶气了，小心我奶瓶给你打掉。', ''],
  ['提桶跑路', '指因为不满工作环境或其他原因，选择离职的一种自嘲方式，形象地体现了外出务工者离职时的状态和心情。', '这家工厂太黑了，我决定明天提桶跑路。', ''],
  ['已黑化', '“已黑化”原意指角色变得邪恶，立场改变。如今在网络上常作为一种时尚标签，表示一种态度，比如受到打击后情绪变化，并不是真正的邪恶。', '妹妹感觉最近总是对谁都不耐烦，真像个“（已黑化）”的角色。', ''],
  ['电车难题', '电车难题是一个著名的伦理学思想实验，考察在危急情况下的道德决策问题。通常为两难选择：牺牲少数人以拯救多数人，还是保持不作为，看似客观将在情感和理性之间求取平衡。它揭示了各种道德哲学立场之间的冲突，特别是对功利主义的挑战。', '在这场讨论会上，大家争论不休，仿佛把公司面临的选择与电车难题相提并论，我们究竟该如何妥善解决问题呢？', '电车难题最早由哲学家菲利帕·福特（Philippa Foot）在1967年的论文《堕胎问题和教条双重影响》中提出。其大致内容为：一辆失控的电车正朝着轨道上的五个人驶去，片刻后就会碾压到他们。然而，你有一个选择——可以拉动一个拉杆，将电车转向另一条轨道。然而，另一条轨道上也绑着一个人。考虑以上状况，你是否应拉拉杆？'],
  ['异父异母的亲兄弟', '“异父异母的亲兄弟”用来形容虚假的或不可靠的兄弟情谊，通常用于讽刺那些明明没有实质性情感纽带却互称兄弟的人。', '虽然他们总是称对方为兄弟，但看起来更像是异父异母的亲兄弟，并没有什么真正的情谊。', '该梗出自姜文指导的电影《邪不压正》，由角色蓝青峰对亨德勒说的一句台词：“我们是兄弟，我们是异父异母的亲兄弟啊！”这句话讽刺了为了某些利益而假意称兄道弟的人。'],
  ['我想要两颗西柚', '用“我想要两颗西柚”表达“我想见你（I want to see you）”的谐音表白，表达思念和想见对方的幽默方式。', '他突然对我说：“我想要两颗西柚。”我还没反应过来，他又补了一句：“因为我想见你。”', ''],
  ['树新风', '“树新风”是一个网络谐音梗，指“吹牛逼”。由英文“tree new bee”谐音而来。', '他说自己一个月能赚百万，简直是在树新风。', ''],
  ['人间德芙', '“人间德芙”用于赞美某些视频剪辑质量非常高，内容流畅，观赏体验如同德芙巧克力般顺滑。', '这个MV编辑得简直太好了，画面和音乐配合得无懈可击，真是人间德芙啊！', '“人间德芙”源自德芙巧克力的广告语“牛奶香浓，丝般感受”，形容一些视频剪辑顺滑自然，无违和感。'],
  ['原谅我当年的年少无知', '“原谅我当年的年少无知”用来幽默地回忆过去说过的豪言壮语，现在执行时发现不切实际。', '甲：你不是说要请我们全班去豪华旅行吗？      乙：原谅我当年的年少无知。', '源于俞灏明被网友调侃关于送房子的承诺。魏晨在520当天发布结婚证照片，宣布婚讯。好兄弟王栎鑫翻出俞灏明十余年前的采访，提醒他兑现当时的承诺：“如果魏晨结婚，我会送他一套房子。” 面对网友的催促，俞灏明幽默回复：“原谅我当年的年少无知。”'],
  ['梅开二度', '梅开二度意思是指同一件事成功地做到两次。在不同语境中，它有不同的用法：在足球中，指同一球员在一场比赛中进了两球；在视频中，指同一个镜头或情节出现两次。', '在昨天的比赛中，梅西梅开二度，帮助球队取得胜利。', ''],
  ['希望人没事', '“希望人没事”原本是表示祝福和关心的话，但如今常被用作反讽、阴阳怪气。通常用于表达不满或讽刺。', '当有人在群里发了假消息后，一个朋友评论道：“什么时候发生的事情，怎么新闻上没看到呢。希望现场的人都没事！”', ''],
  ['新手还在老手已经', '“新手还在老手已经”是一个网络流行句式，通常用于表达经验丰富的人已经做出了进一步或更深层次的行动，而尚不知情的新人仍停留在起点或表面层次。这个句式常用以对比新手与老手在同一情境下的不同反应或行为。', '新手还在观望，老手早已进去。', ''],
  ['玩游戏一定要笑', '“玩游戏一定要笑”是用来讽刺或调侃在游戏中即使遭遇挫折也要保持乐观心态的态度。然而，这句话通常带有反讽意味，因为很多玩游戏的人在实际操作中很难保持冷静和微笑。', '小李在玩《只狼》时屡屡被Boss打败，他自嘲地对同学说：“玩游戏一定要笑，不要愁眉苦脸的。”', ''],
  ['双厨狂喜', '双厨狂喜是指同时喜欢两个作品的粉丝看到两个作品在同一场合、视频或作品中出现时感到特别高兴或兴奋的情绪。', '当我最爱的动漫角色和我喜欢的游戏角色在这个联动活动中相遇，我立刻就双厨狂喜了。', ''],
  ['打在公屏上', '用于直播或视频互动，鼓励观众在公屏上发言，以表达共情或回应。', '看完这段感人的视频，大家纷纷在弹幕上说：“把感动打在公屏上。”', ''],
  ['肾炎', '“肾炎”是“神颜”的谐音梗，用于嘲讽粉丝形容偶像为“神颜”的夸张说法，认为这种夸赞往往带有厚厚的粉丝滤镜，不被大多数人认同。', '看到某家粉丝说他们家偶像是绝对的“神颜”，结果被评论区刷了一片“肾炎”，真是乐坏了围观群众。', ''],
  ['I potato you', '“I potato you”是一句英文俚语，表示“我很喜欢你”，介于“我喜欢你”和“我爱你”之间，处于好感和爱的中间状态。', '我和他说“I potato you”，他笑了，说他也是同样的感觉。', ''],
  ['青春疼痛文学', '青春疼痛文学是一种文学作品类型，专注于描写青春期的痛苦和情感剧变。这类作品常充满颓废和夸张的情感内容，如失恋、堕胎、打架、自杀等，常被认为是“不接地气”的，为了制造痛苦而刻意刻画悲伤情境。如今，该术语也用于调侃那些矫情、非主流的文字，或者是大家年少时写出来的羞耻作品。', '高中时我写了好多让人脸红的日记，现在看来简直就是满满的青春疼痛文学。', ''],
  ['各位爸爸们', '“各位爸爸们”这个梗在网络交流中是用来表达有求于人或者请求帮助时，故意放低身份、讨好对方的用词。它带有戏谑和幽默意味，类似于一种调侃的方式来表示自己在某件事情上的急需和低姿态。', '我这个月已经超支了，钱包空空，各位爸爸们能不能救济一下小弟？', '这个梗来源于斗鱼的主播蛋白，他经常在与粉丝互动时使用这句话作为口头禅。粉丝们也对此表达喜欢并将其广泛传播，因而在网络上成为流行语。'],
  ['直呼内行', '「直呼内行「是一种网络用语，用来调侃一些看似专业、实则不太聪明甚至搞笑的行为或者选择。虽然表面上给予了高度评价，但实际上是一种反讽和自嘲。', '小伙去高档餐厅用优惠券只点泡面，老板看了直呼内行。', ''],
  ['请问哪里能买到您的著作', '“请问哪里能买到您的著作”是一种表达赞同和敬佩的网络用语，用于形容某人的观点或评论非常经典或深刻，以至于值得被“撰写成书”。', '在知乎上看到一个用户详细分析了某事件的前因后果，评论区有人回复：“请问哪里能买到您的著作？”', ''],
  ['与世界分享你刚编的故事', '调侃有人在网上编造不真实的经历或故事。', '看完他在知乎分享的经历，我只想说：与世界分享你刚编的故事。', '源自知乎的口号“知乎，与世界分享你的经验”，因网友在知乎上看到许多夸张或不可信的故事而演变。'],
  ['维金斯养生篮球', '“维金斯养生篮球”这个梗用来形容NBA球员安德鲁·维金斯在比赛中轻松稳重的打法风格，注重节省体力，不做高强度动作。', '维金斯这场比赛得分虽高，但他依旧展示了“维金斯养生篮球”的风采，轻松驾驭比赛。', ''],
  ['平地摔', '平地摔指在没有任何障碍的平地上自己摔倒，通常用于形容一个人可爱、冒失或有点天然呆。', '她在走路的时候突然来了个平地摔，大家都觉得她很可爱。', ''],
  ['猴子不能出痛苦面具', '“猴子不能出痛苦面具”形容一些不合情理或无意义的事情。', '分手后，各种“猴子不能出痛苦面具”的场景在他的日常生活中重演，他知道自己应该继续向前看。', '源于2016年11月15日的一篇《王者荣耀》讨论帖。当时网友在讨论孙悟空这个英雄时，有人提到猴子可以使用多种装备，但“不能出痛苦面具”，因为痛苦面具是AP装备（Attack Power），而猴子是AD英雄（Attack Damage），出这件装备没有实际作用。'],
  ['大白菜鸡毛菜', '“大白菜鸡毛菜”形容某种操作很“菜”（不高明或拙劣），变着花样地表现低水平。', '这场比赛他全程失误，真是大白菜鸡毛菜的操作。', '该梗来源于歌曲《大家一起喜羊羊》的歌词，因歌曲中有大量“菜”字，被游戏博主用来当做“下饭视频”的背景音乐。'],
  ['企鹅肉', '“企鹅肉”用来形容两个人沟通不在一个频道上，一方认真说话，另一方随意回应甚至故意气人，打断谈话。', '她抱怨了一大堆，他却回了句“笑死企鹅肉”，气得她说不出话。', '源于网络上一张图，聊天中一方抱怨对方不重视关系，而对方用一张看似是「企鹅肉「的照片回复，表示不在意或打断。'],
  ['无情哈拉少', '“无情哈拉少”表示“太好了”或“太赞了”的意思。', '今天超市全场五折，真是无情哈拉少！', '该短语结合了“无情”来源于一个大爷的梗“卧槽无情”，表达对某事物的惊叹；与“哈拉少”是俄语“太好了”的空耳。这个短语源自抖音账号@新二的快乐生活 的口头禅。'],
  ['你可能小赚但我永远不亏', '“你可能小赚但我永远不亏”用于在游戏中通过补偿自身失误或者解读比赛局势来避免承认亏损。是一种自我安慰或自我调整的方式，通常是在不利情况下强调积极因素。', '在《英雄联盟》中被对方单杀后，队友评论：“别担心，你可能小赚但我永远不亏，因为我马上传送来收头了。”', '这句话出自游戏主播大司马。每次打《英雄联盟》时，他在出现失误或者“下饭”操作后，就用这句话为自己找借口或调侃对手的失误。'],
  ['一天最多三句话', '“一天最多三句话”是一种表达绝交或生气的戏谑方式，源自小孩子在写绝交信时的语气。它表示虽然生气或闹别扭，但内心仍有和好的愿望，通常被用来缓解紧张气氛。', '在和同事发生误会后，李莉气呼呼地说：“既然你不理我，那我也一天最多跟你说三句话！”', '该梗源于微博账号@班主任的课发布有关熊孩子绝交信的图片，信中有“一天最多说三句话”的内容。'],
  ['端水大师', '「端水大师「是指能够在各种关系或情况中保持公平，不偏袒任何一方的人。这个梗用来形容那些努力做到“一碗水端平”的人，特别是在复杂或容易引发争议的环境中。', '在公司中，她是个真正的端水大师，每个团队的意见她都认真倾听，确保大家都有发言的机会。', '该梗来源于黄晓明在综艺节目《乘风破浪的姐姐》中的表现。他作为成团见证人，为节目中的每位艺人公平宣传，以字母顺序发微博，展示照片并附上一句寄语，以示对所有参赛艺人一视同仁。因此，他被网友戏称为“端水大师”。'],
  ['这是加分项', '“这是加分项”用于表达对某事物的肯定态度，往往是一种鼓励或安慰，即便事情本身可能并不特别出色。', '朋友说自己做的饭不好吃，我尝了尝，笑着说：“其实味道不错，这可是加分项！”', '出自女团选秀节目《乘风破浪的姐姐》中，由成团见证人黄晓明所说的一句话。他用来鼓励对自己不够自信的选手姐姐们。'],
  ['我柜子动了', '“我柜子动了”用来形容在恐怖环境中受到惊吓或幻觉引发的紧张反应。', '昨晚看恐怖片太入迷了，结果突然感觉我柜子动了，吓得我赶紧关掉电视。', '该梗出自CSGO主播茄子在直播玩泰国恐怖游戏《ARAYA》时，他因紧张幻听到家里柜子动了，受到惊吓后的反应。'],
  ['装杯', '「装杯「是「装逼「的谐音，意指有人表现得过于自信或炫耀，做出一些让人觉得不必要的炫耀性行为。在网络或电竞圈，通常用来调侃那些表现得很厉害或者说一些过分谦逊的选手。', '刚刚打游戏明明我已经carry全场，队友还说我是“装杯”，这什么道理！', '该梗源自《英雄联盟》职业选手Jacklove（阿水）和前职业选手姿态的一次游戏直播。在那次直播中，阿水在游戏中拿了五杀后迅速退出游戏，姿态便打趣说：「装杯，文波（阿水的本名）喜欢装杯。「 于是，“装杯”就因此流行开来。'],
  ['有一个老实人他没有说话', '“有一个老实人他没有说话”用于调侃不懂梗的人，形容他们总是认真对待，是不明白玩笑和幽默的人。', '有人认真解释了某个梗，下面立马有人评论：“有一个老实人他没有说话！”', ''],
  ['尬到我脚趾抓地', '“尬到我脚趾抓地”用夸张的方式形容一种极度尴尬或羞耻的情绪。它描述人在感到尴尬时，脚趾会不自觉地蜷缩，就像在抓地一样。为了形容尴尬程度之高，网友们进一步扩展这种比喻，称脚趾抓地能抠出极大程度的东西，例如三室两厅或一个宇宙等。', '他在公司年会上表演了个魔术，结果道具失灵了，真是尬到我脚趾抓地，一个大坑都被抠出来了。', ''],
  ['出道半生归来仍是素人', '形容艺人出道已久，却仍不出名，像素人一样。', '他在娱乐圈努力多年，结果出道半生归来仍是素人。', '出自《吐槽大会》，由李诞用来调侃李汶翰，改自“出走半生，归来仍是少年。”'],
  ['雪花飘飘北风萧萧', '“雪花飘飘，北风萧萧”源自费玉清的歌曲《一剪梅》。最初因外国网红翻唱而走红，成为广为传递的网络梗。逐渐，这个梗在表达对反复无常的抱怨感到厌烦时使用（通常以拼音的形式）。', '朋友：我工作真糟糕，没有任何发展。      你：XUE HUA PIAO PIAO BEI FENG XIAO XIAO。', '由费玉清演唱的《一剪梅》中的歌词“雪花飘飘，北风萧萧”，因网红“蛋哥”的翻唱而在国外爆红。'],
  ['一起爬山吗', '「一起爬山吗「在网络上不仅仅是字面上的爬山活动，更暗指威胁或隐含敌意，有「危险「和「背叛「的含义。', '当朋友问你为什么对一场计划旅行犹豫不决时，你半开玩笑半认真地说：「一起爬山吗？怕被推下去。「', '这个梗出自中国电视剧《隐秘的角落》，由秦昊饰演的角色张东升在第一集中邀请岳父岳母爬山，并在攀登过程中将其推下山，意图谋杀。'],
  ['蒙古上单', '“蒙古上单”指代一种敢于直言、不畏惧后果的勇士精神。', '他在直播间公开批评不合理的规则，真是个“蒙古上单”。', '最初来源于B站用户“蒙古上单”，该用户在CEO陈睿发布的“后浪”视频下留下恶评，随后账号被封，因此被网友称为“勇士”。'],
  ['企业级理解', '企业级理解是一种戏谑或搞笑的表达方式，指明显错误或离谱的理解。有时用来调侃一本正经的胡说八道。', '你的解释还真是企业级理解，完全偏离原意了。', '这个梗最初是由斗鱼直播的李赣（李老八）在卖（假）鞋时发明的，他将自己的鞋子称为“企业级”，并以此为卖点进行宣传。'],
  ['在一声声靓仔中迷失了自我', '在广东，由于 「靓仔「 这个词被广泛用作对男性的友好称谓，使得外地人可能会误以为自己真的很帅，从而产生自我迷失的趣味现象。', '来广东旅游，一天到晚被叫靓仔，真是让我在一声声靓仔中迷失了自我。', ''],
  ['小白船', '“小白船”这个梗来源于童谣《小白船》在电视剧《隐秘的角落》中的出现，成为了恐怖事件的预兆和象征。在剧中，每次这首童谣响起时都会发生命案，因此被赋予了阴森、恐怖的意味。', '看完《隐秘的角落》，再听到《小白船》，心里一阵发毛，总感觉要发生什么不好的事情。', '电视剧《隐秘的角落》，该剧中《小白船》出现三次，与三次命案关联，使得这首歌成了剧情中的“死亡信号”。'],
  ['我还有机会吗', '“我还有机会吗”作为网络流行梗，常用于调侃某事没有希望或机会渺茫，因其在《隐秘的角落》中涉及关键情节，带有幽默和讽刺的意味。', '我的考试成绩那么差，我还有机会吗？', '该梗源自电视剧《隐秘的角落》，由秦昊饰演的角色张东升在剧中说的台词，他在剧中两次提到这句话后，其行为导致三人死亡。'],
  ['说最怂的话打最狠的架', '形容那些平时表现胆小懦弱，但在关键时刻展现出强大战斗力和勇气的角色或人。', '他就像我妻善逸一样，说最怂的话打最狠的架，关键时刻总能让人刮目相看。', ''],
  ['提桶进厂', '「提桶进厂「是形容工人在工厂之间频繁跳槽或更换工作的现象，通常是因为不满意工作环境或生活条件。这个说法突出了工人们在工厂中不稳定的就业状态，也带有一定的调侃意味。', '最近这家工厂加班太多，待遇也不理想，我准备提桶进厂，看看别的地方有没有更好的机会。', ''],
  ['罗玉龙', '「罗玉龙「是罗永浩的绰号，用来调侃他与凤姐（罗玉凤）在吹牛炒作方面的相似之处。', '大家都知道龙哥言辞犀利，「罗玉龙「的称号果然名不虚传。', ''],
  ['乌鸦像写字台', '“乌鸦像写字台”用来表示没有理由或无法解释的事情，类似于无缘无故的喜欢。', '面对朋友的疑惑，他只笑着说：“我对她的喜欢就像乌鸦像写字台一样，没有理由。”', '出自卡洛尔的《爱丽丝梦游仙境》，疯帽子在下午茶会上提出的无解之谜，“乌鸦为什么像一张写字台”。'],
  ['滑铲杀虎', '“滑铲杀虎”是一个网络梗，形象地描述了不切实际且夸张的战斗场景。起源于网友的调侃，讲述了一种通过滑铲动作抵挡并击败老虎的不可思议操作，常用来讽刺或幽默地描述虚构或夸大其词的情况。', '在游戏讨论中，他总喜欢说一些“滑铲杀虎”般的战术，听起来实在太不现实了。', '该梗来源于抗压吧，最初由一个贴吧用户“艾瑞莉娅”在讨论如何击败老虎时，提出了通过滑铲方式杀死老虎的荒诞想法。'],
  ['哥哥进鱼塘吗', '「哥哥进鱼塘吗「是一种调侃性用语，表示邀请对方成为自己的备胎之一。它暗指对方可能不是进入一个专一的爱情关系，而是成为其中许多个暧昧关系中的一个。', '小王对小丽表白时，小丽笑着说：“哥哥进鱼塘吗？可别太认真哦！”', ''],
  ['人性的扭曲还是道德的沦丧', '“人性的扭曲还是道德的沦丧”是一句用来夸大某件事情的严重性或荒谬性，以营造一种过于夸张的搞笑和讽刺效果。常用于调侃一些看似严重实际却并不那么重大的事件。', '朋友吃了我冰箱里的最后一块巧克力，这究竟是人性的扭曲还是道德的沦丧？', '这句话源自中央电视台社会与法频道以前的一档节目《道德观察》，用在节目预告中，通常会在描述一些社会怪现象或极端事件后提问，增强悬疑和戏剧性。'],
  ['在山海经第几页', '“在山海经第几页”是一句戏谑的说法，用来问别人是哪种“妖怪”，即形容对方长相奇特或行为怪异，借用《山海经》中对各种怪物、妖兽的记载进行调侃。', '看你今天的发型，真该问问你在山海经第几页。', ''],
  ['朱晶晶踩你的小白鞋', '「朱晶晶踩你的小白鞋「是用来形容人在做最后的嚣张和挑衅，提醒人不要过于自大和挑衅他人，因为可能会有不良后果。', '小明总是喜欢在同学们面前炫耀新买的东西，大家都说：“可别学朱晶晶踩你的小白鞋那样给自己找麻烦。”', '该梗出自电视剧《隐秘的角落》。剧中角色朱晶晶在挑衅朱朝阳后不久意外坠楼去世，她踩了朱朝阳的小白鞋成为一个象征性事件。'],
  ['代入感很强我已经开始生气了', '该梗用于形容在观看电影、阅读小说或看到某个场景时，由于感同身受而对角色的遭遇产生强烈的情绪反应，甚至开始生气。', '昨天看电视剧，主角被误会的那一段代入感很强，我已经开始生气了。', ''],
  ['fbi open the door', '用于警告和戏谑那些内容不当或涉嫌“ghs”（搞黄色）的人，表示这些行为已被发现。', '他在群里分享了一张擦边图，大家立刻刷屏：“FBI, open the door！”', '源于国外影片中，FBI探员在破门前大喊“FBI, open the door!”的场景。'],
  ['阴兵出动', '指一群打扮奇特且过度使用美颜效果的人，与奇怪的外貌相关。', '看他们的视频，感觉就像阴兵出动，实在是太奇怪了。', ''],
  ['我将来要当一个兔子警官', '“我将来要当一个兔子警官”表示一种积极向上、勇敢追梦的态度，借用《疯狂动物城》中兔子警官朱迪的形象，鼓励自己或者他人克服困难，实现目标。', '小明看了《疯狂动物城》后，非常受启发，总说他将来要当一个兔子警官。', '出自动画电影《疯狂动物城》，电影中的兔子朱迪通过努力成为了动物城的第一名兔子警官。'],
  ['所以爱会消失对不对', '「所以爱会消失对不对「这句话用来表达对爱情消逝的惋惜与无奈，它既可以用在悲伤的场合，也可以用作调侃或讽刺，当感受不到对方的热情或关心时，可以用来反问和质疑两人的感情状态。', '当小美发现小明越来越忙，陪伴她的时间越来越少时，她发了一条信息问他：“所以爱会消失对不对？”', '出自电视剧《我们与恶的距离》第一集，由角色天晴在发现父母关系出现问题时所说。'],
  ['心里没点ac数', '「心里没点ac数「的意思是让对方意识到自己的真实水平或地位，不要对自己有过高估计。这个短语通过替换中间字母，委婉表达了“心里没点B数”（即常用的网络俚语“心里没点逼数”），避免了直接使用可能被视为敏感或粗俗的词汇。', '他一边在讨论会上夸夸其谈，一边还不听别人的意见，真是心里没点ac数。', ''],
  ['正版打野', '“正版打野”这个梗最初来自于游戏英雄联盟的职业选手Xx对IG队员的嘲讽，意指原本战队的正式队员。但随着Xx在比赛中表现不佳，网友反倒用这个词来调侃他，使得“正版打野”带有讽刺和自嘲的意味。', 'Xx在比赛中的失误引发了网友们的一片调侃，纷纷表示“这就是大家期盼的正版打野吗？”', ''],
  ['力微饭否', '「力微饭否「用于嘲讽他人力气不足，类似于询问对方是否没有吃饭。这个梗借用了古文中的句式结构，常用于调侃力气小的人。', '在一场激烈的对战中，如果你的攻击对敌方完全无效，观众可能会在弹幕中刷：力微饭否？', ''],
  ['网抑云阴乐', '“网抑云阴乐”指对网易云音乐评论区中普遍存在的抑郁情绪发言的调侃，暗指很多用户在评论中分享个人伤痛或忧郁故事，有时被认为是无病呻吟或故意卖惨。', '有时候看网抑云阴乐的评论，比听歌还要伤感。', ''],
  ['网抑云时间到', '“网抑云时间到”是指在晚上或其他安静的时刻，人们倾向于用网易云音乐评论区来表达自己内心的孤独和抑郁感。这个时间段被认为是感伤和敏感情绪最容易涌现的时刻。', '“晚上十点，网抑云时间到，准备好纸巾，听歌看评论了。”', ''],
  ['懂的都懂', '「懂的都懂「用于表达某种信息的隐晦或复杂性，只有特定的人会明白，而不了解的人很难进入这个圈子。常常用于玩梗，或表示信息只能意会。', '昨天的电影情节真是细思极恐，懂的都懂，不多说了。', ''],
  ['像个沙口', '“像个沙口”意思是像个小丑一样可笑，用来形容一个人显得可怜或自嘲。', '每次我说了一大堆结果没人回应，我就觉得自己像个沙口。', '该梗出自虎牙平台，在火星包和乐言进行《英雄联盟》直播双排时，因为包子几乎全程自言自语，乐言没有怎么搭理他，于是包子自嘲自己“像个沙口”。沙口是《英雄联盟》中“小丑”萨科的谐音。'],
  ['横扫鸡饿', '“横扫鸡饿”是士力架广告语“横扫饥饿”的谐音，用来形容一个搞笑的视频场景，其中一个人用扫腿的方式来赶走偷吃的鸡。形象化表达了鸡在偷吃时的滑稽和主人的反应。', '看完那个“横扫鸡饿”的视频，笑得肚子都痛了，那只鸡简直是个吃货。', ''],
  ['希望你不要不识抬举', '“希望你不要不识抬举”是一种调侃性质的玩笑话，用于在请求别人帮忙或借东西时增添幽默感。说这句话的人通常在前面表现得非常诚恳，使得最后这句带有些许强硬态度的话显得更有趣。虽然字面上可能看似强势，但实际上并没有贬义，只是表达急需帮助的意思。', '小明：哥们，下周末帮我搬家吧。事后请你吃大餐，希望你不要不识抬举！', '该梗来源于微博用户@Steed的围脖的一条微博。一位粉丝非常喜欢博主的照片，并希望能够转载。她在私信中前面一直保持着非常诚恳的语气，但最后突然加上一句“希望你不要不识抬举”，这种语气的反差被网友们发现后加以调侃和传播。'],
  ['妈妈的好大儿', '“妈妈的好大儿”表示赞誉和亲昵，类似于“妈妈的好儿子”或“好宝宝”。它可以用于形容人或宠物，以表达一种宠溺的情感。', '小明考了100分，妈妈开心地摸着他的头，说：“我们家小明真是妈妈的好大儿。”', '该梗出自抖音博主“你的陈比方”，她在视频中使用“妈妈的好大儿”来称呼她的白色柴犬，这成为一种独特的爱称。随着视频的传播，这句话被网友广泛使用并逐渐成为一种网络梗。'],
  ['有奇怪的东西混进去了', '“有奇怪的东西混进去了”指突然出现一些不相关或令人惊讶的东西，通常用于表达对未知事物的调侃或嘲讽。', '在一个全是萌宠图的社交媒体群里，突然有人发了一张恐怖电影剧照，大家纷纷评论：“啊咧？有奇怪的东西混进去了。”', '这个梗出自动画电影《千与千寻》。在电影中，无脸男进入汤屋后，汤婆婆对这个陌生的存在表示不解，说了一句：“有奇怪的东西混进去了。”这句话后来被网友用于网络调侃。'],
  ['歪嘴战神', '“歪嘴战神”是用来形容网络爽文中男主角的一种特定表情，这表情伴随着剧情的反转。当男主受到他人嘲讽或打击时，他会露出一种歪嘴、邪魅的微笑，象征他的隐藏身份即将揭示，他马上要展现出强大能力和地位。', '看到他被老板怒斥后嘴巴一歪，我心想：这又是“歪嘴战神”要上线了。', ''],
  ['住在山里真不错', '“住在山里真不错”是一句来源于CSGO主播茄子的搞笑短语，常用于表达对生活环境的满意，带有轻松幽默的意味。', '看着窗外的风景，我不由得想起茄子的那句话：“住在山里真不错。”', '该梗来自CSGO主播茄子的一次户外直播。在直播中，茄子在山中度假时说道“真不错，住在山里真不错”。由于其身着大裤衩的搞笑形象和魔性语调，这句话迅速在网上传播开来。'],
  ['脚趾抠出三室两厅', '形容一个人感到非常尴尬、羞愧，尴尬到极点，甚至夸张到像用脚趾抠出一个大房子一样。', '听到自己童年录音被播放出来，我当时脚趾抠出三室两厅了。', ''],
  ['孩子死了来奶了', '「孩子死了来奶了「这个梗用于形容做事拖延、不及时处理，等到事情严重或者无法挽回时才意识到问题的重要性，从而为时已晚。它提醒人们要及时处理问题，以免后悔。', '他一直拖着不去修车，等到车在路上抛锚才去修，这就是真正的孩子死了来奶了。', '这个梗最早起源于2009年的某则新闻报道，报道中提到了一位名叫王某的人因为在救助被困的孩子时耽搁了时间，导致孩子最终不治身亡。在接受采访时，王某说出了「孩子死了来奶了「这句话，意思是他现在才来帮忙已经为时晚了。这则报道在当时引起了轩然大波，并迅速在社交媒体上流传开来。'],
  ['眨眼补帧', '“眨眼补帧”是指在游戏或视频出现卡顿时，通过快速眨眼跳过不流畅画面，使视觉上感觉顺畅的调侃方式。这只是一种玩笑，没有实际作用于改善性能。', '玩《绝地求生》时我电脑突然卡了，弹幕全刷“眨眼补帧”，笑得我都忘了操作。', ''],
  ['变身盖亚', '“变身盖亚”用来调侃一个人在情绪失控或愤怒时发出的吼声，形容这个瞬间像是奥特曼盖亚变身时喊叫的声音。这种吼声可能源于对复杂任务的挫败感，比如在玩难度很高的游戏时沮丧到极点的反应。', '小明在考试成绩出来后看到分数低得可怜，气得原地“变身盖亚”。', '该梗来自于网络主播卢本伟（五五开）在直播时玩一个抡铁锤游戏时的经典时刻。他在游戏中因为失误导致角色下跌时，发出了一声类似奥特曼盖亚变身前的大喊，网友因此创造了“变身盖亚”这一说法。'],
  ['干饭了', '干饭了，意思是准备开始吃饭，一种热情豪爽的说法。', '时间不早了，大家快来，干饭了！', '出自抖音土味博主“诗书达礼之山人”的视频，他在视频中总是在院子里拿着饭菜说“干饭了！干饭了”，引起了他的鸡过来抢食的有趣场景。'],
  ['现已加入肯德基豪华午餐', '用作万能搞笑回复，特别是在涉及食物时，是一种调侃和幽默的方式。', '今天早餐吃的油条，现已加入肯德基豪华午餐。', '来源于2011-2013年期间肯德基的广告词，因视频网站广告推广而被网友恶搞。'],
  ['老倒霉蛋了', '形容一个人特别倒霉，尤其是在游戏比赛中因意外或奇怪的方式死亡。', '「今天我在游戏里被自己的手雷炸死，真是老倒霉蛋了！「', ''],
  ['白骨之后再无西游', '这句话表达了对一款游戏质量下滑的失望，尤其是在经历重要剧情节点后的变质。', '“这部剧拍到这里也太崩了，真是白骨之后再无西游啊。”', '来自网游《斗战神》。在游戏的“白骨精”章节后，因为盈利模式改变和主创团队的离职，游戏质量下降，玩家因此感慨“白骨之后再无西游”。'],
  ['韭菜人', '“韭菜人”特指那些想要以小成本获取大收益，但最终因缺乏识别能力而被欺骗，交了“智商税”的人群。他们自以为能占便宜或获利，结果却被他人利用，反而遭受损失。', '看到这个不切实际的投资回报，许多人心动加入，结果却成了韭菜人，被平台卷走了钱。', ''],
  ['脑补型恋爱', '脑补型恋爱指的是在爱情关系中，一方对另一方进行过度理想化和幻想，而没有考虑对方的真实意图和需求，这种自我感动的恋爱行为可能会给对方造成精神压力和困扰。', '小丽最近陷入了脑补型恋爱，她总是幻想她和那个男生在一起会怎样，甚至想到了两人白头偕老的样子，但实际上他们才认识几天。', ''],
  ['云端孝子', '指那些在微信朋友圈里通过转发祈福图片为父母祈福保平安的年轻人，暗示这些人可能在现实中并未真正尽孝。', '他每天转发那么多祝福图片，俨然成了个云端孝子。', ''],
  ['小嘴抹了蜜', '“小嘴抹了蜜”是一个网络流行语，原用于夸奖人说话好听，但现在多用于反讽，形容某人嘴上跑火车、满嘴脏话或行为低素质，是一种贬义词。', '在观看某主播直播时，他突然开始爆粗口，弹幕上纷纷刷起：“XX小嘴抹了蜜，果然不负所望。”', ''],
  ['战歌起', '“战歌起”是一种评论用语，指代热血、激昂的背景音乐（BGM）的开始，特别是在动漫或影视作品中。当剧情达到高潮或即将开始战斗时，这类音乐会播放，迅速提高观众的情绪，增添紧张感。', '《进击的巨人》片头曲一响，弹幕瞬间刷满“战歌起”。', ''],
  ['冲就完事了', '“冲就完事了”是一种鼓励人们在生活中不要犹豫，放手去做的态度。无论遇到什么事情，不必多想，直接行动。', '在游戏对战中，小明说道：“别犹豫了，咱们冲就完事了，赢下这一局！”', ''],
  ['午马', '“午马”是指那些默默干活、不能有怨言、不能出头的人。由“牛马”演变而来，字面上表示出不了头的“牛马”。', '他在公司里就是个午马，做了很多事却从不被表扬。', ''],
  ['英年早睡', '“英年早睡”是一个提醒年轻人关注健康和正常作息的梗。它强调身体健康的重要性，建议年轻人在打拼的同时也要确保充足且规律的休息。', '他最近开始英年早睡，拒绝了所有晚上的聚会，就想好好调整作息。', ''],
  ['摆烂', '摆烂指在事情无力好转时，不再采取措施而任由事态变坏，类似于破罐子破摔。', '他觉得这次考试太难，准备彻底摆烂，不再复习了。', ''],
  ['听君一席话如听一席话', '“听君一席话如听一席话”用来讽刺某些讲话内容没有实质意义或信息，人们听后没有任何收获。这种表达是一种幽默的调侃，表明对说话内容的无奈或失望。', '听完他的演讲，我只能说“听君一席话如听一席话”，完全不知道他在说什么。', ''],
  ['社恐牛逼症', '“社恐牛逼症”形容一些人在平时是社交恐惧症患者，尽量避免与人接触和交流，但在特定情况下，例如需要集赞、抢票等，能够主动克服恐惧，与人进行社交互动，从而表现出极强的社交能力。', '小明平时见到邻居都避开走，但为了拿到微博抽奖限量款，他突然变得很活跃，展示了他的“社恐牛逼症”。', ''],
  ['半场开香槟', '“半场开香槟”指的是在取得巨大优势后，过早放松，最终被对手逆转的情况。这个短语通常带有调侃和嘲讽的意味，多用于体育赛事和电子竞技中。', '在今年的季后赛中，这支球队上半场大比分领先，结果以为稳操胜券，结果下半场对手打了个漂亮的翻盘，真是“半场开香槟”的教科书案例。', '这个梗出自2005年欧洲冠军联赛决赛。在这场比赛中，AC米兰队在上半场取得了3比0的领先优势，但在下半场被利物浦队追平，并在点球大战中输掉了比赛。赛后，AC米兰的右后卫卡福透露，在中场休息时，全队过早庆祝，以为胜利已经稳操胜券，并打开了准备庆祝的香槟，结果导致了放松警惕，最终输掉了比赛。'],
  ['new一个对象', '调侃程序员因为忙于工作而单身，希望通过编程术语“new”来创建一个虚拟对象。', '他总是加班到很晚，调侃自己要“new一个对象”陪伴。', ''],
  ['演的吧', '“演的吧”通常用于短视频评论中，意指视频内容是演绎的，而非真实发生的事件。这一评论有时是为了讽刺视频的不真实，也可能是单纯的玩梗。', '看着这对情侣的争吵视频，评论里一片“演的吧”，真是让人哭笑不得。', ''],
  ['为什么不ban猛犸', '指在比赛中没有禁止对方使用发挥出色的英雄，导致失利。用来调侃或反思决策失误。', '这次比赛我们输得莫名其妙，真想问一句：为什么不ban猛犸？', '出自DOTA2的Ti10比赛，中国战队LGD在总决赛对阵Team Spirit时，没有禁止对手选择表现强势的英雄“猛犸”，最终输掉了比赛。'],
  ['抢五杀', '「抢五杀「是指在多人在线游戏中，一个玩家即将连续击杀五个敌人获得“五杀”成就时，却被队友抢走了最后一个击杀，导致未能达成。此行为在游戏中较为让人恼火，因为“五杀”是难得的成就。', '张三本想在团战中拿下五杀，没想到最后一个人头被李四抢掉，惹得他非常不满。', ''],
  ['叠甲', '“叠甲”原本是指在游戏中提升角色防御力的动作，现如今在网络语言中被用来指代在表达观点时加入免责声明，以避免被批评或争论。', '这部电影真的不太好看（仅个人观感，不代表大家意见哦）。', ''],
  ['完结撒花', '「完结撒花「是一个用于吐槽或纪念作品完结时的流行用语。它通常在动画、影视剧等作品的最后一集或重要剧情节点之后使用。这个词用于表达作品完结后的庆祝或调侃，并且随着情节的发展，有时用来反讽或恶搞。', '当我看到《进击的巨人》第五集艾伦被巨人吃掉的那一刻，我情不自禁地在弹幕中刷了“完结撒花”。', ''],
  ['花果山高级会议', '指局内交流混乱，像花果山一群猴子在开会。', '看完这场比赛的语音，我只想说，这简直是花果山高级会议。', ''],
  ['牛顿气活了', '指某些场景过于夸张和离谱，以至于违反了物理规律，牛顿看见了会“气得活过来”。', '那个电影里主角能在空中随意行走，牛顿气活了也得质疑一下。', ''],
  ['你喜欢银杏吗', '“你喜欢银杏吗”是用于暗戳戳表白的一句话，表达“以朋友的名义偷偷喜欢着你”的意思。其中，“银”为“有你”，“三生有杏”。', '在聊天时，他突然问我：“你喜欢银杏吗？”我去查了才发现他的用意。', '这句话出自电视剧《月光变奏曲》，剧中角色顾白芷在银杏树下问男主江与城“你喜欢银杏么”，男主也表白“我喜欢银杏，也喜欢你”。'],
  ['对冲式养生', '对冲式养生是一种矛盾的生活方式，指年轻人一边从事对健康有害的活动如熬夜、吃垃圾食品等，一边又积极采取措施如敷面膜、喝枸杞水等，希望抵消这些不健康行为带来的负面影响。', '小王每天熬夜追剧，但早上又泡一杯枸杞茶，他说这是他的对冲式养生策略。', ''],
  ['ddl是第一生产力', '这个梗描述了人们在截止日期（deadline，缩写为ddl）临近时，因感受到压力而变得高效。这是对拖延症的一种戏称，表示尽管拖延，但在压力下能激发出最高的效率。', '离项目提交还有三个小时，我终于开始正经写作了，果然ddl是第一生产力。', ''],
  ['蓝桉已遇释槐鸟', '这个梗用来表达温柔和爱只给予一个特定的人。', '「就像蓝桉已遇释槐鸟，我的心中只有你一个住所。「', '源自印度诗人泰戈尔的《飞鸟集》中的一句话。蓝桉是一种很霸道的植物，身边并不允许有其他种类的植物生长，不过有一种可以在它的树上面栖息，这种鸟叫释槐鸟，也叫红嘴蓝鹊。'],
  ['列文虎克', '“列文虎克”在网络中用于形容那些观察力极为敏锐、能察觉细微细节的人。这种人通常能够注意到别人容易忽略的小细节，就像使用显微镜一样观察事物。', '“你真是个列文虎克，居然连背景墙上那小小的字母都能看到！”', '这个梗来源于17世纪的荷兰科学家安东尼·列文虎克，他是显微镜学家和微生物学的开拓者。列文虎克以其对显微技术的贡献而著称。'],
  ['我听见雨滴落在青青草地', '这个梗隐晦地指代某人被戴了绿帽子，其中“青青草地”暗指草地的绿色，“雨滴”则代表泪滴。', '最近看到他发的状态，我总有种“我听见雨滴落在青青草地”的感觉。', '源自田馥甄演唱的歌曲《小幸运》的歌词：“我听见雨滴落在青青草地”。'],
  ['你惨了你坠入爱河了', '表达对陷入恋爱的调侃和无奈，现在多用于官宣恋情。', '朋友发了个视频说：“你惨了你坠入爱河了”，然后把他和女友的甜蜜合照播出来。', '出自电影《赌侠2》，是吴孟达的台词。'],
  ['网络街溜子', '网络街溜子指的是一种在各种社交或娱乐软件之间来回切换、瞎逛，但并没有具体目的或任务的人。这种行为通常表现为无聊、懒散，类似于现实生活中“游手好闲”的状态，只不过是在互联网世界中进行。', '这个周末我啥事没干成，就一直当个网络街溜子，在各种app之间来回切换。', ''],
  ['我将以高达形态出击', '“我将以高达形态出击”是一句来自电影《头号玩家》中的台词，表现了一种中二且带有英雄情结的宣言。它用幽默的方式表达了人们对变身为强大角色的幻想和一种出击（行动）的决心。', '朋友：比赛要开始了，你准备好了吗？      我：当然了，我将以高达形态出击，让他们见识真正的技术！', '该梗出自电影《头号玩家》，由一个角色“大东”在准备驾驶高达元祖机时说的台词。这句日语台词是“ガンダムで出撃する”，翻译为汉语即“我将以高达形态出击”。'],
  ['什么封把您吹来了', '是“什么风把您吹来了”的谐音，指“你是因为封面才点进来的吗？”，是一个调侃吸引人眼球封面的梗。', '当我看到封面上那只超萌的小猫时，我在评论区打下“什么封把您吹来了”。', ''],
  ['林黛玉发疯文学', '“林黛玉发疯文学”是指模仿《红楼梦》中的林黛玉，用其柔弱、阴阳怪气的语气进行调侃或反击。这种模仿通常通过委婉而带刺的话语表现出来，可以用于社交中表达不满或进行自嘲，在表达时带有一丝幽默和讽刺。', '当朋友许久没有回复信息时，可以说：“你大抵是倦了，竟回我这般敷衍。”这用的是林黛玉式的语气去表达自己的不满。', ''],
  ['嗨害嗨', '“嗨害嗨”是一种引起注意的打招呼用语，因其魔性感觉而在网络上走红。', '每次看到老8的视频，我都期待他经典的“嗨害嗨”开场白。', '出自某位知名美食up主“老8”的视频，他是以奇葩黑暗料理闻名的吃播。'],
  ['国宴', '「国宴「是一个用来形容游戏中顶级的“下饭菜”的梗，表示玩家或队伍的操作非常烂，让观众觉得是在看一个顶级的菜鸟表演。', '今天队友团战操作简直是“国宴”级别，连对面都在帮我们。', '该梗来源于《英雄联盟》（LOL）比赛中的调侃。特别是当RNG和EDG两个中国队伍在大赛中表现不佳时，观众用“国宴”来称呼他们，以调侃其操作水平堪称国家级别的下饭菜。'],
  ['大冤种', '“大冤种”是指一个人显得比较傻，或者做了傻事被称为“大冤种”。也可以指因蒙受冤屈而感到不快的人。它常被用来自嘲或形容他人不走运、不机灵的状况。', '小李加班到深夜，结果第二天发现其实根本没必要，直呼自己是个职场“大冤种”。', ''],
  ['Kiss Kiss', '在网络中，「Kiss Kiss「表示暂停或停止的意思。', '他做了个「Kiss Kiss「的手势，示意理发师稍微停一下。', '出自短视频博主大名一米九masala，在孟加拉国体验理发洗脸服务时，由于理发师的手法过于粗犷，再加上语言不通，导致该博主只能通过飞吻打招呼的方式临时打断理发师的热情服务。'],
  ['95加满', '「95加满「这个梗主要用来讽刺和调侃当前油价高昂不下，导致人们加油时产生经济压力。现已成为一种网络上幽默地表达经济拮据或油价过高的方式。', '因为油价太高，现在去加油站看到有人说“95加满”，我都忍不住想多看两眼，这是真有钱。', ''],
  ['世界上有五种辣', '“世界上有五种辣”是一个土味情话，通过谐音双关的方式，将“我想你辣”作为第五种“辣”，表达想念之情。经过二次创作后，此梗被用于各种谐音玩笑和名场面剪辑。', '世界上有五种辣：微辣、中辣、特辣、变态辣，我想你辣！', ''],
  ['佛不渡本科以下', '调侃现代寺院招聘和尚有学历门槛，讽刺出家也需高学历。', '想摆脱世俗烦恼？记得先拿到本科学历，毕竟“佛不渡本科以下”。', ''],
  ['网易云八级', '“网易云八级”指的是在网易云音乐拥有八级用户等级的人，象征着这个人听过许多歌曲，经历过许多故事，从而理解更多道理。在网络文化中，这个等级被戏称为“好男孩/好女孩”认证，因为这个人把大量时间花在听音乐上，是一个有故事的人。', '每天上下班路上听歌已经成为习惯，终于达到了网易云八级，我也是被官方认证的“好男孩”了。', '“网易云八级”源于一名男网友在社交平台晒出他在网易云的等级已达八级，并称自己是“好男孩”，这一说法引发大量网友关注和讨论，促使大家纷纷晒出自己的网易云等级。网易云音乐团队随后推出了“8级证明书”，8级及以上的用户可获得“好男孩”“好女孩”认证。'],
  ['我真的会谢', '用于表达对生活中让人郁闷或无语的人的调侃和吐槽。', '我真的会谢，网络又断了，还怎么工作？', '出自微博搞笑博主@怨男0的口头禅，因其幽默和讽刺感而流行。'],
  ['啊对对对', '“啊对对对”表示敷衍和摆烂，用来应对无理取闹、尖酸刻薄的人或无端指责，表达不屑与对方计较或合作的情绪。', '面对同事无理的批评，我心里想着“啊对对对”，不再与他争论。', '源自游戏主播“csgo久菜合子”的直播。在一场游戏中，他面对队友的嘲讽，用“啊对对对”反讽回应，引起观众共鸣，后广泛流传。'],
  ['没说就是零卡', '「没说就是零卡「是一种调侃，指的是食物如果没有标明卡路里含量就被假设为不含卡路里，暗示即使食物不健康也不会令人发胖。这个梗是用来打趣那些在健身或饮食中不太严谨的态度。', '今天朋友请我吃小蛋糕，我开玩笑说，没看到卡路里标识，没说就是零卡，吃了也不怕长胖。', '该梗源于抖音博主@秃顶吴彦祖的一段视频。在视频中，他手拿不那么健康的食物，开玩笑地说没有标注卡路里的食物就相当于零卡路里。'],
  ['妹妹说紫色很有韵味', '这个梗用来调侃或形容与紫色相关的事物，暗示紫色具有独特的吸引力。', '看这辆车的颜色，真的和妹妹说的一样，紫色很有韵味！', '来自许嵩的歌曲《多余的解释》，包含歌词“她只是我的妹妹，妹妹说紫色很有韵味”。'],
  ['比比安慕希', '「比比安慕希「是一种中文谐音空耳，用于模仿歌曲《Beep Beep I’m a Sheep》的歌词。该词因其魔性的旋律和幽默的中文谐音而走红，成为网友制作变装视频及其他搞笑内容时的热门用语。', '看了这个变装视频，脑子里全都是比比安慕希，真是洗脑神曲。', ''],
  ['麦乐鸡侠', '「麦乐鸡侠「是指在麦当劳工作时，多给顾客一块麦乐鸡的员工，被视为默默支持消费者的无名英雄，帮助顾客「割资本主义韭菜「。', '「每次去麦当劳买麦乐鸡，我都会心里默默期待遇到麦乐鸡侠，为我多给一块。「', ''],
  ['金钱豹', '金钱豹这个梗寓意着对新一年暴富的期盼和对富贵生活的向往。换上金钱豹的头像象征着希望能够带来金钱和好运。', '看了那么多人换上金钱豹头像，我也赶紧换上，万一新的一年真能暴富呢！', ''],
  ['老师菜菜捞捞', '“老师菜菜捞捞”由“亲爱的老师，期末了，你可爱的学生菜菜的，能不能捞捞我，呜呜呜”这句话缩写而成，是一种撒娇式的请求，表达大学生希望在期末考试时老师能宽容打分，帮助他们不挂科。', '老师，期末考试我真的努力了，求您菜菜捞捞，让我过吧。', ''],
  ['卡农警告', '卡农警告是指一种预示即将发生不好的事情的信号，类似于死亡警告。这种警告会让人感到恐惧和紧张。', '在玩恐怖游戏时突然播放卡农，真是卡农警告，把我吓得差点退出游戏。', '该梗来源于无限流题材电视剧《开端》。在剧中，每当快要发生爆炸的时候，女主会听到卡农的铃声，使得观众和角色都对这种音乐产生了一种条件反射的害怕感。'],
  ['万物皆可钝角', '“万物皆可钝角”是一个网络流行梗，代表任何无法描述或让人困惑的事物。钝角这个词无具体意义，但用来表达网友们的幽默与调侃，是一种玩味语境的方式。', '最近的考试题变得越来越奇怪，真是“万物皆可钝角”了，每道题看得我云里雾里。', '该梗出自B站up主艺能人金广发于2021年11月14日发布的视频《金广发·讲堂》第六课。在视频中，他展示了一道选择题，其中的选项“钝角”毫无关联性，仅为娱乐效果，后被网友广泛传播。'],
  ['有的人出生就在罗马', '这个梗表达了一种对人生起点差异的不平感叹。与“条条道路通罗马”相对比，体现了有些人生来就拥有优越的条件和资源（象征性地描述为“出生就在罗马”），而另外一些人终生辛苦劳作而难以改变命运（象征性地描述为“生来就是牛马”）。', '当我们努力工作赚取微薄的工资时，我们突然意识到，有的人出生就在罗马，而我们却在前往罗马的道路上做牛马。', '此梗出自B站UP主大猛子ym的视频内容，他是一位土木工程毕业生，拍摄工地生活的日常，常自嘲为工地上的牛马。'],
  ['emoha', '“emoha”是“emo”（抑郁、忧伤）与“ha”（哈哈大笑、开心）的结合，形容人在忧郁和开心之间来回切换的情绪波动。', '今天虽然早起很累，但是看到阳光明媚的早晨，瞬间emoha了。', ''],
  ['声微饭否', '「声微饭否「是指「大声点！没吃饭吗？「的文言缩写，用来调侃或反讽他人说话声音小。', '余小c在游戏里突然大喊，弹幕立刻刷满“声微饭否？”。', ''],
  ['德华', '德华这个梗指的是在家中假期间，帮助亲戚朋友照顾孩子的大学生。', '放寒假回家，本来想好好休息，结果变成了德华，每天都要带侄女上兴趣班。', '源于电视剧《父母爱情》中的角色江德华，江德华在剧中无怨无悔地帮助照顾哥哥的五个孩子。'],
  ['钵钵鸡', '指四川特色小吃钵钵鸡，因其魔性洗脑的叫卖声而走红。', '最近在家总是忍不住学那句“钵钵鸡，钵啊钵钵鸡，一元一串的钵钵鸡”。', '源自一位网友在街头录制的一段钵钵鸡摊主的叫卖声，“钵钵鸡，钵啊钵钵鸡，一元一串的钵钵鸡”，因其魔性而迅速传播。'],
  ['内娱嫂子', '内娱嫂子是指娱乐圈中某个明星的女友或妻子，粉丝通常称她们为“嫂子”，这是因为粉丝常称他们喜欢的男明星为“哥哥”，因此自然称呼他女友或妻子为“嫂子”。', '当小王子爆出恋情后，粉丝们纷纷称他的女友为内娱嫂子。', ''],
  ['你算是踢到棉花啦', '“你算是踢到棉花啦”是一种摆烂、顺从的态度与方式来表达放狠话。原本的“踢到钢板”表达强硬对抗，这个梗则恰恰相反，没有实际伤害，但有一定的精神攻击效果。', '当我弟弟以为我会生气时，我只淡淡地回应他：“你算是踢到棉花啦”，他居然一时不知道该怎么接话。', '该梗出自某音博主李玉玲的视频。李玉玲因其声音很像AI客服，在视频中用AI的口气说“哈哈你算是踢到棉花啦”。这种密集性、魔性且上头的表达方式受到了网友的模仿和传播。'],
  ['张万森下雪了', '“张万森下雪了”这个梗用于表达思念之情，其中“张万森，下雪了”可以理解为“我想你”。这是一个文艺式的表达方式。', '每到冬天看到飘雪的日子，我总想对你说：“张万森，下雪了，我好想你。”', '这个梗来源于电视剧《一闪一闪亮晶晶》中的台词，原句是：“张万森，下雪了，你还好吗，我好想你啊，我真的好想你”，因剧中演员张万森的精彩表现而成为网络流行语。'],
  ['南方小土豆', '「南方小土豆「 是一个对南方游客在东北冰雪旅游期间的亲切称呼。这个昵称带有一种幽默和温馨的色彩，形象地描述了南方游客因穿着厚重的羽绒服而显得圆乎乎的样子。', '每到冬天，东北的冰雪城镇就开始热闹起来，到处都是兴奋的南方小土豆。', ''],
  ['使用科技', '“使用科技”指的是学生在完成作业时，依赖搜题软件而不是自己思考，是一种利用科技手段快速完成任务的行为。这种说法常用于对依赖技术进行学习的调侃。', '看到小明快速完成了整套作业，有同学笑道：“看来又是‘使用科技’的成果啊！”', ''],
  ['刚满十八岁', '源自抖音博主“小白龙x”发布的一条采访视频。在视频中，一位女生用夹子音回答“今年多大了？”时，说道“刚满十八岁”，随后又用同样的语调解释自己没有谈过男朋友，理由是“刚满十八岁”。她那夸张、扭曲的语调和诡异的声音让原视频看起来非常“魔性”，引发网友的关注，并迅速成为整活和二次创作的素材。', '朋友聚会时大家讨论感情经历，一个人忽然用夹子音说道：“我没有谈过恋爱，因为——刚满十八岁。”', ''],
  ['房山季鸟猴', '“房山”为北京的一个地名，“季鸟猴”在北京话中是知了的意思，这个梗用于形容话多、声音大、能吵的人，借喻知了的聒噪特性。', '他今天又开始了，跟个房山季鸟猴似的，一吵没完没了。', '源自抖音博主@艺能人金广发的一则短视频段子。视频中，一名网约车司机与男乘客发生纠纷，男乘客找了一名女子来帮忙。女子一开口就说：“‘房山季鸟猴儿’听说过吗？那是我姥姥，马上就到，还有31.7公里，看着办吧。” 司机听后非常困惑，于是打电话问朋友“房山季鸟猴儿”是怎么回事。在得到解释后，司机立刻态度大变，表示认错并请女子做'],
  ['性歹力', '“性歹力”是网友在“性张力”和“性缩力”基础上创造的新词，用来形容某些人自认为自己在散发性感魅力，但实际上却让人感到不适甚至惊恐，令人脚趾蜷缩，牙关紧咬，有一种强烈的反感和排斥感。', '明明只是想要表现成熟的气质，可他一出场就满满的性歹力，让人想掉头离开。', ''],
  ['糊穿地心', '“糊穿地心”是一个网络流行词，用于形容原本非常受欢迎的明星或现象因各种原因失去人气，变得过气。这是一个饭圈中常用的夸张说法。', '曾经红极一时的那位歌手，现在已经糊穿地心，几乎没人再提起他了。', ''],
  ['差生文具多', '「差生文具多「是一个网络流行语，最初用于调侃那些虽然成绩不好，却总是买很多文具装备的学生。现在，这一说法被扩展到其他领域，如健身、做菜、和养花等，形容那些虽然技术不精，但在装备上非常讲究的人。', '他健身时总是穿最新款的运动服，用最先进的健身器材，但练了半年还没学会正确的深蹲姿势，真是典型的差生文具多。', ''],
  ['跳科目三', '跳科目三是指一种近期在抖音上流行的舞蹈形式，因其起源视频被称为“广西科目三”，而得此名称。这一舞蹈风格充满活力，成为许多网友模仿的对象，虽被一些人认为土味，却因其独特性而广泛传播，成为一种文化现象。', '最近抖音上到处都是跳科目三的视频，你看看是不是也想学两步？', ''],
  ['汗流浃背了吧', '「汗流浃背了吧「 用于嘲讽对手实力不行，面对强势对手只能勉强应对，以导致出汗的情境戏谑对手。', '在游戏对局结束后，小明对输了比赛的对手说：「汗流浃背了吧，老弟？不行就多练练。「', '该梗出自火影忍者手游主播 Coke 老师，他在每次对局胜利后都会对被击败的对手说这句话以进行嘲讽。'],
  ['笑拥了', '“笑拥了”是一个谐音梗，实际意思是“笑晕了”。这个短语的来源是因为说话带有口音而将“笑晕了”空耳成了“笑拥了”。', '昨天看那个博主直播，搞笑的问题太多，简直让我“笑拥了”。', '出自抖音视频博主完颜慧德的语录。完颜慧德是一位自称北大毕业的国家二级心理咨询师，因长相酷似三梦奇缘而在网络上走红。'],
  ['脆皮大学生', '“脆皮大学生”这梗用来形容一些在温室环境中长大的00后大学生，他们由于生活条件较好，缺乏艰苦经历，导致身体娇弱容易受伤。', '昨天我室友仅仅是下床踩空了一步，结果脚踝就崴了，果然是个脆皮大学生。', ''],
  ['当代华佗', '“当代华佗”指在短视频中扮演医生，用幽默、出人意料的方式为患者解决各种疑难杂症，常常通过调侃或讽刺的回答达到搞笑效果。', '病人问医生怎么提高工作效率，当代华佗建议：不如直接请个假。', ''],
  ['男人至死是少年', '调侃男人永远不会成熟，永远保持热血和童真。', '他总是对模型车情有独钟，真是印证了“男人至死是少年”。', '源自《银魂》第四话中坂田银时的自言自语，原话是“糟了，今天是《JUMP》的发售日啊！忘了这周是周六发售了，我们折回去？……不过，这说不定是从《JUMP》毕业的好机会，省得被人说这么大年纪了还看《JUMP》……不，男人到死为止都是少年啊！”。'],
  ['菜就多练', '指责一些玩家技术不好却经常质疑他人的行为，但从作弊玩家口中说出显得荒诞。', '你今天枪法不准？没关系，菜就多练，多打几场就好了！', '《穿越火线》主播董广君在与穿越火线前职业选手70kg线上对战后被质疑开挂，随后在直播中发表了“菜 就多练”的言论。事件发酵后，由于广君涉嫌开挂，却发表如此硬气的言论再配上过于魔性的手势，再加上CF外挂泛滥早就令玩家苦不堪言，引发了诸多玩家的声讨及二创。'],
  ['遥遥领先', '“遥遥领先”是一个网络流行语，用来夸大和赞美某些场景或事物，表示其具有显著的优势或与竞争者之间存在较大差距。', '在游戏中他总是能提前布局，最后分数遥遥领先其他玩家。', '该词来源于华为消费者业务CEO余承东在华为发布会中多次使用这个词来形容华为手机与其他品牌之间的差距，因而走红网络。'],
  ['公主请上车', '“公主请上车”是一种网络流行语，起源于一段搞笑视频。通常用于调侃或讽刺，表达对于某种行为或状态的无奈或幽默感。它隐含了一种对生活中不情愿但又不可避免的事情的调侃和戏谑。', '每天起床都像打仗，闹钟一响，我就对自己说：“公主请上班。”', '这个梗来源于一名父亲骑电动车接女儿时，女儿要求父亲说“公主请上车”才肯走的搞笑视频。'],
  ['hhh', '「hhh「是汉字“哈哈哈”的拼音首字母，最初代表哈哈大笑，用于表示开心或觉得某件事有趣。经过时间的沉淀，现在通常表示浅笑。', '朋友发来一个特别冷的笑话，我回复他一个「hhh「表示浅浅一笑。', ''],
  ['佛山电翰', '“佛山电翰”是一位抖音网友，他因长相酷似演员张翰而备受关注。他在视频中标志性的甩手动作成为网络流行的模仿对象，各行各业的网友都争相效仿这一动作。', '昨天在抖音上刷到了“佛山电翰”的视频，大家都在模仿他的甩手动作，真的太好笑了。', ''],
  ['租给大学生', '「租给大学生「是在网络社区中，用于调侃和幽默回应关于狭小或未充分利用空间的帖子。因大学生典型地居住在狭小的地方，且预算有限，因此这种回复暗示可以将这样的空间出租给经济拮据的大学生进行利用。', '楼主：我家厨房旁边有个小角落，不知道用来干嘛，有建议吗？      回复：租给大学生。', ''],
  ['电子呕吐物', '“电子呕吐物”指在情绪低落或失控时发表的一些矫情文字、发疯文学等。第二天回看时往往感到尴尬，并可能选择删除这些内容。', '昨晚心情不好，发了一大堆电子呕吐物，今天都删掉了。', ''],
  ['早f晚e', '「早f晚e「描述了当代网友在一天中经历的情绪变化。早上充满动力和斗志，用“f”代表“fighting”；晚上临睡前则容易陷入情绪低落和迷惑状态，用“e”代表“emo”。', '今天又是早f晚e的一天，早上信誓旦旦要去健身房，晚上却只想躺平。', ''],
  ['泼天的富贵', '「泼天的富贵「是一个网络用语，用来形容一种突然获得的巨大关注度，通常伴随着荣耀和成功。用这句话提醒某人或某个品牌做好准备，即将迎接大量的流量和赚取利益的机会。', '当网红博主分享了一款小众产品后，店主笑称这泼天的富贵简直猝不及防。', ''],
  ['子弹正中眉心', '“子弹正中眉心”表示一个人在年轻时做出的某些看似无关痛痒的决定，会在未来的某个时刻显现出深远的影响。以为是无足轻重的选择，却在某一天意识到这些选择造就了现在的自己。', '高中时选择的专业，以为只是随便的选择，几年后在就业市场上“子弹正中眉心”，才意识到它的重要性。', '该梗出自史铁生的小说《我与地坛》中一段书评，用来形容那些年轻时未能理解的经历或文字，随着岁月的积累，突然领悟到其深刻含义的时刻。'],
  ['理解质疑成为', '“理解质疑成为”是一种表达态度变化的句式，描述了从质疑某种行为或态度到逐渐理解，并最终认同甚至想成为其一员的过程。这反映了一种“真香”定律的情感转变。', '质疑网红，理解网红，成为网红：刚开始对于网红的走红方式感到不屑，后来逐渐理解其努力和创新之处，甚至自己也想尝试成为一名网红。', ''],
  ['行业冥灯', '用于形容那些会导致行业走下坡路的人或事件，带有嘲讽意味，相当于“干一行毁一行”。', '他一加入这个项目，公司业绩就开始下滑，简直是个行业冥灯。', ''],
  ['尊嘟假嘟', '“尊嘟假嘟”是一个谐音梗，表达“真的假的”的意思，通常用于表达疑惑、惊讶和意想不到的情绪，而且以夹子音卖萌的方式呈现。', '你说你中了彩票，尊嘟假嘟？', '该梗出自网络博主@伯恩山bot的社交平台文案：“您说爱我，尊嘟假嘟？”文案以模仿小动物说话的方式展示可爱，逐渐在网络上流行开来，并有专门的表情包释义。'],
  ['哈基米', '“哈基米”现在指可爱的宠物，也可以用来卖萌。', '你家的小狗真是哈基米啊！', '出自《赛马娘 Pretty Derby》第二季第12集，东海帝王哼唱的蜂蜜之歌。'],
  ['嘴强王者', '嘴强王者指的是那些在口头上显得非常能干或者厉害，但在实际行动中却表现平平或者没有能力的人。这个词通常用来讽刺那些只动嘴不动手的人。', '这位嘴强王者在聊天群里总是发表各种高谈阔论，但实际让他动手做时就掉链子了。', ''],
  ['水泥封心', '水泥封心指的是在经历感情伤害后，为了自我保护而不再轻易动感情。', '自从那段感情结束后，他决定水泥封心，不再轻易相信爱情。', ''],
  ['鸡哔你', '“鸡哔你”是一个谐音梗，意思是“击毙你”。', '朋友拍了拍我的肩膀，调侃道：“小心点，不然鸡哔你！”', ''],
  ['如来', '“如来”这个梗用来表达一种模棱两可的回答方式，意味着行动可能正在进行或尚未完成，但通过简单的用词，又巧妙地回应了对方的催促或询问。', '朋友问你晚饭准备好没有，你正在厨房忙的时候可以回应：“如来。”', '该梗出自郭继承教授的一段讲课片段，在片段中他反复强调“如来”和“到底来没来”，从而引发网友的创作与使用。'],
  ['团宠', '团宠指一个团队中最受喜爱和受到最多关注的人。', '在公司里，小李总是受到大家的关爱，简直就是大家的团宠。', ''],
  ['泰裤辣', '“泰裤辣”是“太酷了”的谐音，用来形容很酷的人或事物。', '看到他那段炫酷的舞蹈表演，粉丝们纷纷在评论区刷“泰裤辣！”', ''],
  ['浪浪山', '浪浪山在网络用语中代指家乡。', '每次回到浪浪山，总有一种既熟悉又陌生的感觉。', '动画短片集《中国奇谭》中的《小妖怪的夏天》。小猪妖来自浪浪山，想要离开那里，这反映了许多人对家乡的复杂感情。'],
  ['看完这句曹操撤回了一碗饭', '形容情绪或态度的快速反转。在看到满意的答案或结果后，撤回之前的激烈反应。', '他本来要发火的，看到成绩单后，看完这句曹操撤回了一碗饭。', '来源于电视剧《新三国》中，曹操因兖州被吕布偷袭而愤怒，把饭扣在桌子上，之后冷静下来又将饭扒拉回碗里。'],
  ['你很chill', '“你很chill”用于形容一个人很酷、有态度、随性，不在乎他人眼光。它强调个人的放松、冷静和淡定。', '小王昨天面对困难时表现得非常淡定，大家都称赞他说他很chill。', ''],
  ['满朝文武为何支支吾吾', '这个梗用来调侃那些在内涵视频评论区吞吞吐吐、不敢直接发表意见的人。大家看懂了内容但不好意思明说，因此表现得欲言又止。', '评论区好安静，满朝文武为何支支吾吾，不敢说话了吗？', ''],
  ['电子斗蛐蛐', '电子斗蛐蛐指的是在网上讨论和比较一些作品中角色的战斗力，通过找论证点来决定哪个角色更强，相当于网络版的斗蛐蛐。', '昨天晚上我们在群里来了一场电子斗蛐蛐，讨论超级赛亚人和孙悟空谁更厉害，结果吵到半夜。', ''],
  ['进淄赶烤', '“进淄赶烤”是指赶赴山东淄博这个地方去吃烧烤。这个短语反映了淄博烧烤因网络走红而吸引了大量外地游客前来品尝的现象。', '最近周末没别的计划，就准备和朋友进淄赶烤，尝尝那火出圈的淄博烧烤。', ''],
  ['小镇贵妇', '“小镇贵妇”指的是生活在小镇，有车、有房且工作稳定的人。这些人虽然不生活在大城市，但生活更加轻松和惬意。他们具备让长辈满意的条件，在家庭和事业上看似都很成功。', '每次过年回家看到那些小镇贵妇，我都在想是不是我的生活方式该调整一下。', ''],
  ['我父亲配享太庙', '这个梗用于形容一个人自大，并借此展现其不可撼动的威慑力。用以表示对他人行为的不屑与嘲讽。', '同事说自己工作能力有多强，还提到：“我父亲配享太庙，你们不敢小看我吧？”', '来自电视剧《知否知否应是绿肥红瘦》中角色王大娘子的台词。'],
  ['摸鱼搭子', '摸鱼搭子指的是工作时不专心工作，而是与同事一起闲聊、打发时间的伙伴。这种伙伴关系在工作时可以互相聊天，从八卦到时事，降低工作的枯燥性，但在下班后就不再联系。', '每天上班时间长又单调，幸好有我的摸鱼搭子陪我聊八卦，不然都熬不下去了。', ''],
  ['曹操盖饭', '曹操盖饭指的是情绪转变或反转的过程，起初对某件事感到愤怒或不满，随后逐渐冷静并接受现实。', '面试结果出来，我没被录用，心里气得想摔桌子，后来一想还是去另外的公司尝试一下，真是一个“曹操盖饭”的心态变化。', '出自电视剧《新三国》。曹操因兖州被吕布偷袭而愤怒，把饭扣在桌子上，之后冷静下来又将饭扒拉回碗里。'],
  ['便衣警察摆摊', '“便衣警察摆摊”是用来形容摊主手艺极差，像是新手或外行，难以让人相信是真正的摊贩。通常用来调侃摊主看起来像是临时出任务的便衣警察。', '昨天去小吃街，那个卖煎饼的大爷摊的饼都破成这样了，简直是“便衣警察摆摊”。', ''],
  ['女娲毕设', '“女娲毕设”指的是女娲造人时最完美的作品，用来形容一个人在各方面（如长相、身材、性格、智商、情商等）都非常完美的人。', '她不仅颜值爆表，性格也特别好，简直是女娲的毕设作品。', ''],
  ['人菜瘾大', '指虽然技术不好，但特别热衷于玩游戏的玩家。', '小明每次玩游戏都输，但他总是第一个上线，真是人菜瘾大。', ''],
  ['纯爱战士', '指那些在恋爱关系中坚持纯真、无私、高尚的爱情观的人。', '他是个典型的纯爱战士，一看到复杂的感情戏就会直接跳过。', ''],
  ['画质不如原神', '“画质不如原神”是一个用来调侃或讽刺与《原神》这款游戏相关内容的网络流行语。通常用于幽默地嘲讽某些对《原神》画质有过度自信或迷恋的行为。', '最近新出的那部动画被网友调侃：“这动画的画质不如原神，好失望啊。”', '该梗起源于一名假装成《原神》玩家的人群嘲某人的夜景照片，表达“感觉不如原神。。。画质”的评论，意图是通过这种夸张的对比来讽刺《原神》玩家群体。这种说法逐渐流行起来，并被广泛用于各种场合。'],
  ['放下助人情节尊重他人命运', '这个梗倡导人们放下过度的助人情结，不要总试图以自己的标准去引导或改变他人。提醒一下就行，不必坚持不必要的争论或争吵，要尊重别人的选择和命运。', '面对朋友的生活选择，我决定放下助人情节尊重他人命运，因为这是他自己的路。', ''],
  ['听君一席话犹如庄周带净化', '“听君一席话犹如庄周带净化”是一种讽刺，表示对方说了很多废话、没有用的话，意思与“听君一席话，如听一席话”类似。它形容对方的言论是无效重复的，听了等于没听。', '张三给我讲了一大堆他的投资计划，但听君一席话犹如庄周带净化，根本没有实质内容。', '这个梗源自游戏《王者荣耀》。在游戏中，角色庄周自带强大的净化技能，因此再携带净化技能就显得多余没用，从而引申出这个用于讽刺废话连篇的表达。'],
  ['中了基因彩票', '指在外貌上遗传了父母的优秀基因，长相特别出众。', '她的五官如此精致，真的是中了基因彩票。', ''],
  ['民风淳朴哥谭市', '“民风淳朴哥谭市”是对DC漫画中《蝙蝠侠》系列的虚拟城市哥谭市的反讽与调侃。虽然“民风淳朴”通常指平和的环境，但在这里它表达了哥谭市环境的极度混乱和危险，充斥着犯罪和神经病反派的讽刺性说法。“淳朴”反而指的是暴力和无法无天。', '看了《蝙蝠侠》，我终于明白什么叫“民风淳朴哥谭市”了，居民每天都生活在生死边缘。', ''],
  ['退出文坛我是极力反对的', '“退出文坛我是极力反对的”用于夸赞某人评论精彩、语言出色，堪比文学大师。', '看到你这段话，我只能说，退出文坛我是极力反对的！', ''],
  ['秦始皇摸电线', '这个梗形容赢得太多，以至于感到累了或麻木的状态。因为秦始皇的名字“嬴政”谐音“赢”，结合“摸电线”的动作导致被电麻，形成“赢麻了”的双关。', '昨晚打游戏的时候，我连胜10局，感觉自己就像秦始皇摸电线，真是赢麻了。', ''],
  ['行走的50万', '“行走的50万”是指能被举报并获得奖金的间谍等危害国家安全的人员，因为举报这类行为最高能获得50万元的奖励。因此，抓到这样的“间谍”等同于获得奖金。', '看到有人在街头表现得很可疑，朋友笑着说：“别是个行走的50万吧？”', '该梗来源于北京市国安局在2017年4月10日发布的《公民举报间谍行为线索奖励办法》。办法指出，对于提供线索并对侦破间谍案件有重大贡献的举报，可以给予10万至50万元的奖金。'],
  ['孔乙己的长衫', '“孔乙己的长衫”比喻人们在面对现实困境时的坚持和身份认同。这是对学历和知识分子的自我价值认同的探讨，尤其是在就业压力下的迷茫和焦虑。', '他总是拿着那份文凭，仿佛是孔乙己的长衫，不愿放下也走不出来。', '该梗源自鲁迅1918年的小说《孔乙己》，其中描写主人公孔乙己虽然潦倒，但仍穿着长衫以坚持读书人的身份。'],
  ['孔乙己脱不下的长衫', '“孔乙己脱不下的长衫”这个梗象征着某些人因高学历未能带来预期的成功而感到的困惑与压力，就像孔乙己坚持穿长衫以标榜身份，但未能带来实际改变。它反映了现代人的现实与期望不符的状态。', '小王总是感慨自己找工作时碰壁，他说，自己的硕士学历成了“孔乙己脱不下的长衫”。', '源自鲁迅的小说《孔乙己》，其中描写主人公孔乙己虽然潦倒，但仍穿着长衫以坚持读书人的身份。'],
  ['孔乙己文学', '孔乙己文学是现代年轻人用“孔乙己”形象表达自己虽然有高学历，但现实工作上依旧困顿和失落的一种方式，带有自我调侃和现实讽刺。', '“学历是我下不来的高台，就像孔乙己脱不掉的长衫，让我进退两难。”', '该梗源于鲁迅的小说《孔乙己》，其中描写主人公孔乙己虽然潦倒，但仍穿着长衫以坚持读书人的身份。'],
  ['截图癖', '截图癖指沉迷于截图，把信息或瞬间记录下来，以备日后查看或分享给他人。', '手机相册里有几千张截图，都是截图癖的“杰作”。', ''],
  ['上山的人不要嘲讽下山的神', '指不要在情报不足的情况下轻视或嘲讽看似不如自己的人，因为他们可能有过辉煌的成就。', '新人球员在赛场上对老将冷嘲热讽，旁人提醒道，上山的人不要嘲讽下山的神。', ''],
  ['麻雀啄了牛屁股', '即“雀食牛逼”，是“确实牛逼”的谐音，用来赞美某事物非常出色。', '他的表演让人印象深刻，真是麻雀啄了牛屁股！', ''],
  ['躺裂', '「躺裂「是结合了「躺平「和「裂开「两个词语的网络用语，表示一个人对生活失去热情，不再积极进取，同时心态也崩溃了。', '最近工作压力太大，他整个人已经躺裂了，每天都失去动力。', ''],
  ['乐子人', '“乐子人”指的是以观看和享受事件演变为目的的人，他们主要是在网络上围观各类事件，寻找娱乐和话题。他们有时会参与讨论，但主要是以旁观者的态度，不对事件结果或影响负责。乐子人可以分为不同类型，从单纯的“吃瓜群众”到主动制造话题的角色。', '每当微博上有新的热搜，一群乐子人就会立即涌入评论区，准备欣赏最新的网络戏剧。', ''],
  ['把笋都夺没了', '“把笋都夺没了”由“多损啊”的谐音“夺笋啊”演变而来，形容某人非常缺德、损人或丢脸。', '他说他在朋友生日会上故意忘记送礼物，真是把笋都夺没了。', ''],
  ['拜托超酷的好吗', '“拜托超酷的好吗”是一种使用台湾腔调表达的网络流行语，用来形容某件事情非常厉害或让人惊叹。它可以用来赞美别人做到的自己没做到的事情，或者形容某些看似幼稚但实际上非常吸引人的事情。', '他居然在短短一个月内学会了这项技能，拜托，超酷的好吗！', ''],
  ['没有一袋砂糖橘能过夜', '这个梗指的是砂糖橘这种水果特别好吃，容易让人停不下来。因此，一袋砂糖橘一买回来很快就会被吃完，根本留不到第二天。', '买了一袋砂糖橘给全家解馋，但没想到不到一晚就只剩橘皮了，果然没有一袋砂糖橘能过夜。', ''],
  ['shut up and take my money', '「Shut up and take my money「 表达对某物的强烈喜爱和迫切购买欲望，即使物品存在一些缺陷或问题，仍愿意立即购买，通常因为认为其性价比高或非常值得入手。', '看到苹果发布会的新款手机后，我的第一反应就是：Shut up and take my money!', '该梗出自美国动画片《飞出个未来》（Futurama）。在剧中，主人公 Fry 排队购买 eyephone 时，尽管售货员指出许多缺点，Fry 仍然不耐烦地说出这句经典台词，随后掏出一把钱表示迫切想购买。'],
  ['不开心你就去soul啊', '该梗用于调侃和劝告不开心的人，上述调侃是以一种真诚又搞笑的方式，类似于“实在没事做你就进厂”。', '看你今天心情不好啊，不开心你就去soul啊，说不定还能在里面找到情投意合的朋友。', '此梗出现在抖音平台的emo视频评论区，源于soul这款聊天交友软件的广告宣传，其广告台词“不开心你就去soul啊”成为了流行语。'],
  ['绝望的文盲', '指文化储备不足、对角色理解不到位的演员，尤其是在被提问时无法清楚表述角色或作品内容。', '在采访中，他对角色背景一问三不知，简直就是一个“绝望的文盲”。', ''],
  ['鼠人', '“鼠人”又称“老鼠人”，通常用于自嘲，指代社会底层的人群，带有黑色幽默的色彩。', '每个月月底都得精打细算，感觉自己真是个鼠人。', ''],
  ['鼠鼠', '“鼠鼠”是一个自嘲性的梗，指代社会底层或自认为渺小的人，通常用作形容自己在社会中不重要和微不足道的身份。这一表达起到自我调侃和自我安慰的作用。', '每天加班到深夜回到出租屋，我常感慨自己不过是个鼠鼠。', ''],
  ['鼠鼠我啊', '“鼠鼠我啊”是一种自嘲和自我贬低的表达方式，用“鼠鼠”指代处于社会底层、卑微且微不足道的小人物，表达一种自我调侃的丧文化情绪。', '“每天上班挤地铁，回家吃泡面，鼠鼠我啊，也想过上体面的生活。”', ''],
  ['人矿', '“人矿”指的是在“人口红利”现象中，个人从出生起就被当作消耗品使用的一种无奈调侃。', '在这个行业待久了，感觉自己就像个“人矿”，一直在被消耗。', ''],
  ['交封不杀', '“交封不杀”是用于调侃视频封面与实际内容不符的情况。网友评论“交封不杀”时，有调侃发布者封面吸引人而内容落差大的意思，也可能用于夸奖封面和内容都很吸引人时，表示对此的赞许和共鸣。', '这视频封面看得我心痒痒，点进去才发现风马牛不相及，交封不杀！', ''],
  ['方便面补一切', '“方便面补一切”是一个用于调侃的网络梗，意思是用方便面和502胶水修补各种损坏的物品，指任何损坏都可以用这种方法修复。', '“这手机壳摔坏了，不知道用方便面能不能补好，毕竟方便面补一切。”', '该梗源于抖音网红汪伟，他最初只是用502胶水做家居修复，后来突发奇想，用方便面作为修复材料，并在视频中展示修复过程，引发广泛关注和模仿。'],
  ['要啥自行车', '“要啥自行车”用于形容对已有的东西不满足，还想要更好的，表示不知足或有非分之想。', '你都已经有一辆车了，还想买更好的，真是要啥自行车啊。', '该梗最初出自2001年的一个小品，但在2013年因东北人常使用这句话而在网上走红，再次成为流行语。'],
  ['龙傲天', '龙傲天是形容某些小说、漫画或动画中不合理强大的主角。这类角色通常没有逻辑、缺乏实力，但通过主角光环总能轻松战胜敌人，成功达到人生巅峰。他们的成功完全依赖于剧情的偏爱，没有任何人格魅力或吸引力。', '这部小说的主角简直是个龙傲天，随便挥挥手就打败了大反派。', ''],
  ['天选做饭人', '“天选做饭人”指的是在一个家庭中，当其他成员因为新冠病毒感染都“阳”了，但有一个人没有被感染，就成了负责照顾和做饭的人。这是一种调侃的说法，体现幽默玩笑和无奈的心态。', '在我们家都阳了之后，我成了“天选做饭人”，每天得变着花样给他们做饭。', ''],
  ['冬阴工', '“冬阴工”是“冬阴功”的谐音梗，表示在冬天的阴冷天气中，仍需工作的打工人。它反映了对在家隔离或生病休息人的羡慕，以及对自己继续工作的无奈。', '同事开始居家办公了，我却成为了一个冬阴工，还得每天去公司报到。', ''],
  ['给义乌一点时间', '意思是等待义乌生产出物美价廉的商品，以替代昂贵的产品。', '看到这个新款耳机的价格，我只想说：给义乌一点时间。', ''],
  ['宝娟我的嗓子', '“宝娟我的嗓子”是一个流行于社交媒体平台上的梗，指出现喉咙肿痛、声音沙哑的症状。', '“我这几天感冒重，嗓子简直不堪入耳，真想喊一句‘宝娟我的嗓子’！”', '出自电视剧《甄嬛传》，角色安陵容在嗓子失声时喊出：“宝娟我的嗓子”。'],
  ['我先润了', '“我先润了”中的“润”是“run”的谐音，指赶紧离开，是跑路的意思，强调快速逃离。', '这个游戏真无聊，我先润了。', ''],
  ['我先run了', '“我先run了”表示迅速离开某个地方，类似于“跑路”。通常是为了躲避某个令人不快或感到威胁的环境。', '这游戏对我来说太无聊，我先run了。', ''],
  ['为什么你能发语音', '用于形容文字表达得生动形象，让人读起来仿佛在听语音，能想象出说话人的声音和表情。', '看你写的这段四川话，我真的觉得你在我面前说话，为什么你能发语音？', ''],
  ['撒旦身上纹着你', '“撒旦身上纹着你”是一个调侃性的网络用语，用来形容一个人“比撒旦还邪恶”，虽然这是夸张的修辞，旨在幽默表示某人非常厉害或狠毒。', '那个电影里的反派真是太狠了，简直让人觉得撒旦身上纹着他。', ''],
  ['巴山楚水凄凉地', '这个梗通过将古诗词与英文结合，以押韵的方式创造出幽默或魔性的效果。其主要玩法是以某句古诗词作为开头，并用一句英文押韵句子接续。最初的组合为“巴山楚水凄凉地，responsibility”，后发展为更具趣味性的“巴山楚水凄凉地，baby can you kiss me”。', '巴山楚水凄凉地，baby can you kiss me。', '出自唐代刘禹锡的《酬乐天扬州初逢席上见赠》中的名句“巴山楚水凄凉地”。后在抖音中流行，来自网友们用这些词句玩押韵的创意。'],
  ['这跟在大街上拉屎有什么区别', '“这跟在大街上拉屎有什么区别”用于形容一种非常尴尬的场合或行为，让人感到不适，类似于在公共场合做出让人尴尬的事情。', '小明在全公司面前提了一件私密的事情，他感觉这跟在大街上拉屎有什么区别。', ''],
  ['杨迪厌世脸', '「杨迪厌世脸「是一种搞怪行为，使用杨迪一张严肃且生无可恋的春晚工作证件照片制作的厌世头像，表达现代人普遍的无奈和幽默。', '最近流行用杨迪厌世脸做微信头像，真的是很有喜感。', ''],
  ['剁椒鱼头车', '“剁椒鱼头车”用于形容一些长度特别短的车型，类似于剁椒鱼头的形状，常常显得很滑稽。', '停车场又看到一辆剁椒鱼头车，还真能一位停两个。', ''],
  ['你舅惯着他爸', '该梗是一个谐音梗，表示“你就惯着他吧”，提醒不要过度溺爱或帮助别人，以免对方缺乏独立性。', '“他每次都让你帮忙修改，‘你舅惯着他爸’，以后他自己怎么办？”', ''],
  ['这把高端局', '「这把高端局「原意是指游戏中高水平的对局，但在网络上用来形容人在面对极度紧张、尴尬或危险情况时的一种感慨，表示难以应对的情绪。', '面对这次的财务危机，大家都觉得这把是高端局，不知道该从何下手。', ''],
  ['没活了可以咬打火机', '这个梗用来调侃或形容在没有事情可做或无聊时，可以尝试一些危险或者不寻常的事情来打发时间。', '「今天线上的工作被取消了，没活了可以咬打火机，反正找点事做。「', '此梗来源于短视频博主刀哥的直播间。当时刀哥在直播中尝试用牙齿咬爆打火机，导致了一场小型爆炸，随后他的直播间被封一个月并被罚款700元。'],
  ['油饼食不食', '“油饼食不食”是一个谐音梗，意指“有病是不是？”', '你居然相信这个谣言，油饼食不食？', ''],
  ['连夜走的买的站票', '形容因为见到某人真实样貌后的震惊和失望，急于逃离的心情。', '我本来对他的颜值期待很高，结果见面后令我崩溃，只想连夜走的买的站票。', ''],
  ['足球反着买别墅靠大海', '这个梗用来调侃在足球比赛中，热门球队常常失利的现象，建议反着投注热门球队的比赛结果，以此开玩笑地表达投注足球比赛的不可预测性。', '今年世界杯爆冷太多，感觉“足球反着买，别墅靠大海”说的还真有道理。', ''],
  ['向日葵的花语', '在网络中，向日葵的花语被戏称为“给你点阳光就灿烂”，用来形容那些在外表或表面上看起来温和无害，但实际上话语或行为中具有攻击性的人或事。', '“她看起来那么温柔，没想到说话竟然这么有攻击性，简直就像是向日葵的花语。”', '这个梗来源于一张网络截图，其中一个聊天里的人用《植物大战僵尸》游戏中向日葵的头像进行对话，言辞攻击性强，与游戏中向日葵平和的形象形成鲜明对比。'],
  ['汪小菲背床垫', '「汪小菲背床垫「这个梗源自网友们调侃汪小菲围绕其离婚后床垫争议的情形。据透露，汪小菲对大S再婚后仍使用他们先前的床垫表示不满，网友们就以此作乐，建议他「背回床垫「来夺回属于他的物品。', '自从大S再婚后，网友们就一直戏称汪小菲要把床垫背回去，成了娱乐圈的新笑料。', ''],
  ['爷满离', '“爷满离”是一个网络流行语，是“爷满意的离开了”的缩写。它的意思是表达看到了能满足自己期待的事物后，心满意足地离开。通常用来表示对某个内容的强烈满足与欣赏。', '看到这个教程视频真的太详细了，爷满离！', ''],
  ['这是评论区不是无人区', '提醒评论者注意言行，不要在公众平台发不合适的话，表示这是一个公开的地方。', '用户A：这个角色也太好看了，想□□。    用户B：这是评论区不是无人区，注意点形象。', ''],
  ['你已经没有在乎的人了吗', '这句话表达了一种自嘲或自我解脱的心态，指自己在社会中感到毫无存在感，不必担心被在乎的人注意到自己的错误或尴尬。', '朋友问我为什么敢唱走调的歌，我回答：“你已经没有在乎的人了吗？”', ''],
  ['他们朝我扔泥巴', '“他们朝我扔泥巴”表示面对诋毁、攻击或抹黑时，选择以积极或不同的方式回应。具体表现为以德报怨、化负能量为正向行动。虽然原意是倡导宽容和积极面对恶意，但衍生的句式则表达了不甘受欺负、正面反击的态度。', '他们朝我扔泥巴，我在水里种出自己的荷花。', ''],
  ['闪光弹', '在网络用语中，“闪光弹”引申为一种炫耀行为，特别是在感情或物质生活中表现得令人羡慕或炫目的行为。单身网友常用这个词来形容那些在公开场合亲昵互动的情侣或展示奢华生活的人，感到这是一种刺激、炫目到让人“致盲”的行为。', '朋友在朋友圈晒了一大堆与女朋友的亲密合照，还配上心形表情，简直是扔了一枚闪光弹。', ''],
  ['1080P', '1080P在网络用语中被隐晦地用作骂人，意指“坏蛋”。因为1080P表示高清分辨率，缩写为HD，与“坏蛋”同音。', '你做这件事真是个1080P。', ''],
  ['人死了嘴还是硬的', '这个梗用于形容那些在明知自己错误的情况下，仍然拒不承认错误，继续找借口的人。即便事实已经明摆在眼前，他们依然坚持不改口，显得如同「人死了嘴还是硬「。', '小王明明被抓了现行，但他还在找各种借口解释，真是人死了嘴还是硬的。', ''],
  ['少拿原版骗我', '“少拿原版骗我”通常用来形容某个剪辑视频或二创作品非常精彩，以至于观众觉得它比原版还要好，甚至怀疑原版内容反而是假的。', '这段《亮剑》的鬼畜视频做得太棒了，少拿原版骗我！', ''],
  ['密密麻麻是我的自尊', '表达自己在感情中努力付出却得不到回应的心酸。', '我总是对她无微不至，但她却冷漠相待，哎，密密麻麻都是我的自尊。', ''],
  ['臣这一退就是一辈子', '“臣这一退就是一辈子”用来表达在分手时无奈放手、暗自祝福对方的心情，尤其是在深情过后不得不放下时的心酸和不甘。', '他对她说：“臣这一退就是一辈子，希望你能找到真正让你幸福的人。”', '这个梗源于抖音短视频平台，来自网友@蛙仔太深情分享的一段视频。视频中一位室友在分手时通过电话列举自己的“十宗罪”，表达对过去感情的不舍和遗憾。'],
  ['剑谱第一页先斩心上人', '形容抛开感情杂念后能够专心致志地追求事业，做到心无旁骛。', '张伟最近分手了，他说要按照“剑谱第一页先斩心上人”，全力去拼事业。', ''],
  ['上岸第一剑先斩意中人', '「上岸第一剑先斩意中人「指的是在考上公务员、编制或研究生等成功上岸后，把原本的男朋友或女朋友甩掉的行为。这种行为用来形容一个人在实现重大人生目标后，选择与之前的伴侣分手，追求更匹配的新目标。它也可以比喻在个人变得优秀后，抛弃旧的关系，另找新欢。', '他考上公务员后，没多久就分手了，真应了那句“上岸第一剑先斩意中人”。', ''],
  ['快说你是来旅游的', '这个梗用来调侃某地网友说出让人尴尬的评论时，其他本地网友会以“快说你是来旅游的”来开玩笑和解围，表示希望该网友不是本地人以免拉低地区形象。', '当上海的一位网友在评论区里发表了极为不当的言论，其他上海网友纷纷调侃说：“快说你是来旅游的，别黑我们上海人。”', ''],
  ['我承认我刚才说话声音有点大', '这个梗用于描述在与他人交流时，自己先前强烈反对某一观点或事实，但后来发现自己的观点是错误的，而对方才是正确的，从而陷入尴尬的处境。它反映了一种被「打脸「后的无奈与自我调侃。', '在朋友的坚持下，我终于跟他去了那家新开的餐馆，结果食物好得让我承认我刚才说话声音有点大。', ''],
  ['想刀一个人的眼神是藏不住的', '当有人表露出明显的敌意或攻击意图时，就会被调侃为“想刀一个人的眼神是藏不住的”，意指他们的敌意已经表现在脸上，很容易被看穿。“刀”是狼人杀中的术语，指狼人干掉某个人。', '玩狼人杀时，他总是盯着我，果然是想刀我，眼神真的藏不住。', ''],
  ['不听老人言开心好几年', '反驳传统俗语“不听老人言吃亏在眼前”，表明做出不同选择可能带来意想不到的快乐。', '大家都说要按部就班工作，但我选择了创业，不听老人言开心好几年。', ''],
  ['女朋友是不是有男朋友了', '“女朋友是不是有男朋友了”用来形容怀疑自己在恋爱关系中被背叛或者对方出轨的情况。这是质疑恋人忠诚度的幽默或者半开玩笑的表达方式。', '小明看到女朋友和一个陌生男人一起走在街上，心里默默想：“我女朋友是不是有男朋友了？”', ''],
  ['我选蓝色药丸', '“我选蓝色药丸”用来表达对常见的选择题类帖子的不耐烦或厌恶，通常用于打趣或反讽。', '在那个又要你选超能力的帖子下面，我只想说“我选蓝色药丸”。', '该梗源于电影《黑客帝国》，剧中角色墨菲斯让尼奥在红色药丸和蓝色药丸中进行选择。在网络上，尤其是贴吧，这个情节被改编成各类“选择药丸”的帖子，由于此类帖子泛滥，网友开始用“我选蓝色药丸”来表示对此类内容的敷衍和反感。'],
  ['水一百度会开人一百度会死', '这个梗是提醒人们在生病或身体不适时，应该寻求专业的医疗帮助，而不是依赖网络搜索引擎（如百度）进行自我诊断。因为这种自行诊断的方式可能会带来误导性的信息，让人感到不必要的恐慌或焦虑。', '最近喉咙有点不舒服，我朋友居然让我去百度看看，然后他还引用那句“水一百度会开人一百度会死”的话来嘲笑我渴望找答案的心理。', ''],
  ['电竞贝多芬', '电竞贝多芬最初指的是在玩游戏时键盘敲击速度极快的人，类似弹钢琴的速度。最早是游戏选手厂长的外号，因为他在直播时常放钢琴曲，后来也引申为网络上打字速度飞快的人，尤其是在网上争论或喷人的情境下。', '玩游戏就是要有电竞贝多芬 这样的手速，简直让人眼花缭乱。', ''],
  ['颜值即正义', '“颜值即正义”是一个网络流行语，用来表达对外貌美丽的高度赞赏，强调在某些情况下颜值可以被视为重要的价值或优势。', '见到那个主播现场直播时，弹幕纷纷刷起来：“颜值即正义！”', ''],
  ['你真该死啊', '“你真该死啊”是用来对好兄弟突然过上幸福生活时，表达一种既羡慕又略带嫉妒的“真诚”祝福。它反映了朋友间特有的幽默感和调侃。', '当好兄弟宣布和女友即将结婚时，我意味深长地对他说：“你真该死啊，这比杀了我都难受。”', '这个梗源自网络上一对兄弟的对话。一位网友看到自己的好兄弟幸福美满，发出了带有幽默嫉妒的祝福：“你真该死啊，这比杀了我都难受”。'],
  ['我反对这门亲事', '“我反对这门亲事”是一种网络用语，通常用于表达对某人在社交媒体上公开恋情的不情愿或心碎，但实际上是一种开玩笑的、带有祝福意味的反对。', '当某小鲜肉公布恋情时，粉丝纷纷在留言中写道：“我反对这门亲事！”', ''],
  ['麻辣毛蛋', '麻辣毛蛋最初是指一种特色小吃，但在网络上成为通过特殊的吆喝声来表达食物麻辣程度的搞笑梗。', '吃了这么辣的火锅，我的嗓子都快成“麻辣毛蛋”了。', '该梗出自喜剧团队喷空剧场的一场相声表演，表演中，河南大哥用方言吆喝“麻辣毛蛋”，并通过特别的嗓音表现出被麻辣毛蛋“麻到、辣到”的感觉，演绎得非常魔性和夸张。'],
  ['食大便了', '「食大便了「是「时代变了「的谐音，表达对时代变化、科技进步的感慨和惊讶。', '看到全自动驾驶汽车上路时，某网友感叹：「大人，食大便了，这技术也太先进了吧！「', '这个梗源于德国剑术大师米夏尔·亨特的著作《剑术100式》的第100式——用枪打人，名称为「大人，时代变了「。这个绝招体现了用更动态、更现代化方式解决问题的理念。'],
  ['核区房', '“核区房”是指靠近核酸检测点的房源，方便居民做核酸检测。', '这个小区就是典型的“核区房”，下楼就能做核酸，特别方便。', ''],
  ['上班丑关我下班什么事', '“上班丑关我下班什么事”这个梗指的是职场人士在上班和下班时呈现出的两种截然不同的状态。上班的时候形象随意甚至邋遢，而下班后则打扮得光鲜亮丽，表现出明显的对比和反差。', '今天在公司看到的同事，简直是随意得不行，但是下班后在聚会上，她的装扮让我完全认不出，真是“上班丑关我下班什么事”。', ''],
  ['乐山大佛', '乐山大佛这个梗用来讽刺那些在网络上站在道德制高点指责他人、却缺乏实际同情心和理解的网络喷子。形象比喻这些人看似高高在上、庄严神圣，实际上是自以为是。', '小李每次发条朋友圈，总有几个乐山大佛在下面指指点点，却从来不管事情的全貌。', ''],
  ['科幻片', '在网络文化中，“科幻片”用来指代不可思议且甜美的恋爱故事，通常是对现实生活中难以置信的超甜恋情的调侃。', '看到他们每天都在秀恩爱，我都觉得这是在演科幻片。', ''],
  ['开始理解灭霸', '「开始理解灭霸「是一个网络梗，用于调侃拥挤的环境，比如节假日旅游时的人山人海的状况。人们用这种调侃的方式来表达对「灭掉一半生命以求平衡「这一极端做法的理解，尽管他们并不真的希望如此。', '「今年春节地铁里挤得要死，我是彻底开始理解灭霸了。「', '该梗源于电影《复仇者联盟》中的角色灭霸，他为了维持宇宙的平衡，使用无限手套消灭了一半的生命。'],
  ['杀我别用感情刀', '「杀我别用感情刀「是一种网络用语，表达了情感伤害比身体伤害更疼痛的观点。它意在说明，尽管有很多伤害方式，但情感上的伤害是最难承受的。这句话强调了对情感的珍重和对情感伤害的敏感。', '在分手之后，我只想说：满清酷刑任你挑，杀我别用感情刀。', ''],
  ['加密通话', '原意是“通过技术手段对通话进行加密，防止被窃听”。在网络上，指的是听不懂的对话。', '他们用方言聊着，我完全听不懂，就像在加密通话。', ''],
  ['起夜急李姐', '“起夜急李姐”是“企业级理解”的谐音梗。它用来调侃或形容一种看待问题的方式，这种方式角度刁钻，甚至通过故作曲解来达到一种诙谐或滑稽的效果。', '小王的解释方式总是让人哭笑不得，简直是起夜急李姐。', ''],
  ['格局打开', '“格局打开”用于嘲讽或自嘲某人视野狭窄，建议应该更长远地看问题。常用于讽刺社会不公或特定观点。', '他说为了一点小事吵架就不值得，朋友立马回：“格局打开，这不是小事。”', ''],
  ['孩子飞出来了', '“孩子飞出来了”是一种夸张表达，形容对方的魅力非常强大，以至于不需要和对方经历生孩子的过程，孩子就“飞出来”了。', '看到他的照片，我孩子都要飞出来了！', ''],
  ['面对疾风吧', '“面对疾风吧”常被用来比喻对方的攻击无效或进行无谓的抵抗。', '当老板批评他时，他心里默念：“面对疾风吧”，无惧压力，继续坚持自己的想法。', '该台词出自《英雄联盟》中英雄亚索的W技能“风墙”，风墙可以格挡一切正面弹道类技能。'],
  ['在线等挺急的', '表示问题紧急或急需答案，通常用于求助帖，有时带有调侃意味。', '女友问我她穿这件衣服好看还是那件好看，救救孩子，在线等挺急的。', ''],
  ['科技与狠活', '“科技与狠活”指的是利用食品添加剂和不合规原材料制作食品的方法，揭示食品行业中的不当制作手段和虚假宣传。', '“这个假蟹黄酱就是科技与狠活的典型例子，看完真不敢在外面随便吃东西了。”', '出自网红博主辛吉飞的视频系列，他通过视频展示使用添加剂制作劣质食品的过程。'],
  ['李姐万岁', '李姐万岁是“理解万岁”的谐音，用来表达对错误或尴尬情况的理解和幽默化解。', '这次开会又出现了问题，领导只能无奈地说：“李姐万岁！”', '出自罗永浩的一次发布会，因设备问题频频出错，罗永浩用“理解万岁”来缓解尴尬，后被粉丝改写为“李姐万岁”而广泛传播。'],
  ['年轻人不要太气盛', '用于提醒或调侃年轻人不要过于自信、嚣张。', '职业比赛中，年轻选手表现出色后，观众调侃道：“年轻人不要太气盛！”', '出自电视剧《征服》。在剧中，孙红雷饰演的刘华强去饭店与黑帮老大宋老虎谈判，场面剑拔弩张，互不相让。宋老虎说了一句“年轻人不要太气盛”，刘华强霸气回应：“不气盛叫年轻人吗？”'],
  ['再爱就不礼貌了', '“再爱就不礼貌了”原本是一段告别文案，用于表达感情的克制和终止。后来被演变成一种网络梗，形成“再XX就不礼貌了”的格式，用于幽默地表示“给我到此为止”的意思。', '天气太热了，再不开空调就不礼貌了。', '该梗起源于日语短视频博主将其制作成日语教学视频，并被网友用恶搞方式演绎成“塑料日语版”，营造出一种搞笑的氛围。'],
  ['反派死于话多', '「反派死于话多「指的是在影视作品中，反派本来有机会击败主角，但由于他们过于自信和口若悬河，花时间炫耀或解释自己的动机，结果给主角反击或转机的机会。这种情节让人感到不合逻辑，但却在影视作品中频繁出现，因此成为一种调侃和吐槽的梗。', '在上一集的电视剧里，那个反派又是死于话多，他居然不趁机击败主角，还要讲述他的邪恶计划，结果被打败了。', ''],
  ['世界名画', '“世界名画”这个梗表示一种对少见或意外画面的惊叹或戏谑。在特定情景下，其戏剧性和稀有性让人联想到真正的世界名画的珍贵。', '看到久未更新的偶像团体回归舞台，粉丝们纷纷评论：“这真是世界名画啊！”', ''],
  ['我赌你的枪里没有子弹', '该梗源自电视剧中的台词，用于调侃或讽刺那些夸张、不合理的情节。尤其在面对明显不利情况时，表现出自信且不合逻辑的态度。', '面对老板的批评，小张笑着说：“我赌你的意见里没有建设性建议。”', '出自张子健主演的抗日神剧《猎鹰1949》。在剧中，角色燕双鹰被敌人用枪指着，却自信地说出“我赌你的枪里没有子弹”，最终反败为胜。'],
  ['扛着火车跑', '“扛着火车跑”形容某人想要快速逃跑，比火车还快，表达急切和夸张的逃跑方式。', '他知道事情败露后，立刻扛着火车跑了，再也没联系过我。', ''],
  ['试试就逝世', '“试试就逝世”是调侃人们做出尝试危险行为时面临较大风险的用语。它用来讽刺那些进行莽撞或不智行为的人。', '看到你要从那么高的地方跳下去，我只想说“试试就逝世”。', ''],
  ['无敌的佐菲倒下了', '形容一个看似很强的人或角色突然被打败，产生一种既悲惨又搞笑的反差。', '看他气势汹汹地上场，没想到一下就被打趴下，像是无敌的佐菲倒下了。', '出自《泰罗·奥特曼》第40集，佐菲在海王星被泰兰特击败，旁白说“无敌的佐菲倒下了”。'],
  ['给恋爱脑的姐妹挖野菜', '带有讽刺意味地提醒恋爱脑的人，通过感受生活的艰辛来清醒认识现实。', '她总是为了那个不在乎她的人伤心，我真想带她去挖野菜。', '源自《薛平贵与王宝钏》的故事，王宝钏为了爱情苦苦等待18年，挖野菜度日。'],
  ['王宝钏挖野菜', '王宝钏挖野菜这个梗用来形容那些在感情中过于沉迷，因爱而放弃自身幸福的“恋爱脑”现象。警示人们在恋爱中不要过度牺牲自我，避免因盲目爱情而陷入困境。', '每次看到闺蜜因为男友的一句甜言蜜语就什么都不计较，我都想对她说：“小心别变成王宝钏挖野菜哦！”', '出自电视剧《薛平贵与王宝钏》，剧中描绘了王宝钏为了等待丈夫薛平贵，过了18年依靠挖野菜过活的艰苦生活。'],
  ['37度2', '指爱情的温度，形容遇见喜欢的人时心动的感觉。源于人体正常体温是37度，而心动时会升高至37.2度的说法。', '我遇到你，体温变成了37度2。', ''],
  ['智商盆地', '智商盆地用来调侃或讽刺一个人的智商水平较低。', '他连这个简单问题都搞不懂，真是智商盆地。', ''],
  ['微瑕', '“微瑕”指有轻微瑕疵的物品，在交易过程中描述物品状态时常用。这个词现常用于调侃，即使物品缺陷明显，也称其为“微瑕”。', '我做的蛋糕虽然形状不好看，但味道很好，算是微瑕，不刀哦。', '“微瑕”开始用于二手商品交易，描述物品轻微不完美。此梗走红是因为一个网友出售idol小卡，卡片已明显损坏却声称仅有“微瑕”，引发网友调侃和玩梗。'],
  ['人类的本质复读机', '“人类的本质复读机”是一句调侃，形容人们在网络社区中经常通过重复他人的话语来表达共鸣或赞同。这种重复行为被形象地称为“复读机”，参与者会通过复读某句话来“保持队型”。', '在某论坛上，一位网友发了一句非常搞笑的评论，底下瞬间被相同的回复刷屏，仿佛整个社区都变成了复读机。', ''],
  ['用爱发电', '“用爱发电”指在收益较低或没有收益的情况下，仅出于热情和爱好而继续进行某项活动或工作。', '这群独立游戏开发者虽然挣不了多少钱，但他们一直在用爱发电，努力推出新的作品。', '该词最初源自中国台湾环保人士反对核电的口号，后来被大陆网友用来形容出于兴趣而坚持不懈的行为。'],
  ['省油的灯', '省油的灯用来形容一个人好对付、单纯、没有乱七八糟的心思，是“不是省油的灯”这一俗语的反义词。', '她真是省油的灯，一点小心思都没有。', ''],
  ['社会边角料', '社会边角料指在人群中缺乏存在感和被重视度的人群，类似社会边缘人。', '有时候感觉自己就是个社会边角料，无论怎么努力都没人注意。', ''],
  ['别进直播间', '“别进直播间”是一个网络流行语，用来提醒观众不要被直播封面或预先录制的视频的外貌所吸引，因为进入直播间后可能会发现主播的真实外貌与美颜和化妆后的样子有很大不同。这一表达反映了对美颜和化妆技术的排斥和质疑。', '“我被骗好几次了，再也不信那些漂亮封面，谁信谁傻，别进直播间！”', ''],
  ['写进教科书', '“写进教科书”指对一条特别优秀或幽默的评论表示高度赞赏的调侃。意思是这个评论应该被广泛学习和模仿。', '看到楼上这个评论，我笑出声，真该写进教科书！', ''],
  ['本草纲目', '“本草纲目”在这个梗中指的是周杰伦的一首歌，该歌曲被用作健身背景音乐，因其节奏强烈，被广泛用于刘畊宏的直播毽子操健身课程，成为一种令人闻风丧胆的“神曲”，反映出健身的艰辛。', '每次“本草纲目”一响起，我就自动进入健身模式，开始和刘畊宏一起跳毽子操。', ''],
  ['孤勇者小孩', '指《孤勇者》这首歌成为了小孩子中非常流行的一首“儿歌”，每个小孩几乎都会唱，一旦音乐响起，大家都会合唱。', '街头一群小朋友听到《孤勇者》的音乐响起，立刻变成了“孤勇者小孩”，开始大合唱。', ''],
  ['铁锤妹妹', '“铁锤妹妹”是一个对女生的爱称，带有喜感和反差萌，通常用于称呼自己的女朋友或女生自称，体现出一种接地气和可爱的感觉。', '「我给铁锤妹妹买了个新手机，她开心得不得了。「', '该梗出自2014年春晚小品《扰民了您》，由岳云鹏使用。'],
  ['尿遁', '“尿遁”是指通过借口去上厕所，从而暂时逃避责任或避免面对棘手的情况的人，或者用来缓解尴尬局面。', '在会议上，我看到老板脸色不对，赶紧尿遁去洗手间，想避过一劫。', ''],
  ['u1s1', 'u1s1 是“有一说一”的谐音简写，意思是实话实说、按道理讲的意思。', 'u1s1，这次比赛真的很精彩，值得一看。', ''],
  ['好多丧尸在啃人', '这个梗用“丧尸啃人”生动形象地讽刺那些在公共场合进行亲热行为的情侣，尤其是热吻，表达了单身人士对这种现象的调侃或无奈。', '今天去电影院的时候，好多丧尸在啃人，场面一度非常壮观。', ''],
  ['让子弹飞申遗', '这个梗表达了电影《让子弹飞》在大众文化中的经典地位，特别是其丰富的段子与隐喻在多年后依然被广泛引用和讨论。用「申遗「的说法，幽默地表示该电影具有非物质文化遗产的价值。', '每次看到社会新闻，总是忍不住想起《让子弹飞》里的某个桥段，真的要为这部电影“申遗”。', ''],
  ['懂王', '这个梗用来嘲讽那些对某事物理解不够全面却自认为非常了解的人，带有贬义和讽刺。', '他每次讲话总是那副“没有人比我更懂篮球”的样子，大家都忍不住笑了。', ''],
  ['bking', 'bking是“逼王”的另一种说法，通常用调侃的语气形容一个人看上去很酷，举手投足之间充满光芒，有装逼的倾向。最初含有贬义，随着使用范围扩大，逐渐成为褒义词，用于形容长得帅、酷且有王者之气的人。', '他一出场就自带聚光灯，简直是公司里的bking。', ''],
  ['他在cpu你', '“他在cpu你”中的“cpu”被用来指代“洗脑”或“精神控制”。这个梗形象地表示有人通过语言或行为来影响他人的思想。', '小心点，他在cpu你，别被他的话左右。', '这个梗源于演员许娣的一段采访。当被问到如何面对男友的批评时，她无意中将“PUA”说成“CPU”，于是网友们开始用“CPU”替代“PUA”。'],
  ['平角裤', '平角裤是一个来源于《JOJO的奇妙冒险》的梗，象征着“贫弱”或“太弱了”，用来形容对手实力不济。来自于日语“貧弱ゥ（贫弱、太弱了）”，读作：ひんじゃく（罗马音：hinnjaku），谐音“平角裤”。', '在网上对局中输掉比赛后，对手在聊天框打了“平角裤平角裤”，我才意识到原来是个jojo迷。', '该梗来自《JOJO的奇妙冒险》中的角色DIO。在成为吸血鬼后，DIO认为自己非常强大，在与乔纳森·乔斯达的战斗中，他多次高傲地说出“贫弱”，表示对对手的蔑视。这一日语发音类似于“平角裤”，因此形成了梗。'],
  ['好pay', '「好pay「是“好配”的谐音，源自华语网络饭圈，表示「好配「。通常用来形容两个人非常相配或具有很好的化学反应。', '他们在节目里的互动简直太可爱了，真的好pay！', ''],
  ['微信文字讨好症', '微信文字讨好症指的是一种在人际交流时，通过在文字交流中加入更亲切、俏皮的表达方式，使得对话听起来更友好、更可爱的一种倾向。这种方式通常被用来缓和语气，展现出尽量不具攻击性的态度，以营造出积极、讨人喜欢的形象。', '小明习惯性地把“好的”回复成“好滴”，这让他的朋友们调侃他得了微信文字讨好症。', ''],
  ['女同竟在我身边', '“女同竟在我身边”用于形容或赞赏动画、漫画或游戏中出现的百合情节，引发姬佬们（百合爱好者）极大兴奋与喜爱。', '看完《安达与岛村》，我只想说，女同竟在我身边，真是太甜了！', ''],
  ['失败的man', '“失败的man”是“spiderman”（蜘蛛侠）的谐音，用于调侃某件事或某人未能达到期待的效果，表现得像个失败者。', '他本来想模仿蜘蛛侠做个惊艳的cosplay，结果出来的效果却像个“失败的man”，大家都笑翻了。', '该梗来自B站up主液态冰的一段视频。在视频中，液态冰购买并穿上了一个蜘蛛侠套装，但因造型不佳被网友戏称为“苍蝇侠”，网友在弹幕中使用谐音梗称他为“失败的man”。'],
  ['沉默是今晚的康桥', '「沉默是今晚的康桥「这个梗用于形容某人说了尴尬的话，导致气氛变得非常沉默和尴尬。', 'A：你这么聪明，怎么还没脱单呢？    B：我…… (弹幕：沉默是今晚的康桥)', '该梗出自徐志摩的诗作《再别康桥》的情境，结合对尴尬场合的描述在网络弹幕中流行。'],
  ['娇妻文学', '娇妻文学是指一些女生在网上分享的自以为是被宠爱的经历。这些文字常常带有矫情的语气和文笔，展示一种自己是被霸道总裁般宠爱的“小娇妻”状态。然而，外人看起来这些表达实际上常常显得可笑，与现实脱节，她们不幸而不自知。这种风格逐渐在网络上成为一种受网友调侃的文学体裁。', '她发了一篇长长的微信朋友圈，满是娇妻文学的内容，说男友给她买早餐，但读下来却发现男友只是在楼下给她带了一份煎饼果子。', ''],
  ['王维诗里的', '用“王维诗里的XX”句式来强调某物或某事的不普通和特殊，从而赋予它一种高大上的感觉。', '这不是普通的咖啡，这是王维诗里的咖啡。', '出自国漫《中国唱诗班》中的台词：“这可不是普通的红豆，这是王维诗里的红豆，你没听过王维的相思吗？”'],
  ['你在玩很新的东西', '“你在玩很新的东西”用来高情商地评价那些令人迷惑、难以理解的行为或言论。原本指的是音乐或艺术领域中的创新尝试，具有褒义，现在也用于网络上形容一些奇葩的发言或行为。', '在看到某位up主的「人体喷泉「表演视频后，不知道该如何评价的人评论道：“你在玩很新的东西！”', ''],
  ['老六', '指那些在游戏中不按常规策略行事，专门埋伏或偷袭敌人的玩家，后来泛指行为不按套路出牌的人。', '这局游戏他们队里的老六位置太刁钻，抓了我好几次。', '来源于《CS:GO》中进攻方的自由人战术。自由人通常不与队友正面进攻，而是埋伏在非常规位置，打击敌方回防或潜入敌后协助队友夹击敌人，因此被称为“第六人”（CSGO中对战双方一般各有五个队员）。这种角色在游戏中虽然有重要作用，但因其游离于团队之外、采取偷袭和不按常规出牌的行为，逐渐被贬称为“老六”。'],
  ['电子榨菜', '电子榨菜指在吃饭时观看的视频、文章或听的有声书等娱乐内容，能增加食欲，像榨菜一样起到下饭作用。', '吃饭的时候，我喜欢看《武林外传》当电子榨菜。', ''],
  ['我没有惹你们任何人', '“我没有惹你们任何人”用于表达委屈和无奈，意指自己没有做错事，却无端遭到抨击或不公对待。常用来质疑“为什么针对我”并调侃他人。', '被冤枉后，他无奈地说：“我没有惹你们任何人，你们为什么要这样？”', ''],
  ['荒漠屠夫', '荒漠屠夫这个梗指的是一位在抖音上走红的小姐姐，她以快速、熟练的宰羊技能而闻名。由于她在短时间内能熟练地完成羊的宰杀并且展示整齐的羊肉，她被网友戏称为「荒漠屠夫「。', '这位荒漠屠夫小姐姐真的是手起刀落毫不含糊，八分钟就完成了一整套操作。', '源于《英雄联盟》中的一个角色“荒漠屠夫”，以高伤害的半肉战士著称。'],
  ['石乐志', '“石乐志”是“失了智”的谐音，用来形容失去理智或做出不理智行为的人。', '看到他那样冲动行事，简直石乐志！', ''],
  ['蒙鼓族', '蒙鼓族这个梗用来形容那些假装不明白某个话题或事情，故意装作“蒙在鼓里”的网友。这种回应通常是为了幽默或搞笑，并不是真的不理解对方的意思。', 'A：这部电影里，那个角色其实是反派的卧底。      B：谢谢你告诉我，不然我一辈子蒙在鼓里，我是纯种蒙鼓族。', ''],
  ['叮咚鸡', '“叮咚鸡”是一个谐音梗，意为“等通知”。', '今天问老师这个考试安排是什么？结果老师回答：“叮咚鸡。”', ''],
  ['人生无常大肠包小肠', '「人生无常大肠包小肠「是一句戏谑的短语，表达了人生的不可预料和滑稽，其中以一种幽默和轻松的方式来调侃不如意或尴尬的情境。', '今天打球，球掉到水沟里，把自己搞得全身泥泞，唉，真是人生无常，大肠包小肠。', '该短语出自电影版《海绵宝宝》中章鱼哥的台词。英语原句是“Well, it was fun while it lasted.”，意思是为某些短暂而又愉快的事情终结而感到遗憾。在台配版中，配音演员将其翻译得很接地气和无厘头，成为了“大肠包小肠”，让人感觉既无奈又滑稽。'],
  ['女娲你睡了吗', '「女娲你睡了吗「是一句自嘲性的网络流行语，表示面对颜值极高的人时，感到自惭形秽，并调侃自己长得不好看，引发失眠。搭配「我丑的睡不着「进一步加强自嘲意味。', '看完这个颜值爆表的视频，我瞬间感觉自己是个凑数的，不禁默默地发出一声呼喊：“女娲你睡了吗？我丑的睡不着！”', ''],
  ['半岛铁盒', '这是一个对话梗，用于测试对方是否知道周杰伦的歌曲《半岛铁盒》，以及是否能接住梗，类似于对暗号。', '两人在聊天时，甲突然问：“请问你们这里有卖半岛铁盒吗？”结果乙立刻答道：“有啊，你从前面右转的第二排架子上就有了。”', '周杰伦歌曲《半岛铁盒》的MV对白：“哎，小姐请问一下有没有卖《半岛铁盒》？” “有啊，你从前面右转的第二排架子上就有了” “哦，好，谢谢！” “不会！”'],
  ['前排失语症', '前排失语症指的是当人们在抢到评论区的前排位置时，却不知道该发表评论什么内容的尴尬状态。这种现象反映了一种想要表达但无法找到合适语言的无奈。', '终于抢到前排了，结果却前排失语症发作，只好发个表情。', ''],
  ['天降紫微星', '“天降紫微星”是指某位在知名度不高的情况下，凭借一部作品突然爆红的明星，或在体育圈中指成绩卓越、改变圈子现状的运动员。', '那位新人演员凭借这部电影一夜成名，真是天降紫微星。', ''],
  ['巨硬公司', '调侃微软公司，将“微软”对调为“巨硬”。', '最近巨硬公司的新操作系统发布了，你觉得怎么样？', ''],
  ['你在教我做事啊', '「你在教我做事啊「这个梗用于回应别人对自己的行为提出建议或批评，带有一种反感或者不耐烦的情绪，通常用于调侃或玩笑。', '朋友：你应该早点开始复习，这样才能考好。      我：你在教我做事啊？', '该梗出自电影《逃学威龙2》，角色曹达华在被安慰后用这句话回应，并要求不准说朋友坏话。'],
  ['滑马他是天子啊', '谐音“皇阿玛他是天子啊”，出自《甄嬛传》。剧中，皇上对熹贵妃表达了对后宫妃子背叛的不满：“也是一个雾霾天，朕躲在帷帐后面，额娘被隆科多牢牢地抱着，皇阿玛他是天子啊，朕也是天子，为什么你们要背叛朕？” 这句话被观众恶搞成了“滑马他是天子啊”，用来嘲笑他在感情上的失败和无力掌控后宫局势，暗指他被戴绿帽子的情节。', '每次看到电视剧里皇帝发现自己被妃子背叛的场景，网友们纷纷刷弹幕：“滑马他是天子啊”，调侃皇帝虽然是天子，却管不住后宫。', ''],
  ['二极管', '「二极管「是一个网络用语，形容那些只能看到问题的两个极端，认为事物非黑即白，不具备辩证思考能力的人。这个词通常带有贬义，指代那些思维单一、缺乏换位思考、极端自私的人。', '网上讨论某明星的负面新闻时，他总是像个二极管，只能理解为支持或反对，没有中立讨论的空间。', ''],
  ['谷圣', '「谷圣「是对奥运冠军谷爱凌的戏谑性称呼。它源于她在奥运会后的高曝光率、富裕生活和精英形象，引发部分网友的讽刺和调侃，认为她如同被神化的人物。', '在网上冲浪时，看到有人又把谷爱凌称作「谷圣「，看来她的人生真的太不接地气了。', ''],
  ['音乐裁缝', '“音乐裁缝”是一个网络流行词，指那些通过拼凑、剪辑其他音乐作品的元素来创作新作品的人。这种行为类似于抄袭，但有些人声称这只是一种“相似”不是完全的复制。', '最近那位制作人的新单曲被批评是“音乐裁缝”的作品，因为多人指出其中片段源自其他流行歌曲。', ''],
  ['他说他是岛民', '“他说他是岛民”用来形容一种搞笑的、故作严肃地翻译或解释一些不明确或毫无意义的言论，使其看似合情合理的行为。', '当朋友胡乱地用自创语言表达时，我故作专业地说：“他说他是岛民。”', '来自《明星大侦探》第二季第十一期《疯狂马戏团》，撒贝宁在表演中唱了一串无意义的发音，魏晨随后一本正经地“翻译”为“他说他是岛民”。'],
  ['我的一些美好的品德都会消失', '表达某种强烈的期望，同时夸张地强调如果愿望实现不了，自己所有的优点都会消失。', '如果我不买到这个限量版包包的话，我的一些，比如我的时尚感，还有自信心都会消失。', '出自浙江卫视的一档相亲节目，一位大二女学生周兰君在节目中表示自己希望嫁给富二代，否则觉得很多优点都会失去。完整版为：如果我不嫁富二代的话，我的一些，就是比如我的容貌我的身材，还有我的社交的礼仪，还有美好的品德，美好的性格，甚至是灵魂都会被毁了。'],
  ['打不过就加入', '“打不过就加入”是一种调侃，指当一个人或团队无法战胜对手时，索性加入对方阵营。这通常带有开玩笑或嘲讽的意味，指责对方放弃了原来的立场或忠诚。', '在公司竞争中，经过多次尝试未果后，小王选择投身竞争对手公司，自嘲道：“打不过就加入吧。”', ''],
  ['天选打工人', '天选打工人指的是在疫情期间，当许多人因为健康码异常、核酸检测结果或小区封锁等原因无法工作时，仍然能够上班的人。这个说法带有一种黑色幽默，表达了在疫情的复杂情境下仍能工作的“幸运”或“命中注定”的感觉。', '虽然今天小区封了，单位也封了，但我的健康码和核酸检测都显示正常，我果然是个天选打工人。', ''],
  ['月亮不睡我不睡', '「月亮不睡我不睡「 是一种形象化表达熬夜的意愿，带有文艺色彩，表达一种与月亮一起度过漫漫长夜的浪漫情愫。', '昨晚为了赶作业，月亮不睡我不睡，就这样硬撑到天亮。', ''],
  ['把狗骗进来杀', '突然开始秀恩爱的行为让单身者毫无防备，仿佛被“骗进来杀”。', '在这集电视剧里，看到最后他们突然在一起了，真是把狗骗进来杀啊。', ''],
  ['盲生你发现了华点', '“盲生你发现了华点”用于调侃或赞扬别人发现了被忽视的重要细节或意外的关键点，相当于“你抓住了问题的核心”。', '在讨论中，小明指出了计划的潜在风险，大家赞叹道：“盲生你发现了华点！”', '源自《夏洛克·福尔摩斯》中“华生，你发现了盲点”这句话，网络化改编而成。'],
  ['叠杀人书', '叠杀人书这个梗是指在反复分享和传播过程中，表情包上的水印层层叠加，使水印变得很厚、很密集，如同一种累加效果。', '我看了一下你发的表情包，这水印都快看不清了，真是叠杀人书啊！', '“杀人书”原本是《英雄联盟》中道具“梅贾的窃魂卷”的俗称。该道具能通过击杀或助攻来叠加层数，层数越多则法术强度越高。'],
  ['被绑架了你就眨眨眼', '“被绑架了你就眨眨眼”用于表达对某人行为不符合其常态的质疑和调侃，暗示该人可能被迫或无奈之下做出这些行为。', '看你今天一反常态地勤快得惊人，难道是被逼迫的？被绑架了你就眨眨眼。', ''],
  ['你要老婆不要', '“你要老婆不要”这个梗源自电影《牧马人》，是其中一句台词。它表达了一种简单直接的爱情表达方式，时常被网友用于调侃或表示对简单纯粹爱情的向往。', '在追求心仪的对象时，有人调侃说：“你要老婆不要，我可以立马送来。”', '该梗出自电影《牧马人》，台词是：“老许，你要老婆不要，你要老婆……只要你开金口，我等会儿给你送来……”'],
  ['每年桃花开的时候', '“每年桃花开的时候”是指一种伤感青春失恋的意境，通常出现在情感混剪视频中，表达对过往感情的怀念和失落。', '每年桃花开的时候，我总会翻出那些旧照片，怀念那段青春的日子。', ''],
  ['全员恶人', '“全员恶人”是指一种烂大街的潮流服装风格，被网友戏称为土味社会人穿搭。', '这次聚会的主题是“全员恶人”，大家都穿上了印有这个字样的T恤。', '该词最早出自北野武的电影《极恶非道》，港译名为《全员恶人》。'],
  ['被支配的恐惧', '“被支配的恐惧”是用来形容因某件事物或情况而感到身不由己的恐惧感。通常用于调侃那些不得已而为之的情况，表达一种无法控制的恐惧和无奈。', '那一天，我终于想起被数学作业支配的恐惧，每晚的熬夜都仿佛又回到了眼前。', '该梗源自漫画和动画《进击的巨人》中的旁白台词：“那一天，人类终于回想起了曾一度被它们所支配的恐惧，和被囚禁于鸟笼中的那份屈辱。”这一格式被广泛应用于网络中，表达被某种权威或情形“支配”的恐惧。'],
  ['摆烂式社交', '摆烂式社交是指以摆烂的态度面对不情愿的社交场合，直白表达自己的想法，拒绝不必要的社交，从而减轻压力。', '小明不喜欢参加公司的聚会，于是他采用了摆烂式社交，直言自己需要休息。', ''],
  ['有点东西但是不多', '“有点东西但是不多”用来形容一个人或事物乍看上去似乎有某种能力、特质或优点，但实际上并不全面，只是处于一般般的水平。多数时候用作调侃，表示其实该特质并不显著或可信。', '这个明星有点人气，但是不多，可能是因为他的新剧播出了。', ''],
  ['不要慌不要慌太阳下山有月光', '“不要慌不要慌太阳下山有月光”是一种安慰和鼓励的话语，意思是在生活中即使遇到困难和不如意的事情，也不要感到恐慌和绝望，因为总会有好事情在后面等待。即便太阳下山，还有月光可以照明，意味着在黑暗或低谷期，也会有温暖和希望。', '小明最近工作不顺利，但他常常对自己说：“不要慌不要慌太阳下山有月光”，希望能振作起来。', '这个梗出自新东方的东方甄选直播间，主播顿顿老师为安慰生活处于低谷期的人所说的一段话，在抖音上流行起来。'],
  ['5G就是快', '形容事情进展很快，与网络速度无关，只是一种调侃说法。', '当期待的电视剧改档，比预期提早播出时，你可以说：“5G就是快啊，居然提前上线了。”', ''],
  ['爱丁堡', '“爱丁堡”是网友戏称上海的一种说法，源于2022年3月31日，上海六院发布的文章《新冠笼罩下的“丁丁保卫战”》，该内容引发网友不满，导致上海被调侃称作爱丁堡。', '最近我打算去爱丁堡看看朋友，看看这段时间大家都如何应对。', ''],
  ['迪士尼在逃公主', '网络流行语，用来赞美女性，形容她们像迪士尼公主一样美丽，但她们并不在迪士尼乐园表演，而是像公主们那样“逃离”了某种场合或情境。这个梗源于迪士尼动画中的公主形象，因为许多迪士尼公主在故事中都有过“逃跑”的经历，因此当有人临时需要“逃离”某个场合时，这个梗就被用来形容她们。', '看到朋友打扮得特别漂亮，却匆忙赶着离开聚会，大家都笑着说：“你这是迪士尼在逃公主啊！”', ''],
  ['蜜雪冰城黑化了', '“蜜雪冰城黑化了”这个梗来源于奶茶品牌蜜雪冰城宣传新品时，将其标志性的白色雪王形象改为黑色，给人一种“黑化”的感觉。网友们调侃这可能是因为天气炎热，雪王被“晒黑”了。', '最近去蜜雪冰城买饮料时，发现雪王黑化了，吓我一跳，还以为是天气太热把它给晒黑了！', ''],
  ['电脑配件', '在动漫中，特指角色对白中用“电脑配件”作为掩饰的物品，实际上指代某些不被允许或者不便公开的补品或物品。渐渐地，这个词开始被用作弹幕，以调侃和幽默的方式来评论此类情境。', '看这部动画的时候，每次看到角色递出一箱神秘物品时，我都忍不住想起“电脑配件”这个梗。', '源自动画《某科学的超电磁炮》。在第2集，角色白井黑子用“电脑配件”来掩盖她实际购买的“补品”。'],
  ['果盘先生', '“果盘先生”用来讽刺那些只顾刷野和吃线，全场经济最高但什么贡献也不做的打野玩家。', '我们的打野跟个果盘先生似的，全场经济第一，打团时人影都没见。', '该梗源于抖音王者荣耀博主@小乃丸的一场游戏回放。在这场对局中，我方名为“果盘先生”的打野赵云战绩不佳但经济高，整局只刷野和抢线，不参与抓人或打团。'],
  ['群青', '在网络文化中，“群青”成为一种鬼畜视频梗，通常当视频中某个角色发出长音时，制作者会将这一长音与YOASOBI的歌曲《群青》中的高音部分“啊”进行结合，同时将画面调成一种类似群青色的效果，形成一种戏谑和幽默的效果。', '有人发了一段朋友在卡拉OK高歌的搞笑视频，瞬间就给他配上《群青》的“啊”变成了鬼畜版。', ''],
  ['暖她一整天', '“暖她一整天”是一个网络用语，用于调侃那些在恋爱中不解风情、对恋爱技巧生搬硬套的人。此外，它还讽刺了一些广告标题夸张、内容空洞无聊的现象。', '小明在女朋友说“早呀”时直接回复“暖她一整天”，让大家笑翻了，他果然还是不太懂这些恋爱技巧。', '出自一个广告，那个广告的标题是：【女生说“早呀”，傻子才回“早”，高情商回复暖她一整天】，图中的“高情商回复”指的是一些可以温暖女生的话，但是被一些直男误解成了回复“暖她一整天”就可以展现自己的高情商，结果搞得自己不仅没有温暖女生，反倒挨了一顿骂。'],
  ['心巴', '“心巴” 是一个网络用语，通过仿造上巴（上唇的意思）来幽默地指代心脏。此词调侃性地将身体各部位以“x巴”的格式重新命名，以增加趣味性。', '在表白现场，他满脸紧张地说：“你已经住进了我的心巴。”', ''],
  ['雪糕刺客', '“雪糕刺客”指的是那些看似普通但价格高昂的雪糕，购买时让人感到意外和“被刺”的疼痛感。这个表达反映了雪糕价格上涨和意外负担感。', '我在超市随便拿了个雪糕，结果结账的时候发现自己被雪糕刺客击倒了，竟然花了三十块。', ''],
  ['互联网嘴替', '互联网嘴替指的是那些在网络上能够精准表达出自己心声的网友，尤其是在涉及到想说但不方便或不善于表达的言论时，他们能够巧妙地表达出来。', '每次看到有人写出我想说却说不出来的话，就感觉他们是我的互联网嘴替。', ''],
  ['文件夹已经建好了', '“文件夹已经建好了”用来讽刺或调侃某项目、作品等虽然宣称已经在进行中，但实际上可能还没有真正开始或取得实质进展。多用于表达对项目推进缓慢的无奈或不满。', '玩家：游戏DLC多久能上线呀？      开发者：放心，文件夹已经建好了。      玩家：明白，再等五年是吗？', ''],
  ['合法但有病', '「合法但有病「是指那些虽然不违反法律，但行为本身显得奇怪或尴尬的事情。虽然这些行为是可以做的，但通常没有必要做，让旁人感到困惑或尴尬。', '在地铁上，他把鞋子脱了放在座位上，大家都觉得这是「合法但有病「的行为。', ''],
  ['手磨咖啡', '形容一个人喜欢没事找事或自我炫耀。', '你今天不是刚喝过咖啡吗？怎么又想喝手磨咖啡了？', '电视剧《都挺好》中，苏大强的一句台词“我想喝手磨咖啡”。'],
  ['哥们上过大学吗', '「哥们上过大学吗「是一个用来调侃各类大学招生视频的网络流行语。这些视频通常由大学的学长学姐们拍摄，内容夸张且具有土味幽默色彩，常以一种热情推销的方式进行。', '看到这个视频我忍不住笑了，哥们上过大学吗，真的是太魔性了！', ''],
  ['别在这发癫', '「别在这发癫「意指让对方停止不正常或过激的行为，通常用于轻松或调侃的语境中。', '在群聊中，小明突然发了一大堆奇怪的表情包，小红无奈地回他：「别在这发癫，小心被管理员禁言了。「', ''],
  ['饮茶先啊', '「饮茶先啊「的意思是提醒人们放下手头的工作，去休息，享受一杯茶。这个短语表达了一种对忙碌工作的抵抗，强调生活中应该有片刻的放松。', '「每天下午三点我就自动提醒自己：饮茶先啊，休息一下再继续努力！「', '这个梗源自2020年，网友Bernard Tee在Facebook上上传的一段视频。在视频中，一位大哥用激动的语气催促大家在下午三点多的时候去喝茶，不要再继续工作了。该视频因其夸张及搞笑的表现风格而迅速走红。'],
  ['粉色娇嫩你如今几岁了', '「粉色娇嫩你如今几岁了「是用于讽刺或调侃他人装嫩时使用的一句流行语，指年纪比较大的人装扮或行为与其年龄不符。该短语指向粉色为年轻可爱的人适合的颜色，同时用以质疑穿着者的年龄是否适合。', '在聚会上，几个朋友看到自己的中年朋友穿了一身粉色，便笑道：“粉色娇嫩，你如今几岁了？”', '该句出自电视剧《甄嬛传》中雍正皇帝的一句台词。在剧中，年纪偏大的齐妃为了取悦雍正，特意穿上年轻时他赞赏的粉色衣服。然而，此时的雍正心烦意乱且对齐妃并无太多好感，因此说出此句：“粉色娇嫩，你如今几岁了。”以表达不满。'],
  ['三迟但到', '“三迟但到”指的是尽管张三出现得比较晚，但最终他一定会被提到，调侃罗翔老师在讲课时总会例举的虚拟人物张三。', '看罗翔老师的视频，我就知道张三肯定会三迟但到。', ''],
  ['法外狂徒张三', '“法外狂徒张三”是指在各种法律教育或讨论中被用作案例假想人物的“张三”。这个名字被频繁用于描绘触犯法律的人，象征性地表示一个在法律边缘试探的人物，因此被调侃为“法外狂徒”。', '看完罗翔老师的一堂课，我觉得张三又立了一堆“丰功伟绩”，真正的法外狂徒无疑了。', '该梗源于厚大法考的罗翔老师，这位老师在讲解法律课程时，经常用“张三”作为假设举例的名字。通过B站用户上传的罗翔老师授课视频，“张三”的形象逐渐在网络上火了起来，成为一种网络调侃。'],
  ['东方甄选', '东方甄选指的是新东方教育集团旗下的一种创新式直播带货方式。因其由新东方教师转型而来，以中英双语直播和独特的教学风格，将学术知识与商品推销相结合，吸引了大量观众。网友认为这种高质量的直播带货犹如一股清泉，为传统的带货模式带来了新意。', '自从东方甄选开始直播带货后，观众不但买到了好产品，还增长了知识，一举两得。', ''],
  ['红眼特效', '红眼特效是一种视觉效果，经常用于动漫和鬼畜二创作品，使得人物的眼睛看起来像能发出犀利的红光。这种特效通常用于展现人物的酷炫、专注或带有危险的气息，常伴随夸张的表情或文本，具有强烈反差的喜剧效果，也用于营造装逼时刻。', '在最新的视频里，博主用红眼特效搭配了一段经典动漫场景，制造出一种搞笑的反差效果。', ''],
  ['战术核显卡', '指的是NVIDIA GeForce GTX 690显卡，由于功耗大、温度高，被调侃为“战术核显卡”。', '我的电脑温度太高了，是不是装了个战术核显卡？', ''],
  ['人参公鸡', '“人参公鸡”是“人身攻击”的谐音，用来幽默或讽刺地指出某人对他人的批评或攻击性言论。', '看看你这评价，简直就是满满的人参公鸡啊，也不怕得罪人。', '这个梗来自于2022年春晚，贾玲和张小斐的小品《喜上加喜》。在小品中，张小斐的角色因在网上发布了一段将贾玲角色塑造成不修边幅的形象的视频，贾玲角色心生不满且带来了“人参炖公鸡”以暗示“人身攻击”，还带了其他谐音如“豆角”和“小杜家的鸡肠”。'],
  ['小朋友你是不是有很多问号', '形容对某件事情不理解或感到困惑时的心情。', '看到他突然消失又出现，我不禁想说，小朋友你是不是有很多问号？', '小朋友，你是不是有很多问号？这句话其实是歌词，而且是来源于周杰伦的一首歌曲《听妈妈的话》'],
  ['整点阳间能看的东西', '“整点阳间能看的东西”用于形容网络上那些阴阳怪气或者不合常规的视频、音频或人物。这是对这些内容的一种讽刺，表达了一种希望看到正常和人们更乐于接受的内容的心态。', '最近短视频平台上乱七八糟的视频太多了，真希望能整点阳间能看的东西。', ''],
  ['你已经是个成熟的软件了', '这个梗用以调侃和吐槽软件，讽刺软件虽“成熟”却未达到用户期望的自动化程度，希望软件能自主完成用户的需求。', '支付宝，你已经是个成熟的软件了，该学会自己还花呗了。', ''],
  ['上香', '“上香”用于形容某事物或人物“凉凉了”，即事业或影响力衰退。常在评论中带有嘲讽或惋惜的意味。', '当某位知名主播被封禁，观众在其旧视频下纷纷留言“上香”。', ''],
  ['开朗的网友', '这一梗源自快手视频博主@开朗的怪的视频内容。在他的视频中，他常常读一些搞笑视频的神回复，并将这些评论标注为“开朗的网友”所说，类似于给评论者打上“马赛克”保护隐私。这个搞笑设定逐渐流行，许多网友纷纷将自己的ID改成“开朗的网友”，使得网络上出现了大量的“开朗的网友”。', '现在刷评论区到处都是“开朗的网友”，感觉大家都在网络上集体变成了同一个人，太有趣了。', ''],
  ['韦神附体', '“韦神附体”指考生希望通过祈求韦神（韦东奕）的数学天赋加持，以在考试中取得好成绩。这是一种对韦神数学能力的膜拜和对考试顺利的期望。', '明天就要考试了，希望“韦神附体”，让我超常发挥。', ''],
  ['6馍', '指在感情中对人的态度忽冷忽热，类似“馏馍”过程。', '他最近对我总是6馍，一会儿热情，一会儿冷淡，真搞不懂他在想什么。', ''],
  ['2000大于3000', '“2000大于3000”用来讽刺和调侃那些做出不切实际或夸大事实的言论，通常用于指出某些观点的荒谬性。', '当他说出他不需要工作也能轻松生活时，大家都用“2000大于3000”来讽刺他的天真。', '该梗源于清华大学陈平教授的一次公开发言，他表示“在中国月入2000元人民币比在美国月入3000美元活得舒服得多”，而这一观点被大众认为不符合实际，因而引发广泛讨论和调侃。'],
  ['怎么不算呢', '这个梗讽刺了刘浩存在采访中对自己过于自信，缺乏谦虚态度。', '当朋友夸我做饭好吃时，我半开玩笑回应：“嗯，怎么不算呢？”', '该梗源自刘浩存的一次采访，主持人问：你觉得自己算是天赋型演员吗？一般来说遇到这样的问题就算是影帝也要谦虚一下，结果刘浩存说：嗯…怎么不算呢？'],
  ['开团', '“开团”最初指游戏中与队友一起进行战斗，现指一群人聚集起来共同攻击或嘲讽某个人。', '最近那个明星在网上被“开团”，评论区都是恶搞图片。', ''],
  ['我不是本地人', '“我不是本地人”这个梗，用于表达对某地或某事的不熟悉或不了解，通常是为了避开为难或者麻烦的情况。当一个人不想参与某个话题或纠纷时，也可能用这句话来假装不知情。', '当有人问他对本地政策的看法时，他笑着说：“我不是本地人，这种事我不太清楚。”', ''],
  ['优雅实在太优雅了', '这个梗用于形容行为举止十分得体、从容不迫，甚至在面对突发事件时也能保持冷静和优雅，以至于让人印象深刻，甚至觉得有些魔性或者搞笑。', '在派对上，尽管遇到了意外停电，他依然从容应对，大家都说：“优雅，实在是太优雅了。”', '梗出自动漫《间谍过家家》的一个经典场面。在主角一家为潜伏进名校而参加入学面试时，通过他们在突发事件中的优雅表现，引起负责考核的教职员——监舍的注意。监舍对优雅的极致追求和夸张反应让观众觉得搞笑和印象深刻，因此形成了这个梗。'],
  ['人间清醒', '“人间清醒”指在纷繁复杂的世界中保持清醒，不迷失自我，明确自我定位，理智且踏实地生活和工作。', '张雨剑的表现被称作人间清醒，他在快速走红后依然保持低调和理智。', ''],
  ['你kin你擦', '“你kin你擦”是一种表达无奈或生气的口头禅，实际上是“你看你…擦”。其中，“kin”是“看”的东北方言发音。这句话经常用于对某些行为表示无奈或不满。', '他把水杯不小心打翻了，旁边的人立马冒出一句：“你kin你擦，这么不小心！”', ''],
  ['tony老师', '「tony老师「是对理发师的调侃性称呼，主要用来吐槽那些容易剪砸头发或者推销业余的理发师。该词讽刺地表示理发师对顾客要求的简单修饰常常理解错误，以致剪出令人非议的发型。', '今天去了理发店，只是想修个发尾，结果tony老师给我来了个全新的杀马特造型。', ''],
  ['小肚小肚', '“小肚小肚”是一个谐音梗，指代智能助手“小度”，亦用于戏谑自己的“小肚腩”。', '视频中的朋友对着镜头喊“小肚小肚”，下一秒他的肚子就像气球一样鼓了起来。', ''],
  ['死去的记忆突然攻击我', '「死去的记忆突然攻击我「是一种形象的表达，指的是过去的记忆，尤其是令人尴尬或不堪回首的行为和经历，突然在当下重新浮现，让人感到无所适从或感到过度的羞耻和尴尬。这种回忆可能是小时候的天真、无知行为或者曾经觉得很酷但现在看来并非如此的事情。', '每次看到那些穿着夸张、行为稚嫩的非主流风视频，我的死去的记忆突然攻击我，让我不禁想翻白眼。', ''],
  ['TES48', 'TES48是对英雄联盟职业战队滔博TES的调侃，模仿日本偶像团体AKB48，建议战队用偶像团体运作方式进行管理，让粉丝深度参与其中。', '自从TES变成TES48后，每次比赛都像一场大型公演。', ''],
  ['卑鄙的外乡人', '“卑鄙的外乡人”指在游戏内利用地形、怪物特性、游戏机制漏洞或bug等策略来轻松战胜敌人或攻略难关的玩家。这种打法往往被视为投机取巧或不按常规出牌。', '在《只狼》中，我也成了一次卑鄙的外乡人，把义夫堵在天守阁的角落里一顿暴打。', '该梗出自游戏《血源诅咒》，玩家在游戏中扮演的角色是一个来雅楠血疗的外乡人，被当地NPC称为“卑鄙的外乡人”。'],
  ['俺也一样', '“俺也一样”用来表达一种强烈的认同感、激动或感慨，尤其是在遇到志同道合的人时。', '朋友兴奋地说：“周末我们去吃火锅吧！”我立刻回复：“俺也一样！”', '俺也一样，来自刘关张三人结义的场景，刘备提议三人结为兄弟。关：…关某平生之愿足矣，…但凭驱使，绝无二心！张：（激动）俺也一样！关：某誓与兄患难与共，终身相伴，生死相随！张：（激动）俺也一样！关：有渝此言，天人共戮之！张：（激动）俺也一样！此处张飞突出一个激动、感慨、崇拜、的情感表达，表情真挚有点魔性而且连续复读。'],
  ['我的银行卡密码', '这个梗用来形容一个人所有的行动和意图都被他人彻底看透，就像对方已经知道了你的银行卡密码一样。通常用于调侃在游戏中完全被对手预判、看穿的一方。', '在《英雄联盟》比赛中，选手的所有闪躲和技能释放都被对方预判到，弹幕刷起了“某选手：我的银行卡密码是”。', ''],
  ['精罗震怒', '精罗震怒是用来调侃那些对古罗马文化有浓厚兴趣的人（即“精神罗马人”），当他们看到古罗马相关的信息时表现出的强烈反应。', '看到电影中的罗马士兵穿错了盔甲，精罗震怒。', ''],
  ['甜心奶奶', '「甜心奶奶「是对歌手王心凌的一种爱称，源自她在《乘风破浪的姐姐》第三季中的初舞台表现。尽管她已经40岁，但仍旧用一首《爱你》等表演让90后粉丝感到怀旧和激动。这个称呼体现了粉丝对她甜美形象和活力的喜爱。', '「王心凌的舞台表现真的太棒了，甜心奶奶一如既往给人惊喜！「', ''],
  ['谁的青春DNA动了', '指原本对自己印象深刻的事物再次出现时，激起了强烈的青春回忆和情感共鸣。', '当我看到王心凌在《浪姐三》上唱起她的经典歌曲时，谁的青春DNA动了！', ''],
  ['釜山图书馆', '“釜山图书馆”是指在电竞赛事中，当客场队伍获胜时，主场观众一片寂静的场景，形容为“图书馆”般的安静。', 'RNG在MSI上的表现太强了，把釜山变成了釜山图书馆。', '该梗来源于2022年英雄联盟MSI比赛，由于RNG战队线上参赛并取得了优异成绩，釜山主场观众在他们获胜时非常安静，因此被网友称为“釜山图书馆”。'],
  ['听我说谢谢你', '“听我说谢谢你”是一种讽刺形式主义的表达，尤其是在感谢防疫人员时，表现出让人尴尬的感恩行为。', '公司开会结束时，大家齐声唱“听我说谢谢你”，让新来的同事感到莫名其妙。', '原本是一首教导孩子感恩的儿歌，但在抖音上一段孩子为上门检测核酸的工作人员表演这首歌的手势舞视频走红后，这首歌变成了形式主义的象征。各地学校和单位纷纷效仿，用这首歌来感谢防疫人员。然而，这种表演逐渐被认为是一种表面化的形式主义，因为防疫人员本身已经很疲劳，却还要观看这些表演，甚至有时还要配合跳舞。'],
  ['寄', '“寄”是G的谐音，原为电子竞技中的礼貌用语，代表Goodgame的缩写。最初用来表示对一局游戏的满意和结束，表示技不如人的甘拜下风。而在网络文化中，常用于形容“完蛋了”或处于劣势、一种摆烂的心态。', '“这把游戏明显要寄，我还是提前打字GG好跑路。”', ''],
  ['大的要来了', '用来夸大某事件的重要性，引起关注或点击，通常是一种调侃或幽默的方式。', '新版手机要发布了，科技论坛上大家都在说：“大的要来了！”', ''],
  ['忙都忙忙点好啊', '“忙都忙忙点好啊”作为一种调侃，表达了在生活中子女因为忙碌而无法常回家看望父母的现象，这句话表面上理解为体谅孩子的忙碌，实际上却隐含着父母的失落与对团聚的渴望，传达出了一种心酸的关怀与无奈。', '每当我忙得没时间回家看望父母时，我就会想起“忙都忙忙点好啊”这句话，心里总是有些愧疚。', '该梗来源于一个早期的公益广告。广告讲述过年时父母为孩子准备好了年夜饭，但孩子因忙碌无法回家。父母在电话中理解般地说：“忙，都忙。忙点好啊！”。这一情节也在2022年的游戏《原神》的拜年活动中被引用，进一步传播了这个情感表达。'],
  ['橘外人', '「橘外人「指的是那些不属于或无法融入某个特定圈子的局外者。在网络语境中，通常用来形容不太了解某个领域或文化的人。「橘「在此特指「橘文化「，但可以泛指任何圈子。', '作为一个技术小白，我完全是程序员圈子的橘外人，看不懂他们的笑话。', ''],
  ['电摇嘲讽', '源自外网博主Cyranek分享的一个魔性斗舞视频，视频中两个火柴人鬼畜地摇摆身体，动作像是被电击一样，整个过程持续了三分钟左右，十分搞笑夸张。随着视频在网络上的传播，国内的网友们对其进行了二次创作，将这些滑稽的动作变成了嘲讽他人的素材。', '当看到有人夸大其词的时候，我忍不住用电摇嘲讽的视频回应。', ''],
  ['卢雷元年', '“卢雷元年”用来形容2022年，因为电子科技大学的两名学生卢XX和雷XX在毕业设计中舞弊被曝光，导致全国高校加强了对毕业设计的要求。', '“今年的毕业设计要求太严格了，真是名副其实的卢雷元年。”', ''],
  ['胶泥', '“胶泥”是“Jony”的谐音梗，源于说唱圈，用来调侃歌曲《sorry Jony》中频繁出现的“Jony”一词，逐渐在网络上流行开来，成为一种幽默的表达方式。', '今天真倒霉，刚下雨就出门，鞋都湿了，胶泥！', ''],
  ['宁那贝儿', '宁那贝儿是迪士尼角色“玲娜贝儿”的谐音，指宁静和那英这两位在《乘风破浪》节目中气场强大的女艺人的组合名称。这个名字是取自她们在节目中互相斗嘴但仍有互动的关系，表现出一种亦敌亦友的状态。', '在最新一集的《乘风破浪》里，宁那贝儿的互动真的特别精彩，简直不容错过。', ''],
  ['退退退', '「退退退「是指一种大妈在吵架时使用的搞笑且魔性的动作，包含跺脚、手势如击剑，同时大喊「退退退「，仿佛在驱逐恶灵。', '看见评论区吵得不可开交，我都想发个「退退退「来个大招了。', '来源于一个网络视频，视频中一位大妈与司机发生争执，因摆摊占用停车位被质疑非法经营，大妈不回应质问，只做出「退退退「的动作。'],
  ['王心凌男孩', '“王心凌男孩”指的是那些在青少年时期曾喜欢并追随台湾歌手王心凌的男生们。随着时间的推移，这些男生大多成家立业，如今随着《乘风破浪的姐姐》第三季（简称“浪姐三”）的播出，他们因王心凌的出场和其经典歌曲《爱你》而重新感受到了当年的青春与激情。这个梗形象地描述了这些90后男生在当今怀旧浪潮中的活力复现。', '最近在朋友圈里看到一大批的“王心凌男孩”，原来都是当年听《爱你》长大的。', ''],
  ['谢谢甄嬛', '“谢谢甄嬛”是网友们用来庆祝甄嬛（《甄嬛传》中的主角）生日的梗，表达对该角色逆风翻盘、苦尽甘来的励志生活态度的欣赏和向往。这一事件在网上引发了大家对美好生活的期盼，希望通过这种祝福获得好运和福气。', '“今天是甄嬛的生日，大家都在说‘谢谢甄嬛’，希望能接到好福气！”', ''],
  ['建议专家不要建议', '这个梗反映了网友对专家重复、空洞建议的不满和调侃。许多专家建议被认为没有实际意义，解决不了现实问题，导致网友反过来用讽刺的方式建议专家不要再给出此类建议。', '最近专家建议少开夜车，我想说大家都很清楚，关键是条件不允许啊，建议专家不要建议。', ''],
  ['潘周聃', '潘周聃这个梗指的是一位名叫潘周聃的学霸，他在节目《最强大脑》中的出场方式给人留下了深刻的印象。由于场地的狭窄，他起身时的扭头和侧身动作显得非常拽酷，给人一种气势不凡的感觉，因此被网友们用来玩梗和模仿。', '在班级聚会上，小明模仿潘周聃的学霸式起身，引得全场爆笑。', ''],
  ['我是云南的', '“我是云南的”是指一首极具洗脑效果的喊麦歌曲，创作者为了一位来自云南怒江傈僳族的精神小伙，借此宣传自己的家乡和民族文化。这首歌因其旋律和歌词的感染力，尤其是表演者独特的长发舞动，迅速走红网络。', '每次听到“我是云南的”，我都会忍不住跟着哼唱，这旋律太洗脑了。', '我是云南的，来源于某视频平台上一位来自于云南怒江市的精神小伙为自己家乡创作的一首洗脑的喊麦歌曲，完整的歌词内容是：我是云南的，云南怒江的，怒江泸水市，泸水市六库，六库傈僳族，傈僳族是这样叫，乌鸦叫作阿南，青蛙叫作欧巴，老公叫作搓趴，老婆叫作搓嘛，香菜叫作野穴，红薯叫作阿梦，老虎叫作喇嘛，黄瓜叫作阿布。南瓜叫作阿普，鸡蛋'],
  ['痛太痛了', '「痛太痛了「是一句表现极度悲痛或痛苦的台词，可以表示心理上的悲伤或生理上的疼痛。在网络文化中，它常被用于调侃或营造中二氛围。', '在看了一部感人的电影后，小明感慨道：“痛，太痛了，我的心被剧情狠狠揪住了！”', '该梗出自《英雄联盟》中的角色破败之王·佛耶戈的台词。佛耶戈的背景故事讲述了他的妻子伊苏尔德被毒害离去，佛耶戈悲痛欲绝而说出“痛，太痛了”。'],
  ['婉拒了哈', '“婉拒了哈”是一种委婉拒绝别人的表达方式。在直接拒绝可能会带来尴尬或伤感情的情况下，用这种说法既达到了拒绝的目的，又通过“了哈”这种轻松的语气缓和了气氛，让对方更容易接受。', '朋友邀请他出去吃饭，他想留在家里休息，于是回复对方：“今天累了，婉拒了哈，下次一定去！”', ''],
  ['贩剑文学', '贩剑文学是一种通过谐音“贩剑”与“犯贱”而形成的戏谑表达方式，通常用于与朋友互动时的幽默或无厘头表演。', '昨晚上和朋友聊得没话题了，他又开始他的贩剑文学，全程我都无语凝噎。', ''],
  ['你真是个老6', '贬义，形容行为阴险狡诈的人，特别是在游戏中采取隐藏伎俩来得胜的人。', '我们都冲锋了，就你一个人在后面不动，真是个老6。', '“老6”来源于《CS:GO》中进攻方的自由人战术。自由人通常不与队友正面进攻，而是埋伏在非常规位置，打击敌方回防或潜入敌后协助队友夹击敌人，因此被称为“第六人”（CSGO中对战双方一般各有五个队员）。这种角色在游戏中虽然有重要作用，但因其游离于团队之外、采取偷袭和不按常规出牌的行为，逐渐被贬称为“老6”。'],
  ['仰泳鲈鱼', '仰泳鲈鱼形容刚刚死去，肚皮朝上的鲈鱼，以区别于新鲜活鱼。这种死去的鱼通常价格较低，“仰泳鲈鱼”这个称呼实际上是商家以幽默和高情商的方式来描述便宜出售的死鱼，以吸引顾客注意。', '昨天去超市，本以为会买到新鲜的鲈鱼，结果看到的都是促销的仰泳鲈鱼。', ''],
  ['那你报警吧', '「那你报警吧「 是一种表达无奈和想要结束争论的态度，通常用来表示不想再继续与对方纠缠或争论下去。如果对方坚持不休，那么就让第三方来处理。', '「你一直纠结这件事情，我也说不清，那你报警吧，看是不是我错了。「', ''],
  ['上巴', '“上巴”指人中，与“下巴”相对应。', '昨天做核酸的时候，那棉签直接戳到了我“里巴”。', '这个梗来源于台湾一则买地纠纷的报道。曾大爷在接受采访时，描述自己被打到人中，但因汉语不流利，一时想不起“人中”这个词，情急之下说成了“上巴”。虽然“上巴”并不存在，但大家通过上下文和手势明白他说的是人中。这个幽默的词汇迅速走红，成为调侃的梗。'],
  ['燕子没有你我怎么活啊', '表达分手后的无奈和失望，也用来调侃舔狗深情。', '看完比赛后说：“燕子没有你我怎么活啊”，真不舍得这个赛季结束。', '该梗出自电影《从你的全世界路过》中岳云鹏扮演的猪头的台词，猪头和燕子曾经是一对。两人的校园爱情是甜蜜的，但毕业后就分开了，当小燕子从国外回来时，猪头准备结婚，小燕子准备分手，面对小燕子的分手，猪头明明很不舍但还是祝燕子幸福，车一边开，猪头一边追着跟燕子说话，最后还是崩不住了大哭求燕子别走：“燕子没有你我怎么活啊”。'],
  ['从百草园到三味书屋', '“从百草园到三味书屋”是一个网络流行语，用于形容某件事情或内容非常搞笑或离谱。', '在观看一个搞笑视频时，网友纷纷在弹幕中评论：“这段子太好笑了，简直是从百草园到三味书屋。”', '这个梗来源于日本弹幕文化。日语中的“笑”用罗马音首字母表示为“w”，日本网民常用“w”来表达好笑，类似于英文中的“lol”。大面积的“w”像是满屏的草，于是用“草”来代替“W”，从而形成这个梗。'],
  ['生产队的驴', '“生产队的驴”是用来形容特别忙碌或被过度使用的状态。这个短语来源于一句俗语“生产队的驴都没有你忙”，用来对比一个人或物处于高强度的使用状态。虽然用“驴”来形容听上去可能不那么高尚，但在这个语境下并不是用来骂人的，而是一种轻松幽默的表达。', '最近加班太多了，我都快成“生产队的驴”了。', ''],
  ['桌面清理大师', '「桌面清理大师「是一个网络用语，用来形容那些因为愤怒或焦虑而突然把桌上的物品全部推翻甚至掀桌的人。尽管这样做会导致一片混乱，但桌面却瞬间变得空无一物，就像被快速清理了一样。', '看到那位领导一怒之下把所有文件推到地上，大家都戏称他是办公室里的桌面清理大师。', ''],
  ['脚尖上的酸菜', '「脚尖上的酸菜「是用来嘲讽老坛酸菜的生产过程不卫生。这个梗反映了消费者对某些食品厂家生产方法的不满和质疑。', '听到公司食堂要推出老坛酸菜面，大家纷纷调侃说，这不会是“脚尖上的酸菜”吧？', '该梗源自2022年中国中央电视台举办的3·15晚会。当时曝光了统一老坛酸菜面的供应商插旗菜业，他们的酸菜并不是传统的老坛腌制，而是工人在土坑中光脚踩制的，引发公众哗然。'],
  ['李华不写信了', '源于2020年高考英语全国卷作文，不再以李华为主角。形容一种情怀的结束，代表学生时代的一段回忆终结。', '高考结束了，看到题目才知道，李华不写信了，仿佛青春也结束了。', ''],
  ['四十米大刀', '“四十米大刀”是一个调侃式的网络用语，源于一个误报新闻标题，因其夸张和不现实的描述引发网友的搞笑联想。现多用于幽默地表达不满或威胁。', '看完这篇文章，我的40米大刀已经饥渴难耐了。', '起因是因为某新闻小编一时手误，将新闻标题误写成“监拍女子持40米长刀当街砍人”，而脑洞大的网友们，脑补出40米长刀砍人的画面，顿时觉得笑点满满，因而被众网友调侃，慢慢用来在网络上打架，却比寻常的骂架用语多了点调侃味道。'],
  ['防止小孩误食', '源于人们对带孔物品的调侃。原本是为防止孩子误吞而设计的通气孔，但有人问菜刀上的圆孔用途时，网友恶搞回应：“防止小孩误食”。此后，任何带孔物品的用途都会被玩笑称为“防止小孩误食”，成为网络上的搞笑回应。', '在某论坛上有人问充电器上为什么有孔，一位网友立刻回应：「防止小孩误食。「', ''],
  ['大比兜', '“大比兜”是“嘴巴子”或“耳刮子”的更粗俗的说法，意思是打嘴巴子或者被掌掴。现今，它常被用作形容遭遇不幸或糟糕的情况，成为一种表达悲惨经历的幽默方式。', '生活给了我一个大比兜，你们可以想想，对于一个二十来岁的孩子，一个比兜给造成多大的心理伤害啊呜呜呜！', ''],
  ['猪脑过载', '「猪脑过载「是一个用来调侃某人一时反应迟钝或思维停滞的网络用语。通常用于描述一个人遇到困难而无法迅速找到解决方案，从而显得憨态可掬的状态。', '今天做数学题的时候，我真是猪脑过载，半天都算不出结果。', ''],
  ['焯', '“焯”是用于代替爆粗口“草”的一种委婉表达，通常在表达尴尬或窘境时使用。', '当他在众人面前摔倒时，他只能无奈地说了一句：“焯，这也太尴尬了。”', ''],
  ['yyds', 'yyds是“永远的神”的缩写，用来称赞某人或某事物非常优秀，值得敬仰和追随。', '李易峰主演的新剧太精彩了，简直是演技yyds。', ''],
  ['yjjc', 'yjjc是“一骑绝尘”四个字的拼音首字母缩写，用来形容明星艺人的人气和资源斐然过人，断壁断层。它表示某人在某方面表现极为杰出，很难被超越。', '这位新生代偶像凭借几部热播剧迅速走红，真是圈内的yjjc。', ''],
  ['咱也不知道咱也不敢问', '“咱也不知道，咱也不敢问”是一句幽默的话，用来形容一些无法解释、不便过问或令人惊叹的事情。它被网友们用来以幽默的方式自嘲或评论各种现象。', '看直播时，小白秀出了惊人的技巧，大家感叹之余只能说：“咱也不知道他为啥这么优秀，咱也不敢问。”', ''],
  ['耗子尾汁', '「耗子尾汁「其实是「好自为之「的谐音梗，出自马保国的视频演讲。马保国因普通话不标准将“好自为之”说成了“耗子尾汁”，该梗用来调侃或讽刺在做事情时需要自我注意，特别是在一些不满或批评的上下文中。', '当朋友无视你的建议直接行动时，你可以调侃地说：“兄弟，你可要耗子尾汁，没有回头路可走了。”', '该梗出自浑元形意太极拳掌门人马保国与两位年轻人对战的视频。在对战中，马保国被年轻人多次打倒，他在事后的视频中指责对方不讲武术道德，并劝诫“好自为之”。因其普通话发音不准，这句话听起来像“耗子尾汁”，因此走红网络并成为梗。'],
  ['我劝你善良', '“我劝你善良”用来讽刺或规劝心怀恶意的人，提醒对方不要恶意中伤或言行不善。同时，它也是网络上的一种常见吐槽语，常用于调侃。', '有些人为了吸引眼球，总是胡编乱造新闻，我劝你善良。', ''],
  ['卷心菜', '卷心菜指的是一种内卷中的尴尬角色，他们虽然参与竞争，但内心不情愿，显得能力较弱（菜）。同时也可能是一种反向凡尔赛，用来掩盖其真实的强大。', '他总说自己是个卷心菜，但实际上他每次考试都是第一名。', ''],
  ['吴京踩了周杰伦', '吴京踩了周杰伦，谐音梗，“京踩绝（杰）伦”，即“精彩绝伦”。', '这部电影的打斗场面堪称吴京踩了周杰伦，真是精彩绝伦。', ''],
  ['咱就是说', '「咱就是说「是一种口头禅，通常用于句首或句尾，虽然没有实际意义，但增加了语气的幽默和随意感。', '咱就是说，今天的天气真不错。', ''],
  ['双标美羊羊', '「双标美羊羊「是用来形容在行为上对不同的人持有双重标准的人，尤其是在评价或对待他人时表现出明显的偏好。这一用法源于动画角色美羊羊对喜羊羊和沸羊羊的明显双重标准。', '小王每次提出的方案都被经理批评，但同样的方案如果是小李提的就会被称赞，真是个双标美羊羊。', ''],
  ['猛犸颠勺', '猛犸颠勺指的是游戏《Dota 2》中半人猛犸-马格纳斯的技能“獠牙冲刺”，技能动画像在颠勺一样。', '玩马格纳斯最大的乐趣就是用猛犸颠勺来戏弄敌人。', ''],
  ['爷童回', '爷童回是“爷的童年回来了”的缩写，指成年人因为看到或听到与童年回忆有关的事物而感到激动，就像童年重新回来一样。', '当我在电视上重温小时候的经典动画《猫和老鼠》时，简直是爷童回，记忆如潮水般涌来。', ''],
  ['广长', '「广长「是一个戏谑的称呼，用于指代S11全球总决赛中FPX战队的小天在比赛中打出的伤害4397，这个数字正好比之前厂长在世界赛中打出的4396伤害高1点，因此被称为「广长「。', '在这场比赛中，小天打出4397的伤害，队友们提到这个数值时都管他叫“广长”。', ''],
  ['海狗', '海狗是一个网络用语，用来形容那些试图撩很多人但始终成功不了，既像“海王”又像“舔狗”的人。通俗地说，海狗就是同时巴结讨好很多人的人，尽管多方撩拨，却仍显得卑微。', '他每天在社交平台给好多女生留言，还经常送礼物，但都没引起对方注意，简直是个海狗。', '海狗，火自脱口秀大会第四季何广智的段子，他讲到自己有一个朋友经常在朋友圈给所有美女点赞评论，并问广智：你说我这种行为算不算海王？广智说：你这种到处舔人的，只能算海狗。'],
  ['你礼貌吗', '“你礼貌吗” 用于调侃或缓解尴尬，通常在看到或听到不合适或唐突行为时，用来指出对方失礼或无理。', '在游戏群里，有人上来就自曝是高手，我想说：“你礼貌吗？在这个群里藏龙卧虎呢。”', '由于歌手耿斯汉与袁娅维第一次见面就向她要微信，震惊了在场所有人，周深见此行为，立即上前发出的灵魂拷问：“你礼貌吗?你礼貌吗?你礼貌吗?”表情与语气颇具喜感，缓解了当事人的尴尬，自此成梗。'],
  ['抖一中', '「抖一中「是指在抖音平台上，被粉丝称为世界第一中单的LOL职业选手Chovy。粉丝在抖音上常常夸赞Chovy对线技术卓越，认为他是目前最强的中单选手，因此得名。', '最近在抖音上看到好多人吹Chovy，大家都在叫他抖一中。', ''],
  ['凉水怎么可能冲开绿茶', '凉水怎么可能冲开绿茶，这个梗用于讽刺那些抱怨被“绿茶”女生骗的男生，指出如果他们自己不主动迎合或回应，“绿茶”女生是不会成功的。它强调互动是双向的，对方之所以有效是因为自己提供了机会。', '小张总抱怨自己被绿茶女生骗，其实凉水怎么可能冲开绿茶，要不是他自己天天献殷勤，哪有空子可钻？', ''],
  ['沸羊羊我讨厌你', '“沸羊羊我讨厌你”是用来形容人们对待不同人有不同态度的情况，尤其是在喜欢的人和不喜欢的人之间的差异。', '当朋友A和朋友B都给她发信息时，她回复：“朋友A，你真幽默！”，然后说：“朋友B，我讨厌你。” 真是“沸羊羊我讨厌你”的既视感。', '沸羊羊我讨厌你，是在动画片喜羊羊的某一集，美羊羊在指责沸羊羊整天就是打架无所事事的，还说了沸羊羊真粗鲁，表现出很讨厌的样子。喜羊羊走了出来说了一句：是我要打架的。这时候的美羊羊马上说了一句：喜羊羊真厉害啊。'],
  ['川沙妲己', '川沙妲己是对上海迪士尼的新角色玲娜贝儿的戏称，因其可爱迷人而得名。', '玲娜贝儿刚推出就成了网红，被大家称作川沙妲己。', '上海迪士尼度假区推出的新角色玲娜贝儿，由于其迷人的特质，在社交平台上受到热烈关注。上海迪士尼位于川沙镇，因此得名“川沙妲己”。'],
  ['心软的神', '“心软的神”原指韩剧《孤单又灿烂的神：鬼怪》中鬼怪角色，他在救女主的母亲时说：“你今天很走运，遇到了如此心软的神。” 引申为让自己心软的恋人或令人期待的美好爱情。', '看完了《鬼怪》，我也想遇到一个心软的神，来场甜甜的恋爱。', ''],
  ['早知道还是原道', '“早知道还是原道”是用来调侃在耳机爱好者中，花了高价购买耳机却不如性价比高的原道耳机。原道是淘宝上售价9.9包邮的一款耳机，以性价比著称。', '花了几千块买的耳机竟然音质还不如原道，真是的，早知道还是原道。', ''],
  ['红浪漫', '“红浪漫”用于代指一些“高档”洗浴中心或娱乐场所。', '朋友笑着说：“咱们去‘红浪漫’体验一下高档服务吧！”', '出自2013年辽宁春晚，由赵本山、刘小光、田娃表演的小品《中奖了》。小品中的台词“欢迎光临红浪漫，拿好手牌楼上请男宾三位！”让“红浪漫”这个名字广为人知。'],
  ['献出心脏', '“献出心脏”这个梗代表着为了国家和人民奉献一切的精神。这个短语用于表达一种全心全意的献身和忠诚的意愿。', '当朋友为了帮助团队成功而彻夜工作时，你可以对他说：“你真是献出心脏了！”', '该梗出自日本动漫《进击的巨人》，在剧中是兵团的敬礼动作和口号，握拳置于左胸，表明“为公奉献心脏的决心”。'],
  ['越共', '越共，指代像越南游击队一样无处不在、隐蔽性强、战斗力高的人，常用于调侃。', '他每次考试前都不见人影，成绩出来全是高分，简直像个越共。', ''],
  ['消失的眼角膜', '“消失的眼角膜”指明明很明显的事物却被忽视，形容视而不见的现象。', '明明电影海报上写着名字，他还是问我是什么电影，我只能回复他是《消失的眼角膜》。', ''],
  ['德云社在逃成员', '「德云社在逃成员「是一种戏称，用来形容一个角色或人物非常能说会道并且很搞笑，像是一个喜剧演员。这个梗来源于游客对北京环球影城威震天的调侃，他在与游客互动中表现得极其幽默和健谈。', '看了威震天和游客斗嘴的视频，真觉得他像极了德云社在逃成员，简直能说会道。', ''],
  ['剧抛脸', '剧抛脸指一个演员演技非常好，每演一部作品都能完全融入角色，看不出上一个角色的影子。', '这个演员真是剧抛脸，每个角色都演得深入人心。', ''],
  ['人不行别怪路不平', '「人不行别怪路不平「的意思是没有过不去的路，只有不行的人。这是一种讽刺和激励，表达面对困难时应该反思自己的能力，而不是责怪环境。', '他总说困难太多，做什么都不顺，其实就像那个梗说的，人不行别怪路不平，他该提升一下自己的能力了。', ''],
  ['破防了', '“破防了”原本是一个游戏术语，指的是游戏中装备或技能的防御被突破。后被引申用于形容在现实生活中，个人在心理层面上受到冲击或“受伤”，即心理防线被突破。', '他努力维持冷静，但当听到那些不公平的批评时，还是破防了。', ''],
  ['发疯文学', '「发疯文学「是一种通过文字表达强烈情绪的方式，通常以带有夸张、抓狂的语句呈现。这种表达方式常用来表示不满、怒火或者其他激烈情绪，通过大段的情绪渲染来传达内心的冲动和不满。', '「你为什么总是避开我的问题？每次我打开话题都被你轻描淡写地遮掩，我感觉自己像是一个无足轻重的人，你真的关心过我的感受吗？还是一切只是敷衍的掩饰，我不重要！「', ''],
  ['pfox', 'pfox 是“平凡偶像”的缩写，指的是一种谦逊的表达方式，强调偶像也是普通人，只是在某些方面较为出色而被人们关注。', '欧阳靖在节目中自称 pfox，认为自己是个平凡偶像，也想传递这种接地气的感觉给粉丝。', '该词来源于芒果台热播综艺中的rapper欧阳靖。他以此词自称，表达自己是一个平易近人的偶像。'],
  ['废话文学', '废话文学是一种语言风格，看似传递信息，实则没有实质内容，给人一种“说了但好像又什么都没说”的感觉。', '每呼吸60秒，就过去了1分钟。', ''],
  ['太怪了再看一遍', '“太怪了再看一遍”用于形容某些奇葩、难以形容但又非常有趣且让人着迷的内容，让人忍不住重复观看。', '昨天刷到一个绝地武士和小龙女跳舞的视频，太怪了再看一遍。', ''],
  ['亚特兰蒂斯正在苏醒', '“亚特兰蒂斯正在苏醒”是一句网络流行语，源于对不明声音的夸大解读，通常用来调侃或搞笑地描述对某些现象或事物的过于严重或者不切实际的解读。', '小明在咖啡店听到机器运转的声响，认真地说：“亚特兰蒂斯正在苏醒”，引来大家一阵笑声。', '源自抖音博主“肖冷冷的剧情演绎”的一段搞笑视频。在视频中，教授和主角对话，教授宣称他们破译了鲸鱼的叫声，主角一边听一边破译，得出惊讶的结论：“亚特兰蒂斯，正在苏醒？！” 这段夸张的表演引发了网友的广泛模仿和调侃。'],
  ['玻璃渣里找糖', '“玻璃渣里找糖”是一种形容方式，用来表示在一个令人心痛或虐心的情境中试图找到一些甜蜜或欢乐的时刻。这种心态常见于观看或阅读那些情感起伏较大的影视剧或小说时，观众会在整体虐心的情节中寻求甜蜜的小瞬间。', '这部剧太虐了，男女主一直误会重重，我每集都在玻璃渣里找糖，希望他们能快点和好。', ''],
  ['河南拔智齿', '“河南拔智齿”是“很难不支持”的谐音。用于表达对某事的肯定与支持。', '这个新出的功能太好用了，河南拔智齿！', ''],
  ['社死现场', '“社死现场”指的是一个人在公众面前出丑到无地自容、觉得自己“社会性死亡”的情境。这种情况下，感到极度尴尬，以至于想找条地缝钻进去。同“公开处刑”用来描述当众丢脸的情况类似。', '当他在会议上不小心放了一个响屁，那一刻他觉得自己正处于社死现场。', ''],
  ['凡尔赛', '凡尔赛这个梗指的是在社交媒体上用看似平和的文字、不经意间流露出优越感的一种表达方式，通常通过反向描述、先抑后扬、明贬暗褒等手法进行隐晦的炫耀。', '昨天陪我家的狗在私人游泳池游泳，结果它玩累了不想回家，真是太让人头疼了。', '该词源于漫画《凡尔赛玫瑰》，但在网络上是因一种特定的表达模式而流行的。'],
  ['钓鱼佬永不空军', '“钓鱼佬永不空军”是一种调侃和自嘲，用来表示钓鱼爱好者在任何情况下都不会空手而归。如果钓不到鱼，他们总会找到其他替代收获，比如摸虾、摘野菜等，总之不能毫无收获。', '小李这次去钓鱼虽然没钓到鱼，但摘了不少野菜，他说钓鱼佬永不空军。', ''],
  ['六公主', '“六公主”指的是中央六台CCTV6。这个称号源于CCTV6独特的风格，表现出“任性”的一面。六公主经常大胆选择和更改电影播放内容，有时还会以敏感或尖锐的方式触及社会热点。尽管如此，它很少受到批评，反而有时得到央视的支持，就像被宠爱的小女儿一样。', '今天CCTV6又改节目单了，真不愧是“六公主”。', ''],
  ['七夕取消', '在疫情背景下，通过调侃牛郎织女因为没有打疫苗和没有做核酸检测而无法相会，因此“七夕取消”作为一种幽默表达，用以调侃现实中因疫情而遇到的封锁措施和出行限制。', '接天庭通知：牛郎织女没有打疫苗，没有做核酸检测，今年的七夕取消。', ''],
  ['因吹思停', '“因吹思停”是指许昕发球前想吹气但忍住的举动，因其谐音“interesting”而成为网络梗。', '许昕因吹思停，不得不忍住这个习惯性动作，真是太“interesting”了。', '这个梗源于2020年东京奥运会期间，由于疫情防控规定，乒乓球运动员不能在比赛中吹球和触摸球台。乒乓球员在发球前吹口气和摸球台是他们的习惯性动作，但本届奥运会为了防疫，运动员被禁止做这些动作。由于这些动作已经成为球员们的条件反射，因此中国乒乓球队主教练刘国梁在接受采访时开玩笑说，不吹气和不摸桌子是他们备战奥运会最艰难的部'],
  ['打开了但是没有完全打开', '“打开了但是没有完全打开”是一种吊粉丝胃口的行为，形容一种吊人胃口的悬念制造手法。', '每次追剧到关键时刻就戛然而止，真是“打开了但是没有完全打开”的感觉。', '出自B站短视频博主旅途船长，他在视频中试图打开一个锁住的木箱，但每当看似要打开时，又用各种理由拖延。'],
  ['捡手机文学', '捡手机文学是一种伪造聊天记录的网络创作形式，通常假称自己捡到了名人的手机，从而开始虚构对话和故事。', '“最近我在网上看到一个‘捡手机文学’故事，差点以为是真的呢。”', ''],
  ['watch out', '在网络用语中，“watch out”被用于替代“卧槽”，调侃中国羽毛球选手陈清晨在赛场上的呐喊声。这个梗讽刺性地用英语表达中文粗话。', '她扔掉包时突然大喊“watch out”，引得大家一脸懵。', '该梗源自2021年东京奥运会上中国羽毛球选手陈清晨在比赛中的呐喊声。由于发音问题，网友调侃她是在喊“watch out”。'],
  ['红伞伞白杆杆', '这个梗来源于一首云南的童谣，用来提醒人们不要随意食用野生蘑菇，以免中毒。童谣描述的是一种毒蘑菇（毒蝇伞）的特征，通过夸张和重复的歌词来警示食用后导致不良后果。', '朋友A：“野外露营的时候看到了很多蘑菇呢！” 朋友B：“小心红伞伞白杆杆哦，记得不要乱吃！”', '这个梗出自一首云南的童谣，歌词为：红伞伞，白杆杆，吃完一起躺板板。躺板板睡棺棺，然后一起埋山山。埋山山哭喊喊，全村都来吃饭饭，吃饭饭有伞伞，全村一起躺板板。'],
  ['乌兰图雅躲汉子', '“乌兰图雅躲汉子”这个梗指的是歌手乌兰图雅在演唱《套马杆》时，经常故意不唱“汉子”这两个字的现象。这个行为引发观众的调侃，逐渐形成了一个网络梗。', '每次听《套马杆》，我都在期待乌兰图雅会不会再次“躲汉子”。', ''],
  ['拿来吧你', '“拿来吧你”是一种玩笑式的索要表达，表示看中某物并自信地“想要”或“值得拥有”。', '看到朋友的新款手机特别好看，忍不住说：“拿来吧你，这是我的了！”', ''],
  ['招生减章', '“招生减章”是网友在短视频平台上发布的内容，通过真实展示某些高校设施的破败现状，用以讽刺学校招生宣传中夸大的言辞，旨在提醒学生在填报志愿时慎重考虑。', '最近刷到了我们学校的招生减章，果然又是满屏的对比画面。', ''],
  ['不愿再笑', '不愿再笑，表示内容非常搞笑，已经笑到不想再笑了。', '今天的电视剧剧情太搞笑了，我看到最后已经不愿再笑了。', ''],
  ['勇敢牛牛不怕困难', '“勇敢牛牛不怕困难”是一种鼓励积极向上的励志口号，传递出对生活充满期待和积极面对困难的精神。', '每当学习遇到瓶颈，我总是对自己说：“勇敢牛牛不怕困难，加油！”', '该梗出自抖音视频博主@庸，他在视频中展示了与朋友的聊天记录，其中包含一张带有“勇敢牛牛不怕困难”文本的表情包。朋友鼓励他以强大的气势喊出这句话，这一行动随后在抖音上被广泛翻拍传唱。'],
  ['ball ball you', '“ball ball you”是“求求你”的谐音表达，表示恳求、请求的意思。', '高数真的太难了！ball ball you，放过孩子吧！', ''],
  ['60e', '60e是“60亿”的谐音，用来形容某个团体或偶像拥有极其庞大的粉丝数量，夸张地表示全世界都是其粉丝。它表达了人气旺盛和狂热追随的程度。', '「对于WE来说，他们的60e粉丝都是来自全世界的拥趸，没有什么比这更夸张的吹捧了。「', ''],
  ['输的什么液想你的夜', '“输的什么液 想你的夜”是一句改编的“土味情话”，用于表达对某人的思念和爱意。网友们通过这句话创造了许多类似句式的玩梗对话。', '宝，我今天去种地了，种的什么地？对你的死心塌地。', ''],
  ['菜是原罪', '「菜是原罪「意指在任何竞技赛事或领域中，能力或表现不佳是最根本的错误或不足。在电子竞技中，成绩被视为最重要的，其他因素显得次要。', '在团队合作中，他常常自嘲「菜是原罪「，提醒自己要不断提高技能。', '这句话出自英雄联盟职业选手草莓，他在2018年夏季赛后发表在微博上。当时他的战队WE接连失利，面临粉丝的批评和指责，草莓用这句话表达对粉丝失望心情的理解。'],
  ['高街女帝', '“高街女帝”是一种自拍姿势，拍摄时从脖子向下俯拍，小腿后翘，手肘藏在身体后面，并用单手比“耶”。这种姿势在短视频平台上很流行，显得身材很好。', '最近抖音上好多小姐姐都在模仿“高街女帝”姿势。', ''],
  ['希望你永远不懂', '“希望你永远不懂”是一种表达情感的网络用语，原本用于希望他人不经历自己经历过的悲伤。然而，这句话在网络上渐渐演变为一种具有矫情和自我感伤色彩的表达，甚至被网友用来调侃，故意在一些明显的常识后面加入这句话，增加戏剧效果。', '“昨晚熬夜追剧结果今天迟到了，希望你永远不懂。”', ''],
  ['肌肉金轮', '“肌肉金轮”是指将LOL知名主播大司马的脸通过AI换脸技术换到国外肌肉猛男身上，形成的搞笑组合。因为大司马的名字中带“金”，所以取名为“肌肉金轮”。', '最近在网上看到一个视频，简直笑死我了，原来是“肌肉金轮”。', ''],
  ['privilege', '“Priviledge”这个梗用于描绘那些自我高傲、优越感强的人，以调侃方式展现对特权意识的讽刺。', '既然提到privilege，那我就来说说我高傲在哪。我捡垃圾从来不捡塑料的，易拉罐最次，还会捡一些不锈钢金银铜铁，但是我要强调我并不是偷的，写到这里我的高傲尽数体现。', ''],
  ['外卷', '外卷是指通过向外拓展新资源的方式进行竞争，是内卷的对立面。外卷可以理解为开拓新的资源以避免无谓的竞争，也可以指大家共同停止内卷化的过度竞争。', '我们不要再内卷了，看看有没有什么外卷的机会，可以从别的地方获取新的资源。', ''],
  ['蚝爹油', '“蚝爹油”是英语短语“how dare you”（意为“你们怎么敢”）的中文谐音，用作网络梗时，通常表示对某事的愤怒或不可置信，带有夸张与调侃的意味。', '你竟敢在加班的时候偷懒，真是蚝爹油！', '这个梗源自瑞典环保少女Greta Thunberg在联合国气候大会上的发言时的情绪化用语。由于她的要求被认为是不切实际，网友们将这句“how dare you”制作成表情包，成为流行梗。'],
  ['山东菏泽曹县', '“山东菏泽曹县”这个梗用来调侃和夸张地赞美曹县的快速发展或特有的地方文化。', '新开的商场好豪华，简直有种“山东菏泽曹县”的感觉。', ''],
  ['工业糖精', '「工业糖精「用来形容内容极其公式化、为了甜而甜的小说和电视剧。这类作品通常遵循固定套路，没有新意，情节套路化、缺乏创意，读者或观众会觉得厌倦。', '最近看的那部电视剧充满了工业糖精的味道，情节发展完全可以预测。', ''],
  ['卑微文学', '卑微文学是一种以“宝”为开头的舔狗式日记文学风格，表现出无论对方如何对待自己，都始终充满感激与幻想的状态。', '宝，今天你没有理我，但我知道你肯定是太忙了，只要你开心我就满足了。', ''],
  ['两面包夹芝士', '“两面包夹芝士”是“两面包夹之势”的谐音，描述一种夹击的情形或局势。用于形容被两种力量或选择夹在中间，进退两难的情景。', '我的手头工作和学业任务繁重，真是两面包夹芝士，不知道该先做哪个。', '这个梗出自b站up主“一只大哈鱼”的视频“3000块全没了！各位喝醉了一定要管好自己，我真服了！”。视频中因醉酒而进行高消费的自嘲“醉话”引发关注，“两面包夹之势”成为其中的经典句子，并快速传播为“两面包夹芝士”。'],
  ['中国人的八大原谅', '“中国人的八大原谅”是指一些常用的宽慰语句，表达了中国人在特定情境中习惯性的宽容和妥协。这些话语常用来化解尴尬局面或者减轻冲突，也蕴含了一些道德绑架的意味。八大原谅分别是：来都来了、都不容易、都是朋友、是个孩子、人都死了、大过年的、给个面子、为了你好。', '工作中遇到合作方小失误，同事劝我用八大原谅，看在来都来的份上，就算了吧。', ''],
  ['就是玩儿', '“就是玩儿”是一个自我调侃的网络用语，表现出一种不按常理出牌或者反差行为的幽默，通常搭配“我就是玩儿体”的句式，用以制造喜剧效果。这个梗通常用于幽默地表达一种无所谓或随意的心态。', '对象生气，我不哄，就让他气着，哎，就是玩儿。', '该梗源自博主宋富贵的短视频作品。其中，他展示了一些诸如点了拌面不吃、在下雪天不打雪仗等日常反差情景，视频结尾用“哎，就是玩儿”总结，引发网友模仿和再创作。随着这些视频的走红，网友们纷纷创造类似的幽默句式，使其成为一种流行的表达方式。'],
  ['眼睛里进砖头了', '眼睛里进砖头了，形容特别感动到想哭，是“眼睛里进沙子了”的夸张版本，用来委婉表示对某事物的深切感动。', '看完那个小动物救助的视频，我的天，眼睛里进砖头了。', ''],
  ['人间的青草地需要浇水', '“人间的青草地需要浇水”是“你被绿了”的隐晦版本，用来委婉地表达某人被背叛或欺骗的情况。', '“看到他女友和别人约会，真的感觉人间的青草地需要浇水了。”', '该梗出自方大同的歌曲《每个人都会》，其中有一句歌词是“人间的青草地需要浇水，内心的花园就不会枯萎”。这句歌词被博主们用于一些搞笑视频中，延伸出了“被绿”的意思。'],
  ['笑死了但没完全笑死', '「笑死了但没完全笑死「用于形容某件事情非常搞笑，但并没有真的被笑死，是一种夸张的幽默表达。', '你的笑话笑死了但没完全笑死，我还想听下一个！', ''],
  ['丫头文学', '丫头文学指的是一些普通却自信的男人在试图吸引女孩子注意时所表现的言行，通常是在被拒绝后试图将对方的拒绝解释为对自己有意思，从而强行自我感觉良好。', '他跟我说“丫头别嘴硬了，眼神不会说谎的”，一副坚持认为我喜欢他的样子，真是典型的丫头文学。', ''],
  ['心疼giegie', '用于模仿和调侃“绿茶女孩”用嗲声撒娇的行为，常用于形容装可怜或亲昵的语气。', '他刚买的新手机被摔坏了，我都要心疼giegie了。', '来自抖音用户悦悦大叔的视频，视频中一个坐在电瓶车后座的女孩用很嗲的声音扮演绿茶，最后扭捏的叫哥哥(giegie)成为了梗的恶搞来源。'],
  ['恒河猴', '“恒河猴”原意是指普通的猕猴，但在网络用语中，它指的是那些在童年时期经历了创伤，缺乏爱和陪伴，导致其一生都无法摆脱这些影响的人。', '小明的父母总是忙于工作，他很少感受到家庭的温暖，他常说自己是一个“恒河猴”。', '这一说法出自心理学家哈里·哈洛的实验，他使用恒河猴进行研究，探讨婴儿时期的亲密关系对于人类后续生活的影响。实验揭示了早期缺乏亲密关系对心理发展的深远影响。'],
  ['这是你家高粱饴吗', '“这是你家高粱饴吗”是一种在抖音上流行的带货梗，通过博主侯美丽讲述的一系列夸张表现，特别是其独特的推销方式，被网友广泛模仿和引用。这个梗展示了一种幽默、夸张的广告形式，使观众对普通商品产生了有趣的关注。', '朋友聚会时，有人带了自制糖果，另一个朋友大声问道：“这是你家高粱饴吗？”大家立刻笑了起来。', '这是你家高粱饴吗，出自抖音博主侯美丽的家乡美食，主要卖高粱饴糖，她的每个带货视频套路都如出一辙由于表情之浮夸，拉的丝之长，让人直夸一声好颜艺，引起了很多网友们的模仿。于是，这是你家高粱饴吗，靠“洗脑”、“魔性”成功出圈。'],
  ['什么是快乐星球', '“什么是快乐星球”是指一首带有魔性色彩的说唱歌词，它由于其独特的土味中二风格和简易的旋律而引起广泛关注，被用作一种幽默或调侃的表达方式。', '小明最近总是情绪低落，我给他听了一遍“什么是快乐星球”，结果他马上笑了出声。', '该梗出自《快乐星球5》，由角色带小帅（由马嘉祺饰演）在剧中的表演。这句话流行是在抖音等短视频平台上被广泛传播之后。'],
  ['giegie', '“giegie”是用一种撒娇或嗲声喊“哥哥”的方式，通常带有调侃或搞笑的意味。', '他一听到那个女生叫他“giegie”，就忍不住笑出声来。', '来自抖音用户悦悦大叔的视频，视频中一个坐在电瓶车后座的女孩用很嗲的声音扮演绿茶，最后扭捏的叫哥哥(giegie)成为了梗的恶搞来源。'],
  ['嘉禾望岗', '嘉禾望岗作为广州地铁的一个车站，因其承载着人们的离别和相聚的故事而走红网络。它象征着青春的分道扬镳，因为此地不仅连接交通枢纽，还临近许多学校，是学生情侣分别的地方，也成为上班族追梦的起点或终点。', '每次从嘉禾望岗上车，我都会不禁感叹，这里真是充满了青春的回忆和别离的地方。', ''],
  ['感情是对抗路的大忌', '“感情是对抗路的大忌”这个梗是用来戏谑在游戏中过于感情用事会影响表现，暗示玩家应集中注意力，不为情感所扰。', '最近打游戏总输，果然应了那句“感情是对抗路的大忌”。', '这个梗出自游戏主播【是一只鱼】的一句话。他说“感情是对抗路的大忌”，但由于在某美女主播的视频下互动频繁，网友们认为他用实际行动违反了这句“至理名言”。'],
  ['嘎嘎以嘎斯', '“嘎嘎以嘎斯”是东北话，意指非常过瘾、很开心的感觉。', '今天天气特别好，和朋友们去公园野餐，简直是嘎嘎以嘎斯。', ''],
  ['岚语', '岚语是一种网络流行语，指用说英语的方式来说中文，使得普通话带上一种英语发音的独特效果。这是一种娱乐性的语言游戏，不具备实际的语言功能。', '朋友聚会上，小王突然说了一句岚语，逗得大家哈哈大笑。', '岚语出自抖音博主“五十岚上夏”的视频，他通过这种特别的语调，把普通的中文词句变得像有英语发音一样，引发了网友的模仿和传播。'],
  ['每个人身上都有毛毛', '每个人身上都有毛毛，这是一个源自一首魔性洗脑歌曲的梗，歌曲内容简单且带有极高的传染性，通常用来描述人或者动物（尤其是宠物）的毛发，并以其幽默和搞笑的氛围在社交媒体上广为流传。', '我一整天脑子里都是那句“每个人的身上都有毛毛”，太洗脑了！', '每个人身上都有毛毛，是一首非常魔性洗脑的歌《毛毛歌》，原唱是张帝。完整歌词是“每个人的身上都有毛毛~让我为你唱毛毛~到底我们身上有些什么毛~让我唱给你们知道”。'],
  ['背后的原因却很暖心', '「背后的原因却很暖心「是一种对新闻标题中常见的转折句式的调侃，讽刺许多媒体为了吸引读者，喜欢用这种反转的方式来制造噱头。这种标题往往让人觉得背后的原因会是一个有趣或感人的故事，但实际内容可能并不如标题所述。', '昨天晚上熬夜赶项目，今早迟到了，背后的原因却很暖心，因为我帮同事实在不忍心拒绝。', ''],
  ['笋都被你夺完了', '“笋都被你夺完了”由“多损啊”的谐音“夺笋啊”演变而来。用来形容某人的行为非常损，即刻薄或没有同情心，多用于调侃和玩笑。', '“你这件事做得太绝了，笋都被你夺完了！”', ''],
  ['全国人民都看得到', '全国人民都看得到，意思是调侃他人在公共平台上发布不适合公开的言论或行为，提醒其注意言辞，全国人民都能看到。', '你写的日记内容太私人了，请注意，全国人民都看得到！', '源自网上问医的聊天记录，因问诊者言语露骨，被医生提醒“请你自重，全国人都可以看到”。'],
  ['费拉不堪', '「费拉不堪「是从英文单词「Fellah「演化而来的，意指曾经拥有辉煌历史的民族、帝国或文化，在受到外族入侵或内部纷争后，无法恢复往日荣光、任人欺凌。也可以形容一个人曾拥有良好名声和财富，但因内外因素的影响而一蹶不振、无法改变现状。', '许多人认为罗马帝国的衰落正是一个费拉不堪的经典例子，从辉煌的文明沦落到被各部落侵袭。', ''],
  ['这里是缅甸北部', '「这里是缅甸北部「用于调侃某个地方或情境有些特殊或与众不同的情况。', '朋友来到我的房间，看着满地的书，我说：“这里是缅甸北部，欢迎来到我的世界，娇贵的小公主。”', '来自网络小说《插翅难飞》中男主的台词：“这里是缅甸北部，我生长的地方，欢迎来到我的世界，娇贵的小公主。”'],
  ['伤害性不大侮辱性极强', '“伤害性不大，侮辱性极强”指的是一种言谈或行为，虽然没有造成直接的物理伤害，但却在心理或情感上对人产生了深刻的负面影响。这种行为或话语常常看似无害，但实际上蕴含着极深的讽刺或嘲讽，能够给予他人强烈的精神打击。', '“能不能把你的花呗余额截个图发给我，我朋友问我借钱。”这句话看似平常询问，但实际暗示对方可能经济紧张，属于典型的“伤害性不大，侮辱性极强”。', ''],
  ['炒冷饭', '炒冷饭指的是对过往事件或旧闻进行重新翻炒和炒作，具有一定的攻击性或贬义。', '那个明星又在社交媒体上炒冷饭，把自己多年前的事情重新拿出来说。', ''],
  ['中了抖音的毒', '“中了抖音的毒”形容一些年轻用户在长时间使用抖音APP后，模仿其视频内容的现象，特别是在语言表达上。这个形容反映了他们对抖音内容的深度模仿，就像神经中毒一样难以自控。', '自从他沉迷于抖音后，说话的语气和用词都变了，真是中了抖音的毒。', ''],
  ['精苏', '是“精神苏联人”的缩写，指在精神上非常喜欢或认同苏联文化的人。原本它指的是对苏联的政治、经济、军事和文化有强烈兴趣并进行崇拜的人。然而，随着该词的广泛使用，它也逐渐被用来调侃那些对苏联文化有些盲目崇拜的人。', '小张对苏联的历史和文化非常痴迷，每天都研究苏联的政治制度，甚至朋友们都开始叫他“精苏”。', ''],
  ['肉蛋奶警告', '“肉蛋奶警告”源自2018年3月21日“回形针Paperclip”与“世界自然基金会”合作发布的视频“如何快速消灭巴西森林”，视频中包含大量呼吁中国人少吃肉蛋奶的语句，引起广泛争议，故被网友们调侃为“肉蛋奶警告”。', '看来我的午餐要减少肉食，避免朋友对我发出「肉蛋奶警告」。', ''],
  ['太好孝了', '“太好孝了”的意思是“太好笑了”，其中“孝”字是指粉丝对偶像的过度崇拜行为的一种讽刺。用“孝”代替“笑”，强调这种行为虽然看起来像孝顺，但实际上是一种错误的偶像崇拜。', '看到他对偶像的崇拜，我只想说，太好孝了。', ''],
  ['亲爱的周游', '“亲爱的周游”是用来指代心中特殊的人或自己的一个符号，用于表达情感和记忆，而无需暴露其真实身份。', '“亲爱的周游，我最近特别努力地生活，一直在留住生活中的美好，偶尔羡慕，但也不害怕。”', '出自自媒体平台“故野”写的随笔，故野发的视频文案里第一句通常是“亲爱的周游”。'],
  ['蚌埠住了', '“蚌埠住了”是“绷不住了”的谐音，用来形容情感上受到了较大冲击，快撑不住了的状态，比如要哭或要笑。', '看完这个感人的电影，我真的蚌埠住了。', ''],
  ['幸好我不识字', '幸好我不识字，是一句调侃的话，用来表达对不想看到内容的自我逃避和无所谓的态度，最初用于面对秀恩爱。', '朋友在朋友圈晒幸福合照，我只能默默点赞并心想：幸好我不识字。', ''],
  ['前方低能', '前方低能，是提醒观众接下来可能会看到某个蠢蠢的行为。', '看到他打算用手接住飞盘，我赶紧提醒旁边的人：“前方低能。”', '来源于《非正式会谈》主持人大左的名言。'],
  ['深圳女孩', '深圳女孩指的是那些在聚会时不聊八卦，而是专注于讨论如何赚钱的女生。总体上泛指专注于赚钱的女性。', '她们聚会时总聊投资和经济，真是一群深圳女孩。', ''],
  ['小丑竟是我自己', '小丑竟是我自己，表示某人努力讨好他人，却没有得到任何回报，最后发现自己像个小丑一样可笑。', '他每天给她送早餐，等到告白时才发现她有男朋友，小丑竟是我自己。', ''],
  ['心中无女人拔刀自然神', '心中无女人拔刀自然神，描述的是一些人更关注游戏或其他兴趣爱好而不是感情或异性。', '他在游戏里一拿到稀有武器就兴奋得不得了，真是心中无女人，拔刀自然神。', ''],
  ['全糖去冰', '「全糖去冰「用于形容人的甜美和温柔，或者表达对未来甜蜜温暖的期望。', '她是个典型的全糖去冰女孩，笑起来让人觉得特别温暖。', ''],
  ['有bear来', '“有bear来”是一个网络流行语，通过谐音的方式将“有备而来”转化成音近的词语，用以调侃或幽默地表示某人准备充分。', '看他信心十足，看来是有bear来。', '该梗出自中国武术人物马保国的视频片段，其中他解释失败原因时，说到“看来是有备而来”，而被网友空耳为“有bear来”。'],
  ['找个厂子上班', '「找个厂子上班「是用来调侃某人不擅长某种活动或事务，尤其是在电竞圈中，当某个玩家游戏操作不佳时，建议他放弃游戏去「找个厂子上班「，意指他不适合从事当前的活动。这句话是一种幽默的批评或调侃，通常没有恶意。', '主播今天的操作实在是太差了，观众纷纷在弹幕上调侃：“这水平别玩了，赶紧找个厂子上班吧！”', ''],
  ['爷青回', '「爷青回「是「爷的青春又回来了「的缩写，用来表达那些曾在青春时期出现的经典事物重新回归带来的一种怀旧和感慨。', '当我看到《灌篮高手》即将重制版上映，心里只有一句话：爷青回！', ''],
  ['去码头整点薯条', '「去码头整点薯条「这个梗用来幽默地表达出许多人在面临人生哲学问题时偏向于回归简单、具体需求的态度。它表现了一种对生活琐事、基本需求的关注，反映了常人生活中“为了生活而生活”的现实。', '在人生规划面前，有的人可能会选择“去码头整点薯条”的生活态度，专注于解决眼前的温饱问题。', '该梗来源于一张网络流行图，其内容是两只鸟的对话，其中一只在探讨生存的意义，而另一只则一心想要去码头吃薯条。这个情景既搞笑又带有生活哲理，迅速在网络上流行开来。'],
  ['干饭人', '「干饭人「是指那些在吃饭方面非常积极和热情的人，通常以幽默和调侃的方式描述他们在吃饭时的投入和狂野。这个词强调了吃饭对一些人的重要性，描绘了一种风趣和现实生活中关于美食的热情。', '干饭人就要有干饭人的亚子。', ''],
  ['痛苦面具', '痛苦面具指一种表情非常痛苦且夸张，常用于形容人因失落或尴尬而扭曲的面部表情，也常引发观众的幽默感。', '他今天被老板骂了一顿，下班后他的脸简直就是个痛苦面具。', '源于手游《王者荣耀》中的装备“痛苦面具”，但这个梗开始流行是因为一个网络视频，其中男子因分手后流露出十分魔性的痛苦表情。'],
  ['独轮车', '在互联网语境中，「独轮车「指的是一个人不断重复刷同一句话，类似于复读。在直播平台中，这通常通过插件实现，用于提升直播间人气或干扰交流。', '「这个人又开独轮车了，屏幕上全是他重复的话，太烦人了。「', ''],
  ['依萍如洗', '用来形容在双十一购物过后因为支付尾款而变得非常穷困的状态。', '双十一过后，钱包空空如也，真是依萍如洗。', '出自@我的前任是极品 对电视剧《情深深雨濛濛》改词创作的短视频，视频里陆依萍说了一句话：（双十一后）别叫我依萍了，我现在不是依萍，我是“依萍如洗”。'],
  ['内卷', '内卷指的是一种竞争过程中，无意义的资源消耗和无效的努力。即所有参与者都在不断提高付出和成本，但结果却没有实质性地改善或提升。通常是某种过度竞争现象，导致大家都捞不到好处，只有极少数人获益。', '大家为了在社交媒体上获得更多的关注，拼命发内容、买粉丝，这种内卷简直让人疲惫不堪。', ''],
  ['年轻人不讲武德', '“年轻人不讲武德”用于讽刺或调侃某些人不按常规或规则行事，通常带有幽默和讽刺的意味。', '最近公司新来的年轻人完全不按流程走，真是“年轻人不讲武德”啊。', '源自太极拳师马保国在一场比试后的言论。马保国在与年轻人王庆民的比试中，短短30秒内被三次击倒，直接被KO。事后，马保国发布视频控诉：“年轻人不讲武德，偷袭我这个69岁的老人家。”他还表示，传统功夫讲究“点到为止”，如果他真发力，一拳就能把对方的鼻子打骨折。'],
  ['打听打听谁是爹', '「打听打听谁是爹「用来表示在某个圈子或区域中自己最厉害、最强，没有人能超越。这通常用于开玩笑或表示自信和霸气。', '城南城北一条街，打听打听谁是爹。', ''],
  ['真还传', '“真还传”是一个谐音梗，源自罗永浩在《脱口秀大会》上自嘲的还债经历，暗指他一边还债一边感慨人生曲折，幽默地想象成一部关于自己还债故事的“传记”。', '听说罗永浩又还了好几亿，他的《真还传》真是越来越长了。', ''],
  ['收手吧阿祖', '收手吧阿祖，指劝人适可而止，不要再继续下去。', '看到朋友加班太晚，我对他说：“收手吧阿祖，身体要紧。”', '这个梗来自成龙和吴彦祖演的新警察故事。在这部电影当中吴彦祖饰演一位反派角色，在最后被包围的时候被劝投降：“阿祖，收手吧，外面都是警察！”'],
  ['当狗中单', '当狗中单，指在一场比赛中，请某人辅助或配合自己，像“当狗”一样忠诚地支持。', '今天打游戏我主攻输出，你就给我当波狗中单，听我指挥。', ''],
  ['我喜欢发育', '「我喜欢发育「是形容个人或团队在游戏中倾向于通过稳步提升自身实力再采取行动，而不是立刻进攻。', '在游戏刚开始的时候，我喜欢发育，总是先打资源再找机会对抗。', ''],
  ['你永远可以相信宋义进', '“你永远可以相信宋义进”是表达对IG电子竞技战队选手宋义进（Rookie）技术和实力的绝对信任。这句话源于Rookie在遭遇质疑时，用以回应粉丝和外界对他个人能力的怀疑，传递出他对自己实力的自信。', '在IG比赛失利后，粉丝们纷纷留言“你永远可以相信宋义进”，给Rookie加油打气。', ''],
  ['野区栓条狗都能赢', '野区栓条狗都能赢，用来形容某个团队或队伍在某个领域表现极其出色，甚至认为可以轻松获胜，即使是非专业人员或能力较低者参与，也不会影响结果。它通常带有一些自信或轻视对手的意味。', '「这队最近状态太好了，感觉他们完全不需要担心任何对手，简直是‘野区栓条狗都能赢’的节奏。「', '该梗出自2019年英雄联盟季中邀请赛（MSI）期间，IG战队的选手高振宁（游戏ID：Ning）的赛前垃圾话。他表示，只要IG战队的其他四名队员在，野区随便找个不具备专业水平的选手（甚至是让一只狗待在野区）也能获胜。然而，随后IG战队被TL战队以3:1击败，这句话反而成为了一个被调侃的黑点。'],
  ['电竞唢呐', '电竞唢呐是指电子竞技选手高振宁（Ning）和喻文波（JKL）因嗓门大而被网友戏称为「电竞唢呐「。这个称呼主要用来调侃他们在游戏基地里和游戏直播中高声喊话的习惯，特别是JKL嗓门大的特点。', '在直播中，JKL问高振宁符文怎么点，用他的大嗓门调动了整场的气氛，真是名副其实的电竞唢呐。', ''],
  ['我要去搬砖了', '我要去搬砖了，是用来表示不再闲聊或吹牛，要回去工作了。这里的“搬砖”是一种自嘲的说法，形容工作辛苦且工资不高的状态，也带有一种无奈的调侃，是对自己生活现状的一种幽默的反应。当用于评论“炫富”的内容时，还带有一种略微嫉妒或羡慕的语气。', '每次和朋友吹完牛逼，我都会说一句“好了，不聊了，我要去搬砖了”。', ''],
  ['尾款人', '“尾款人”是一种调侃用语，指在双十一期间支付定金后，等待支付尾款的人。', '小王双十一买了很多东西，现在成了名副其实的尾款人。', ''],
  ['打工人', '打工人是对上班族的一种自嘲式称呼，用于描述那些拼命工作却报酬微薄的职场人，表达一种乐观调侃的生活态度。', '“早安，打工人，新的一天继续努力奋斗吧！”', ''],
  ['早八人', '“早八人”指的是早上八点就要上第一节课的大学生，表达了这些学生的辛苦和无奈，同时也带有一种自嘲和幽默的态度。这一称呼源自于“打工人”，用来形容为生活和学业而奔波不易的状态。', '“早八人，没有魂，我要睡长觉了，今天一定肝高数。”', ''],
  ['爬山警告', '「爬山警告「是一种调侃式的威胁，与「带你去爬山「表达了类似的意思，象征着对某人不怀好意的威胁，暗示有来无回。当然，这只是一种幽默的网络用语。', '「你再惹我生气，小心我带你去爬山哦！爬山警告！「', '这个梗源自电视剧《隐秘的角落》，其中秦昊饰演的反派张东升带岳父岳母去爬山，表面上是和和气气地拍照，实则临时起意，将二老推下山崖致死。'],
  ['滋醒警告', '“滋醒警告”是一种幽默表达，意思是“醒醒，不要做白日梦了”，常用于提醒别人不要沉迷幻想。', '听说你准备追求明星，滋醒警告，还是踏踏实实工作吧。', ''],
  ['律师函警告', '律师函警告指的是用法律手段进行威胁，表示如果对方不停止其行为，自己将发出律师函进行法律诉讼。', '在网上讨论时，有人散布虚假信息，另一位网友立刻回复说：“小心律师函警告哦！”', ''],
  ['泥头车', '在网络语境中，“泥头车”是一个用来形容某人行为莽撞、横冲直撞的梗，通常用来形容人做事不顾后果或技术不佳（如在电竞中表现不够理想）。此外，它也被用来表达对某些令人不快或愤怒情况的强烈反应。', '“这个队友玩的像个泥头车一样，直接冲进敌人堆里被秒杀了。”', ''],
  ['肉蛋葱鸡', '“肉蛋葱鸡”是“肉弹冲击”的谐音，用来形容一些游戏中非常糟糕或“下饭”的操作，意指操作很菜或水平很低。', '昨晚打《英雄联盟》，看到队友一波“肉蛋葱鸡”的操作，我忍不住笑出了声。', '该梗源自游戏《英雄联盟》中的一个英雄角色“酒桶”的技能“肉弹冲击”。游戏主播大司马在玩这个角色时，经常因其不尽如人意的操作引发观众的调侃，将技能名称谐音成“肉蛋充饥”和“肉蛋葱鸡”。'],
  ['秋天的第一杯奶茶', '秋天的第一杯奶茶是一种表达关心和爱的方式，象征着被人惦记和爱护。', '今年秋天的第一杯奶茶，我收到了朋友发来的惊喜红包，感觉被温暖包围。', ''],
  ['我太难了', '“我太难了”表达了一种面对生活压力与困难的无奈感，是网民用于调侃和释放生活压力的常用短语。', '每天加班到深夜，我太难了。', '我太难了出自“快手”视频网站上的一个“土味视频”。视频配了一曲忧伤的音乐，主播眉头紧锁，眼神空洞，一边说着“我太难了，老铁，最近压力很大”，一边欲哭无泪地用双手紧紧扶住额头。该视频发布后，“我太难了”立即引爆网络。'],
  ['发烂发臭', '“发烂发臭”是一种带有诅咒意味的话语，通常用于表达对某人的不满或恶意，希望对方的生活变得糟糕。', '他抢了我的点子还不道歉，真希望他的项目从此发烂发臭。', '该梗出自电影《小时代2》，角色南湘在顾里的生日宴会上对顾里说出这句狠话。“我也发自内心的祝愿她，从今以后，和我的人生一样，开始发烂，发臭！”'],
  ['无脑下单', '无脑下单是讽刺当前一些直播平台和短视频与电商合作，共同“坑”观众的现象，形容不假思索地购买商品。', '看了某主播的直播，我差点就无脑下单了，还好及时清醒。', '出自视频博主“郭仙人”的模仿电商系列视频。他通过一人分饰两角的形式，与带货主播互动时经常使用这句话，讽刺电商直播中的忽悠行为。'],
  ['人类还有希望吗', '用于调侃在网络上发布奇怪或无厘头视频的人，表达夸张的疑惑或对人类行为的玩笑性失望。', '当看到主播戴着奇怪的面具疯狂跳舞时，评论区有人刷道：“人类还有希望吗？”', ''],
  ['开屏暴击', '开屏暴击指视频一开始就呈现出非常震撼或让人受刺激的画面，可能是因为美颜、名场面或者令人难以接受的内容。', '这个影片的开屏暴击太强了，我都看呆了。', ''],
  ['如果这都不算爱', '“如果这都不算爱”是ACG圈中用来表示角色之间深厚感情的表达，意指这样的情感就是真爱。', '在动画中，角色A冒着生命危险去救角色B，观众感叹：“如果这都不算爱，那什么才算呢？”', '该梗出自张学友的歌曲《如果这都不算爱》。'],
  ['摄影师晚餐加根鸡腿', '这是在动画或者影视作品中的一种调侃。当某个镜头出现了令人满意的视角或者画面时，观众会说“摄影师晚餐加根鸡腿”来表示赞赏和感谢。', '在一部动画中，当美女角色经过水坑时反光显得非常自然有趣，观众们纷纷在弹幕中打出“摄影师晚餐加根鸡腿”以示赞赏。', ''],
  ['摄影师你明天不用来上班了', '这个梗用于调侃动画或影视作品中，期待福利镜头却出现视角突然移开或者特写不合时宜的行为。观众以此表达对拍摄角度的不满或讽刺。', '镜头本来快要扫到关键位置，却突然抬头拍天空，弹幕纷纷飘过：“摄影师你明天不用来上班了！”', ''],
  ['声优都是怪物', '“声优都是怪物”这个梗用于赞美声优在配音中展现的高超技艺和多变表现。声优常常需要一人分饰多角、适应反差极大的角色、甚至表现出普通人难以模仿的声效。', '在《龙珠》中，野泽雅子能够完美切换多个角色，简直就是“声优都是怪物”！', ''],
  ['是在下输了', '“是在下输了”是用于表达甘拜下风的网络流行语。通常用于承认在某方面不及他人，亦可用于调侃或讽刺。', '在网友晒出自己精美的手工艺品后，评论区有人感叹：“这手艺实在太精湛，是在下输了！”', ''],
  ['我敬你是条汉子', '「我敬你是条汉子「是一句网络流行语，用于赞赏在动画、影视或现实中展现出勇气和自我牺牲精神的人物。在一些情况下，这句话也带有调侃和讽刺的意味，特别是当角色平时表现懦弱而突然做出壮举时。', '在某部动画中，当角色为了保护朋友选择自己承担所有责任，观众纷纷在弹幕上刷屏：“我敬你是条汉子！”', ''],
  ['祥瑞御免', '「祥瑞御免「是指一种讽刺性的说法，用来形容由于接触某人而可能遇到霉运。最初与作家马伯庸有关，传说他总是能在事故中幸免于难，而他身边的人却常遭厄运。因此出现了这个梗意味避开霉运或召唤厄运。', '最近运气不太好，和朋友打趣时，她直接来了一句“祥瑞御免”，希望自己别再倒霉。', ''],
  ['想多了', '弹幕中的常见吐槽语，通常用于当观众觉得某角色对事情的分析或推测过于复杂、敏感时进行调侃。观众作为上帝视角，拥有完整的情报，因此，当看到作品中的角色基于有限的信息做出错误判断或过于细致的推测时，观众会用“想多了”来吐槽角色的“过度解读”。', '在电视剧里，男主误以为女主在暗恋他，观众明知并非如此，便会在弹幕里刷：“想多了。”', ''],
  ['内容过于真实引起不适', '用于评论那些让人看了之后产生不适感的帖子、博文或视频。', '看完这个视频我的胃都开始翻腾了，真是内容过于真实引起不适。', ''],
  ['缘妙不可言', '「缘妙不可言「这个梗的含义是强调人生中的偶然性和不可预知性，包括不可预料的分别和相遇。它常用来调侃在偶然情况下发生的戏剧性事件或结果。', '在游戏直播中，玩家无意中击中了隐藏的对手，弹幕上纷纷刷起了“缘妙不可言”来调侃这次意外。', '该梗出自1999年上映的中国电影《缘，妙不可言》，后成为网络节目《瞎看什么》及《阅后即瞎》的口头禅。'],
  ['外国人少是有原因的', '「外国人少是有原因的「是一种戏谑的评价，用于吐槽外国人进行极限运动、疯狂科学实验或作死行为等，让人觉得不可思议甚至危险的活动。它在调侃这些“作死”行为的同时，通过幽默的方式解释为何外国人的数量似乎相对较少。', '看到一个老外在摩天大楼边缘跑酷，我只能感叹：终于知道为什么外国人那么少了。', ''],
  ['这么可爱一定是男孩子', '“这么可爱一定是男孩子”是一种对外貌特别可爱角色的调侃，尤其是在ACG（动画、漫画、游戏）作品中。该梗原本用于形容正太（年轻男性）的可爱程度，但随着流行，它被用来开玩笑说那些看起来特别可爱的角色，实际上可能是男孩子，甚至在现实中用来调侃某些女性角色。表达了一种性别外貌颠覆的风潮。', '在最新一集《旋风管家》中，看到被误认为是男孩子的可爱角色后，观众纷纷发弹幕吐槽：“这么可爱一定是男孩子！”', '该梗源自结城さくや的漫画《春日部高校女装部》，原文为「こんな可愛い子が女の子のはずがない」（直译为：这么可爱不可能是女孩子）。'],
  ['人干事', '“人干事”源自“这是人干的事吗”的缩写，主要用来吐槽不合理或者让人无法接受的事物，多用于表达对某视频内容的不满或出入预期的情况。', '在看到电视剧的结局原来就是一场梦之后，弹幕上全是“人干事”的抱怨。', ''],
  ['这是人干的事吗', '「这是人干的事吗「（简称「人干事「）是一种用来吐槽不可接受或令人意想不到的事物的成句，多用于表达不满或对某事物感到震惊。', '同事对堆积如山的工作量感到崩溃，愤怒地说：“这真的是人干的事吗？公司竟然指望我们一天完成这些任务。”', ''],
  ['字幕组调皮了', '「字幕组调皮了「是一个常见的网络吐槽梗，通常用于观众在观看影视作品时，发现字幕组在字幕内容中加入了不在原文本中的吐槽内容或网络用语，引入了幽默效果或意外的笑点。这样的翻译有时能够增加观影的趣味，但也有可能破坏原有的观看体验。这个梗表达了观众对字幕翻译的评价，可以是赞赏也可以是批评。', '在观看《可塑性记忆》时，我看到字幕写着“泥垢了”，不由得笑出了声，真的是字幕组调皮了。', ''],
  ['笑容由我来守护', '“笑容由我来守护”是一种用于表达对某人笑容的喜爱和想要保护情感的吐槽用语。这句话通常在某人的微笑给人留下深刻印象或在强调某人的笑容时使用。', '看到她那阳光般的微笑，我心中不禁涌起一种冲动：这笑容由我来守护。', '该用语出自《假面骑士空我》中的主角五代雄介所说的台词：“大家的笑容由我来守护”。这句台词后来被广泛用于网上讨论和吐槽中。'],
  ['别光喝酒吃菜啊', '“别光喝酒吃菜啊”指发言或行为不切实际，像喝醉了一样，不着调甚至有些愚蠢。用于劝人清醒且别再继续说胡话。', '你居然说你能在一个月内赚一百万，别光喝酒吃菜啊，冷静点。', ''],
  ['几个菜啊喝成这样', '“几个菜啊喝成这样”用来形容某人的行为或者发言非常离谱、怪异，仿佛是喝醉了酒一样，显得不切实际甚至有些愚蠢。', '在某个热帖下，有人评论了一段异常离谱的理论，另一位网友回复道：“几个菜啊喝成这样，真是服了。”', ''],
  ['七夕布谷鸟', '七夕布谷鸟是一个描述单身者在七夕情人节渴望不再孤单的网络梗。布谷鸟的叫声被谐音为“不孤不孤”，表达了人们希望在七夕这一天不会感到孤单的美好愿望。', '每到七夕情人节，我就希望能变成七夕布谷鸟，不孤不孤。', ''],
  ['七夕青蛙', '“七夕青蛙”是一个网络流行梗，主要用于调侃单身人士。因为青蛙的叫声与“孤寡”一词的谐音相似，与七夕节相关联，用于调侃在七夕仍单身的朋友。', '今年七夕还是一个人？听，七夕青蛙在叫：孤寡孤寡！', ''],
  ['妈已经走十年了', '“妈已经走十年了”是一个用来调侃某人演技浮夸的网络梗，源自欧阳娜娜在综艺节目《演员的诞生》中的一次表演。因其过于用力且尴尬的情感抒发，使得原本应悲伤的场景显得非常滑稽，成为网友恶搞和模仿的对象。', '朋友在KTV用力演唱情歌时，我忍不住笑出了声，就像看到“妈已经走十年了”一样。', '该梗出自演技竞演综艺节目《演员的诞生》，欧阳娜娜在与郑昊对战时演出的《我的父亲母亲》片段中的一段台词“妈已经走十年了”。'],
  ['小脑斧', '“小脑斧”是“小老虎”的谐音，是一种卖萌的俏皮话。', '今天在网上看到有人画小脑斧，真的好可爱！', ''],
  ['当然是选择原谅她啊', '“当然是选择原谅她啊”这个梗用于调侃被戴绿帽子的人，表面上是劝慰受害者，实际上借此围观取乐，对当事人造成二次伤害。这句话传递出一种讽刺和无奈的态度。', '小李在网上吐槽女朋友出轨的事，评论里一堆人刷着“当然是选择原谅她啊”。', ''],
  ['我能怎么办我也很绝望啊', '“我能怎么办我也很绝望啊”是一种表达无可奈何、无能为力的绝望情绪的网络用语。常用于调侃、吐槽或自嘲。', '每次考完试看到成绩单，我都默默想到：“我能怎么办我也很绝望啊。”', ''],
  ['老哥稳', '「老哥稳「是一种用来夸赞对方很厉害或表现出色的网络用语。其中“老哥”是对对方的一种敬称，而“稳”则表示对方很有能力或表现得很出色。', '他每次在比赛前预测的结果都很准确，大家都说老哥稳。', ''],
  ['请开始你的表演', '“请开始你的表演”是一种表达洗耳恭听或期待展示的态度，有时则用来调侃装逼行为。', '朋友滔滔不绝地讲述他在某地的冒险经历，我对他说：“请开始你的表演，我洗耳恭听。”', '该词来源于电视选秀节目中评审对参赛选手的常用台词。'],
  ['你有freestyle吗', '“你有freestyle吗”是吴亦凡在《中国有嘻哈》节目中频繁对选手提出的一个灵魂提问，指的是询问选手是否具备即兴说唱的能力。freestyle在这里指即兴创作说唱歌词，这是一种需要极强临场应变能力和创作能力的技能。这个问题成为了检验说唱选手能力的重要标杆。', '新来的同事告诉我他喜欢说唱，我不禁问他：“你有freestyle吗？”', ''],
  ['颜表立', '“颜表立”是“颜色代表立场”的缩写，用颜色表示对特定角色或偶像的支持和喜爱。源于应援文化，粉丝用特定颜色的物品表达对偶像的支持。', '在《LoveLive!》的演唱会直播中，弹幕中粉丝们用五颜六色的字体刷着各自偶像的颜表立，每种颜色都代表着他们最爱的角色。', ''],
  ['中文十级', '“中文十级”主要用于赞美和调侃外国人或不流利中文使用者拥有高超的中文水平。该用语常用于夸奖那些在鬼畜视频中被空耳成中文的内容、外国人及非中文的声优或VOCALOID成功演绎中文歌曲或台词。此外，这个短语还借来源自外国人汉语考试的网络段子，产生出不少娱乐性质的语言和语法难题。', '在观看外国歌手用生涩的中文演唱《你好》的时候，弹幕中有人调侃道：“中文十级，名不虚传！”', ''],
  ['船新版本', '“船新版本”是指“全新版本”，通常用于调侃和模仿不标准的普通话发音。', '游戏刚更新完，大家都迫不及待想体验这个“船新版本”。', '该梗来源于香港明星张家辉（渣渣辉）为游戏《贪玩蓝月》做广告宣传时，他在发广告台词时普通话不标准，把“全新版本”说成了“船新版本”。广告因其独特的港普发音而成为网络流行语。'],
  ['震惊体', '震惊体是一种吸引眼球的标题风格，常用于自媒体文章的标题，通常以“震惊！”开头，后面跟着一些引人注目的信息，以激发读者的好奇心，诱导点击阅读。这种标题实际上往往夸大其词，与文章内容的关联度不高。', '震惊！男人看了沉默，女人看了流泪！', ''],
  ['我点了', '“凯哥我点了”是表示投降的意思，通常用于在游戏中认为胜利无望时。', '游戏打不过时，观众们在弹幕上不断刷“凯哥我点了，准备再来一局吧”。', '该梗出自斗鱼平台《英雄联盟》主播洞主，凯哥是他的游戏搭档。当洞主觉得无望时，会不经商量直接投降，然后告诉凯哥“凯哥我点了”。这种行为令观众抓住并调侃，因此在直播间大量使用。'],
  ['你怎么这个亚子', '“你怎么这个亚子”就是“你怎么这个样子”的意思，用来调侃别人行为或状态特别。', '小明忘了带伞，全身湿透了。朋友见状笑道：“你怎么这个亚子？”', '该梗出自电视剧《巴啦啦小魔仙》中的角色游乐王子，由于发音不标准，网友借此调侃，被称为“摸仙堡方言”。'],
  ['小孩子才做选择题', '“小孩子才做选择题”用于表示在面临选择时，成年人不需要非此即彼，而是可以全部选择。一般用于表达既想要这样又想要那样的欲望或贪婪。', '当朋友问我喜欢海滩还是大山时，我笑着回答：“小孩子才做选择题，我全都要。”', ''],
  ['难道只有我一个人觉得', '「难道只有我一个人觉得「是一种表达方式，用于强调个人对某事物的看法不同于普遍意见。最初可能是为了寻求认同和归属感，但在使用中常带有一种自以为是、与众不同的优越感，从而引发反感。', '难道只有我一个人觉得这部电影其实并不好看吗？大家都在夸，我反而没那么喜欢。', ''],
  ['恭喜这个b站用户', '“恭喜这个b站用户” 的完整句是：“恭喜这个B.....站用户”，是一种用于调侃和祝贺在抽奖活动里中奖的B站用户的表达，带有羡慕、嫉妒和幽默的感情。同时，也可以用来嘲笑意外糗事。它通过在转折处加省略号来制造搞笑效果。', '哇，中奖的概率这么低，恭喜这个b站用户！', ''],
  ['有丶东西', '“有丶东西”是用于评价他人表现的网络用语，可以表示欣赏和赞美，也可用于讽刺和挖苦。', '看到他精彩的操作，我不得不说：“你这个比有丶东西的。”', '该梗来源于主播山泥若（滕杨少主），因其直播时常常使用这句话，广为流传。'],
  ['不灭之握', '“不灭之握”是指英雄联盟解说任栋在采访选手时，通过一些意外的、搞笑的方式，成功让被访选手尴尬或出糗。这种互动逐渐成为一种有趣的梗，受到了玩家的欢迎。', '每次看到任栋采访，我都在期待又会有哪个选手遭受“不灭之握”的洗礼。', '该梗起源于2016年季中冠军赛，任栋在采访传奇选手Faker时，通过一个“假握手”的动作让Faker陷入尴尬。'],
  ['C位出道', '“C位出道”指某个艺人在团体中占据核心位置，显示出其强大实力和重要性，多用于形容明星在团队中的突出表现。', '在这次选秀节目中，他一路过关斩将，最终C位出道，成为团队的核心。', '该词来源于真人秀节目《偶像练习生》，在该节目中，练习生经过比赛和大众投票，第一名将作为男团的中心人物（C位）出道。'],
  ['雨女无瓜', '“雨女无瓜”是一个谐音梗，意为“与你无关”。它用来表示与某人或某事无关，常用于调侃和回怼。', '甲：你听说那个八卦了吗？ 乙：那不是我的事，雨女无瓜。', '这个梗出自电视剧《巴啦啦小魔仙》，由角色游乐王子的台词而来。因为演员的普通话带有方言口音，“与你无关”听起来像“雨女无瓜”，因此被网友制作成表情包广泛使用。'],
  ['要你寡', '「要你寡「是“要你管”的谐音表达，用来表示这件事与你无关，无需插手或过问。', '当朋友过于热心想插手你的私事时，可以直接说：“这件事情要你寡！”', '该词语出自经典儿童剧《巴啦啦小魔仙》中的角色游乐王子。游乐王子讲话带有腔调，其发音被网友恶搞成各种谐音梗，最终通过网络传播逐渐走红。'],
  ['来了老弟', '“来了老弟”是一种魔性且洗脑的问候语，通常用于对熟客或朋友的热情欢迎。', '每次打开游戏，我的队友总爱用“来了老弟”来欢迎我上线。', '有一位抖音ID叫诤友的网友，他本来正在减肥，但是每次健完身都忍不住想吃烧烤，身体总是不由自主的走向腰子姐的烧烤店。因为经常去的原因，所以腰子姐每次都会说“来了，老弟”。'],
  ['像极了爱情', '“像极了爱情”是一个网络流行语，最初源自网易云音乐评论，用于描述某些情景看似或让人联想到爱情，但并不特指爱情本身，更多带有一种调侃、嘲讽意味。由于其含义抽象多变，它在各种语境中被广泛使用，成为一种表达复杂感受或无言逻辑的方式。', '当我收到一个意外的大红包，我不禁感叹：“这个红包像极了爱情。”', ''],
  ['紫腚能行', '紫腚能行是谐音梗，来源于东北话“指定能行”，表示一种吉祥祝愿，尤其在高考等重要场合中，希望通过一些特别穿着来取得好成绩。', '高考前夕，许多考生都在寻找紫色内裤，希望在考试中紫腚能行。', ''],
  ['你怎么回事老弟', '“你怎么回事老弟”是一句用于表达疑惑、不解或调侃的话，常配合萌宠等搞笑图片使用，以形成一种“反差萌”的搞笑效果。', '当朋友突然在群里发了一段无厘头的语音时，立刻有人发了“你怎么回事老弟”的表情包，大家都哈哈笑。', ''],
  ['摇了我吧', '“摇了我吧”即“饶了我吧”，是一种源自东北方言的求情表达，用于请求原谅或宽恕，带有一丝搞笑的味道。', '在游戏中失误后，队友笑着说：“小伙汁，求求你摇了我吧，这把真的不行。”', ''],
  ['安排上了', '“安排上了”作为网络用语，表达的是某件事情已经被处理或完成，或者某人开玩笑地表示要进行一项任务。这个词汇带有霸气且俏皮的语气，通常用于强调果断、有效的行动。', '朋友告诉我他找到了心仪的工作，我说：“不错啊，人生赢家，工作都安排上了。”', ''],
  ['6324', '「6324「是对一个直播间的代称，原先是孙笑川所在的抽象工作室直播间的房号，成为抽象话和整个团队的代表数字。', '自从6324被封后，许多嗨粉纷纷转战其他平台，继续延续他们的抽象话文化。', ''],
  ['我佛了', '“我佛了”是一种表达无奈、无语或者让人啼笑皆非的反应的网络用语，其实是“我服了”的谐音变体，用法主要用于调侃和玩梗。', '朋友在游戏里连续送人头后还振振有词地解释，小李无奈地发消息：“我佛了，你真的是天选之子。”', '“我佛了”出自6324抽象工作室，是其掌门人李赣在直播《英雄联盟》时喷队友时所用的一句话。因为四川方言中“服”的发音接近“佛”，嗨粉们也开始使用这个梗，并在2016年的抽象tv贴吧中流行开来。'],
  ['家乡的樱花开了', '“家乡的樱花开了”用来调侃某人是日本人，通过“家乡樱花盛开”来暗示此人来自日本。', '在孙笑川的直播间里，有人留言：“川桑，家乡的樱花又开了，快回去看看。”', ''],
  ['黑人问号', '“黑人问号”是指一种表达疑惑或困惑状态的表情或情绪，通常以“黑人问号.JPG”或“黑人问号脸”来呈现。', '当小明听到数学老师说要加周六课时，他整个人都是一脸的黑人问号。', '该表情包的原型是NBA球星尼克杨。在2015年YouTube视频《透过镜头第4集：尼克杨的日常生活》中，尼克杨的困惑表情被捕捉并广泛传播。该表情在国外被称为“Confused Nick Young”，传入中国后被称为“黑人问号”。'],
  ['还有这种操作', '表示震惊或疑问，意指“居然还有这种套路”。通常用于表达对于一些难以理解或意想不到的情况的反应。', '看到他用这种方法赢得比赛，我只能说一句：还有这种操作？', ''],
  ['意不意外惊不惊喜', '“意不意外惊不惊喜”用来调侃具有戏剧化或出人意料反转的事件，带有一种轻松的挑衅意味。', '他悄悄准备了生日惊喜，突然出现在她面前：“意不意外？惊不惊喜？”', '这句话源自周星驰电影《家有喜事1992》，角色何里玉（张曼玉）和常欢（周星驰）的经典对白。'],
  ['你的良心不会痛吗', '“你的良心不会痛吗”是一句网络流行语，用来调侃或谴责他人行为不当或不合情义，带有指责的意味。', '朋友明明答应帮忙却放了鸽子，还在朋友圈上晒美食，你回了句：“你的良心不会痛吗？”', ''],
  ['皮皮虾我们走', '「皮皮虾我们走「是一句网络流行语，用来表达一种冒险、行动或者召集伙伴一起做某事的意味。它结合了对皮皮虾这种强大生物的夸张称赞。', '今天周末大家都没事的话，皮皮虾我们走，一起去爬山！', ''],
  ['扎心了老铁', '“扎心了老铁”是一句表达内心受到极大刺激或创伤的感叹，用于向朋友诉苦或抱怨。“老铁”意为“铁哥们”或亲密朋友，“扎心”表示内心受到伤害。', '今天考试居然多扣了10分，真是扎心了老铁。', ''],
  ['小拳拳捶你胸口', '“小拳拳捶你胸口”是一句用于撒娇的网络流行语。表达方式轻松可爱，常用于聊天中表现撒娇和戏谑的情境。', '当她生气时，总爱对我说：“哼，我要用小拳拳捶你胸口，让你记住！”', '2017年上半年，一位女性网友在微博上分享了自己和老公撒娇被怼的聊天截图，其中包含了“小拳拳捶你胸口”这句话。这句撒娇的话因为其可爱的表达方式而意外走红。'],
  ['真香', '“真香”是一个网络流行语，常用于指代某人在说出狠话后被现实打脸的尴尬且搞笑的瞬间。这个词用来形容人们在拒绝或批评某事物后，又不得不接受甚至喜欢上它的情境。', '他本来信誓旦旦地说永远不会看那部电视剧，结果第一集还没结束就发朋友圈说“真香”。', '“真香”来源于中国真人秀节目《变形计》第八季《远山的抉择》中，主人公王境泽在初到农村生活时发誓绝不会吃农村的食物，结果后来因为饥饿而食言，吃得津津有味，并说出“真香”二字。这段情节后来被网友们制作成了表情包广泛传播。'],
  ['你号没了', '「你号没了「是一种网络用语，用来警告某人注意言行，否则可能导致其账号被封。这句话带有一种俏皮的威胁意味，常用于提醒或调侃在网络上发表不当言论的人。', '看到有人在微博上大胆评论娱乐圈的绯闻明星，网友纷纷留言：「小心说话，你号没了！「', '这个梗来源于著名LOL职业选手厂长Clearlove7，事件发生在一场游戏中，当时厂长面对一个攻击他的黑粉，用「你再说一句，你号没了，信吗「这样的句式来回应对方。因厂长在游戏圈的影响力，这句话迅速走红，并被缩写为「再号信「成为常用梗。'],
  ['可以但没必要', '「可以但没必要「常用于表示一件事情在技术上可行，但从个人或策略上觉得没有必要去做。这种表达方式带着一些自嘲和调侃，常用于掩饰内心的犹豫或自我安慰。', '玩游戏的时候队友说：“可以杀塔下敌人，但没必要，小心自己的命。”', ''],
  ['我自闭了', '“我自闭了”这个梗用来调侃自己处于消极、失落或者失去信心的状态。这个说法源于“自闭症”，在这个语境中，它比喻一个人被外界打击后陷入了自我封闭、不愿交流的情绪中。', '玩了一下午都没赢一局，我自闭了。', ''],
  ['得不到我的认可', '「得不到我的认可「是一种网络梗，通常用于表达对某事物持批判立场或不满意。起源于电竞圈，具体用于讽刺或调侃某个团队或个人，即便他们在某些领域表现出色，但由于未达到某个特定成就（比如赢得S赛冠军），因此“永远得不到认可”。', '在讨论中，有人说道：“如果他不成为公司CEO，永远得不到我的认可！”用来揶揄某人的成就。', '该梗源自一个电竞比赛流行的弹幕评论：“拿不到S赛冠军，RNG永远也得不到我的认可。” 这句话在亚运会后的RNG比赛直播间中引发热议。RNG粉丝众多，批评的声音不多，但这句评论极具存在感。起初针对RNG，后被广泛应用于其他领域。'],
  ['搞快点', '“搞快点”或缩写为“gkd”是一个网络流行语，用于催促他人加快速度完成某事。最初用于表达对未分享资源的急切期待，但现已广泛适用于任何需要快速推进的场合。', '在看直播时，当主播出现长时间断片，观众纷纷在弹幕中刷屏：“搞快点，我们还等着呢！”', ''],
  ['奶茶肚', '奶茶肚是指由于经常喝奶茶导致的肚子发胖的一种调侃用语，针对那些热爱奶茶的人。它反映了现代人在饮用高糖分饮料后容易出现体重增加的现象。', '最近我胖了不少，都快有奶茶肚了，看来得少喝奶茶了。', '该词出自2018年微博网友@猕猴桃好酸呀的一条博文，其内容提到“如今我们不担心自己有什么啤酒肚了，应该担心的是奶茶肚。”'],
  ['滚出克', '“滚出克”是指“滚出去”的方言谐音，多用于表达不满或驱赶某人，一般在网络互动中使用。', '主播B的直播间被粉丝带节奏，引来粉丝们齐刷“你滚出克”。', ''],
  ['盘她', '有两种含义：1. 盘她可以理解为“撩她”；2. 盘她也可以表示“揍她”。', '那个女孩太漂亮了，我想盘她。', '源于《相声有新人》里孟鹤堂、周九良的相声《文玩》中的一句台词：“干干巴巴的，麻麻赖赖的，一点都不圆润，盘他！”'],
  ['这谁顶得住啊', '“这谁顶得住啊”用于表达在面对巨大差距或者诱惑时的无法承受。', '看着满桌子的美食，这谁顶得住啊！', ''],
  ['人人', '「人人「是对韩文表情文字「ㅅㅅ「的汉化，表示一种赞许或欣慰的笑容，相当于中文流行语「666「。', '队友刚才的操作真是人人，太厉害了！', '该梗源于玩《英雄联盟》（LOL）韩服高端局的主播与韩国玩家互动，经常看到韩国玩家用「ㅅㅅ「来表达赞赏，因此在中文观众中被转化为「人人「。'],
];
